[Lem 4 of arXiv:2606.18877, 'Ergodic Properties of Non-Linear Density-Dependent Perturbations of the Ornstein--Uhlenbec'] Under the same assumptions as in Lemma~\ref{lem:unifbound}, there exists a unique probability density \(\pi\) solving the stationary form of~\eqref{eq:NFPE}. Moreover, \(\pi\in C^1(\R^d)\) and satisfies 
\begin{equation}
\pi(x)=g^{-1}(-\Phi(x)+\mu),\quad x\in\mathbb{R}^{d}
\end{equation}
where 
\begin{eqnarray}
g(r)=\int_{1}^{r}\frac{1}{s\,\Xi(s)}\,ds,\quad r> 0,
\end{eqnarray}
and $\mu$ is the unique number in $\mathbb{R}$ such that 
\begin{equation}
\int_{\mathbb{R}^{d}}g^{-1}(-\Phi(x)+\mu)\,dx=1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 27 (Uniqueness of the nonzero vector invariant law) of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Fix $A>0$ and $N\geq1$ for which $K_{A,N}$ admits a nonzero invariant law
  $\nu_{A,N}$ on $(0,1]$. Then $P_{A,N}$ has a unique invariant probability
  $\pi_{A,N}$ on $[-1,1]^N$ with $\pi_{A,N}(\{0\})=0$, namely
  \begin{equation}
    \pi_{A,N}=\nu_{A,N}J_{A,N}.
  \end{equation}

