[Lemma lem:SAW_bubble of arXiv:2605.15545, 'Crossover from subcritical to critical decay: \\ random walk, self-avoiding walk, percolat'] Let $d \ge 5$.
For any $\gamma > 0$, there is a $\delta = \delta(\gamma) > 0$ such that for $z \in [z_c - \delta, z_c)$ and $\mu \in \Omega_z$,
\begin{equation}
{\sf B}^{(2\mu)}(z) \le {\sf B}^{(0)}(z_c) + \gamma .
\end{equation}

[Lemma lem:semi-good of arXiv:2512.12124, 'A discontinuous percolation phase transition on the hierarchical lattice'] Let $a>0$ and let $J : \mathbb{H}_L \to \mathbb{R}_{\geq 0}$ be a kernel so that $J\left(e\right) \geq \frac{a L \log (j)}{L^{2j}}$ for every edge $e$ with $|e|=L^j$. Then, for all $k\in \mathbb{N}$ there exists a constant $C=C(k,J)$ such that \begin{align}
	&\mathbb{P}_{J} \left( \Lambda_{n,n+k} \textnormal{ is not connected} \right) \leq C n^{-\tfrac{a}{2}} \textnormal{ and}\\

    & \mathbb{P}_{J} \left( \Lambda_{n,n+k} \textnormal{ has a cluster of density $\gamma$} \right) \leq C  n^{-a(1-\gamma)}
	\end{align}
    for every $n\geq 1$ and $\gamma \in \{L^{-k},2L^{-k},\ldots,1-L^{-k},1\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 29 (Bad nodes) of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] For a fixed node $(S,j)$, let
	\begin{equation}
		N(S,j)=\{\tilde S\in \Se_{(S,j)}:\; (\tilde S,k) \mbox{ is arbitrage node and } \tilde S_{k+1}\neq \tilde S_k \mbox{ for some } k\geq j\}.
	\end{equation} 
	A node $(S,j)$ is called \emph{bad}, if $\mathcal{S}_{(S,j)}= N(S,j)$. Otherwise, $(S,j)$ is said to be \emph{good}.

[Lemma lemDensityEstimate of arXiv:2411.18563, 'Lower tails for triangles inside the critical window'] Under Condition~(ConditionThm1 of the paper), 
\begin{align}

\mathbb{E}_{\lambda,\zeta}|G| &= (1+o(1)) \frac{1}{2} \sqrt{\frac{W(2\zeta c^2)}{2\zeta}} n^{3/2} 
\intertext{and}

\mathbb{E}_{\lambda,\zeta} X(G) &= (1+o(1)) \frac{1-\zeta}{6} \left(  \frac{W(2\zeta c^2)}{2\zeta}\right)^{3/2}    n^{3/2} \,.
\end{align}
Moreover, $|G|=(1+o(1))\mathbb{E}_{\lambda,\zeta}|G|$ and $X(G)=(1+o(1))\mathbb{E}_{\lambda,\zeta} X(G)$ with high probability with respect to $\mu_{\lambda,\zeta}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 16 (Corollary $6.6$ in \cite{HeyLod25}) of arXiv:2505.06187, 'Preferential Attachment Trees with Vertex Death: Persistence of the Maximum Degree'] Suppose that $b$ and $d$ are such that Assumptions~\eqref{ass:A1} and \eqref{ass:C1} are satisfied, and let $\cS\coloneq \{\lim_{t\to\infty}|\bp(t)|=\infty\}$ be the event that the process $\mathrm{BP}$ survives. Then,  
		\begin{align}  
			\lim_{M\to\infty} \P{\sup_{t\geq 0} |\cB(0,t)|\e^{-\lambda^*\!t}\geq M}&=0, 
			\intertext{and} 
			\lim_{M\to\infty} \Ps{\inf_{t\geq 0} |\cB(0,t)|\e^{-\lambda^*\!t}\leq 1/M}&=0.
		\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 26 of arXiv:2608.17509, '2608.17509'] Fix \(0<\theta_*<\pi\), and let \(K\subset S_{\theta_*}\) be compact. Then each \(D_{a,L}\) is holomorphic on \(S_{\theta_*}\), and
\begin{equation}

\sup_{L\geq 1}\sup_{\theta\in K}|D_{a,L}(\theta)|<\infty.
\end{equation}

[Definition 1 (Hilbert module {\cite[Chapter~1) of arXiv:2608.30589, 'Vector-Valued Wavelet Bases as Hilbert $\mathbb{M}_m(\mathbb{R})$-Module Bases: A Construc'] {lance1995hilbert}}]
Let $\mathcal{A}$ be a (real) $C^*$-algebra.
A \emph{pre-Hilbert $\mathcal{A}$-module} is a left $\mathcal{A}$-module $\mathcal{H}$ equipped with an $\mathcal{A}$-valued inner product $\langle\cdot,\cdot\rangle_{\mathcal{A}}:\mathcal{H}\times\mathcal{H}\to\mathcal{A}$ such that for all $x,y\in\mathcal{H}$ and $A\in\mathcal{A}$:
\begin{enumerate}[label=(\roman*)]

  \item $\langle x,x\rangle_{\mathcal{A}}\ge 0$;
  \item $\langle x,x\rangle_{\mathcal{A}}=0$ implies $x=0$;
  \item $\langle x,y\rangle_{\mathcal{A}}=\langle y,x\rangle_{\mathcal{A}}^{*}$;
  \item $\langle Ax,y\rangle_{\mathcal{A}}=A\,\langle x,y\rangle_{\mathcal{A}}$.

\end{enumerate}
The induced norm is $\|x\|_{\mathcal{A}}:=\|\langle x,x\rangle_{\mathcal{A}}\|_{\mathcal{A}}^{1/2}$.
If $\mathcal{H}$ is complete for this norm, it is called a \emph{Hilbert $\mathcal{A}$-module}.

[Proposition of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{prop:rand_elec_net_rec}
    Let $G$ be a transitive graph of polynomial growth with $d = 2$, and let $\mathcal E$ be a random electrical network on $G$ such that the conductance of each edge is identically distributed (possibly dependent) random variable dominated by a Cauchy tail.

    Then $\mathcal E$ is recurrent almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2606.27520, 'Critical curve of loop percolation on the $d$-regular tree'] The critical curve $\kappa\mapsto \alpha_c(\kappa)$ is continuous, differentiable at $\kappa \neq \kappa_c$, and monotone increasing for $\kappa \geq \kappa_c$. Furthermore, 
 \begin{equation}
\alpha_c(\kappa) = \frac{2\sqrt{d}(d-1)^{3/4}}{d-2} \sqrt{\kappa - \kappa_c} + O_d(\kappa - \kappa_c),\quad\text{as }\kappa \downarrow \kappa_c
\end{equation}
and 
\begin{equation}
\alpha_c(\kappa) = d^2 \log \bigg( \frac{d-1}{d-2} \bigg)(1+\kappa)^2 + O_d(1),\quad\text{as }\kappa\to\infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

