[Lem 11 of arXiv:2609.03869, '\bf Sharp asymptotics for a transport model with a nonlocal condition of the Fisher-KPP ty'] The solutions $\lambda(\xi)\in\mathbb{C}$ of \eqref{A4} with respect to $\xi\in\R$ satisfy the following properties:
	\begin{itemize}
		\item[(i)] $\Re\lambda(\xi)< 0$ when $\xi\in\R\backslash\{0\}$, and $\lambda(0)=0$;

		\item[(ii)] there exists $\varep\!>\!0$ such that  $\lambda(\xi)$ is uniquely defined for $\xi\in[-\varep,\varep]$, and it has the  expansion:
		\begin{equation}
			\lambda(\xi)=-\mathbf{i}c_*\xi- b\xi^2+\mathbf{i}k\xi^3 +O(\xi^4),~~~~~\text{as}~\xi\to 0,
		\end{equation}
		with $
			b>0$ given in \eqref{notation}, and $k\in\R$.
	Therefore, up to decreasing $\varep>0$,  
	\begin{equation}

			\big|\lambda(\xi)-(-\mathbf{i}c_*\xi- b\xi^2)\big|\le \frac{b}{2}\xi^2~~~~~~\text{for}~\xi\in[-\varep,  \varep].
	\end{equation}

		\item[(iii)] for $\varep>0$ chosen in (ii), there exists  some $\bar\lambda<0$ such that $\lambda(\xi)$ for each $\xi\in\R\backslash[-\varep,\varep]$ satisfies $\Re\lambda(\xi)\le \bar \lambda<0$.
	\end{itemize}

