body:
[Lemma 35 of arXiv:2605.09459, 'Multipoint connectivity in the branching interlacement process'] Let $k \geq 2$, $x_1,\dots,x_k\in\mathbb{Z}^d$, and $\sigma_u$ with law $\mathrm{Poi}(u, W^*)$. Then
  \begin{align*}
    \left\{\!\!\begin{array}{c} x_1,\dots,x_k \text{ are connected} \\ \text{ with less than } n(k,d) \\ \text{ trajectories of } \sigma_u \end{array}\!\!\right\} 
     = \bigcup_{n=1}^{n(k,d)-1}\!\!\!\bigcup_{w_1,\dots,w_n\in\sigma_u} \bigcup_{T \in \mathfrak{T}_{k,n}} \bigcup_{y_1,\dots,y_{n-1}} \bigcap_{i=1}^n \left\{\!\!\begin{array}{c} w_i \text{ connects the labels}\\ \text{of its adjacent edges } \\ \text{in } T(\overline{w}_n,\overline{x}_k,\overline{y}_{n-1}) \end{array}\!\!\right\}.
  \end{align*}

[Proposition 38 of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Let $\pi_{A,N}$ be an invariant probability for $P_{A,N}$ on $\Kcal_N$ with
  $\pi_{A,N}(\{0\})=0$. Then, for every bounded measurable
  $\varphi:\Kcal_N\to\R$,
  \begin{equation}
    \int_{\Kcal_N}\varphi(y)\,\pi_{A,N}(\mathrm{d}y)
    =
    \int_{\Kcal_N}
    \int_{\R^N}
    \varphi\bigl(\tanh(A\norm{x}_2 g/\sqrt N)\bigr)\,
    \mathcal G_N(\mathrm{d}g)\,\pi_{A,N}(\mathrm{d}x).
  \end{equation}
  Moreover, $\pi_{A,N}(\partial[-1,1]^N)=0$ and $\pi_{A,N}$ is absolutely
  continuous on $(-1,1)^N$. If $f_{A,N}$ denotes its density, then, for
  $x\neq0$ and $y\in(-1,1)^N$,
  \begin{equation}
    \kappa_{A,N}(x,y)
    =
    \prod_{i=1}^N
    \frac{\sqrt N}{A\norm{x}_2\sqrt{2\pi}}
    \frac{1}{1-y_i^2}
    \exp\left(
      -\frac{N\,\arctanh(y_i)^2}
      {2A^2\norm{x}_2^2}
    \right)
  \end{equation}
  is the transition density from $x$ to $y$, and
  \begin{equation}
    f_{A,N}(y)
    =
    \int_{\Kcal_N\setminus\{0\}}
    \kappa_{A,N}(x,y)\,\pi_{A,N}(\mathrm{d}x).
  \end{equation}
  If $\pi_{A,N}(\mathrm{d}x)=f_{A,N}(x)\,\mathrm{d}x$, this becomes
  \begin{equation}
    f_{A,N}(y)
    =
    \int_{\Kcal_N\setminus\{0\}}
    \kappa_{A,N}(x,y)f_{A,N}(x)\,\mathrm{d}x .
  \end{equation}

[Lemma lm:o2 of arXiv:2605.26048, 'Classification of the eternal solutions and multiple coalescing shocks in the KPZ fixed po'] The following holds for almost-every $\omega$. Let $\varphi\in\Phi_\omega$ and let $\xi\in\operatorname{supp}(\varphi)$.  Then for every $\varepsilon>0$ there exists   $T_0 = T_0(\varepsilon,\xi)<0$ such that for all $T<T_0$, there exists an interval $J_{T,\xi}\subseteq \mathbb{R}$ \rm{(}depending on $\varepsilon$\rm{)} such that 
    \begin{equation} 
        (W\star\varphi\,)(x,T)=(\Wf{{\varphi_{I_\varepsilon}}})(x,T)>(\Wf{{\varphi_{I^c_\varepsilon}}})(x,T), \qquad \forall x\in J_{T,\xi}.
    \end{equation}
    Moreover, for every $(x_0,t_0)\in\mathbb{R}^2$, there exists $T_0' = T_0'(\varepsilon,\xi,x_0,t_0) < t_0$ so that for all $T < T_0'$, 
\begin{equation}
        [g^{\xi,L}_{(x_0,t_0)}(T),g^{\xi,R}_{(x_0,t_0)}(T)]\subseteq J_{T,\xi}.
    \end{equation}

