        \begin{split}
            \sum_{j=0}^{n-K} \frac{\left(n-j-1 \right)!}{\left(n-K-j \right)!}j^{1+\varepsilon} & = \sum_{j=0}^{\left\lfloor \frac{n}{2} \right\rfloor} \frac{\left(n-j-1 \right)!}{\left(n-K-j \right)!}j^{1+\varepsilon} +\sum_{j=\left\lfloor \frac{n}{2} \right\rfloor+1}^{n-K} \frac{\left(n-j-1 \right)!}{\left(n-K-j \right)!}j^{1+\varepsilon}\\
            & \le  n^\varepsilon \left(\frac{1}{2^\varepsilon}\sum_{j=0}^{\left\lfloor \frac{n}{2} \right\rfloor} \frac{\left(n-j-1 \right)!}{\left(n-K-j \right)!}j +\sum_{j=\left\lfloor \frac{n}{2} \right\rfloor+1}^{n-K} \frac{\left(n-j-1 \right)!}{\left(n-K-j \right)!}j ...","release_manifest_digest":"sha256:7068ae1e04fc266ab2eea2cbbb767b1557d1801e19e17157954955664a95e1f5","revision_digest":"sha256:8c09d1396a86b2db5b9e9e5b48bb6a80f2b0e03433305e1339598920a27dcf2b","source_id":"arxiv:2503.22334","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

