[Definition def:thickdisk of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Fix $W\ge\frac{\gamma^2}{2}$ and let $\beta = \gamma+ \frac{2-W}{\gamma}\leq Q$. Let $\hat\psi=\psi_1+\psi_2$ where $\psi_1$ and $\psi_2$ are independent distributions on $\mathcal{S}$ such that: 
		\begin{enumerate}
			\item $\psi_1(z) = X_{\mathrm{Re}(z)}$, with
			\begin{equation}
			X_t:=\left\{ \begin{array}{rcl} 
				B_{2t}-(Q-\beta) t & \mbox{for} & t\ge 0\\
				\tilde{B}_{-2t} +(Q-\beta) t & \mbox{for} & t<0
			\end{array} 
			\right.
			\end{equation}
	        where $(B_t)_{t\ge 0}$ and $(\tilde{B}_t)_{t\ge 0}$ are independent standard Brownian motions conditioned on  $B_{2t}-(Q-\beta)t<0$ and  $ \tilde{B}_{2t} - (Q-\beta)t<0$ for all $t>0$\footnote{This conditioning can be made sense of via Bessel processes; see e.g.~[DMS14].};  
			\item $\psi_2$ has the same law as $h_{\mathcal{S}}^2$.
		\end{enumerate}
		 Let   $\mathbf{c}$ be independently sampled from $\frac{\gamma}{2}e^{(\beta-Q)c}dc$ and set $\psi = \hat\psi+\mathbf{c}$. Let  $\mathcal{M}^{\textup{disk}}_{0,2}(W)$ be the infinite measure describing the law of $(\mathcal{S}, \psi, -\infty, +\infty)/{\sim_\gamma}$. We call a sample from $\mathcal{M}^{\textup{disk}}_{0,2}(W)$ a (two-pointed) \emph{quantum disk of weight $W$}.

[Theorem of arXiv:2606.01683, 'Singular-value gap of nonreversible Markov processes'] Assume $\gamma > 0$.
    For $n \geq 1$, we have the following upper and lower bounds on $\Delta_n$:
    \begin{align*}
        &\text{(i)}  \qquad  \Delta_n \leq \frac{2}{\sqrt{\gamma n}}\\
        &\text{(ii)} \max_{n \leq k \leq 2n} \Delta_k \geq \frac{1}{2\gamma n +3}.
    \end{align*}

[Corollary 68 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] For every $0\le k\le r_w$,
\begin{equation}
 \Nrm(A_{w,k})
 =\left.\partial_z^{L-k}\Nrm(F_w)\right|_{z=0}
 \in\RV.
\end{equation}
Equivalently,
$(-1)^k\Nrm(G_w^{(\length(w)+k)})$ is a realizable-volume polynomial.

