body:
[Theorem thm: of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},\mu,T)$ be a capacity preserving system. If $\mu$ is continuous from above and concave then the following four statements are equivalent:
	\begin{longlist}
		\item $\mu$ is ergodic;
		\medskip
		\item there exists $Q\in\operatorname{core}(\mu)\cap \mathcal{ M}^e(T)$ such that $\mu(A)=Q(A)$ for any $A\in\mathcal{I}$, and 
	\begin{align*}
	\lim_{n\to\infty}&\max_{P\in\operatorname{core}(\mu)}\frac{1}{n}\sum_{i=0}^{n-1}\int f\cdot(g\circ T^i)dP\\
	&=\max_{P\in\operatorname{core}(\mu)}\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}\int f\cdot(g\circ T^i)dP=\int fd\mu\int gdQ
	\end{align*}
		for any $f,g\in B(\Omega,\mathcal{F})$ such that $g\ge 0$;
		\medskip
		\item there exists $Q\in\operatorname{core}(\mu)\cap \mathcal{ M}(T)$ such that 
		\[\lim_{n\to\infty}\max_{P\in\operatorname{core}(\mu)}\frac{1}{n}\sum_{i=0}^{n-1}P(B\cap T^{-i}C)=\max_{P\in\operatorname{core}(\mu)}\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P(B\cap T^{-i}C)=\mu(B)Q(C)\]
		for any $B,C\in \mathcal{F}$;
		\medskip

		\item there exists $Q\in\Delta^{\sigma}(\Omega,\mathcal{F})$ such that  $\mu|_{\mathcal{I}}\ll Q|_{\mathcal{I}}$  and
		\begin{equation*}
			\liminf_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}\mu(B\cap T^{-i}C)\ge\mu(B)Q(C)\text{ for any }B,C\in\mathcal{F}.
		\end{equation*}
	\end{longlist}

[Lemma comparaison of arXiv:2412.02486, 'On the curvatures of \\ random complex submanifolds'] Using the above notations, for any $T\in \sym_\mathbb{C}(n-r,r)$ the following holds.
	\begin{enumerate}
\item 	$\displaystyle \min_{ (x,y)\in (\mathbb S^{2n-2r-1})^2 } |T(x,y)|_{\mathbb{C}^r}
	= \min_{([X],[Y])\in (\mathbb{C} \mathbb{P}^{n-r-1})^2 }\|\Phi_1(T)([X],[Y])\|_{\mathrm{FS}}$,
	\item 	$\displaystyle \min_{x\in \mathbb S^{2n-2r-1}} |T(x,x)|_{\mathbb{C}^r}
	= \min_{[X]\in \mathbb{C} \mathbb{P}^{n-r-1} }\|\Phi_2(T)([X])\|_{\mathrm{FS}}$,
	\item 	$\displaystyle \min_{x\in \mathbb S^{2n-2r-1}} \|T(x,\cdot)\|_{\mathbb{C}^r}
	= \min_{[X]\in \mathbb{C} \mathbb{P}^{n-r-1}}\|\Phi_3(T)([X])\|_{\mathrm{FS}}$.
	\end{enumerate}

[Theorem 10 of arXiv:2606.03661, '2606.03661'] Let $\mathscr{L}_t[f(t);z]$ be the Laplace transform of the function $f(t)$ with conjugate variable $z$. Here $t$ denotes the time variable and $z$ is the Laplace dual variable. Then 
\begin{equation}

\begin{split} 
& \mathscr{L}_t[t^\mu \Psi_\alpha^\nu(-\kappa t);z] \\[1ex]
& \quad = 
\frac{1}{z^{1+\mu}} \frac{G(1+\nu)}{G(2+\nu-\alpha)} \frac{1}{2\pi i} 
\int_{c-\infty}^{c+\infty} \left(\frac{\kappa}{z}\right)^{-s} \Gamma(1+\mu-s) 
\Gamma(s) \frac{G(2+\nu-\alpha-s)}{G(1+\nu-s)} \, ds 
\end{split}
\end{equation}
with $\mu > -1$.

