[Definition order of arXiv:2605.08624, 'On the sum-of-digits measures and Cusick's conjecture via stopped random walks'] Define two maps $L, R \colon 2\mathbb{N}+1 \to 2\mathbb{N}+1$ by
\begin{equation}
L(t) = 2t - 1, \qquad R(t) = 2t + 1.
\end{equation}
We define a partial order $"\preceq"$ on $2\mathbb{N}+1$ as follows:
 $s \preceq t$ if and only if either $s=t$, or there exists a finite sequence $w_1, \ldots, w_n \in \{L, R\}$
such that
\begin{equation}
t =w_n \circ \cdots \circ w_1(s).
\end{equation}

[Definition def:LSI of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] A measure $\theta \in \mathcal{P}(\ensuremath{\mathbb{R}}^m)$ satisfies a log-Sobolev inequality (LSI) with constant $C <\infty$ if for every continuously differentiable function $f: \ensuremath{\mathbb{R}}^m \rightarrow \ensuremath{\mathbb{R}}$ such that $\mathbb{E}^\theta[f^2] = 1$, we have
\begin{align*}
    \mathbb E^\theta[f^2 \log f^2] \leq C \mathbb E^{\theta}[|\nabla f|^2].
\end{align*}
We use ${C}_{LS}(\theta)$ to denote the best possible constant $C$.

[Lemma 12 of arXiv:2607.13273, 'Asymptotics of transition densities for L\'evy processes with stochastic resetting'] For all $b>a\geq0$ and $c>0$ we have
        \begin{equation}
        \liminf\limits_{\substack{t\to\infty,\,|y|\to\infty\\ t/|y|^{\alpha/2}<M}}
             \frac{\displaystyle\int_{at}^{bt}  e^{-m s} p(s,y) \dx[s]}{\displaystyle \int_0^{ct} e^{-m s} p(s,y) \dx[s]} =
            \liminf\limits_{\substack{t\to\infty,\,|y|\to\infty\\ t/|y|^{\alpha/2}<M}}\ 
            \frac{\displaystyle \int_{a\kappa(t,y)}^{b\kappa(t,y)}\eta(z,1) \dx[z]}
            {\displaystyle \int_{0}^{c\kappa(t,y)}  \eta(z,1) \dx[z]}  > 0.
        \end{equation}

