body:
[Theorem 6 of arXiv:2608.13358, 'Extreme points of sets of probability measures and $\phi$-divergences'] For an element $p \in \cM$, the following statements are equivalent.
    \begin{enumerate}
        \item $p$ is an extreme point of $\cM$.
        \item  There exists no $p' \in \cM\setminus \{p\}$ with $p'\ll p$ and $p$-a.s.\ bounded density $\frac{\mathrm{d}p'}{\mathrm{d}p}$.
        \item  For all $q\in \cM$ with $p\ll q$ and all $\eps\in (0,1)$, there exists no $p' \in \cM\setminus\{p\}$ with $p'\ll q$ and $q$-a.s.\ bounded density $\frac{\mathrm{d}p'}{\mathrm{d}q}$ and
        \begin{equation}
           (1+\eps) \frac{\mathrm{d}p}{\mathrm{d}q} -\eps\frac{\mathrm{d}p'}{\mathrm{d}q}\geq 0 \quad q\text{-a.s.}
        \end{equation}
        \item 
        For every $p'\in\cM\setminus\{p\}$, every $p'$-admissible dominating measure $q$ of $p$, every $\eps_0 \in (0,1]$ satisfying condition \ref{it:admissible:eps} in Definition~\ref{def:admissible}, and every continuous convex function $\varphi \colon [0,\infty)\to [0,\infty)$ with $\varphi(0)>0$ and $\varphi=0$ on $[a,\infty)$ for some $a\in(0,\eps_0)$, the point $\lambda = 1$ is a strict local maximizer of the map
        \begin{equation}
        [0,1] \to [0,\infty),\quad \lambda \mapsto \Div{\varphi}{\lambda p + (1-\lambda)p'}{q}.
        \end{equation}
    \end{enumerate}

[Lemma smash-module-internal-hom of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $({\mathcal{C}},X)$ be an idempotent in $\CAT_T^\textup{$S$-cc}$. Then ${\mathcal{D}}\in\CAT_T^\textup{$S$-cc}$ is a ${\mathcal{C}}$-module if and only if evaluation at $X$ defines an equivalence
    \begin{equation}
        \ev_X\colon\ul{\textup{Fun}}^\textup{$S$-cc}_T({\mathcal{C}},{\mathcal{D}})\xrightarrow{\;\smash{\raisebox{-0.25ex}{\ensuremath{\scriptstyle\sim}}}\;}{\mathcal{D}}.
    \end{equation}
    \begin{proof}
        By Remark~(rk:S-cc-closed of the paper), the symmetric monoidal structure on $\CAT_T^\textup{$S$-cc}$ afforded by the parametrized Lurie tensor product is closed, with internal homs given by $\ul{\textup{Fun}}^\textup{$S$-cc}$.
        Thus, the fully faithful functor $\textup{fgt}\colon\text{LMod}_{\mathcal{C}}(\CAT_T^\textup{$S$-cc})\to \CAT_T^\textup{$S$-cc}$ admits a right adjoint such that the counit is given for any ${\mathcal{D}}$ by the map $((eq:cofree-counit of the paper))$.
        The claim now follows since the essential image of any fully faithful left adjoint consists precisely of those objects for which the counit is invertible. 
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

