body:
[Lemma 75 (Relationship between $\gtorus$ and $\gnulltori$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] When restricted to the tangent space of $\doublenulltoritwoarg{\ubar}{u}$, we have the following identity for $\gnulltori$ relative to the double-null coordinates:
		\begin{equation} 
			\gnulltori = \gnulltori\left(\nullgeop{x^A},\nullgeop{x^B}\right) \mathrm{d} x^A \otimes \mathrm{d}x^B,
		\end{equation}
	where with $\gtorus_{AB} = \gtorus(\geop{x^A},\geop{x^B})$, 
	we have:
		\begin{align} 
			\gnulltori\left(\nullgeop{x^A},\nullgeop{x^B}\right) & = 
			\gtorus_{AB} 
			+   
			\frac{\geop{x^A}\ubar}{\geop{t} \ubar} \gtorus_{BC} \Lunit^C  
			+   
			\frac{\geop{x^B}\ubar}{\geop{t} \ubar} \gtorus_{AC} \Lunit^C 
			+ 
			\frac{(\geop{x^A} \ubar) \geop{x^B} \ubar}{(\geop{t} \ubar)^2} \gtorus_{CD} \Lunit^C \Lunit^D.
		\end{align}
	Moreover, relative to the double-null coordinates, the following identity holds:
		\begin{align} 
			\gnulltori^{-1} = \gnulltori^{-1}\left(\mathrm{d} x^A,\mathrm{d} x^B\right) \nullgeop{x^A}\otimes \nullgeop{x^B},
		\end{align}
	where: 
		\begin{align} 
			\gnulltori^{-1}\left(\mathrm{d} x^A,\mathrm{d} x^C \right)\gnulltori\left(\nullgeop{x^C},\nullgeop{x^B}\right) = \updelta_B^A,
		\end{align}
	and $\updelta_B^A$ is the Kronecker delta. 

	Next, let $\gtorusdoublenullCOV$ be the $2\times 2$ matrix with the following entries:
	\begin{equation}
		\gtorusdoublenullCOV^B_A \eqdef \updelta_A^B - \frac{\geop{x^A} \ubar}{\Lunit \ubar} \Lunit^B, 
	\end{equation}
	where $\updelta_A^B$ is the Kronecker delta. Then the following identity holds:
	\begin{equation}
		\geop{x^A} = \gtorusdoublenullCOV^B_A \nullgeop{x^B} + \frac{\geop{x^A} \ubar}{\Lunit \ubar} \Lunit. 
	\end{equation}
	Furthermore, 
	we have the following relationship between 
	$\gtorus_{AB}$	and 
	$
	\gnulltori\left(\nullgeop{x^A},\nullgeop{x^B} \right)
	$:
	\begin{subequations}
	\begin{align} 
		\gtorus_{AB}
		& 
		= \gtorusdoublenullCOV_A^C \gtorusdoublenullCOV_B^D \gnulltori\left(\nullgeop{x^C},\nullgeop{x^D} \right),
		\\
		(\gtorus^{-1})^{AB} 
		& 
		= (\gtorusdoublenullCOV^{-1})_C^A (\gtorusdoublenullCOV^{-1})_D^B \gnulltori^{-1}\left(\mathrm{d} x^C,\mathrm{d} x^D \right).

	\end{align}
	\end{subequations}
	In addition, the inverse $(\gtorusdoublenullCOV^{-1})_A^B$ of $\gtorusdoublenullCOV_B^A$, defined by
	$(\gtorusdoublenullCOV^{-1})_B^C \gtorusdoublenullCOV_C^A = \updelta_B^A$, can be expressed as follows:
	\begin{align} 
		(\gtorusdoublenullCOV^{-1})_A^B 
		& 
		= 
		\updelta_A^B 
		+ 
		\frac{\geop{x^A}\ubar}{\geop{t} \ubar} \Lunit^B.
	\end{align}
	Finally, we have the following identities:
	\begin{subequations}
		\begin{align}
			\gnulltori\left(\nullgeop{x^A},\nullgeop{x^B} \right) & = (\gtorusdoublenullCOV^{-1})_A^C (\gtorusdoublenullCOV^{-1})_B^D \gtorus_{CD},  \\
			 \gnulltori^{-1}\left(\mathrm{d} x^A,\mathrm{d} x^B \right) & = \gtorusdoublenullCOV_C^A \gtorusdoublenullCOV_D^B (\gtorus^{-1})^{CD}. 
		\end{align}
	\end{subequations}

[Proposition lem:rho-closed of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] Let $w\ge10$ and set
\[
  \lambda_w=\frac{14(w-1)}{36w-25}.
\]
Then $\ell=\mu(w)$ satisfies
\begin{equation}
  (1+\lambda_w^2)\ell^2-(5+\lambda_w)\ell+6-4w\le0.
\end{equation}
Relaxing $\lambda_w\ge\tfrac38$ in (equation eq:rho-sharp of the paper) gives
\begin{equation}
  73\ell^2-344\ell+384-256w\le0,
\end{equation}
and hence the closed form
\begin{equation}
  \mu(w)<\frac{15}{8}\sqrt w+\frac{12}{5}.
\end{equation}
Moreover (equation eq:rho-closed of the paper) holds for every $w\ge1$.

[Proposition 8 of arXiv:2608.04644, 'Khinchin's and Chung's Laws of the Iterated Logarithm at Time Zero for the Linear Stochast'] Recall that $H$ is defined in \eqref{def:H}. Suppose that  Condition \ref{hypo}  holds  and that $H<1$. Then there exists a constant
$c_{2,1}:=\max\left\{C_{1/2,1}, 2^{H+1}\textcolor{black}{\widetilde{\kappa}}\right\}>0$ such that, for all $t\ge s\ge0$ and $x\in\mathbb{R}^d$,
\begin{equation}
	\|u(t,x)-u(s,x)\|_{L^2(\Omega)}
	\le c_{2,1} |t-s|^H.
\end{equation}

