[Deff rv-vanish of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] For collections of random variables $\{X_t\},\{Y_t\}$ defined on the same probability space and $Y_t > 0$ a.s., we say $\{X_t\}$ vanishes over $\{Y_t\}$ if one of the following equivalent conditions hold:
    \begin{enumerate}
        \item $\forall \epsilon > 0, \exists M > 0$ such that almost surely $|X_t|\mathbbm{1}_{|X_t|>M} \leq \epsilon Y_t$ for all $t$.
        \item $\forall \epsilon > 0, \exists N > 0$ such that almost surely $|X_t| \leq N + \epsilon Y_t$ for all $t$.
    \end{enumerate}

[Lemma 10 of arXiv:2608.29984, 'On Cauchy Problems for Parabolic Equations with Rough Coefficients'] Let the multi-variable Fourier multiplier $\sigma(\xi,\eta)\in C^{\infty}(\R^{d}\times\R^{d}\setminus (0,0))$ satisfies
\begin{equation}
\begin{split}
&|\p_{\xi}^{\alpha}\p_{\eta}^{\beta}\sigma(\xi,\eta)|\lesssim_{\alpha,\beta}(|\xi|+|\eta|)^{-|\alpha|+|\beta|},\ \forall (\alpha,\beta),\ \forall (\xi,\eta)\neq (0,0);\\
&\sigma(\xi,0)\equiv 0.
\end{split}
\end{equation}
Define the bilinear Fourier integral operator
\begin{equation}
B_{\sigma}(f,g)(x):=\int_{\R^{2d}}e^{ix\cdot(\xi+\eta)}\sigma(\xi,\eta)\hat{f}(\xi)\hat{g}(\eta)d\xi d\eta,\ x\in\R^{d}.
\end{equation}
Then for all $1<p<\infty$, we have
\begin{equation}
\|B_{\sigma}(f,g)\|_{L^{p}(\R^{d})}\lesssim_{p,\sigma}\|f\|_{L^{p}(\R^{d})}\cdot [g]_{BMO(\R^{d})}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:matchingbord of arXiv:2601.20502, 'Optimal matching under size priority'] Let $(G,o,w)$ be a finite weighted graph with a unique optimal matching $M_{\mathrm{opt}}$. Let $H>0$ and assume that $G^H:=B_H(G,o)$ is a tree. 
    Define the decorated graph $(G^H,o, (i_M,Z_M))$ as follows:
    \begin{enumerate}
        \item Set $(i_M,Z_M)(u,v)=(0,0)$ if $v$ is on the boundary and not matched by $M_{\mathrm{opt}}$ to the exterior of $G^H$. In other words, $(i_M,Z_M)(u,v)=(0,0)$ if $d(v,o)=H+1$ and $(v,u') \notin M_{\mathrm{opt}}$ for $u' \sim v, u' \neq u$.
        \item Set $(i_M,Z_M)(u,v)=(1,+\infty)$  if $v$ is on the boundary and matched by $M_{\mathrm{opt}}$ to the exterior of $G^H$.
        \item Use Recursion~(equation eq:systemrecursionzoombis of the paper) to define $(i_M,Z_M)$ on the remainder of $(G^H,o)$.
    \end{enumerate}
    Then an edge $(u,v)\in G^H$ is in $M_{\mathrm{opt}}$ if and only if
     \begin{align*}
         (i_M,Z_M)(u,v)+(i_M,Z_M)(v,u)\overset{\lex}{<} (1,w(u,v)).
     \end{align*}

[Lem 21 of arXiv:2605.21638, 'Markov renewal theory for transfer operators and point processes on the line'] Let $N\in \N$, $L> N r_\mathrm{hc}$, and $(z_j)_{j\in \Z}\in \R_+^\Z$. Let $(x_j)_{j\in \Z}$ be the sequence defined by $x_0 =0$ and $x_j - x_{j-1} = z_j$. Define 
	$\Delta_{N,L} = \{(x'_1,\ldots,x'_{N})\colon\ 0 \leq x'_1 <\cdots < x'_N< L\}$. Then, assuming $x_{N+1} = z_1+\cdots + z_{N+1} =L$, we have 
	\begin{multline*}
		\widehat \pi_{N+1,L}(A \mid (z_j)_{j\in \Z} ) = \frac{1}{\mathrm{norm.}} \int_{\Delta_{N,L}} \1_A\bigl(x'_1,x'_2-x_1,\ldots,L-x'_{N}) \\
		\times \exp\Bigl( - H \Bigl( \delta_{x'_1}+\cdots + \delta_{x'_n} \Big| \sum_{j\in \Z\setminus \{1,\ldots, n\}} \delta_{x_j} \Bigr)\Bigr) \dd x'_1\cdots \dd x'_{N}. 
	\end{multline*}

[Theorem 9 of arXiv:2606.22940, 'From smooth to discontinuous kernels: a variance transfer principle for hyperuniform proce'] Let $ s\in (0,1),\beta >0.$
  \begin{itemize}
\item  Let $ \gamma \in (0,1],\varphi \in \F_{ \gamma }^{ *}$. Then there is $ C_{ \varphi }$ not depending on $ N,R$ such that
\begin{align*}
  \textrm{Var}\left(\X_{ N}^{ s,\beta }(\varphi _{ R})\right) \leqslant C_{ \varphi }V_{ 1-s,\gamma  }(R).
\end{align*}
\item Any  limit point $ \P^{ s,\beta }$ of $ \X_{ N}^{ s,\beta }$ is stationary and  $ (1-s)$-hyperuniform, hence for $ \gamma >0,\varphi \in \F_{ \gamma }$, 
\begin{align*}
  \textrm{Var}\left(\P^{ s,\beta }(\varphi _{ R})\right) = O(V_{ 1-s,\gamma }(R)).
\end{align*}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 31 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$, $\beta\geq 0$, and $n\geq 1$. Then, for every $e\in E(\Lambda_n)$, one has
\begin{equation}
	\phi^1_{\Lambda_{2n},\beta}[\omega_e]-\phi^0_{\Lambda_{2n},\beta}[\omega_e]\leq \big(\langle \sigma_0\rangle_{\Lambda_{n},\beta}^+\big)^2.
\end{equation}

