[Thm RL of arXiv:2411.03104, '{\bf Coupling Methods and Applications on Path Dependent McKean-Vlasov SDEs}\footnote{Supp'] Assume {\bf (A)}. Then there exists an increasing function $c:(0,\infty)\rightarrow[0,\infty)$ such that for positive $f\in\mathscr{B}_b(\mathbb R^d)$,
	\begin{equation*}\begin{split}
	&((P_t^\ast\mu_0)\circ \pi_0^{-1})(\log f) \\
&\leq\log \{((P_t^\ast\nu_0)\circ \pi_0^{-1})(f)\}+\frac{c(t)}{t}\mathbb W^{\mathscr C_\infty}_2(\mu_0,\nu_0)^2,\ \ t> 0,  \mu_0,\nu_0\in \mathscr P_{2}(\mathscr C_\infty).\end{split}\end{equation*}
Consequently, it holds
\begin{align*}
\|(P_t^\ast\mu_0)\circ \pi_0^{-1}-(P_t^\ast\nu_0)\circ \pi_0^{-1}\|_{var}^2&\leq2\mathrm{Ent}((P_t^\ast\mu_0)\circ \pi_0^{-1}|(P_t^\ast\nu_0)\circ \pi_0^{-1})\\
&\leq \frac{2c(t)}{t}\mathbb W^{\mathscr C_\infty}_{2}(\mu_0,\nu_0)^2,\ \ t>0,  \mu_0,\nu_0\in \mathscr P_{2}(\mathscr C_\infty).
\end{align*}

