[Definition 43 (Isonormal Gaussian process) of arXiv:2605.14630, '2605.14630'] Let $\H$ be a separable Hilbert space. 
A stochastic process $W = \setsuch{W(h)}{h\in\H}$ defined on a complete 
probability space $(\Omega,\cF,\fP)$ is an \emph{isonormal Gaussian process} 
if $W$ is a centred Gaussian family of random variables such that 
\begin{equation}
 \expec{W(h_1)W(h_2)} = \pscal{h_1}{h_2}_\H
\end{equation} 
for all $h_1, h_2\in\H$.

[Corollary 57 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] For every compact set $K \subseteq \bZ_T$, 
 \begin{equation}
    \lim_{n \to \infty} \sup_{s \in [0,T],\, \bX \in K} \lvert  M_s^{n,z}(\bX) - M_s^z(\bX) \rvert = 0.
  \end{equation}
Moreover, for every $\eta>0$, we have
   \begin{equation}
      \lim_{n \to \infty} \mathbb{P}_n \left( \left\{ \bX \in \bZ_T: 
      \sup_{s \in [0,T]} \lvert  M_s^{n,z}(\bX) - M_s^z(\bX) \rvert> \eta  \right\}\right)= 0.
     \end{equation}

