[Prop Prop_Universal_Slice of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Let
  $\mathbf{Sl} \subseteq \mathbf{Dir} \times \mathbf{Ram}$ be a slice and
  $({\mathbf{p}}_0,[{\mathfrak l}_0]) \in \mathbf{Sl}$.
  \begin{enumerate}
  \item

    For every $({\mathbf{p}},[{\mathfrak l}]) \in \mathbf{Sl}$ the identity maps induce tame isomorphisms
    \begin{align*}
      H_a^\infty\Gamma\paren{X{\backslash} \mathrm{Br}({\mathfrak l}_0),S\otimes{\mathfrak l}_0;{\mathbf{p}}_0}
      &\cong
        H_a^\infty\Gamma\paren{X{\backslash} \mathrm{Br}({\mathfrak l}),S\otimes{\mathfrak l};{\mathbf{p}}} = \mathbf{E}_{{\mathbf{p}},{\mathfrak l}}, \\

      H_b^\infty\Gamma\paren{X{\backslash} \mathrm{Br}({\mathfrak l}_0),S\otimes{\mathfrak l}_0;{\mathbf{p}}_0}
      &\cong
        H_b^\infty\Gamma\paren{X{\backslash} \mathrm{Br}({\mathfrak l}),S\otimes{\mathfrak l};{\mathbf{p}}} = \mathbf{F}_{{\mathbf{p}},{\mathfrak l}}, \quad\text{and} \\

      \Gamma\paren{\mathrm{Br}({\mathfrak l}_0),\check S_{{\mathbf{p}}_0}}
      &\cong
        \Gamma\paren{\mathrm{Br}({\mathfrak l}),\check S_{{\mathbf{p}}}} = \mathbf{G}_{{\mathbf{p}},{\mathfrak l}}.
    \end{align*}
  \item

    The maps
    \begin{align*}
      {\mathbf{D}}|_\mathbf{Sl} \mskip0.5mu\colon\thinspace \mathbf{Sl} \times H_a^\infty\Gamma\paren{X{\backslash} \mathrm{Br}({\mathfrak l}_0),S\otimes{\mathfrak l}_0;{\mathbf{p}}_0} &\to H_b^\infty\Gamma\paren{X{\backslash} \mathrm{Br}({\mathfrak l}_0),S\otimes{\mathfrak l}_0;{\mathbf{p}}_0} \quad\text{and} \\
      {\mathbf{res}}|_{\mathbf{Sl}} \mskip0.5mu\colon\thinspace \mathbf{Sl} \times H_a^\infty\Gamma\paren{X{\backslash} \mathrm{Br}({\mathfrak l}_0),S\otimes{\mathfrak l}_0;{\mathbf{p}}_0} &\to \Gamma\paren{ \mathrm{Br}({\mathfrak l}_0),\check S_{{\mathbf{p}}_0}}
    \end{align*}
    induced by ${\mathbf{D}}$ and $\mathbf{res}$ are tame smooth.
  \end{enumerate}

