[Proposition 4 of arXiv:2608.17449, 'Spectral Simplicity and Joint Eigenvalue Densities\\ for a Non-Gaussian Brownian Time Chan'] As defined above, $\Omega_{\rm can}$ and $M_b$ satisfy
\begin{equation*}
 \Prob(\Omega_{\rm can})=1.
\end{equation*}
The map
\begin{equation*}
 b\longmapsto M_b:
 (\Omega,\Borel(\Omega))
 \longrightarrow
 \bigl(\mathcal M^+_{\rm fin}(D),\Borel(\mathcal M^+_{\rm fin}(D))\bigr)
\end{equation*}
is measurable, and
\begin{equation*}
 M_{n,b}\Longrightarrow M_b,\qquad b\in\Omega_{\rm can}.
\end{equation*}
Moreover, for every $g\in C(\overline D)$,
\begin{equation}
 \int_Dg\,dM_{n,b}\longrightarrow\int_Dg\,dM_b
 \quad\text{almost surely and in }L^2(\Prob),

\end{equation}
and
\begin{equation}
 \Ex\int_Dg\,dM_b=\int_Dg(x)\,dx.

\end{equation}

