body:
[Proposition prop:ritz of arXiv:2608.30888, 'Three-term asymptotics for discrete\\ Hardy--Rellich constants in high dimension'] For every fixed $\ell\geq1$,
\begin{equation}
 \mu_{\ell,N}
 =2^\ell N^\ell+\gamma_\ell N^{\ell-1}
  +O_\ell(N^{\ell-2}),
\end{equation}
where
\begin{equation}
 \gamma_\ell
 =3\ell(\ell-1)2^{\ell-2}
  -\frac{\ell^2 2^{2\ell}}{2^\ell-1}.
\end{equation}
In particular,
\[
 \gamma_1=-4,\qquad
 \gamma_2=-\frac{46}{3},\qquad
 \gamma_3=-\frac{324}{7},\qquad
 \gamma_4=-\frac{1936}{15}.
\]
The variational principle therefore gives the upper bound
\begin{equation}
 C_\ell(N)\leq
 2^\ell N^\ell+\gamma_\ell N^{\ell-1}+O_\ell(N^{\ell-2}).
\end{equation}

