[Lemma lem:zeros_disc of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] Let~$\operatorname{Disc}_w(P)$ be the discriminant of the polynomial~$P$ in the variable~$w$, and let~$p(z)=z^{2\ell}\operatorname{Disc}_w(P)$. Then
\begin{equation}
p(z)=\left((z-1)^\ell \Tr \Phi(z)\right)^2-4(z-1)^{2\ell}.
\end{equation}
The function~$p$ is a degree~$2\ell-1$ polynomial with zeros
\begin{equation}
0=z_0>z_1\geq z_2>z_3\geq z_4>\dots >z_{2\ell-3}\geq z_{2\ell-2}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:maintheorem of arXiv:2608.11603, 'Continuous-time directed polymers to the Critical SHF via moments'] {}
	There exists $\theta_{\star} \in \mathbb{R}$ such that the  semigroup defined in equation~(equation eqn:predeltabosegas_semigroup of the paper) converges strongly to the semigroup generated by the Hamiltonian in equation~(equation eqn:deltabosegas_semigroup of the paper). That is, for all $f \in \mathcal{L}^{2}(\mathbb{R}^{2[\![n]\!]})$, $\norm{\mathcal{Q}_{\varepsilon}^{[\![n]\!], \theta}(t)f - \mathcal{Q}^{[\![n]\!], \theta_{\star}}(t)f } \to 0$ as $\varepsilon \to 0$. The constant $\theta_{\star}$ is explicitly given by:
	\begin{align*}
		\theta_{\star}
		= 2\theta + \frac{1}{\pi}\int_{\mathbb{R}^2} \int_{\mathbb{R}^2} \int_{\widehat{\mathbb{T}}^{2}} &\kappa(y_{\operatorname{r}}) \Bigg[\frac{e^{\operatorname{i} \eta_{\operatorname{r}} \cdot (\floor{y_{\operatorname{r}}} - \floor{y'_{\operatorname{r}}}) } -1} {	\F{\mathcal{L}}_{1,n}(\widetilde{\eta}_{0 \alpha})} \Bigg] \kappa(y'_{\operatorname{r}}) \, \mathrm{d} \eta_{\operatorname{r}} \, \mathrm{d} y_{\operatorname{r}} \, \mathrm{d} y'_{\operatorname{r}} \\  
		& +  \frac{1}{\pi}\int_{\widehat{\mathbb{T}}^{2}} \Bigg[\frac{1}{	\F{\mathcal{L}}_{1,n}(\widetilde{\eta}_{0 \alpha})} - \frac{1}{\norm{\eta_{\operatorname{r}}}^2}\Bigg] \, \mathrm{d}\eta_{\operatorname{r}} +\frac{\log 2}{2\pi} - \frac{G}{\pi^2} + 2\log\pi \,  ,
	\end{align*}
where $G=0.915965\ldots$ is the Catalan's constant and
\begin{equation*}
  	\F{\mathcal{L}}_{1,n}(\widetilde{\eta}_{0 \alpha})  \coloneqq 4 \sum_{m_1 \in \mathbb{Z}^2} \sin^{2}\Big(\frac{\eta_{\operatorname{r}} \cdot m_1}{2} \Big) \nu(m_1) \, .
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

