[Thm 7 of arXiv:2605.05430, 'Dirichlet problems and exit distributions for the telegraph process and its planar extensi'] For all $x\in\mathbb{R},\;y\in[0,L]$, it holds that
\begin{equation}h_1(x,y)=\frac{\lambda\;y\,(L-y)}{c^2}+\frac{2\,(L-y)}{c}\end{equation}
and
\begin{equation}h_3(x,y)=\frac{\lambda\;y\,(L-y)}{c^2}+\frac{2y}{c}.\end{equation}
Consequently, we have that
\begin{equation}h_0(x,y)=h_2(x,y)=\frac{\lambda\;y\,(L-y)}{c^2}+\frac{\lambda L +c}{\lambda\,c}\end{equation}
and \begin{equation}h(x,y)=\frac{\lambda\;y\,(L-y)}{c^2}+\frac{2\lambda L +c}{2\lambda\,c}.\end{equation}

[Cor w1-w2-p-in-dme of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] For all $p,C > 0$ we have $W_1^{p/2} + CW_2^p \in \tilde{\mathcal{D}}^{ext}_+(\mathcal{M})$ and the following hold with $x = (rv, z)$:
\begin{multline*}
\begin{aligned}
    \mathcal{L} (W_1^{p/2} + CW_2^p) &= \frac{p}{2}W_1^{p/2 - 1}\mathcal{L} W_1 + \frac{p}{4}(p/2-1)W_1^{p/2-2}\Gamma W_1 \\ 
    &\qquad + pCW_2^{p-1}\mathcal{L} W_2 + \frac{p}{2}(p-1)CW_2^{p-2}\Gamma W_2 
\end{aligned}
    \\
\begin{aligned}
    &= \frac{p}{2^{p/2}}(2 + \|x\|_{\beta,2}^2)^{p/2-1}\Big(-\|x\|_{\beta+1/2,2}^2 +\ip{x}{F(x)}_\beta + \frac{1}{2}\|G(x)\|_{\beta,2}^2\Big) \\
    &\qquad + \frac{p}{2^{p/2}}(p/2-1)(2+\|x\|_{\beta,2}^2)^{p/2-2}\|G(x)^*x\|_\mathcal{U}^2 \\
    &\qquad + pC(1+\|x\|_{L^1})^{p-1}\Big(\ip{x}{\tilde e} + \ip{F(x)}{1}\Big) \\    
    &\qquad + \frac{p}{2}(p-1)C(1+\|x\|_{L^1})^{p-2}\|G(x)^*1\|_\mathcal{U}^2 
\end{aligned}
\end{multline*}
and
\begin{multline*}
    \Gamma(W_1^{p/2} + CW_2^p) \lesssim (p/2)^2W_1^{p-2}\Gamma W_1 + p^2C^2W_2^{2p-2}\Gamma W_2 \\
    = \frac{p^2}{2^p}(2+\|x\|_{\beta,2}^2)^{p-2}\|G(x)^*x\|_\mathcal{U}^2 + p^2C^2(1+\|x\|_{L^1})^{2p-2}\|G(x)^*1\|_\mathcal{U}^2  \,.
\end{multline*}

[Lemma 9 (Positive zero of the signed generator) of arXiv:2606.22066, 'A Bessel-zero obstruction to hyperbolic complete monotonicity of noncentral chi-square den'] Let \(a,b,\theta>0\).  Then the entire function
\begin{equation}
t\mapsto e^{bt}{}_0F_1(;a;-b\theta t)
\end{equation}
has a positive real zero.

