[Lemma lem:kesten-gambler of arXiv:2411.10113, 'Long-range one-dimensional\\ internal diffusion-limited aggregation'] Suppose that~(equation ass:irreducible of the paper) holds.
 \begin{thmenumi}[label=(\roman*)]
\item Suppose that $\Exp ( X^2 ) < \infty$ and $\Exp X =0$. Then,
for every $c \in {\mathbb R}_+$,
 \begin{equation}

     \lim_{N \to \infty} \bP_0 \bigl( S_{\eta_{[-cN, N]}} > N \bigr) 
     = \frac{c}{1+c} .
 \end{equation}
\item Suppose that~(equation ass:stable-alpha of the paper) holds with $\alpha \in (1,2)$.
Then, for every $c \in {\mathbb R}_+$,
 \begin{equation}

     \lim_{N \to \infty} \bP_0 \bigl( S_{\eta_{[-cN, N]}} > N \bigr) 
     = \frac{\Gamma(\alpha)}{\Gamma (\alpha/2)^2} \int_{(1+c)^{-1}}^1 u^{\frac{\alpha}{2}-1} (1-u)^{\frac{\alpha}{2}-1} {\mathrm d} u .
 \end{equation}
  \end{thmenumi} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Brailovskaya--van Handel comparison estimates) of arXiv:2608.04824, 'Strong Convergence for a General Class of Random Matrix Models'] With \(H\) and \(G\) as above, the following statements hold.  For
\(t\geq0\),
\begin{equation}
 \mathbb P\left\{
 d_{\rm H}(\spn(H),\spn(G))>C\varepsilon_H(t)
 \right\}\leq D e^{-t},
\end{equation}
where
\begin{equation}
 \varepsilon_H(t)
 =\sigma_*(H)t^{1/2}
  +R(H)^{1/3}\sigma(H)^{2/3}t^{2/3}
  +R(H)t.
\end{equation}
Here \(d_{\rm H}\) is Hausdorff distance.  For every fixed \(r\geq1\),
Theorem~2.9 with its parameter \(q=\infty\) gives
\begin{equation}
 \left|
  \bigl(\E\trn_D H^{2r}\bigr)^{1/(2r)}
  -\bigl(\E\trn_D G^{2r}\bigr)^{1/(2r)}
 \right|
 \leq C_r\bigl(R(H)^{1/3}\sigma(H)^{2/3}+R(H)\bigr).
\end{equation}
Finally, for \(t\geq r\),
\begin{align}
& \mathbb P\bigg\{
 \left|(\trn_D H^{2r})^{ \frac{1}{2r}}
       -\bigl(\E[\trn_D H^{2r}]\bigr)^{ \frac{1}{2r}}\right|
 \notag 
 >C\left(\sigma_*(H)
       +R(H)^{1/2}\bigl(\E[\trn_DH^{2r}]\bigr)^{ \frac{1}{4r}}\right)t^{\frac{1}{2}}
       +CR(H)t\bigg\} \\
 & \leq 2e^{-t}.

\end{align}
The constants in \eqref{eq:bvh-spectrum} and
\eqref{eq:bvh-concentration} are universal, while \(C_r\) may depend on \(r\).
These are Theorems~2.6 and~2.9, with \(q=\infty\), and Lemma~9.20
of~\cite{brailovskaya-van-handel-2024}, written with normalized traces. (Proof in the paper; no proof environment follows the statement in the TeX.)

