[Lem 39 of arXiv:2608.28148, 'Flows and homotopies of Banach Lie algebroids'] Let $\mathfrak{u}\colon [0,1]\times U\to A$ be a $C^{k,\infty}$-time-dependent local section, $k\geq 1$, and assume that the evolution $\mathfrak{F}_\mathfrak{u}^{t,s}$ of the time-dependent complete lifts $\mathcal{X}_{\mathfrak{u}_t}$ is defined on the relevant domains for all $s,t\in[0,1]$.

Then the following assertions hold for the push-forward of sections. 
\begin{enumerate} 
\item For every local section $w$, the time-dependent section $Y_t:=(\mathfrak{F}_\mathfrak{u}^{t,s})_*w$ is for every $x$ for which the flows are defined the unique solution of 
\begin{align}
\frac{\partial Y_t}{\partial t}(x) = \LB[Y_t,\mathfrak{u}_t]_A(x), \qquad Y_s(x)=w(x).
\end{align}
\item Let $f\colon [0,1]\times U\to A$ be a $C^{k,\infty}$-time-dependent local section. Define pointwise 
$v_t(y) := \int_0^t \mathfrak{F}^{t,r}_{\mathfrak{u},\varphi_{r,t}(y)} \left( f_r(\varphi_{r,t}(y)) \right)\,dr$ whenever all the terms are defined. For fixed $t,y$, the integral is the Bochner integral\footnote{cf. \cite[Sections 23-25]{Sche97} for the definition and basic properties used in the following.} in the Banach fibre $A_y$. Then $v$ is the unique $C^{k,\infty}$-solution of 
\begin{align}
\frac{\partial v_t}{\partial t} - f_t = \LB[v_t,\mathfrak{u}_t]_A, \qquad v_0=0.
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma proj-formula-underived of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $\alpha\colon G\to G'$ be a homomorphism of compact Lie groups, and let $X\in\cat{$\bm G$-$\textbf{\textup{L}}$-Top}$, $Y\in\cat{$\bm{G'}$-$\textbf{\textup{L}}$-Top}$. Then the map
    \begin{equation}
        (\alpha_!\textup{pr}_1, \varepsilon\circ \alpha_!\textup{pr}_2)\colon \alpha_!(X\times \alpha^*Y)\to \alpha_!X\times Y
    \end{equation}
    is an isomorphism in $\cat{$\bm{G'}$-$\textbf{\textup{L}}$-Top}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm G-global-as-slice of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $\alpha\colon G\to G'$ be a homomorphism of compact Lie groups and let $B\in\cat{$\bm G$-$\textbf{\textup{L}}$-Top}$ cofibrant. Then 
    \begin{equation}
        \alpha_!\colon\cat{$\bm G$-$\textbf{\textup{L}}$-Top}_{/B}\to \cat{$\bm{G'}$-$\textbf{\textup{L}}$-Top}_{/\alpha_!B}
    \end{equation}
    is the left adjoint in a Quillen equivalence (for the usual slice model structures). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Zconstruction of arXiv:2601.20502, 'Optimal matching under size priority'] Let $\mathbb{T}$ be a unimodular decorated BGW tree with reproduction law $\pi$ and edge weight law $\omega$. Let $\mathcal{H}$ be a solution to the system given by System~(equation eq:systemzoomh0singular of the paper) with input $\pi$ and $\omega$.
    \begin{enumerate}[label=\roman*)]
        \item There exists a random decorated tree $(\mathbb{T}',((i_{\mathcal{H}},Z_{\mathcal{H}})(u,v))_{(u,v) \in \overset{\rightarrow}{E}})$ such that the marginal law of each $(i_{\mathcal{H}},Z_{\mathcal{H}})(u,v)$ is $\zeta'_{\mathcal{H}}$, the marginal law of $\mathbb{T}'$ is the law of $\mathbb{T}$ and such that for any $(u,v) \in \overset{\rightarrow}{E}$:
        \begin{equation}
    \begin{aligned}
        (i_{\mathcal{H}},Z_{\mathcal{H}})(u,v)=\maxlex\left( (0,0) , \maxlex_{\substack{ u' \sim v \\ u' \neq u}}\left( (k,w(v,u'))-(i_{\mathcal{H}},Z_{\mathcal{H}})(v,u') \right) \right).
    \end{aligned}
\end{equation}
        \item The rule
        \begin{align}
            (u,v) \in \mathbb{M}_{\mathcal{H}} \Leftrightarrow (i_{\mathcal{H}},Z_{\mathcal{H}})(u,v)+(i_{\mathcal{H}},Z_{\mathcal{H}})(v,u)\overset{\lex}{<} (k,w(u,v)) 
        \end{align}
        defines a matching on $\mathbb{T}$. This rule is equivalent to the following vertex rule:
        $u$ is matched if and only if there exists $v\sim u$ such that
\begin{equation}
        \vphantom{\underset{v' \sim u}{\overset{\lex}{\argmax}}}
        (k,w(u,v))-(i_{\mathcal{H}},Z_{\mathcal{H}})(u,v) \overset{\lex}{>} (0,0),
\end{equation}
in which case $u$ is matched to the vertex $v$ defined by
\begin{equation}
        v=\underset{v' \sim u}{\overset{\lex}{\argmax}} \left( (k,w(u,v'))-(i_{\mathcal{H}},Z_{\mathcal{H}})(u,v') \right).
\end{equation}

        \item The random decorated tree $(\mathbb{T}', (i_{\mathcal{H}},Z_{\mathcal{H}})_{(u,v) \in \overset{\rightarrow}{E}})$ viewed as $\mathbb{T}'$ with an additional decoration is unimodular.
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:1 of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] There exist constants $0<C_2(k)<1$ and $R_0(k)>0$ such that for all $R>R_0$ and $x,x_i\in\mathbb{R}^3$,
\begin{equation}
    \mathbb{P}_{\vec{x}}\times\mathbf{P}_{x}\Big(W[0,\tau_{\partial B(x,R)}]\subseteq \sausage{\mathcal{W}}{2}\Big)\leq C_2^{\sqrt R}.
\end{equation}

