body:
[Lem mostlytrans of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $\mathcal{G}$, $\mathcal{G}'$ be two mostly-transverse $C^0$-foliations on $\mathbb{T}^2$. Then, for every $\varepsilon>0$, there exist $C^0$-foliations $\widetilde{\mathcal{G}}$ and $\widetilde{\mathcal{G}}'$ such that
    \begin{itemize}
        \item $\widetilde{\mathcal{G}}$ and $\widetilde{\mathcal{G}}'$ are isotopic, via an $\varepsilon$-$C^{0}$-small isotopy, to $\mathcal{G}$ and $\mathcal{G}'$, respectively,
        \item $\widetilde{\mathcal{G}}$ is positively transverse to $\widetilde{\mathcal{G}}'$ everywhere.
    \end{itemize}

[Lemma 13 of arXiv:2609.02808, 'Minimizers of Laplace eigenvalues under a lower curvature bound'] On $(\Sph^2,\round)$, indexed with multiplicity,
\begin{equation}
\la_k(\Sph^2)=\ell(\ell+1)\qquad\text{if and only if}\qquad \ell^2\le k\le(\ell+1)^2-1,
\end{equation}
for each integer $\ell\ge0$. In particular the value $\ell(\ell+1)$ first occurs at the
index $k=\ell^2$, and occurs with multiplicity $2\ell+1$.

[Prop p:GZ-uniform-TF of arXiv:2607.18194, 'Temperature chaos in directed polymers'] {GZ22}}]
    Given $L\geqslant 1$, there exists a random constant $\mathfrak{C}_{(p:GZ-uniform-TF of the paper)}>0$ such that the following is true.
    First, we have 
    \begin{align*}
        \mathbb{P}(\mathfrak{C}_{(p:GZ-uniform-TF of the paper)} > m) \leqslant Ce^{-cm^{2}}
        \qquad\text{for all $m\geqslant 0$,}
    \end{align*}
    where $C,c>0$ are constants depending only on $L$.
    Second, for any $(s,x;t,y)\in\mathbb{R}^{4}_{\uparrow}\cap[-L,L]^4$, the geodesic $\Pi_{(s,x),(t,y)}$ satisfies
    \begin{align*}
        \sup_{r\in[s,t]}
        \left|
            \Pi_{(s,x),(t,y)}(r) - \frac{x(t-r) + y(r-s)}{t-s}
        \right|
        \leqslant \mathfrak{C}_{(p:GZ-uniform-TF of the paper)} \,
        (t-s)^{2/3} \log^3\left(2 \vee \frac{1}{t-s}\right).
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 39 (Scaling law for Nesterov) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] \normalfont
Assume \(\eta<1\) and \(k\gtrsim\max(\eta^{-1}_\rho,(1-\rho)^{-1})\). Then
\begin{equation}

\mathbb E[\cE(\btheta_k)]\eqsim
\begin{cases}
(\eta_\rho k)^{-s}+\dfrac{\sigma^2}{B}\eta_\rho, & 1-\rho\gtrsim\sqrt{\eta},\\[2mm]
N(k)+(\eta_\rho k)^{-s}+\dfrac{\sigma^2}{B}\min\{\eta_\rho,\eta_\rho^{1/\beta}\}, & \dfrac{\eta}{B^\beta}\lesssim1-\rho\lesssim\sqrt{\eta},
\end{cases}
\end{equation}
where \(N(k)\) denotes the underdamped transient and satisfies \(0\leq N(k)\lesssim\min\{1,(\eta k)^{-s}\}\rho^k\). If \(1-\rho\lesssim\eta/B^\beta\), the dynamics are not risk stable. (Proof in the paper; no proof environment follows the statement in the TeX.)

