[Lemma lem:revprelim of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Suppose $\mathbf{x} \in \mathrm{Meso}(N)$, where $N = \omega(\sqrt{n})$. Let $\varepsilon \in (0,1]$ and $\beta \in (0,1/2)$. Further, suppose that $n\gamma_n^+ \geqslant g(n)$, where $g(n) = \Omega(n^\alpha)$ for some $\alpha > 0$. Then the following hold.
    \begin{enumerate}[label=(\alph*)]
        \item Suppose that $N/g(n)^{1/2-\beta} = \omega(\sqrt{n})$. Then we have
        \begin{equation*}
            \lim_{n \to \infty} \Ps{\mathbf{x}}{X_{t_n} \in \Meso{N/g(n)^{1/2-\beta}}} = 1,
        \end{equation*}
        where $t_n = mn / \gamma_n^+ (\log(g(n)^{1/2-\beta}) + \theta)$ steps, where $\theta = \log (2dm)$.
        \item Suppose that $N/g(n)^{1/2-\beta} = O(\sqrt{n})$. Then, for all $n$ large enough, we have
        \begin{equation*}
            \Ps{\mathbf{x}}{X_{t_n} \in \mathrm{Centre}(C)} \geqslant 1 - 3\varepsilon/4,
        \end{equation*}
        where $t_n = mn / \gamma_n^+ (\log(N/\sqrt{n}) + \theta)$ steps, $C = 1 + 4dm\sqrt{2\log(\frac{4dm}{\varepsilon})}$, and $\theta = \log (2dm)$.
    \end{enumerate}

