body:
[Theorem th:d3 of arXiv:2411.13505, 'Capacity of loop-erased random walk'] Let $d=3$. Then
\begin{equation}
    \lim_{n\rightarrow\infty}\frac{\Ca_{\mathbb{Z}^3}(\eta[0,n])}{3n^{1/\beta}}=\C_{\mathbb{R}^3}(\gamma[0,1])
\end{equation}
in distribution. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:splitting of arXiv:2608.30888, 'Three-term asymptotics for discrete\\ Hardy--Rellich constants in high dimension'] The energy-dependent effective Hamiltonian on $\mathcal E_N$, at energies
$(2N)^\ell+O(N^{\ell-1})$, is
\begin{align}
 (2N)^\ell I
 +(2N)^{\ell-2}
 \bigg[&\binom\ell2(\mathcal J_N+\mathcal B_N)
 \nonumber\\[-1mm]
 &-\frac{\ell^2 2^\ell}{2^\ell-1}\mathcal B_N\bigg]
 +O_\ell(N^{\ell-3/2}).
\end{align}
More precisely, for each fixed $C>0$ the remainder is uniform for all real
$z$ satisfying $|z-\Lambda_N|\leq C N^{\ell-1}$.
Hence the trivial component has correction $\gamma_\ell N^{\ell-1}$, while both
non-trivial components have the common leading correction
\begin{equation}
 \gamma_\ell^\perp
 =\ell(\ell-1)2^{\ell-2}
 -\frac{\ell^2 2^{2\ell-1}}{2^\ell-1}.
\end{equation}
Moreover,
\begin{equation}
 \gamma_\ell^\perp-\gamma_\ell
 =\ell2^{\ell-1}
 \left(1+\frac{\ell}{2^\ell-1}\right)>0.
\end{equation}
The spectral equation has a unique root in each of the three first-shell
components.  The invariant root is simple, while the roots associated with
$\mathcal E_N^{\mathrm{ev},0}$ and $\mathcal E_N^{\mathrm{odd}}$ have multiplicities
$N-1$ and $N$, respectively.  These roots satisfy
\begin{align}
 z_{\mathrm{triv},N}
 &=\Lambda_N+\gamma_\ell N^{\ell-1}
 +O_\ell(N^{\ell-3/2}),\\
 z_{\mathrm{ev},N},\ z_{\mathrm{odd},N}
 &=\Lambda_N+\gamma_\ell^\perp N^{\ell-1}
 +O_\ell(N^{\ell-3/2}).
\end{align}
Thus the bottom of the first-shell cluster lies in the hyperoctahedrally
invariant sector and is simple for all sufficiently large $N$.

[Lemma 44 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] On every homogeneous component on which the indicated reciprocal operators
are defined,
\begin{equation}
 \mathcal R_{M,r+1}\,\mathscr K_i^{(z)}\,\mathcal R_{M,r}
 =1-(x_i+z)\partial_i,
\end{equation}
and consequently
\begin{equation}
 \omega\bigl(1-(x_i+z)\partial_i\bigr)\omega
 =\Pi_{n-i}^{(z)}.
\end{equation}

[Theorem 8 of arXiv:2606.11142, 'Strong invariance principles for diffusions, Markov chains and their perturbations.'] (Theorem 1.3 from \cite{KozhinaThesis}). Fix $T > 0$ and let us define a time-grid $\mathbb{T}_N := \{t_i\}_{i=1}^N$ for $N \in \mathbb{N}$. Under assumptions A1, A2, AD3 there exist constants $C \ge 1$ and $c \in (0, 1]$ such that for all $0 < t_i < t_j \le T$ and all $((x, y), (x', y')) \in (\mathbb{R}^{2d})^2$:
\begin{equation*}
|(p^\epsilon_h - p_h)(t_i, t_j, (x, y), (x', y'))| \le C \bar{\Delta}_{\epsilon,\gamma,q} \, p_{c,K}(t_j - t_i, (x, y), (x', y')),
\end{equation*}
where $p_{\epsilon,h}$ and $p_h$ stand for the transition densities of the perturbed and original Euler schemes respectively, starting from $(x, y)$ at time $t_i$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:profile-sharp-subg of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[definition]{def:profile-sharp-subg}
We say that the random field satisfies \(({\rm PSG})_p\) if, for every
\(N\), \(x\in\mathbb S^{N-1}(1)\), and \(s\in\mathbb R\),
\begin{equation}
 \mathbb E e^{s h_N^J(x)}\le e^{s^2/(2N)}.
\end{equation}
This rank-one/profile-direction bound is a convenient finite-\(N\)
sufficient condition for the weaker tail-rate input below.

