body:
[Corollary 17 of arXiv:2608.13687, 'Multiplicative chaos from random multiplicative functions'] Let $(A_p)_p$ be as in Case \caseS or Case \caseR, and fix a collection of scalars $(c_p)_p \subset \C$ in Case \caseS or $(c_p)_p \subset \R$ in Case \caseR satisfying
\begin{align}
    \sum_{n\in\N} \Big( \sum_{p\in I_n} |c_p|^2\Big)^{1/2} <\infty\,.
\end{align}
Fix $j\geq 1$.  Then the series 
\[
    F_{N,\ep}(x) \coloneqq \sum_{p \leq N} \frac{c_p}{p^{j\ep}}  A_p p^{-ijx}
\]
satisfies
\begin{align}
    \E \exp \, (\lambda \sup_{N,\ep \geq 0 } \|F_{N,\ep}\|_\infty)<\infty
\end{align}
for all $\lambda \geq 0$. Additionally, $F_{N,\ep}$
converges uniformly over $\cI$ almost surely as $\min(N,1/\ep)\to\infty$.

[Lemma 25 (High-probability row alignment) of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Let $\X \in \R^{m\times n}$ be a random matrix with independent, non-negative entries. Assume there exists $\lambda_{\min} > 0$ such that $\E[\X_{ij}] = \bLambda_{ij} \ge \lambda_{\min}$ for all $i, j$. Suppose the entries have uniformly bounded sub-exponential norms, $\max_{i,j} \|\X_{ij}\|_{\psi_1} \le K_\psi$ (here $K_\psi$ denotes the Orlicz-$\psi_1$ scale of the entries, not the bounded-cost parameter $K$ of Assumption \ref{assump:bounded_cost}). Define the overlap threshold parameter $a = \frac{1}{2}\lambda_{\min}^2$. Then there exists an absolute constant $c > 0$ such that the row alignment condition holds uniformly for all pairs of rows (including $i_1 = i_2$) with probability at least:
	\begin{align}
		\P\left( \forall i_1, i_2 \in [m],\ \sum_{j=1}^n \X_{i_1 j}\X_{i_2 j} \ge a n \right) \ge 1 - m^2 \exp\left( - c \min\left( n \frac{\lambda_{\min}^4}{K_\psi^4}, \sqrt{n} \frac{\lambda_{\min}}{K_\psi} \right) \right).
	\end{align}

[Definition eq:defncLmet of arXiv:2604.10020, 'The directed landscape in half-space'] Fix $\rho\in\mathbb{R} \cup \{-\infty\}$. For a  continuous path $\pi:[s,t]\to \mathbb{R}_{\ge 0}$, its \emph{length in $\mathcal{L}^\rho$} is
		\begin{equation}  
	\|\pi\|_{\mathcal{L}^\rho}=\inf_{k\in \mathbb{N}} \inf_{s=t_0<t_1<\cdots < t_k=t} \sum_{i=1}^k \mathcal{L}^\rho(\pi(t_{i-1}), t_{i-1}; \pi(t_i), t_i).
		\end{equation}
		A path $\pi$ is a \emph{geodesic} from $(\pi(s), s)$ to $(\pi(t), t)$ if $\|\pi\|_{\mathcal{L}^\rho} = \mathcal{L}^\rho(\pi(s),s; \pi(t),t)$.

[Theostar theotauberian of arXiv:2605.06488, 'Continuous-state branching processes with L\'evy-Khintchine drift-interaction: Laplace dua'] \
\begin{enumerate}
\item \textbf{Tauberian theorem}: Let $\ell:(0,\infty)\to (0,\infty)$ be slowly varying at $0$ (respectively, at $\infty$) and $\alpha\in[0,\infty)$ and $U$ be a locally finite measure on $[0,\infty)$. One has
\begin{align*}\int_0^{\infty}e^{-xz}U(\mathrm{d} z) \sim x^{-\alpha}\ell(1/x), \ &(x\rightarrow \infty, \text{ resp. } 0)\\ &\Longleftrightarrow
\int_0^{z}U(\mathrm{d} v)\sim z^{\alpha}\ell(z)/\Gamma(1+\alpha), \ (z\rightarrow 0, \text{resp. } \infty).
\end{align*}
\item \textbf{Monotone density theorem}: Suppose that $U(\mathrm{d} z)=u(z)\mathrm{d} z$, where $u:(0,\infty)\to (0,\infty)$ is monotone on some neighbourhood of $0+$ (respectively of $\infty$). If there exists $\alpha>0$ and a function $\ell$ slowly varying at $0$ (respectively, at $\infty$) such that 
\[ \int_0^zu(v)\mathrm{d} v\sim z^{\alpha}\ell(z) \ (z\rightarrow 0, \text{resp. }\infty), \text{ then }
u(z)\sim \alpha z^{\alpha-1}\ell(z) \ (z\rightarrow 0, \text{resp. }\infty).\]
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

