[Thm 16 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] Assume that conditions \ref{H0}, \ref{H0.5}, \ref{H1}, \ref{H2b}, \ref{H3} and 
    \begin{equation*}
\beta+\delta<\frac12\min\{\alpha,1-\alpha\}
\end{equation*}
hold true. Then, weak uniqueness in the sense of Definition \ref{uniqueness} holds for \eqref{abstract_formulation}.

[Prop Sgn-irred of arXiv:2609.00672, 'Deciding superellipticity and computing the Weierstrass normal form'] Let $g\ge 2$ and $n\ge 2$ with $\mathcal S_{g,n}\ne\emptyset$, and put $m=m(g,n)$. Then

\begin{equation}
\mathcal S_{g,n}=\mathcal M(g,C_n,\mathbf C_{g,n}),
\end{equation}

and $\mathcal S_{g,n}$ is irreducible of dimension

\begin{equation}
\dim\mathcal S_{g,n}=
\begin{cases}
m-3, & n\mid m,\\
m-2, & n\nmid m.
\end{cases}
\end{equation}

[Definition eqn-HR_VR of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Let $B_R$ be the open ball in $\mathbb{R}^d$ centered at $0$ with radius $R>0$. We define the following spaces
\begin{equation}  
H_R \coloneqq \{ u \in H: \supp u \subset B_R  \}
 \qquad V_R \coloneqq V \cap   H_R,
\end{equation}
with the inner products and norms inherited respectively from the spaces $H$ and $V$.

[Corollary prop:9 of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] In the scaling limit $n\to\infty$, $n\tau=t>0$,
\begin{align}
\lim_{n\to\infty} {\operatorname{\mathbf{E}}}_{U(n)} \big\{(1+x)^{N_{n, {t}/{n}}(q)}\big\} = \sum_{k=0}^{\infty}  \,
\frac{q^{\binom k 2}\, e^{t\left(1-\frac{1}{q^{k}}\right)}     }{(q;q)_k }\,   x^k, \quad \quad q\in (0,1).
\end{align}

