\begin{align*}
 \sup_{x\in [0,1]} |P_t f(x)| \leq \sup_{x\in [0,1]}\left(\int_{0}^{1} p_{t}(x,y)^{p^{\prime}} dy \right)^{\frac{1}{p^{\prime}}} \left( \int_{0}^{1} |f(y)|^p dy \right)^{\frac{1}{p}},
\end{align*}
where $\frac{1}{p^{\prime}} + \frac{1}{p} =1$.
Recall the well-known Nash--Aronson estimate (see, e.g., \cite{DS26})
\begin{align*}

  0\leq p_t(x,y) \leq \frac{1}{\sqrt{2\pi t}}\exp^{-\frac{(x-y)^2}{2t}}, \quad \forall\, x,y \in [0,1].
\end{align*}
Hence
