    d_{t+1}
    \leq
    \norm{\mathcal T_{t+1}(Y_t^{(N)})-
      \mathcal T_{t+1}(X_t^{(N)})}_2
    +\norm{Q_\varrho(\mathcal T_{t+1}(Y_t^{(N)}))-
      \mathcal T_{t+1}(Y_t^{(N)})}_2.
  \end{equation*}
