[Lem magnetization of arXiv:2608.25362, 'Fluctuations of the free energy of the Sherrington--Kirkpatrick model with ferromagnetic i'] {Chen14}}]
    For any open subset $U$ of $[-1, 1]$ with $\inf \{ \left\vertx -y\right\vert : x \in U, y \in \Omega(\boldsymbol{\beta}, \gamma, h) \} > \delta$ for some $\delta > 0$, we have
    \begin{align*}
        \E \langle I( m \in U ) \rangle \leqslant K \exp \left( -{N}/{K} \right),
    \end{align*}
    where $K = K(\delta)$ is a constant independent of $N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary Main-Theorem-corollary of arXiv:2411.04500, '\LARGE Probabilistic Approaches to The Energy Equality in Forced Surface Quasi-Geostrophic'] Let $ \varepsilon>0 $ and $ m(\varepsilon)\in \mathbb{N}_+ $ satisfy the scaling regime (equation scaling-m of the paper). Let $\theta_{\varepsilon,m(\varepsilon)}$ be the solution of
	(equation SPDE-SQG-m of the paper) with initial data $ \theta_{\varepsilon, m(\varepsilon)}(0)\sim \mathcal{G}(0,\varepsilon P_{m(\varepsilon)}/2)$ and let $ \mu_{\varepsilon, m(\varepsilon)}$ be the law of $\theta_{\varepsilon, m(\varepsilon)}$ on $\mathbb{X}_{\alpha,\alpha/2}.$  
	Suppose that  $ \theta $ is a weak solution of (equation PDE-SQG of the paper) for some $g \in L^2([0, T];L^2(\mathbb{T}^2))$ in the sense of Definition (def-weak-solution-skeleton-equation of the paper).
	\item (i) Assume that
	\begin{equation*}
		\frac{1}{2}\|\theta(T)\|_{L^2(\mathbb{T}^2)}^2+\int_0^T\|\theta(s)\|_{H^\alpha(\mathbb{T}^2)}^2\,\mathrm{d}s>\frac{1}{2}\|\theta(0)\|_{L^2(\mathbb{T}^2)}^2+\int_0^T\langle\Lambda^{\alpha}\theta, g\rangle\,\mathrm{d}s,
	\end{equation*}
	then $\theta$ violates the large deviations lower bound:
	\begin{equation*}
		\inf _{\{ G\text{ is open in }\mathbb{X}_{\alpha,\alpha/2}:  \theta\in G\}} \liminf _{\varepsilon \rightarrow 0} \varepsilon \log \mu_{\varepsilon,m(\varepsilon)}(G)<-\mathcal{I}(\theta).
	\end{equation*}
	\item (ii)  Assume that
	\begin{equation*}
		\frac{1}{2}\|\theta(T)\|_{L^2(\mathbb{T}^2)}^2+\int_0^T\|\theta(s)\|_{H^\alpha(\mathbb{T}^2)}^2\,\mathrm{d}s<\frac{1}{2}\|\theta(0)\|_{L^2(\mathbb{T}^2)}^2+\int_0^T\langle\Lambda^{\alpha}\theta, g\rangle\,\mathrm{d}s,
	\end{equation*}
	then $\mathfrak{T}_T \theta$ violates the large deviations lower bound:
	\begin{equation*}
		\inf_{\{G\text{ is open in }\mathbb{X}_{\alpha,\alpha/2}, \,\mathfrak{T}_T \theta\in G\}} \liminf _{\varepsilon \rightarrow 0} \varepsilon \log \mu_{\varepsilon,m(\varepsilon)}(G)<-\mathcal{I}(\mathfrak{T}_T \theta).
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 10 (Precise isotropic spectral tail) of arXiv:2607.07712, 'Parameter-Space Heat Flow, Gaussian Density Ratios, and Sharp Hermite Truncation Rates'] Assume \(0<|\sigma|<1\) and \(u\neq0\). Then
\begin{equation}
\|K_{u,\sigma}-\Pi_{\le M}K_{u,\sigma}\|_{L^2(\gamma_d)}^2
\sim
\frac{1}{1-\sigma^2}
a_{M+1}(u,\sigma).

\end{equation}
Consequently,
\begin{equation}
\|K_{u,\sigma}-\Pi_{\le M}K_{u,\sigma}\|_{L^2(\gamma_d)}
\sim
\left(
\frac{C_{d,u,\sigma}}{1-\sigma^2}
\right)^{1/2}
(M+1)^{\frac d8-\frac38}
\exp\!\left(
\frac{|u|}{|\sigma|}\sqrt{M+1}
\right)
|\sigma|^{M+1}.

\end{equation}
Equivalently, one may replace \(M+1\) by \(M\) in the slowly varying
factors, at the cost of multiplying the leading constant by \(|\sigma|\).

[Lemma 183 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Take $\delta'\in(0,\delta)$  and suppose that
for $\rho=\rho_{a}$ (note $\bB_{r}$)
\begin{equation}

\widetilde{ D\sigma }_{p_{0},\rho}:=\sup_{t}\sup_{r\leq \rho }r\sup_{B\in \bB_{r}}\dashnorm D\sigma(t,\cdot)\|_{L_{p_{0}}(B)}\leq \widetilde{D\sigma}(d,d_{1},\delta,\delta') ,
\end{equation}
where $\widetilde{D\sigma}(d,d_{1},\delta,\delta')$
is easily found from
\index{$S$@Miscelenea!$\widetilde{D\sigma}_{p_{0},\rho}$}
\index{$S$@Miscelenea!$\widetilde{D\sigma}$}
 the proof that follows.
Then  
for all $\varepsilon \in(0,\rho_{a}]$   the functions  
$\sigma^{(\varepsilon)},b^{(\varepsilon)}$ satisfy 
Assumptions \ref{assumption 12.20,1} and~\ref{assumption 12.13,1}. (Proof in the paper; no proof environment follows the statement in the TeX.)

