[Lemma le:modified_source of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Given $k \in \mathbb{N}_+$ and ${\scaleobj{1}{\square}}_m \in \mathcal{G}_k$, for any ${0 \leqslant i \leqslant k-1}$, and any anti-symmetric vector field defined on the induced graph of maximal cluster
		\begin{equation*}
			w:\overrightarrow{E_d}(\mathscr{C}_*^{\widetilde{\mathbf{a}}^\delta_{m}}({\scaleobj{1}{\square}}_m))\rightarrow \mathbb{R},
		\end{equation*} such that $w\vert_{E_d(\Gamma_m)}=0$,  there exists a vector field $\Tilde{w}$ supported on open bonds $\overrightarrow{E_d}^{\widetilde{\mathbf{a}}^\delta_{m}}(\mathscr{C}_*^{\widetilde{\mathbf{a}}^\delta}({\scaleobj{1}{\square}}_m))$, such that 
		\begin{equation*}
			\nabla \cdot \Tilde{w} = \nabla \cdot w,
		\end{equation*}
		and satisfies the point-wise estimate
		\begin{equation}

			\forall e \in E_d({\scaleobj{1}{\square}}_m), \qquad \vert \Tilde{w}(e)\vert \leqslant 
			\sum_{{\scaleobj{1}{\square}} \in \mathcal{P}_{k,i}({\scaleobj{1}{\square}}_m)} \boldsymbol{1}_{\{\mathsf{r} {\scaleobj{1}{\square}}  \supseteq e \}} \sum_{e'\cap {\scaleobj{1}{\square}} \not = \emptyset} |w(e')|.
		\end{equation}
		Moreover, for every $k \geqslant 2$ and $0 \leqslant i \leqslant k-2$, there exists a finite positive constant $C(\mathsf{r}, d, i)$ such that the following weighted $L^2$-bound holds uniformly for all $w$ and $\alpha \geqslant 0$
		\begin{multline}
			\sum_{\substack{{\scaleobj{1}{\square}}\in \mathcal{P}_{k,i}({\scaleobj{1}{\square}}_m)\\
					{\scaleobj{1}{\square}}\not \subseteq \Gamma_m}}|{\scaleobj{1}{\square}}|^\alpha \sum_{e\in E_d(\mathscr{C}_*^{\widetilde{\mathbf{a}}^\delta_{m}}(\mathsf{r} {\scaleobj{1}{\square}}))}|\widetilde w(e)|^2 \\
			\leqslant C \sum_{\substack{{\scaleobj{1}{\square}}\in \mathcal{P}_{k,i+1}({\scaleobj{1}{\square}}_m)\\
					{\scaleobj{1}{\square}}\not \subseteq \Gamma_m}}|{\scaleobj{1}{\square}}|^{\alpha+4} \sum_{e\in E_d(\mathscr{C}_*^{\widetilde{\mathbf{a}}^\delta_{m}}(\mathsf{r}{\scaleobj{1}{\square}}))}|w(e)|^2.
		\end{multline}

