body:
[Lemma 7 of arXiv:2607.09246, 'Scaling limit of 1+1 dimensional directed polymer with power-law tail and spatial correlat'] Let \(\tau_N>0\).  Assume that, for all large \(N\), Lemma
\ref{lem:far-product-section2} can be applied at the scales
\(h_2,\ldots,h_m\).  Then, for every fixed \(\varepsilon,\delta>0\),
\begin{equation}
\begin{aligned}
\mathbb Q(U_N>\varepsilon\tau_N)
&\le
\mathbb Q(G_N(\delta)^c)
+
\sum_{j=2}^m
\left[
C\frac{\beta_NNh_je_N}{I_{j-1}}
+
\mathbb Q(D_{h_j})
\right]                                                     \\
&\quad
+
\frac{C}{\delta\varepsilon\tau_N}
\sum_{j=2}^m
\exp\{-I_{j-1}/4+C\mathfrak d_N(h_j)\},
\end{aligned}
\end{equation}
and
\begin{equation}
\begin{aligned}
\mathbb Q(L_N>\varepsilon\tau_N)
&\le
\mathbb Q(G_N(\delta)^c)
+
\frac{C}{\delta\varepsilon\tau_N}
\sum_{j=2}^m e^{-I_{j-1}/2}.
\end{aligned}
\end{equation}

