[Thm th:2.2 of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] Suppose $\xi = g_\alpha < 1-2\sqrt{\alpha}$. Then, it holds
	\begin{equation}
	\begin{aligned}
	\lim_{T \to \infty} \mathbb{P}(x^f_{\alpha T}(T) > \xi T - S T^{1/3}) 
	&= \lim_{T \to \infty} \mathbb{P}(x_{\alpha T}(t) > \xi T - f(T-t)-ST^{1/3} \ \forall t \in [0,T]) \\
	&\hphantom{= } \times \lim_{T \to \infty} \mathbb{P}(\tilde{x}_{\alpha T}(T) > \xi T - S T^{1/3}). 
	\end{aligned} 
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem_hfbmLowerBound of arXiv:2608.17463, 'Persistence probabilities of fractional L\'evy fields indexed by hyperbolic space and othe'] Let $R>0$ be an arbitrary finite radius. For the hyperbolic fractional L\'evy field on $\mathbb{H}_{d}$ there exists a constant $C_2$, such that, for all $\varepsilon>0$ small enough,
    \begin{align*}
        \prob{\sup_{\eta\in\mathcal{B}_R(O)} X_H(\eta) < \varepsilon} \geq C_2 ~ \varepsilon^{\frac{d}{H}} ~ \left(\sqrt{-\log \varepsilon}\right)^{-\frac{d}{H}}.
    \end{align*}

