[Proposition 22 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] Suppose $v\in(-\alpha,0)\setminus \ZZ$ and $m\in\ZZ_{\geq 0}$ is such $v+m<0$. Let  $u=v+m$.
 \begin{enumerate}[(A)]
  \item    If $2v\not\in\ZZ_{\leq 0}$ 
     then
         \begin{multline}
         \GG_N(\alpha,v+m,v)
        \\   = \tfrac{1}{
    2\pi \Gamma(2v+m)} \int_{0}^\infty \left|\Gamma(\alpha+\i x)\right|^{2N} \tfrac{|\Gamma(v+\i x)|^2|\Gamma(v+m +\i x )|^2}{|\Gamma(2\i x)|^2}\d x
    -2S_1+2S_2,
     \end{multline}
     where
     \begin{multline*}
         S_1=\tfrac{1}{ \Gamma
   (1-2 v)} \sum_{j=0}^{m-1} \tfrac{(-1)^{j}  (j+v)  (m-j-1)! (2 v)_j
   (m+2 v)_j}{j! }  \Gamma(\alpha +j+v)^N \Gamma (\alpha-j-v )^N
     \end{multline*}
     and
     \begin{multline*}
         S_2= {(-1)^m} \sum _{i=0}^{\lfloor -v\rfloor -m} \tfrac{(i+m+v) \Gamma
   (-m-2 v+1) }{i! (i+m)! \Gamma (-i-2 m-2 v+1) \Gamma
   (-i-m-2 v+1)}
   \\ \cdot  \Big[N(\psi
   (i+m+v+\alpha )-\psi (-i-m-v+\alpha
   ))+\frac{1}{i+m+v}+\psi (-i-2 m-2 v+1)\\ +\psi
   (-i-m-2 v+1)-\psi (i+m+1)-\psi
   (i+1)\Big]\Gamma (\alpha-i-m-v )^N \Gamma (\alpha+i+m+v)^N.
     \end{multline*}
  \item   If  $v\in(-\alpha,0)\setminus \ZZ$ is such that $2v\in\ZZ_{\leq 0}$, then  formula \eqref{G(v+m,v)} still holds, except that the integral term vanishes:
  \begin{equation}

       \GG_N(\alpha,v+m,v)=-2S_1+2S_2.
  \end{equation}
\end{enumerate}

[Lem of arXiv:2411.09988, 'A Study in Markov Chains, Loop-Erased Random Walk and Loop Soups'] Suppose $x \in A$, $V \subset \partial A$ and $H_A(x,V)>0$. Let $\{X_n\}$ be the Markov chain started at $x$ and $T =\min\{k\geq0:X_k \in \partial A\}$. Then for $y \in A_x \cup V$,
    \begin{equation*}
        \mathbb{P}^x\{X_1=y \mid X_T \in V, x \notin \{X_1, \ldots, X_{T-1}\}\} = \frac{p(x,y)H_{A_x}(y, V)}{H_{\partial A_x}(x, V)}.
    \end{equation*}
    Here $A_x = A \backslash \{x\}$.

