[Lemma lm:CapArea of arXiv:2411.19163, '\bfseries Random polytopes in convex bodies:\\ Bridging the gap between extremal container'] For any $\mathbf{v}\in\mathbb{S}^{m-1}_+$, ${\boldsymbol{\beta}}\in [0,\infty)^m$ and $s\in(\max\{s_1(\mathbf{v}),0\},\|\mathbf{v}\|_1)$ we have
        \begin{align*}
             \operatorname{Vol}_{m-1}(C(\mathbf{v},s);{\boldsymbol{\beta}})&\asymp (\|\mathbf{v}\|_1-s)^{\beta+m-1}  \prod_{i=1}^m v_i^{-\beta_i-1}.
        \end{align*}
        For $m=1$ we may choose $\beta_1>-1$.
        Note also that for $m\ge 2$ we have $s_1(\mathbf{v})\ge 0$, while for $m=1$ we have $s_1(\mathbf{v})=-1$.

[Definition def-stochastic-leray of arXiv:2411.04500, '\LARGE Probabilistic Approaches to The Energy Equality in Forced Surface Quasi-Geostrophic'] We say that $(\theta_{\varepsilon,\delta(\varepsilon)},W)$,  $\left(\Omega, \mathcal{F},\{\mathcal{F}_t\}_{t \in[0, T]}, \mathbb{P}\right)$ is a stochastic generalized Leray solution of (equation SPDE-SQG of the paper) with initial data $\theta_0$ if, $ \theta_0 $ is an $ H^{\alpha-2\beta}(\mathbb{T}^2) $-valued random element, $ W $  is a cylindrical Wiener process on $ H^{\alpha-2\beta}(\mathbb{T}^2)$ independent of $\theta_0$, and
	$\theta_{\varepsilon,\delta(\varepsilon)}$ is a progressively measurable process satisfying:

	(i)   $\mathbb{P}$-almost surely, $\theta_{\varepsilon,\delta(\varepsilon)}\in L^\infty([0,T];H^{\alpha-2\beta}(\mathbb{T}^2)) \cap L^2([0,T];H^{2\alpha-2\beta}(\mathbb{T}^2))\cap C([0,T];H_w^{\alpha-2\beta}(\mathbb{T}^2))$.

	(ii) $\mathbb{P}$-almost surely, for every $\varphi \in C^{\infty}\left([0, T];H^\infty(\mathbb{T}^2)\right)$,  for all $t\in[0,T]$, 
	\begin{equation*}
		\begin{aligned}
			&\left\langle\theta_{\varepsilon,\delta(\varepsilon)}(t), \varphi(t)\right\rangle+\int_0^t\left\langle\theta_{\varepsilon,\delta(\varepsilon)}(s), \Lambda^{2\alpha} \varphi(s)\right\rangle \,\mathrm{d}s=\left\langle \theta_0, \varphi(0)\right\rangle+\int_0^t\langle\theta_{\varepsilon,\delta(\varepsilon)}(s),\partial_s\varphi(s) \rangle\,\mathrm{d}s\\&-\frac{1}{2}\int_0^t\left\langle R_2 \theta _{\varepsilon,\delta(\varepsilon)} (s) ,\left[\Lambda, \partial_1 \varphi(s)\right]\Lambda^{-1} \theta_{\varepsilon,\delta(\varepsilon)}(s)\right\rangle \,\mathrm{d} s\\&+\frac{1}{2}\int_0^t\left\langle R_1 \theta _{\varepsilon,\delta(\varepsilon)} (s) ,\left[\Lambda, \partial_2 \varphi(s)\right]\Lambda^{-1} \theta_{\varepsilon,\delta(\varepsilon)}(s)\right\rangle \,\mathrm{d} s+\sqrt{\varepsilon}\int_{0}^t \langle \Lambda^{2\beta}\varphi(s),\sqrt{Q_\delta(\varepsilon)}\,\mathrm{d}W(s)\rangle.
		\end{aligned}
	\end{equation*}
	Here and subsequently, the nonlinear terms $ \left\langle R_j \theta _{\varepsilon,\delta(\varepsilon)} (s) ,\left[\Lambda, \partial_i \varphi(s)\right]\Lambda^{-1} \theta_{\varepsilon,\delta(\varepsilon)}(s)\right\rangle (i,j=1,2)$ are defined by the $ H^{-1/2}-H^{1/2} $ dual, see Section (section-Preliminary of the paper) for details.

	(iii)  $ \theta_{\varepsilon,\delta(\varepsilon)} $ satisfies the pathwise $ H^{\alpha-2\beta}$-energy inequality: $\mathbb{P}$-almost surely, for all $t\in[0,T]$, 
	\begin{equation}
		\begin{aligned}
			\frac{1}{2}\left\| \theta_{\varepsilon,\delta(\varepsilon)}(t)\right\|_{H^{\alpha-2\beta}(\mathbb{T}^2)}^2 +\int_0^t\left\| \theta_{\varepsilon,\delta(\varepsilon)}(s)\right\|_{H^{2\alpha-2\beta}(\mathbb{T}^2)}^2 \,\mathrm{d}s&\leqslant  \frac{1}{2}\left\|\theta_0\right\|_{H^{\alpha-2\beta}(\mathbb{T}^2)}^2  \\
			+\sqrt{\varepsilon} \int_0^t\langle \Lambda^{2\alpha-2\beta} \theta_{\varepsilon,\delta(\varepsilon)}(s),\sqrt{Q_{\delta(\varepsilon)}}\,\mathrm{d}W(s)\rangle&+\frac{\varepsilon}{2}\left\|\Lambda^{\alpha} \circ \sqrt{Q_{\delta(\varepsilon)}}\right\|_{HS}^2 t.
		\end{aligned}
	\end{equation}

[Lemma 18 of arXiv:2608.23462, '2608.23462'] Let $\beta>0$ and assume that $(\hat Y^x_t)_{t \ge 0}$ is $2$-dissipative with constant $\beta$ and $f$ is $L_f$-Lipschitz. Under Assumption~\ref{assu:regularity}, $\Phi$ is differentiable in $x$, its derivative is jointly continuous on $\R^{d_1+d_2}$, and for all $\alpha>0$, there exists a constant $C_{\alpha,\beta} >0$ satisfying
    \begin{align*}
        |D_x \Phi (x,y)| \leq C_{\alpha,\beta} (1+|y|^\alpha)
    \end{align*}
    for all $x \in \R^{d_1}$ and $y \in \R^{d_2}$.

