[Lemma avldptx of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Fix any {\small$\mathrm{D}=\mathrm{O}(1)$} and {\small$\delta>0$}, both independent of {\small$N$}. With high probability, we have the following for any admissible {\small$\mathfrak{q}_{\n}$} in the sense of Definition (definition:admissible of the paper):

\begin{align}
\sup_{\t\in[0,1]}\sup_{|\x|\leq N^{\mathrm{D}}}|\mathbf{Av}^{\mathbf{T},\mathbf{X},\mathfrak{q}_{\n}}_{\t,\x}|\lesssim N^{-\frac12+\frac34\delta_{\mathbf{S}}+\delta}.
\end{align}

[Theorem thm:pure-time-calibration of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] Let $A\in W^{1,1}(0,T;\mathsf{S}^d)$ satisfy, for some
$0<\lambda\leq\Lambda<\infty$,
\begin{equation}
 \lambda I_d\preceq A(t)\preceq\Lambda I_d.

\end{equation}
For the zero-drift reference $b=0$, $a(t,x)=A(t)$, put
$\operatorname{Cov}_A(t):=\int_0^tA(s)\,\mathrm d s$, and denote its reference
process by $X^A$.  Then $\mu_t=N(x_0,\operatorname{Cov}_A(t))$, and
$\lambda tI_d\preceq\operatorname{Cov}_A(t)\preceq\Lambda tI_d$.  Put
\begin{equation*}
 e_A(t):=\lambda^{-1}\left\lVert \dot A(t)\right\rVert_{\mathrm{op}},
 \qquad
 h_A(t):=\frac1{\lambda t^2}
       \int_0^ts\left\lVert \dot A(s)\right\rVert_{\mathrm{op}}\,\mathrm d s,
 \qquad \chi_A:=e_A+h_A.
\end{equation*}
Then $e_A,h_A,\chi_A\in L^1(0,T)$.  For $K>0$, define
\begin{equation}
 \omega_{A,K}(t):=\exp\left(-K\int_t^T\chi_A(s)\,\mathrm d s\right).

\end{equation}
For every $K>0$, one has $\omega_{A,K}\in W^{1,1}(0,T)$; moreover, it is bounded
above and below by positive constants, and, for every $\alpha\geq0$,
$t^\alpha\omega_{A,K}$ is a
regular weight of order $\alpha$.  There is
$K_{\mathrm{hom}}=K_{\mathrm{hom}}(\Lambda/\lambda)>0$ such that every
$K\geq K_{\mathrm{hom}}$ gives the sharp calibration
\begin{equation}
 C_{t^\alpha\omega_{A,K}}(X^A)=C_\alpha^{\mathrm{Br}}
 \qquad\text{for every }\alpha\geq0.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 566 of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Under the \textit{Fr\'{e}chet-Hoeffding} \textit{upper-bound }iteration (\ref
{562}), the compound maps 
\begin{equation}
\Phi _{n}=T_{0}\circ T_{1}\circ \cdots \circ T_{n},  
\end{equation}
where again $T_{n}$ denotes the inverse of $L_{n}(x)$, converge pointwise
and locally uniformly on $(0,1)$ to the constant map 
\begin{equation}
\Phi _{\infty }(x)=1\qquad x\in (0,1).  
\end{equation}

