[Lemma lem:vthd of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] {bass1992lifetimes}}]
    If for any $x\in D$, there exists $b>0$ such that
\begin{equation}
\mathrm{dist}(x',\partial D)\ge C_6(b+l(\gamma_x(x,x')))^{1/\alpha},\ \text{ for all } x'\in\gamma_x,
\end{equation}
letting $\delta(x)$ be the supremum of $b$'s that satisfy (equation eq:2193 of the paper), then this ${\delta}$ is bounded continuous, and satisfies conditions (i) and (ii) in Definition~(def:thd of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor clt:I_n of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] Let $I^{(n)}:=\left(I_1^{(n)},\dots,I_m^{(n)}\right)\overset{d}{=}M(n;1/m,\dots,1/m)$. Then, with $\mu^{(n)}=(n/m,\ldots,n/m)^t$, we have
    \begin{align}
        I^{(n),\ast}:=\frac{I^{(n)}-\mu^{(n)}}{\sqrt{n}}\overset{d}{\longrightarrow} N=(N_1,\ldots,N_m),
    \end{align}
    where $\mathcal{L}(N)=\mathcal{N}(0,\Sigma)$ with 
\begin{equation}
\Sigma = \left( \begin{array}{cccc}
    \frac{m-1}{m^2} &-\frac{1}{m^2}& \cdots & -\frac{1}{m^2} \\
    -\frac{1}{m^2} & \ddots & &\vdots\\
    \vdots &  & \ddots& -\frac{1}{m^2} \\
    -\frac{1}{m^2} & \dots & -\frac{1}{m^2}& \frac{m-1}{m^2}
    \end{array}
    \right).
\end{equation}

[Defi 26 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] Given a probabilistic set-up $(\Omega,\mathfrak{F},{\mathbb F}= \{\mathfrak{F}_t\}_{t\geq 0},\mathbb{P},(W_t)_{t\geq 0})$ as defined in Subsection \ref{Notations}, and an ${\mathcal F}_0$--measurable initial condition $X_0$ with values in ${\mathcal U}^2({\mathbb S} )$ satisfying ${\mathbb E}[\| X_0\|_2^p] < + \infty$ for all $p \geq 1$, we say that a pair of  processes $(X_t,{\eta}_t)$ solves the equation \eqref{RHSE2}, initialized at $X_0$, if
\begin{enumerate}
\item[(i)] $(X_t)_{t\geq 0}$ is continuous $\mathbb{F}-$adapted with values in $\mathcal{U}^2(\mathbb{S})$; almost surely, the path $(X_t)_{t \geq 0}$ belongs to $L^2_{\rm loc}([0,+\infty),{\mathcal H}^1_{\rm Sym}({\mathbb S}))$ (i.e., $(X_t)_{0 \le t \le T} \in L^2([0,T],{\mathcal H}^1_{\rm Sym}({\mathbb S}))$). Moreover, 
\begin{equation*}
\forall T>0, \quad {\mathbb E} \int_0^T \| D_{\mathbf{x}} X_t \|_2^2 {\mathrm d} t < + \infty, \quad 
 {\mathbb E} \int_0^T \int_{\mathbb S} \frac1{\vert D_{\mathbf{x}} X_t({\mathbf x})\vert} {\mathrm d}{\mathbf x} < + \infty;
\end{equation*}
\item[(ii)] $({\eta}_t)_{t\geq 0}$ is a continuous $\mathbb{F}\text{-adapted}$ process that takes values in $\mathcal{H}_{\mathrm{Sym}}^{-2}(\mathbb{S})$, starting from $0$ at $0$ such that, with probability 1, for any $\varphi \in \mathcal{H}_{\mathrm{Sym}}^{2}(\mathbb{S})\cap \mathcal{U}^2(\mathbb{S})$ the path $t\mapsto\langle {\eta}_t, \varphi\rangle$ is non-decreasing;

\item[(iii)]  with probability one, for any $\varphi \in \mathcal{H}_{\mathrm{Sym}}^{2}(\mathbb{S})$, for all $t \geq 0$
\begin{align}
\langle X_t, \phi \rangle =
\langle X_0,\phi \rangle + \frac{1}{2}\int_0^t \Big\langle \frac{1}{D_{\mathbf{x}} X_r},D_{\mathbf{x}} \phi \Big\rangle \mathrm{d}r  + \int_0^t \langle X_r,\Delta_{\mathbf{x}} \phi \rangle \mathrm{d}r + \langle {\eta}_t,\phi\rangle +\langle W_t,\phi\rangle, \quad t \geq 0;
\end{align}
\item[(iv)] for any $t\geq 0$,
\[\lim_{\epsilon\searrow 0}\mathbb{E}\int_{0}^{t} \mathrm{e}^{\epsilon \Delta} X_r\cdot\mathrm{d}{\eta}_r =0, 
\quad
\lim_{\epsilon \searrow 0}
\mathbb{E} \biggl[\biggl\vert  \int_{0}^{t}  \int_{\mathbb S}\frac{ \mathrm{e}^{\epsilon \Delta} 
D_{\mathbf{x}} X_r({\mathbf x})}{D_{\mathbf{x}} X_r({\mathbf x})} \mathrm{d}{\mathbf x} -t  \biggr\vert \biggr]=0,
\]
with the first integral being interpreted as in Theorem \ref{thm:integral:varsigma}.\end{enumerate}

[Theorem thm:design of arXiv:2510.22778, 'Free denoising diffusion models'] Let $\mu_{*}$ be a compactly supported probability measure with a density $\psi_{*}$
that is H\"older continuous on $K:=\supp\mu_{*}$, and let $f\in C(K)$ with $f>0$.
Then the principal value in
\begin{equation}
  b_{*}(x)=-f(x)^{2}\,H(f^{2}\mu_{*})(x),
  \qquad H(f^{2}\mu_{*})(x)=\mathrm{p.v.}\!\int_{K}\frac{f(y)^{2}\,\mathrm{d}\mu_{*}(y)}{x-y}
\end{equation}
converges for every $x\in K$ and $b_{*}$ is itself H\"older continuous there, and
$\mu_{*}$ is a stationary spectral law of the free diffusion
$\mathrm{d} X_{t}=b_{*}(X_{t})\mathrm{d} t+f(X_{t})\mathrm{d} S_{t}\,f(X_{t})$.

