[Lemma 9 of arXiv:2608.27398, 'Strict Stability and Strict Minimality of Regular Area-Minimizing Hypercones: A Quantitati'] For each sign $\pm$ there is a smooth vector field $Z_\pm$ tangent to
$\Sigma_\pm$ such that
\begin{equation}
    \diver_{\Sigma_\pm}(\psi_\pm Z_\pm)=\psi_\pm
    \qquad\text{on }\Sigma_\pm,
\end{equation}
and
\begin{equation}
    |Z_\pm(z)|\leq C_{\C}|z|
    \qquad\text{for every }z\in\Sigma_\pm.
\end{equation}

[Definition 1 of arXiv:2606.03661, '2606.03661'] Let $\alpha \in (0,1)$ and $\nu>-1$. For a differentiable function 
$f:\mathbb{R}^+ \to \mathbb{R}$, the beta-weighted derivative
of $f$ is defined by
\begin{equation}

(\mathscr{D}_t^{(\alpha,\nu)} f)(t) := 
\frac{t^{\alpha-\nu-1}}{\Gamma(1-\alpha)} 
\int_0^t \tau^\nu (t-\tau)^{-\alpha} f^\prime(\tau) \, d\tau .
\end{equation}

[Theorem 30 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $\alpha\in\mathbb R$. The assignment
\begin{equation}

\hat\Lambda_{S,1,\alpha}^{\mathrm q}:Z\hat C^{1}(\Delta^3_T;B_\alpha)\to \mathfrak Q_{\mathrm{fr},\mathrm{log}}^{1,\alpha},
\quad h\mapsto \hat\Lambda_{S,1,\alpha}^{\mathrm q}h,\quad 
\bigl(\hat\Lambda_{S,1,\alpha}^{\mathrm q}h\bigr)^\tau:=[r_{\mathrm d}^\tau(h)]_\tau,
\end{equation}
is a well-defined continuous linear map. It satisfies the following properties
\begin{enumerate}
\item for every $\tau\in[0,T]$ and every representative $r^\tau\in \bigl(\hat\Lambda_{S,1,\alpha}^{\mathrm q}h\bigr)^\tau$, $\delta r^\tau = h^\tau$;

\item in particular, for every $0\le s\le u\le t\le T$ and every representative $r^t\in \bigl(\hat\Lambda_{S,1,\alpha}^{\mathrm q}h\bigr)^t$, $(\delta r^t)_{tus}=h_{tus}$;

\item for every $h\in Z\hat C^{1}(\Delta^3_T;B_\alpha)$, the uniform estimate $\|\hat\Lambda_{S,1,\alpha}^{\mathrm q}h\|_{\mathfrak Q_{\mathrm{fr}, \mathrm{log}}^{1,\alpha}}\le C_{T} M_{\alpha,T}\|h\|_{1,\alpha}$ holds.
\end{enumerate}

[Theorem 6 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {McDiarmid's Inequality under ATE}


    Let $X \sim \nu$ on $\mathcal X^n$ that fulfills $\kappa$-ATE. Assume $f : \mathcal X^n \to \R$ fulfills the bounded differences property with constants $c = (c_1,...,c_n)\T$. Then, for all $t > 0$ we have
    \begin{align*}
        \P\Parent{|f(X) - \E[f(X)]| \geq t} 
        &\leq 2\exp\Parent{-\frac{2t^2}{\kappa \twonorm{c}^2}}. 
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

