[Proposition 21 of arXiv:2609.03954, 'Galois representations ramified at one prime via relative deformation theory'] Put
\begin{equation}
        q=A+s+C.
\end{equation}
For every $\alpha\in\mathcal B$, the image of $\rho_{2A}^*$ contains
an element lying in the $q$-th congruence subgroup whose leading term
at level $q$ is $X_\alpha$.  Moreover
\begin{equation}
        q+1\le2A-R.
\end{equation}

[Corollary 22 (Dubins' inequality with portfolio bands, $T < \infty$) of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] Let $g_0, \ldots, g_T$ be a given, real valued, supermartingale. Also, $\Pi_{0, k}^{c, H}$ is a portfolio process as indicated above and such that $g_j \geq  \Pi_{0, j}^{c, H}$ on $\mathcal{S}$ and for all $0 \leq j \leq T$.

 Assume the definitions of $\rho_k, \tau_k$ as above, in particular $c \leq a <b$ are given  and $T < \infty$. Furthermore assume that $(L)-a.e.$ holds, then for any $k \geq 0$:
\begin{equation} 
\overline{\sigma}({\bf 1}_{\{\tau_{k+1} < T\}}) \leq
\Big(\frac{a-c}{b-c} \Big)^{k+1}.
\end{equation}

[Lemma l32 of arXiv:2411.13875, 'Large deviations at the origin of random walk in random environment'] Fix $\kappa > 0$, $j\ge 1$ and $\mathcal S:=\{\sigma_1,\dots,\sigma_j\} \subseteq \mathcal P_{\mathbb V}^{(\kappa)}$ with all $\sigma_i$'s distinct. Assume that there exists some $u \in \mathbb Q^d$, with $|u|_2=1$,  such that
\begin{equation}

\langle \mathrm d(\sigma_i), u \rangle =0
\end{equation}
for all $1\le i\le j$, where $\mathrm d(\sigma_i)$ is the drift of $\sigma_i$ as defined in (equation eq:defdrift of the paper). Then, given $\varepsilon > 0$, for any $\overline{\lambda}=(\lambda_1,\dots,\lambda_j) \in \Delta_j$  

there exists some periodic environment $\omega_{\mathbf n,\mathbf p}$ with $\mathbf p=(\vec{p}(x)) \in \mathcal S^{\mathbf{B}_\mathbf n}$ such that $P_{0,\omega_{\mathbf n,\mathbf p}}$-almost surely, for every $1 \leq m \leq j$,
\begin{equation}

\limsup_{n\to\infty}\left|\frac{\sum_{i=0}^n1_{\{X_i\in S_m\}}}{n}-\lambda_m\right|\le\varepsilon,
\end{equation}
where $S_m$ is the set of sites $x\in \mathbb Z^d$ such that $\omega_{\mathbf n,\mathbf p}(x)=\sigma_m$. As a matter of fact, $\omega_{\mathbf n,\mathbf p}$ can be chosen as a $(u;r_1,\dots,r_j)$-strip periodic environment generated by the $\sigma_1,\ldots,\sigma_j$ for some $r_1,\dots,r_j$.

[Lemma 40 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let be $\eta>0$, $\varepsilon\in (0,1)$ and $b\geq (2v)\vee(2\lambda)$. Then
\begin{equation}

\E\Big[\big\Vert\ind_{U_{0,b,\varepsilon}}\big\Vert_{H^{-\eta}(\C)}^{2}\Big]^{1/2}
\leq \dfrac{2}{\sqrt{\pi}}\big\Vert\ind_{D}\big\Vert_{H^{-\eta}(\C)}\,
\varepsilon^{\pi/(32 b^{2})},
\end{equation}
and
\begin{equation}

\E\Big[\big\Vert\ind_{\widetilde{U}_{0,b,\varepsilon}}\big\Vert_{H^{-\eta}(\C)}^{2}\Big]^{1/2}
\leq \dfrac{2}{\sqrt{\pi}}
\Big(\int_{D^{2}}
\Big(\Big(\dfrac{\varepsilon}{\CR(z,D)}\Big)\wedge 1\Big)^{\pi/(16 b^{2})}
\LK_{\eta}(\vert w-z\vert)\,d^{2}z\,d^{2}w\Big)^{1/2}.
\end{equation}
Fix a deterministic smooth cutoff function $f_{0}:D\rightarrow [0,1]$, compactly supported in $D$.
Assume that
\begin{displaymath}
\varepsilon\,\leq \inf_{z\in\operatorname{Supp}(f_{0})}\CR(z,D).
\end{displaymath}
Then
\begin{equation}

\E\Big[\big\Vert f_{0}\ind_{\widetilde{U}_{0,b,\varepsilon}}\big\Vert_{H^{-\eta}(\C)}^{2}\Big]^{1/2}
\leq \dfrac{2}{\sqrt{\pi}}
\big\Vert f_{0}\big\Vert_{H^{-\eta}(\C)}
\Big(
\dfrac{\varepsilon}{\inf_{\operatorname{Supp}(f_{0})}\CR(z,D)}
\Big)^{\pi/(32 b^{2})}.
\end{equation}

