[Lem 14 of arXiv:2604.13134, '\bf From Gaussian to Gumbel: extreme eigenvalues of complex Ginibre products with exact ra'] Uniformly on $x\in [-\widetilde{\ell}_{1,\infty}(n), \widetilde{\ell}_{2,\infty}(n)],$ we have the following estimates.
	\begin{enumerate}
		\item If $1\leq j\leq j_n,$ then
		\begin{equation}
			\widetilde{M}^{(n)}_{j, j}(x)=\frac{(1+O((\log\alpha_n)^{-1}))}{\sqrt{2}\pi\alpha_n^{1/4}\tilde{u}^{3/2}_n(j, x)}e^{-\frac{\widetilde{u}^{2}_n(j,x)}{2}}.
		\end{equation} 
		\item If $j_n< j< t_n,$ then
		\begin{equation}
			\widetilde{M}^{(n)}_{j, j}(x)\lesssim\frac{1}{\alpha_n^{1/4}\widetilde{u}^{3/2}_n(j,x)}e^{-\frac{3\widetilde{u}^{2}_n(j,x)}{8}}+n^{-4/5} .
		\end{equation} 
		\item For the endpoint $j=t_n,$
		\begin{equation}
			\widetilde{M}^{(n)}_{t_n, t_n}(x)\leq	n^{-4}.
		\end{equation}
	\end{enumerate}

