[Definition 4 of arXiv:2608.00449, 'First-order phase transitions in the hard-core model'] \label[definition]{def:pf}
    For a graph $G=(V,E)$, let $\cI(G)=\{I\subset V : \forall u,v\in I, uv\notin E\}$ be the set of independent sets in $G$ (including the empty set). If $G$ is finite, then for a formal parameter $\lambda$, the \emph{partition function} $Z_G(\lambda)$ is defined by
    \[ Z_G(\lambda) = \sum_{I\in \cI(G)}\lambda^{|I|}.\]

[Definition 6 of arXiv:2506.09462, 'Transition Path Theory For L\'{e}vy-Type Processes: SDE Representation and Statistics'] The \textbf{\(AB\)-transition starting point distribution} on \(A^c \cap (\partial A + 1)\) and the \textbf{\(BA\)-transition starting point distribution} on \(B^c \cap (\partial B + 1)\) are defined as follows:
    \begin{equation}
        \begin{aligned}
            \eta_A^{*}(x) &= v_A^{*-1} \int_{\bar{A} \cap (\partial A + 1)} \int_{|r| < 1} \mathbf{1}_{\{\mathrm{dist}(y, A^c) \leq F(y, r)\}} \nu(\d r) \eta_A^-(y)\d y, \quad x \in A^c \cap (\partial A + 1), \\
            \eta_B^{*}(x) &= v_B^{*-1} \int_{\bar{B} \cap (\partial B + 1)} \int_{|r| < 1} \mathbf{1}_{\{\mathrm{dist}(y, B^c) \leq F(y, r)\}} \nu(\d r) \eta_B^-(y)\d y, \quad x \in B^c \cap (\partial B + 1),
        \end{aligned}
    \end{equation}
    where \(v_A^*\) and \(v_B^*\) are normalization constants, ensuring that \(\eta_A^*\) and \(\eta_B^*\) define probability measures on \(A^c \cap (\partial A + 1)\) and \(B^c \cap (\partial B + 1)\), respectively.

[Prop eq:FE_h_right of arXiv:2606.06187, 'How to Study Reflected Brownian Motion in a Quadrant via Kernel Functional Equations?\\ \m'] For $(x,y)\in\mathbb C^2$ such that $\Re x>0$ and $\Re y>0$, we have
\begin{equation}

K^*(x,y)\,\widehat h^\rightarrow(x,y)
=
k_1^*(x,y)\,\widehat h^\rightarrow_1(y)
+
k_2^*(x,y)\,\widehat h^\rightarrow_2(x)
+
c\,h^\rightarrow(0,0),
\end{equation}
where
\begin{equation}

    \left\{
    \begin{array}{rcl}
    K^*(x,y) & = & \frac{1}{2}(x^2+y^2+2\rho xy)-\mu_1x-\mu_2y,\\
    k_1^*(x,y) & = & \frac{1}{2} (x-r_1 y)+\rho y +\mu_1,\\
    k_2^*(x,y) & = & \frac{1}{2} (y-r_2 x)+\rho x +\mu_2,\\
    c & = & \frac{1}{2}(r_1+r_2)-\rho.
    \end{array}
    \right.
\end{equation}

[Proposition 13 of arXiv:2609.03803, 'List-distance consistent vertices in trees are confined to a path'] Let $G=SP(w;1,\ell_2,\dots,\ell_k)$ with $k\ge4$ and $\ell_k\ge2$. Then
\begin{enumerate}
\item[\textup{(i)}] $\bigl\lceil \ell_k/2\bigr\rceil+1\ \le\ \ldc(G)\ \le\
\bigl\lceil \ell_k/2\bigr\rceil+2$;
\item[\textup{(ii)}] if $\ldc(G)=\lceil \ell_k/2\rceil+2$ and $\ell_k\ge3$, then
every optimal labeling $c$ satisfies \eqref{eq:B2} with $\ell_{i_0}=1$ and
$m\ge4$, and $S_c(G)$ consists of the leaf $v_{i_0,1}$ together with
$\lceil \ell_k/2\rceil+1$ vertices of the leg $i_1$.
\end{enumerate}

