[Prop FV734 of arXiv:2411.07809, 'Pirogov--Sinai Theory Beyond Lattices'] Suppose $G$ satisfies Assumption~(as:3 of the paper).
   For any $\tau$ sufficiently large, there exists $\lambda_\star = \lambda_\star(C_{\text{iso}}, D, \Delta,\tau)$ and an increasing
  sequence $(c_{n})_{n\geq 0}$ with
  $2\leq c_{n}\uparrow c_\infty \leq 3$ so that for  $\lambda_\textsf{e} > \lambda_\star$, $\lambda_{\textsf{o}}\in\mathcal{U}$, and all $n \geq 1$, the following statements hold: 
  \begin{enumerate}
  \item For $\gamma\in\mathcal C_{\leq n}$,
    \begin{equation}

      \widehat{w}_\gamma \leq e^{-\tau |\gamma|}
    \end{equation}
    and if $\gamma\in\mathcal C_{\leq n}^{x}$, $x\in \{\textsf{e},\textsf{o}\}$,
    \begin{equation}

      a^x_n \Delta_x|\mathsf{Int}\gamma|^{1/2} \leq \kappa/2 \text{ implies }
      \widehat{w}_\gamma = \widetilde{w}_\gamma. 
    \end{equation}
    Moreover, $\widehat{w}_\gamma$ is continuously differentiable in
    $\lambda_{y}$, $y\in \{\textsf{e},\textsf{o}\}$, and
    \begin{equation}

      \left| \frac{d \widehat{w}_\gamma}{d
          \lambda_{y}}\right| \leq \frac{R
        |\gamma|^2}{\lambda_{y}} e^{-\tau |\gamma|},
    \end{equation}
    where $R =4(1+\|\chi'\|_{\infty})$, with $\chi$ the $C^1$ cutoff function defined above.
  \item Assume $\Lambda=\mathsf{Int}\gamma$ for $\gamma\in\mathcal C_{\leq n}$.
    Then for $x,y\in \{\textsf{e},\textsf{o}\}$,
  \begin{align}

    Z^x_{\Lambda} &\leq \exp\left( \widehat{\psi}_n \Delta_{x} |\Lambda \cap V_{x}| + c_n |\gamma| \right) 
    \\

  \abs{\frac{d Z^{y}_{\Lambda}}{d\lambda_{x}}} &\leq \frac{|\Lambda\cap V_{x}|}{\lambda_{x}} \exp
    (\widehat \psi_{n} \Delta_{y} |\Lambda\cap V_{y}| +
    c_{n}|\gamma|).
  \end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

