[Defn eq: def of bfL and bfM of arXiv:2608.23156, 'Disc counting statistics of the real Ginibre ensemble'] {Structured matrices}
Let $\mathbf{L}_N(R)$ and $\mathbf{M}_N(R)$ be the $n\times n$ matrices with
entries
\begin{equation}
\begin{split}
[\mathbf{L}_N(R)]_{j,k} &:= \frac{\gamma(2j-1,NR^2)}{\Gamma(2j-1)} \delta_{j,k},
\\
[\mathbf{M}_N(R)]_{j,k} &:= \frac{ \gamma(j+k-\tfrac{3}{2},N R^2)}{\sqrt{2\pi\Gamma(2j-1)\Gamma(2k-1)}}, 
\end{split}
\end{equation}
where $\delta_{j,k}$ denotes the Kronecker delta.

We further define the $n\times n$ matrices $\mathbf{E}_{N,1}(R)$ and
$\mathbf{E}_{N,2}(R)$ by
 \begin{equation}
 \begin{split} 
        [\mathbf{E}_{N,1}(R)]_{j,k} &:= \frac{ 2^{j-\frac{1}{2}} N^{k-1} R^{2k-2} e^{-\frac{NR^2}{2}} \gamma(j-\tfrac{1}{2}, \tfrac{NR^2}{2})}{\sqrt{2\pi\Gamma(2j-1)\Gamma(2k-1)}},
        \\ 
        [\mathbf{E}_{N,2}(R)]_{j,k} &:= \frac{ E_N(j,k;R) }{\sqrt{2\pi\Gamma(2j-1)\Gamma(2k-1)}}.   
 \end{split}
    \end{equation}
Here, $\delta_{j,k}$ denotes the Kronecker delta, and
    \begin{equation}
        E_N(j,k;R):= -(NR^2)^{j+k-\frac{3}{2}} \int_0^\pi   \sin((2j-2k +1)\theta) e^{-NR^2 \cos 2\theta} \operatorname{erfc}(\sqrt{2N}R \sin\theta)\,d\theta .
    \end{equation}

