[Defi def:elec_energy of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] [Electric energy]
Let $I\subset \IR$ be an interval.
\begin{enumerate}
    \item We call electric fields on $I$ the set of all vector fields $E$ in $L^p_{loc}(I\times \IR,\IR\times \IR)$, for some $1<p<2/(s+1)$ fixed
\item Let $\xi$ be a finite point configuration in $I$ and $E$ an electric field on $I$. We say that $E$ is compatible with $\xi$ in $I$ provided 
\begin{align}
    -\textup{div}\,\left(\left\lverty\right\rvert^sE\right)=c_s\left(\xi-\delta_{\IR}\right) \text{ in }I\times \IR,
\end{align}
in the sense of distributions. Here  $\delta_{\IR}$ is the Radon measure on $\IR\times \IR$ defined by \begin{align*}
    \int_{\IR^2} f(x,y) d\delta_{\IR}(x,y)=\int_{\IR} f(x,0)dx,\quad f\in C_c(\IR^2,\IR).
\end{align*}
Similarly, in (equation eq:hypersurf of the paper) the point configuration $\xi$ is interpreted as a measure on $\IR^2$ via  
\begin{align*}
    \int_{\IR^2} f(x,y) d\xi(x,y)=\int_{\IR} f(x,0)d\xi(x)\quad f\in C_c(\IR^2,\IR).
\end{align*}
\item If $E$ is compatible with $\xi$ in $I$, for $\eta\in (0,1)$  we define the $\eta$-truncation of the electric field $E$ as
\begin{align*}
    E_{\eta}(x,y):=E(x,y)-\sum_{p\in \xi\cap I}\nabla f_{\eta}((x,y)-(p,0)),
\end{align*}
    where $f_{\eta}$ is the function
    \begin{align*}
        f_{\eta}(x,y):=\left(g(x,y)-g(\eta)\right)_+
    \end{align*}
     and $g(\eta)$ is defined by $g(\eta)=g(\eta,0)$.
\item Let $\xi$ be a point configuration on $\IR$. We define the global electric energy of $\xi$ as
\begin{align*}
     \tilde{\mathcal W}^{elec}(\xi):=\inf_E \left(
    \lim_{\eta\to 0}\left( 
    \limsup_{n\to \infty}\frac{1}{\left\lvert\Lambda_n\right\rvert}\frac{1}{c_s}\int_{\Lambda_n\times \IR}\left\lverty\right\rvert^{s}\norm{E_{\eta}}^2-g(\eta)
    \right)
    \right),
\end{align*}
where the $\inf$ is taken over electric fields $E$ that are compatible with $\xi$ in $\IR$.
\item For $\mathsf{P}\in \mathcal P_{s,1}(\Gamma)$ we set \begin{align*}
    \mathcal W^{elec}(\mathsf{P}):=\int \tilde{\mathcal W}^{elec}(\xi)\mathsf{P}(d\xi).
\end{align*}


\end{enumerate}

[Lem lem13 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Let $\delta_1$ be as in Lemma (lem11 of the paper). Then there exist $B=B(a,h)>0$, $\Gamma_2=\Gamma_2(a,h)>0$ and $\Gamma_3=\Gamma_3(a,h)>0$
  such that if ((init of the paper)) holds, and if $T\in (0,T_{max}]$ is such that
  \begin{equation} \label{uut}
	|u| + |u_t| \le \delta_1
	\qquad \mbox{in } \Omega\times (0,T),
  \end{equation}
  then for
  \begin{equation} \label{F1}
	{\mathcal{F}}_1(t):=\frac{1+Ba}{2} \int_\Omega |\nabla u|^2
	+ \int_\Omega H^{(1)}(u,u_t) + B \int_\Omega H^{(2)}(u,u_t),
	\qquad t\in (0,T_{max}),
  \end{equation}
  we have
  \begin{equation} \label{13.1}
	\Gamma_2 \int_\Omega v^2 \le {\mathcal{F}}_1(t) \le \Gamma_3 \int_\Omega |\nabla u|^2 + \Gamma_3 \int_\Omega |\nabla u_t|^2
	\qquad \mbox{for all } t\in [0,T)
  \end{equation}
  and 
  \begin{eqnarray}\label{13.2}
	{\mathcal{F}}_1'(t) + \Gamma_2 {\mathcal{F}}_1(t)
	\le \Gamma_3 \int_\Omega |u|\cdot |f(u,u_t,\nabla u,\nabla u_t)|
	+ \Gamma_3 \int_\Omega |u_t|\cdot |f(u,u_t,\nabla u,\nabla u_t)|
	+ \Gamma_3 \int_\Omega |u_t|^3

  \end{eqnarray}
  for all $t\in (0,T)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:stabAction of arXiv:2601.19630, 'Mass generation for the two dimensional O(N) Linear Sigma Model in the large N limit'] Let $\varphi \in C^{\infty}(\Lambda_{L})$ and $p \geq 1$.  
The following uniform bound holds:
\begin{align}
\sup_{N \in \mathbb{N}, \epsilon>0 }\bigg \|\int_{\Lambda_{L}}\frac{1}{N}: \|Z_{\epsilon}(x)\|^{4}_{\mathbb{R}^{N}}:_{m} \varphi(x) dx \bigg \|_{L^{p}(d\mu_{m,L}^{\otimes N})} &\lesssim \|\varphi\|_{L^{2}(\Lambda_{L}) }  m^{-1} (p-1)^{2}.

\end{align}
Furthermore, for any  $\epsilon, \kappa>0$ and $\delta< \frac{1}{2}$ it holds
\begin{align}
&\bigg \|\int_{\Lambda_{L}}\frac{1}{N} \big (: \|Z_{\epsilon}(x)\|^{4}_{\mathbb{R}^{N}}:_{m}-:\|Z_{\kappa}(x)\|^{4}_{\mathbb{R}^{N}}:_{m} \big ) \varphi(x) dx \bigg \|_{L^{p}(d\mu_{m,L}^{\otimes N})} \nonumber \\
&\qquad\qquad \lesssim \|\varphi\|_{L^{2}(\Lambda_{L}) } |\epsilon-\kappa|^{\delta} m^{-(1+\delta) }(p-1)^{2}.
\end{align}

