[Theorem 1 of arXiv:2411.13062, 'Graphon-Theoretic Approach to Central Limit Theorems for $\epsilon$-Independence'] Let $(g_n)_{n \ge 1}$ be a sequence of finite simple graphs where $V(g_n)=[n]$. Assume that $g_n \to w$ in the graphon sense. Let $a_1^{(n)},\ldots,a_n^{(n)} \in \mathcal{A}$ be $g_n$-independent identically distributed centered (self-adjoint) random variables with variance one, for every $n \ge 1$. Then 
    \begin{align*}
        S_n=\frac{1}{\sqrt{n}}\sum_{k \in [n]}a_k^{(n)}
    \end{align*}
    converges in distribution to a law $\mu_w$ that depends only on $w$. Moreover, its odd moments vanish, whereas, for any $p\in \mathbb{N}$, we have
    \begin{align*}
        \int x^{2p}\, \text{d}\mu_w=\sum_{\pi \in P_2(2p)}\rho(f_\pi,w).
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition d:dir-space of arXiv:2510.13659, 'On the energy image density conjecture of Bouleau and Hirsch'] We call $(X,d,\mu, \mathcal{E}_p, \mathcal{F}_p, \Gamma_p)$ a local $p$-Dirichlet space if the following hold:
		\begin{enumerate}  
			\item \textbf{Locally compact space}: $(X,d,\mu)$ is a locally compact metric space equipped with a Radon measure $\mu$.
			\item \textbf{Completeness:} 	The space $\mathcal{F}_p$  is a subspace of $L^p(X,\mu)$ and
			$\mathcal{E}_p: \mathcal{F}_p \to [0,\infty)$ is a non-negative function such that $\mathcal{F}_p$ is a Banach space when equipped with the norm $\norm{f}_{\mathcal{F}_p}=(\norm{f}_{L^p}^p+\mathcal{E}_p(f))^{1/p}$.
			\item \textbf{Homogeneity:} For all $f\in \mathcal{F}_p$ there exists a finite non-negative Borel measure $\Gamma_p \langle f \rangle$ on $X$ such that $\Gamma_p \langle f \rangle(X)= \mathcal{E}_p(f)$   and for all $\lambda \in \mathbb{R}$
			\[
			\Gamma_p\langle \lambda f\rangle = |\lambda|^p \Gamma_p\langle f\rangle.
			\]
			\item \textbf{Sublinearity:} For every $f,g\in \mathcal{F}_p$ and every Borel set $A\subset X$, 
			\begin{equation} 
				\Gamma_p\langle f+g\rangle(A)^{\frac{1}{p}}\le \Gamma_p\langle f\rangle(A)^{\frac{1}{p}}+\Gamma_p\langle g\rangle(A)^{\frac{1}{p}}
			\end{equation}
			\item \textbf{Chain rule:} For all $f\in \mathcal{F}_p$, $g\in \Lip(\mathbb{R})$ with $g(0)=0$,  we have $g \circ f \in \mathcal{F}_p$ and
			\begin{equation} 
				d\Gamma_p\langle g\circ f\rangle \le \LIP[g]^p d\Gamma_p\langle f\rangle.
			\end{equation}
			\item \textbf{Locality:} For every $f\in \mathcal{F}_p$ and open set $A\subset X$, if $f|_A=c$ $\mu$-a.e., then $\Gamma_p\langle f\rangle(A)=0$. 
			\item \textbf{Weak lower semicontinuity:} For every $f\in L^p(X)$, and for any sequence of functions $(f_i)_{i \in \mathbb{N}}$ in $\mathcal{F}_p$ such that $f_i\to f \in L^p(X)$ with $\sup_{i\in \mathbb{N}} \mathcal{E}_p(f_i)<\infty$, then $f\in \mathcal{F}_p$ and
			\begin{equation} 
				\Gamma_p\langle f \rangle(A)\le \liminf_{i\to \infty} \Gamma_p\langle f_i \rangle(A)
			\end{equation}
			for every Borel set $A\subset X$. 
		\end{enumerate}

[Cor box-product-bifun of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] For any compact Lie group $G$, the functor
    \begin{equation}
        {-}\boxtimes{-}\colon\cat{$\bm G$-$\textbf{\textup{L}}$-Top}\times\cat{$\bm G$-$\textbf{\textup{L}}$-Top}\to\cat{$\bm G$-$\textbf{\textup{L}}$-Top}
    \end{equation}
    is homotopical and a left Quillen bifunctor.
    \begin{proof}
        We may factor $((eq:box-product-single-G of the paper))$ as
        \[
            \cat{$\bm G$-$\textbf{\textup{L}}$-Top}\times\cat{$\bm G$-$\textbf{\textup{L}}$-Top}\xrightarrow{\;{-}\boxtimes{-}\;}\cat{$\bm{(G\times G)}$-$\textbf{\textup{L}}$-Top}\xrightarrow{\;\Delta^*\;}\cat{$\bm G$-$\textbf{\textup{L}}$-Top},
        \]
        where $\Delta=(\textup{id},\textup{id})\colon G\to G\times G$ is the diagonal embedding. The first functor is a homotopical left Quillen bifunctor by the previous lemma, while the second one is homotopical and left Quillen by Lemmas~(lemma:restr-right-Quillen of the paper) and~(lemma:restr-inj-left-Quillen of the paper).
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2606.29131, '2606.29131'] Suppose that Assumption {\rm\ref{a1-1}}{\rm(i)} and Assumption {\rm\ref{a1-2}} hold, and
that there exists $\beta>0$ such that
\begin{equation}
\lim_{\e \to 0}\xi_{1,\beta}(\e)=0,
\end{equation}
where $\xi_{1,\beta}(\e)$ is defined by \eqref{e1-8a}. Fix this $\beta$.
For any $n\ge1$, let $v_n^\e$ be defined by \eqref{e2-14a} above with $h\in \M_{\beta}$. Then, for any $n\ge1$, there exists a constant $C_0(n)>0$ such that for all $\e>0$,
\begin{equation}
\begin{split}
\|v_{n}^\e\|_{L^2(\R^d;dx)}\le
C_0(n)\left(\xi_{1,\beta_0}(\e)+\xi_{2,\beta_0}(\e)\right)^n,
\end{split}
\end{equation}
where $\beta_0:=\min\{\alpha,\beta\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

