[Definition 75 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Put
\begin{equation}
\bZ= C([0,\infty),\rU^\prime),
\end{equation}
and let $X$ be the canonical process on $\bZ$ defined by
 \[
 X: [0,\infty) \times  \bZ \ni (t,\omega) \mapsto \omega(t) \in \rU^\prime.
 \]
As in \cite{Mik+Roz_1998}, we introduce the following objects 
 \begin{align}
     \mathscr{D}_t= \sigma(X_s,\,s \leq t),\;\;
     \mathscr{D}_{t +}= \bigcap_{s >t} \mathscr{D}_s,\;\;
     \mathbb{D}= (\mathscr{D}_{t +})_{t \in [0,T]}, \mbox{ and }
     \mathscr{D}= \sigma(X_s,\,s \geq 0),
      \end{align}
and we also refer the reader to the definition \eqref{eqn-D_t-D_t+} and \eqref{eqn-mb-D}.

[Definition 3 ($(\beta,\sigma)$-consistency of $\emprashomonset$) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] Given $\emprashomonset$ with distribution $\tau$, a random model $\rf$ $\iid \tau$, an instance $x \in \dtest$, the expected model $\E_{\rf}[\rf(x)]$ of the empirical Rashomon set $\emprashomonset$ at $x$, a random perturbation $\rlocaltest$ $\iid \Unif(\ltwohsphere(x,\sigma))$, and parameters $\beta \in [-\frac{1}{2},\frac{1}{2}]$ and $\sigma > 0$, let 
	\begin{align}
	 \consistency(\emprashomonset,x)
    =\abs*{\E_{\rf}\bracks*{\rf(x)} 
        - \frac{1}{2}} 
    - \E_{\rf,\rlocaltest}\bracks*{\abs*{\rf(x) - \rf(\rlocaltest)}},
    \end{align}
be the margin of the expected model of $\emprashomonset$ at $x$, penalized by the expected variability around $x$, where the expectation is taken jointly with respect to the perturbation $\rlocaltest$, and the model $\rf$. Then the expected model of $\emprashomonset$ is said to be $(\beta,\sigma)$-consistent at $x$ if, 
    \begin{align} 
    \consistency(\emprashomonset,x)  \ge \beta.
    \end{align}

[Theorem 26 of arXiv:2607.28614, 'Tampered Memory Elephant Random Walk on one-dimensional integer lattice'] Let $\theta_n$ be as in \eqref{Eq: recursion_general_SA}. Suppose the following assumptions are satisfied. 
\begin{enumerate}[i.]
\item $\sup_{n \ge 1} \lVert \theta_n \rVert < \infty$. 
\item $h$ is a Lipschitz function, that is, there exists $L>0$, such that, $\lVert h(x)-h(y) \rVert \le L \lVert x-y\rVert$.
\item $\sup_{n \ge 1} \E \left[ \lVert \Delta M_{n}\rVert ^2 |\FF_{n-1} \right] < \infty$.
\item Assume that $r_n \longrightarrow 0, \text{ a.s.}$ as $n \to \infty$.
\item Let $\theta^*$ be an equilibrium point of $h$, that is, $\theta^* \in \{\theta: \, h(\theta)=0\}$, such that $\langle \theta-\theta^*, h(\theta)\rangle <0$, for all $\theta \neq \theta^*$.
\end{enumerate}
Then, as $n \to \infty$
\begin{equation}

\theta_n \longrightarrow \theta^*, \text { a.s.}
\end{equation}
where the convergence is sample path dependent, in case, $\theta^*$ is not unique. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th:TV_asympt of arXiv:2411.04690, 'Asymptotic distribution of the derivative of the taut string accompanying Wiener process'] Let $(W_t)_{t\geq 0}$ be a Wiener process; for $\mu\in\mathbb{R}$ define
	\begin{equation*}
		X_t := W_t- \mu t,\quad t\geq 0.
	\end{equation*}
	Then, as $T\to +\infty$,
	\begin{equation*}
		\begin{aligned}
		\frac{1}{T}\,TV^{r}(X,[0,T])
		&\xrightarrow{\text{a.s.}}
		m_{r}(\mu),
            \\
            \frac{1}{T}\,UTV^{r}(X,[0,T])
		&\xrightarrow{\text{a.s.}}
		q_r(\mu),
		\end{aligned}
	\end{equation*}
	where
	\begin{equation}

		m_{r}(\mu)=
		\begin{cases}
			\mu \coth({r\mu}),\ &\mu\neq 0;\\
			r^{-1},\ &\mu=0;
		\end{cases}
        \end{equation}
        \begin{equation}

		q_r(\mu)=
		\begin{cases} \frac12 (\mu \coth(r\mu)-\mu),& \mu \not=0; \\
		\frac12 r^{-1},& \mu=0.
	\end{cases}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 66 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] For every $w\in S_n$,
