[Lemma 6 of arXiv:2604.10244, 'Ergodicity for regime-switching neutral stochastic functional differential equations with '] There exist constants \( 0<c_{1}<c_{2}< \) \( \infty \) such that for any \( i \in \S \) and \( 0 \leq  u<t \),
		\begin{equation}
			c_{1} \mathrm{e}^{-\zeta(t-u)} \leq \mathbb{E}_{\mathbb{P}_2}\left[\exp \left(\int_{u}^{t} f\left(\Lambda^{i}(v)\right) \mathrm{d} v\right)\right] \leq c_{2} \mathrm{e}^{-\zeta(t-u)},
		\end{equation}
		where $\mathbb{E}_{\mathbb{P}_2}$ denotes the expectation with respect to $\mathbb{P}_2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop eigenfunction of arXiv:2411.12149, 'Airy limit for $\beta$-additions through Dunkl operators'] [Op]
Fix $\beta>0$, $N\in \mathbb{Z}_{\ge 1}$. For any $k=1,2,\ldots$, 
\begin{equation}
    p_{k}(\mathcal{D}_{1},\ldots,\mathcal{D}_{N})B_{(a_{1},\ldots,a_{N};\beta)}(x_{1},\ldots,x_{N})=p_{k}(a_{1},\ldots,a_{N})B_{(a_{1},\ldots,a_{N})}(x_{1},\ldots,x_{N};\beta).
\end{equation}
Here we evaluate the polynomial $p_k$ on the operators $\mathcal{D}_1, \dots, \mathcal{D}_N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def-Dmut of arXiv:2506.10448, 'Hitting probabilities and the Ekstr\"om--Persson conjecture'] Let $\mu \in \mathcal{P}(\mathbb{R}^d)$. For every $t\geq 0$, let 
\begin{equation}

D_\mu(t):= \{ x \in \spt \mu\mid \dimlocl \mu (x)\leq t \}.
\end{equation}
The lower Hausdorff and packing multifractal spectra of the lower local dimension of $\mu$  
are defined by 
\begin{align*}
F_{\mu}(t)& := \dimh D_\mu(t),\\
H_{\mu}(t)& :=\dimp D_\mu(t),
\end{align*}
where $\dimh$ and $\dimp$ stand for the Hausdorff and packing dimensions, respectively.

[Cor DoubIntCond of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] Under the assumption of Theorem (thm:DoubInt of the paper), one has
\begin{equation}
\int_{0<s<t<1}\big(e^{2\pi i(px_{s}+qx_{t})}-e^{2\pi i(px_{t}+qx_{s})}\big)dy_{s}dy_{t}=0
\end{equation}
for all $p,q\in\mathbb{Z}\backslash\{0\}$ with $p+q\neq 0.$

[Lemma 7 of arXiv:2604.15152, 'The Multinomial Allocation Model and the Random Box Load'] Denote
\[Q_n(r,t):=(r!t!)^{-1}\rE\Big[\xi^r\eta^t(1-q_X-q_Y)^{n-r-t}\Big],\]
where $\eta=nq_Y$.
Then
\begin{equation}
Q_n(r,t)=\rE[p_r(\xi)]\rE[p_t(\xi)]+n^{-1}(r! t!)^{-1}\rE\Big[\xi^r\eta^t\delta_n(r+t,\xi+\eta)\Big],
\end{equation}
 and 
\begin{align}
 Q_n(r,t)&=\rE[p_r(\xi)]\rE[p_t(\xi)]+n^{-1}\Big((r+t)\big(\rE[p_r(\xi)]\rE[p_t(\xi)\xi]+\rE[p_t(\xi)]\rE[p_r(\xi)\xi]\big)-\rE[p_r(\xi)\xi]\rE[p_t(\xi)\xi]\Big) \nonumber\\
&-(2n)^{-1}\Big(\rE[p_r(\xi)]\rE[p_t(\xi)\xi^2]+\rE[p_t(\xi)]\rE[p_r(\xi)\xi^2]\Big)+n^{-2}(r!t!)^{-1}\rE\Big[\xi^r\eta^r \delta_n^*(r+t,\xi+\eta)\Big]. 
\end{align}

