[Proposition many_events_C of arXiv:2603.05491, '\textbf{Local limits of uniform triangulations with boundaries in high genus}'] Fix $n,g,\ell \ge 0$ and $(p_1,\cdots,p_{\ell}) \in (\mathbb{N}^{*})^{\ell}$. We also fix $t \in \mathcal{T}_{\mathbf{p}}(n,g)$ and $\varepsilon > 0,p\ge 4$. Suppose that there exist distinct edges $e_1,\cdots,e_{1000\varepsilon |\mathbf{p}|}$ on $\partial_1\cup \cdots \cup \partial_{\ell}$ such that for all $1 \le j \le 1000\varepsilon |\mathbf{p}|$:
\begin{center}
$(t,e_j)$ satisfies $(\mathcal{O})$ or $(\mathcal{H}_{2\varepsilon^{-1} p })$.
\end{center}  
Then one of the following two statements holds:
    \begin{enumerate}
        \item There exists $I \subset \{1,\cdots,1000\varepsilon |\mathbf{p}|\}$ such that $r:= |I| \ge \varepsilon p^{-1}|\mathbf{p}|$ and denoting by $f_{i}$ for the triangle that lies behind the edge $e_{i}$, we have $t \backslash \bigg(\bigsqcup_{i\in I}f_i\bigg) \in \mathcal{T}_{\mathbf{q}}(n',g')$ for some $\mathbf{q} = (q_1,\cdots,q_{\ell'})$, where $(\ell-\ell')+2(g-g')= r $ and $n' \le n + |\mathbf{p}|$.
        \item There are more than $\varepsilon|\mathbf{p}|$ edges $e \in \partial t$ such that $(t,e)$ satisfies $(\mathcal{C}_{\varepsilon^{-1},p})$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 of arXiv:2608.30409, 'Gradient estimates and volume doubling for locally finite weighted graphs with $CD\psi(n,-'] Let $G=(V,E)$ be a locally finite weighted graph and let $\psi\in C^1(0,+\infty)$ be a concave function with $H_{\psi}<\infty$. Suppose $0<g\in \mathbb{R}^{V}$. Then for any $x\sim y$, 
    \begin{equation*}
        \log\frac{g\left(y\right)}{g\left(x\right)}\leq\sqrt{H_\psi \frac{\mu_{\max}}{w_{\min}}}\sqrt{\Gamma^{\psi}\left(g\right)\left(x\right)}.
    \end{equation*}

