body:
[Definition 5 of arXiv:2609.00736, 'Modalities in non-classical variations of S4'] We say that a $\csf$-model $M = \tuple{W, W^\bot, \preceq, \R, V}$ is:
    \begin{itemize}
        \item \emph{forward confluent} iff $w \R v$ and $w\preceq w'$ implies there is $v'$ such that $w' \R v'$ and $v\preceq v'$;
        \item \emph{downward confluent} iff $w \preceq  v \R v'$ implies there is $w'$ such that $w \R w'$ and $w' \preceq v'$;
        \item \emph{locally linear} iff $w\preceq v$ and $w\preceq u$ implies that either $v\preceq u$ or $u\preceq v$.
    \end{itemize}
    Forward and downward confluence are illustrated in Figure \ref{figure::confluences}.
    \begin{figure}[ht]
        \centering
        \tikzstyle{world}=[circle,draw,minimum size=5mm,inner sep=0pt]
        \begin{tikzpicture}
            \node (w) at (0,-2) {$w$};
            \node (w2) at (0,0) {$w'$};
            \node (v) at (2,-2) {$v$};
            \node (v2) at (2,0) {$v'$};

            \draw[->] (w) -- (w2) node[midway,left] {$\preceq$};
            \draw[->] (w) -- (v) node[midway,below] {$\R$};
            \draw[dashed,->] (v) -- (v2) node[midway,right] {$\preceq$};
            \draw[dashed,->] (w2) -- (v2) node[midway,above] {$\R$};
        \end{tikzpicture}
        \begin{tikzpicture}
            \node (w) at (0,-2) {$w$};
            \node (w2) at (0,0) {$w'$};
            \node (v) at (2,-2) {$v$};
            \node (v2) at (2,0) {$v'$};

            \draw[dashed,->] (w) -- (w2) node[midway,left] {$\preceq$};
            \draw[->] (w) -- (v) node[midway,below] {$\R$};
            \draw[->] (v) -- (v2) node[midway,right] {$\preceq$};
            \draw[dashed,->] (w2) -- (v2) node[midway,above] {$\R$};
        \end{tikzpicture}
        \begin{tikzpicture}
            \node (w) at (0,-2) {$w$};
            \node (w2) at (0,0) {$w'$};
            \node (v) at (2,-2) {$v$};
            \node (v2) at (2,0) {$v'$};

            \draw[->] (w) -- (w2) node[midway,left] {$\preceq$};
            \draw[dashed,->] (w) -- (v) node[midway,below] {$\R$};
            \draw[dashed,->] (v) -- (v2) node[midway,right] {$\preceq$};
            \draw[->] (w2) -- (v2) node[midway,above] {$\R$};
        \end{tikzpicture}
        \caption{Schematics for forward (left), backward (center), and downward (right) confluence. Solid arrows correspond to the universal quantifiers and dashed arrows correspond to the existential quantifiers.}

    \end{figure}

[Corollary smallessoft of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Let $L_{a,N}$ be an LUE with parameters satisfying $\lim\limits_{N\rightarrow\infty}\frac{N}{N+a}=\gamma\in(0,1)$. Suppose $\lambda_{min}^N$ is the least eigenvalue of the $L_{a,N}$ and $TW_2(s)$ is the distribution function of the least eigenvalue of an Airy point process. Let $\tilde{\lambda}^N_{min}:=\frac{\lambda_{min}^N+\mu_L}{\sigma_L}$ be the left-soft-edge-scaled least eigenvalue of $L_{a,N}$. Then for large $N$,
    \begin{equation*}
        |\mathbb{P}\{-\tilde{\lambda}_{min}^N\le s\}-TW_2(s)|\le \frac{g(s,\gamma)e^{-s}}{N^{\frac{2}{3}}}.
    \end{equation*}
    where $g$ is the same function as in Theorem (LUE left soft of the paper).

