[Proposition 3 of arXiv:2608.21551, '\bf Sparse Separable Factor Analysis in the Complex Domain with an Application to Local Fi'] For $j=1,\ldots,d$, suppose $\Sigmab_j=\Lambdab_j\Lambdab_j^\star+\Psib_j$, where $\Psib_j$ is diagonal with positive diagonal entries. There exists a unique vector $(c_1,\ldots,c_d)$ satisfying $c_j>0$ for $j=1,\ldots,d$ and $\prod_{j=1}^d c_j=1$ such that the rescaled parameters $  \widetilde{\Lambdab}_j = c_j^{1/2}\Lambdab_j$ and $  \widetilde{\Psib}_j = c_j\Psib_j$ satisfy
\begin{align}
  \min\left\{
    \operatorname{diag}(\widetilde{\Psib}_1)
  \right\}
  =
  \cdots
  =
  \min\left\{
    \operatorname{diag}(\widetilde{\Psib}_d)
  \right\}.

\end{align}
The rescaling constants are
\begin{align*}
  c_j
  =
  \frac{\overline{\psi}_{\min}}{\psi_{j,\min}},
  \qquad
  \psi_{j,\min}
  =
  \min\left\{
    \operatorname{diag}(\Psib_j)
  \right\},
  \qquad
  \overline{\psi}_{\min}
  =
  \left(
    \prod_{\ell=1}^d\psi_{\ell,\min}
  \right)^{1/d}.
\end{align*}
Moreover, if
$\widetilde{\Sigmab}_j = \widetilde{\Lambdab}_j\widetilde{\Lambdab}_j^\star + \widetilde{\Psib}_j$, then $\widetilde{\Sigmab}_d\otimes\cdots\otimes \widetilde{\Sigmab}_1 = \Sigmab_d\otimes\cdots\otimes\Sigmab_1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:tk of arXiv:2606.05830, '{ Biased Random Walk on $\mathbb Z_+$ with Traps of Linearly Increasing Depth}\footnote{Su'] Fix $0<\lambda\ne 1.$ {\rm(i)} We have
\begin{align}
  E[T_k]= \frac{2\lambda(\lambda^2+\lambda-1)}{(\lambda-1)^2(1+\lambda)}\lambda^{k-1}
-\frac{\lambda^2+2\lambda-1}{(\lambda-1)^2}
+\frac{2\lambda^{2-k}}{(\lambda-1)^2(1+\lambda)},\quad k\ge1,
\end{align}
 and \begin{align}
  E[T_k^2]\le c_2\left(\lambda\vee \lambda^{-1}\right)^{2k}, \quad k\ge 1
\end{align} for some constant $c_2$ depending only on $\lambda.$

 {\rm(ii)}
  There exist constants $c_3>0$ and $\delta>0$ depending only on $\lambda$ such that
\begin{equation}
P(T_k \ge c_3 (\lambda\vee\lambda^{-1})^k) \ge \delta,\quad k\ge1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2608.29984, 'On Cauchy Problems for Parabolic Equations with Rough Coefficients'] Assume $u_{0}(x)$ and $f(t,x)$ satisfies the assumptions in Theorem \ref{main}, then
\begin{equation}
\begin{split}
&\|u_{0}^{\epsilon}\|_{\dot{H}^{r}(\R)}\lesssim \|u_{0}\|_{\dot{H}^{1}(\R)}+\|u_{0}\|_{\dot{H}^{r}(\R)}+o_{\epsilon}(1),\ \forall r\in[1,1+s],\\
&\|f^{\epsilon}\|_{L^{2}([0,T]\times H^{t}(\R))}\lesssim \|f\|_{L^{2}([0,T]\times H^{t}(\R))}+o_{\epsilon}(1),\ \forall t\in[0,s].
\end{split}
\end{equation}
Assume $u_{0}(x)$ and $f(t,x)$ satisfies the assumptions in Theorem \ref{maintwo}, then
\begin{equation}
\begin{split}
&\|u_{0}^{\epsilon}\|_{H^{r}(\R)}\lesssim \|u_{0}\|_{H^{r}(\R)}+o_{\epsilon}(1),\ \forall r\in[0,s],\\
&\|f^{\epsilon}\|_{L^{2}([0,T]\times H^{t}(\R))}\lesssim \|f\|_{L^{2}([0,T]\times H^{t}(\R))}+o_{\epsilon}(1).\ \forall t\in [-1,s-1].
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

