[Lem 180 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] [annealed second moment bounds for 
$\bar{D}^{\RomIII}$ and 
$\bar{D}^{\frozen,\RomIII}$]

Let $\bar{D}^{\RomIII}$ and $\bar{D}^{\frozen,\RomIII}$ 
be defined by \eqref{e:barD} and \eqref{e:barD.plus} (see also \eqref{e:drift.error.III}).  We then have
	\[
	\frac{\E[\Delta\bar{D}^{\RomIII}(q_d)^2]}
		{q_d p'(q_d)}
	\le \frac{L^{O(1)}\BUCKETS \delta}{N}
	\]
for all $0\le d\le \dmax-1$. 
The same bound holds with $\bar{D}^{\frozen,\RomIII}$ in place of $\bar{D}^{\RomIII}$.
\begin{proof}
Recalling the notation from \eqref{e:normalized.vectors.x},
we can rewrite \eqref{e:drift.error.III} as
	\[
	\frac{\Delta\bar{D}^\RomIII(q_d)}
		{[\delta_d q_d p'(q_d)]^{1/2}}
	= \frac1{|B|^{1/2}}
	\bigg(
	\sum_{a\in B}
	\frac{\bmeta^a(q_{d+1})}{|B|^{1/2}},
		\frac{\bar{\bx}(q_d)}{N^{1/2}}
		\bigg)
	\equiv
	\frac1{|B|^{1/2}}
	\bigg(\bmeta^B(q_{d+1}),
	\frac{\bar{\bx}(q_d)}{N^{1/2}}
		\bigg)\,.
	\]
Note that $\bar{\bx}(q_d)$ is measurable with respect to $\cG(q_d)$, and $\bmeta^B(q_{d+1})$ is a standard gaussian in $\R^N$ conditional on $\cG(q_d)$. It follows that
	\[\frac{\E[\Delta\bar{D}^\RomIII(q_d)^2]}
		{\delta_d q_d p'(q_d)}
	\le 
	\frac{1}{M}\E\bigg[ \sum_{B\in\mathcal{B}(q_d)} 
	\bigg(\bmeta^B(q_{d+1}),
	\frac{\bar{\bx}(q_d)}{N^{1/2}}
		\bigg)^2\bigg]
	\le \frac{O(1)\BUCKETS
		\E[\|\bar{\bx}(q_d)\|^2]}{MN}\,,
	\]
and the claim for $\bar{D}^\RomIII$ follows by combining Lemma~\ref{l:bar.x.subgaus} with Lemma~\ref{l:sg.norm.bound}. The claim for
$\bar{D}^{\frozen,\RomIII}$ then follows by using \eqref{e:barD.vs.plus}.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 (Finite-volume conditional relative entropies are (in general non-uniformly) controlled by entropy-production per site) of arXiv:2608.13677, 'Asymptotically complete free-energy dissipation: \\ a coarse MLSI holds at any positive te'] \label[lemma]{lemma:MLSI_type_bound_for_finite_volume_conditional_entropies}
    For every \(n \in \mathbb{N}\) there is a \(\delta_n > 0\) such that for all \(\mu \in \mathcal{P}_\theta\) it holds 
    \begin{align}
        \frac{h_{\Lambda_n \vert \Lambda_n^c}(\mu)}{\vert \Lambda_n\vert}
        \,\leq\, \delta_n^{-1} \,\sigma(\mu).
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2609.02808, 'Minimizers of Laplace eigenvalues under a lower curvature bound'] Let $D>0$ and let $\varphi\colon[0,D]\to[0,\infty)$ be continuous, positive on $(0,D)$,
and such that
\begin{equation}
\varphi''+\varphi\ \le\ 0\qquad\text{in the sense of distributions on }(0,D).
\end{equation}
Then
\begin{equation}
\mu_j(\varphi)\;\ge\; j(j+1)\qquad\text{for every } j\ge 0 .
\end{equation}
If equality holds for some $j\ge1$, then $D=\pi$ and $\varphi$ is a positive constant
multiple of $\sin$, so that $X_\varphi$ is the Legendre model. (Proof in the paper; no proof environment follows the statement in the TeX.)

