[Theorem thm:tailrl-weight-form of arXiv:2609.02987, 'Tail Likelihood Reinforcement Learning'] For an input $x$, the population-level gradient of TailRL{} is estimable as,

\begin{equation}
\nabla_\theta J_{\mathrm{TailRL{}}}(\theta;x)
=\mathbb{E}_{z\sim\pi_\theta(\cdot\mid x)}
\left[
\left(
\int_0^{r(x,z)}
\frac{d\tau}{p_\theta(x,\tau)}
\right)
S(x,z)
\right].

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 17 of arXiv:2609.03869, '\bf Sharp asymptotics for a transport model with a nonlocal condition of the Fisher-KPP ty'] \begin{equation*}
	\limsup_{t\to+\infty}\big(\psi_1(t,i,x)-\mathcal{V}(t,i,x)\big)\le 0\le \liminf_{t\to+\infty}\big(\psi_2(t,i,x)-\mathcal{V}(t,i,x)\big),
	\end{equation*}
 uniformly in $i\in[0,i_\dagger)$ and $X^-(t)\le x\le X^+(t-i)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 28 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] Under the same assumptions as in Lemma \ref{lemma_separation}, one has 
 	 \begin{equation}
 	 	\mathbb{P}\big( z_i^{\diamond} \xleftrightarrow{} \cup_{x\in \widetilde{\eta}} \widetilde{B}_x(\cref{const_lemma_separation2} m_\diamond ) \cup \mathfrak{B}^{\diamond}_{m_\diamond,\cref{const_lemma_separation2}}  \mid v_i \xleftrightarrow{} w_i \big) \le  \epsilon. 
 	 \end{equation}

