	\begin{align*}
		\Q^{(k),\bm \theta}_{T,r}&\paren{\chi_\emptyset\in {\rm d}t,\bo{L}_{\emptyset}=\bm{\ell}\left| c (\varsigma^{(1)}_{t+})=i , \tau_1>t\right. }= \frac{\ell_ip_r(\bm{\ell})\paren{\prod_{m\in[d]}\E_m\left[e^{-\bm \theta\cdot \bo Z_{T-t}}\right]^{\ell_m}}	}{\E_r\left[Z^{(i)}_{t}\prod_{m\in[d]}\E_m\left[e^{-\bm \theta\cdot \bo Z_{T-t}}\right]^{Z^{(m)}_{t}}\right]}\alpha_re^{-\alpha_rt}{\rm d}t.	
	\end{align*}

