[Theorem 5 (Kac, Pleijel) of arXiv:2507.06186, '2507.06186'] If $\partial D$ is sufficiently regular (e.g., smooth), then
\begin{align}

\msf T_0(t)=\tfrac{\msf{A}(D)}{2\pi}t^{-1}
-\tfrac{\msf{L}(\partial D)}{4\sqrt{2\pi}}t^{-1/2}+O(1)\qquad\text{as }t\to0,
\end{align}
where $\msf L(\partial D)$ is the length of the curve
$\partial D$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2608.31008, 'Stability of gravitational instantons with a bounded Killing vector field'] Assume the geometric hypotheses of \cref{thm:intro-bounded} and
normalize $K$ as above.  For every $0<\varepsilon<\tfrac12$ there is
a solution of
\begin{equation}
 \Delta u=V+2, \text{ with}
\end{equation}
\begin{equation}
 u=-\tfrac{r^2}{2}+w,\qquad
 |\nabla_b^jw|=\mathcal{O}(r^{1+\varepsilon-j}),
\end{equation}
and the tensor $k_K$ of \eqref{eq:k-def} satisfies
\begin{equation}
 |\nabla^jk_K|=\mathcal{O}(r^{-1+\varepsilon-j}),\qquad j=0,1,2.
\end{equation}
In particular, it satisfies the decay assumptions for dynamical destabilizations of ALF metrics from \cite[Definition 5.1]{KO}.

[Lem Wiener:caterpillar of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] In the case of a caterpillar, we have
    \begin{align*}
    \begin{split}
        W_n=&\sum_{i<j} (j-i+2)I_i^{(n)}I_j^{(n)}+\sum_{i,j=1}^m (\vert j-i\vert+1)I_j^{(n)}\\
        &+\sum_{i=1}^m I_i^{(n)}(I_i^{(n)}-1)+\frac{(m-1)m(m+1)}{6}.
    \end{split}
    \end{align*}

[Proposition 11 (Chaos asymptotics, \(H^*(m)<1/2\)) of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] Let \(\delta(\varepsilon)>0\) be such that \(\delta(\varepsilon)\xrightarrow{\varepsilon\rightarrow 0} 0\) and \(\varepsilon/\delta\rightarrow 0\) as \(\varepsilon\rightarrow 0\). For \(\varepsilon\) small enough, for any \(0\leq r\leq m-1\),
\begin{equation}

\mathbb{E}[T_{2m-2r}^2]\leq D^{\mathrm{Diag}}_{H,m,r}\delta+D^{\mathrm{Off}}_{H,m,r}f(\delta,\varepsilon,m,r),
\end{equation}
with \(D^{\mathrm{Diag}}_{H,m,r}, D^{\mathrm{Off}}_{H,m,r}>0\) read off Lemmas~\ref{lem: second chaos m=1 H<1/2}--\ref{lem: asymptotics m>1 H<1/2}, and
\begin{equation}

f(\delta, \varepsilon, m,r) =
\begin{cases}
\delta(\varepsilon/\delta)^{2m(2-2H)-2} \quad &r< r_I\wedge r_S\\
\varepsilon^{2(m-r)(2-2H)} \quad &r> r_I\vee r_S\\
\delta^{2(m-r)(2H-2)}(\varepsilon/\delta)^{2m(2-2H)-2} \quad &r_S< r < r_I\\
\delta(\varepsilon/\delta)^{2(m-r)(2-2H)} \quad &r_I< r< r_S
\end{cases}
\end{equation}
The borderline cases \(r(2H-2)=-1\) or \(2(m-r)(2H-2)=-1\) carry the same orders up to logarithmic corrections: when \(r=r_I\) and \(r(2H-2)=-1\),
\[
f(\delta,\varepsilon,m,r) \sim
\begin{cases}
\delta(\varepsilon/\delta)^{2(m-r)(2-2H)}\log(\delta/\varepsilon)^2, & H^*(m)>1/4,\\
\varepsilon^{2(m-r)(2-2H)}\log(\delta/\varepsilon)^2, & H^*(m)<1/4;
\end{cases}
\]
when \(r=r_S\) and \(2(m-r)(2H-2)=-1\),
\[
f(\delta,\varepsilon,m,r) \sim
\begin{cases}
\varepsilon^{2(m-r)(2-2H)}\log(\delta), & H^*(m)>1/4,\\
\log(\delta)(\varepsilon/\delta)^{2m(2-2H)-2}, & H^*(m)<1/4;
\end{cases}
\]
and when \(r=r_I=r_S\) (so that \(H^*(m)=1/4\)), \(f(\delta,\varepsilon,m,r)\sim \varepsilon\log(\delta)\log(\delta/\varepsilon)\). In particular,
\begin{equation}

\mathbb{E}[(C_{\varepsilon, \delta}-\mathbb{E}[C_{\varepsilon, \delta}])^2]\lesssim \delta+\varepsilon^{2(2-2H)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 29 of arXiv:2607.28614, 'Tampered Memory Elephant Random Walk on one-dimensional integer lattice'] Let $\theta^*$ be an equilibrium point for the mean field function $h$, that is, $\theta^* \in \{\theta: \, h(\theta)=0\}$, where $h$ is as in \eqref{Eq: recursion_general_SA}. Let $\theta_n$, $\Delta M_n$, and $r_n$ be as in \eqref{Eq: recursion_general_SA}, and $\theta_n \longrightarrow \theta^*, \text{ a.s.}$ as $n \to \infty$. 
Further, assume that 
\begin{equation}

h(\theta)= \left(\theta -\theta^*\right) Dh(\theta^*)+ o(\lvert \lvert \theta -\theta^*\rvert \rvert^{1+\epsilon}) \text{ as } \theta \rightarrow \theta^*, \text{ for some } \epsilon>0,
\end{equation}
and the following version of the Lindeberg-Feller condition holds
\begin{equation}

\frac{1}{n} \sum_{m=1}^n \E\left[\lvert \lvert \Delta M_m\rvert \rvert ^2 \mathbf{1}_{\{\lvert \lvert \Delta M_m\rvert \rvert \ge \epsilon \sqrt{n}\}}\mid  \FF_{m-1}\right] \longrightarrow 0, \text{ a.s. or in } L_1, \text{ for all } \epsilon>0.
\end{equation}
Let $\Gamma$ be a positive semi-definite matrix, such that,
\begin{equation}

\frac{1}{n} \sum_{m=1}^n \E \left[\Delta M_m \left(\Delta M_m\right)^\top \mid \FF_{m-1}\right]\rightarrow \Gamma, \text { a.s. or in } L_1. 
\end{equation}
Let the maximum eigenvalue $\rho^*=\frac{1}{2}$, and the error $r_n$ satisfy the following 
\begin{equation}

\sum_{k=1}^n r_k = o\left(\sqrt{\frac{n}{log n}}\right), \text{ a.s.}
\end{equation}
Then 
\begin{equation}

\frac{\sqrt{n}}{\sqrt{\log n}} \left(\theta_n -\theta^*\right)\stackrel{d}{\longrightarrow} N\left(0, \widetilde{\Sigma}\right) \text{(stably)},
\end{equation}
where 
\begin{equation}

\widetilde{\Sigma}= \lim_{n \to \infty}\frac{1}{\log n}\int_{0}^{\log n} {\left(e^{-(D(-h(\theta^*)-\frac{1}{2}I_d) u}\right)^\top \Gamma e^{-(D(-h(\theta^*)-\frac{1}{2}I_d) u} \mathrm{d}u}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 1 of arXiv:2506.17045, '\LARGE{On bivariate Archimax copulas: Level sets, mass distributions and related results}'] Let $A \in \mathcal{A}$, $h_A$ be defined as in eq. \eqref{eq:fct_h} and let $L$, $R$ be defined according to eq. \eqref{eq:definition_L_R}. Then the following assertions hold:
   \begin{itemize}
        \item[$(i)$] $h_A$ is a non-increasing, convex function on $(0,1]$, which is strictly decreasing on $(0,R]$ and fulfills $h_A(t) = 1$ for every $t \in [R,1]$;
        \item[$(ii)$] $h_A^{[-1]}$ is a strictly decreasing and convex function on $[1,\infty)$;
        \item[$(iii)$] $G_A$ is a non-negative, non-decreasing and right-continuous function on $\mathbb{I}$, which is positive on $(L,1]$. Furthermore, if $L>0$, $G_A(t) = 0$ holds for every $t \in [0,L)$ and $G_A(t) = 1$ holds for every $t \in [R,1]$.
    \end{itemize}

[Theorem 9 (Hard Edge) of arXiv:2511.12623, 'The eigenvector bead process'] We recall Convention~\ref{conv:inverse-stieltjes-branches}, and use the same convention for the inverse branches of the Stieltjes transform appearing below. 
Let $\alpha = T - N \ge 0$ denote the rectangularity parameter of the Wishart ensemble.
For $u, v \in \mathbb{N}$, the overlaps satisfy
\begin{equation}
\Omega^{(N)}_{u,v}
\;\mathrel{\underset{N \to \infty}{\overset{d}{\sim}}}\;
\frac{g_v \, \sqrt{\xi_v}}{\,D_{g^2, \xi, \alpha}^{-1}(0)_u - \xi_v\,}
\left(
    \sum_{v' \in \mathbb{N}} 
    \frac{(g_{v'})^2\xi_{v'}}{\bigl(D_{g^2, \xi, \alpha}^{-1}(0)_u - \xi_{v'}\bigr)^2}
\right)^{-1/2}.
\end{equation}

\noindent
Here $(\xi_u)_{u \in \mathbb{N}}$ follow the Bessel point process associated with the parameter $\alpha$, 
and $(g_u)_{u \in \mathbb{N}}$ are i.i.d.~standard Gaussian random variables 
$\mathcal{N}(0,1)$, independent of $(\xi_u)$.

\medskip
\noindent
The function $D_{g^2, \xi, \alpha}(z)$ is defined by
\begin{equation}
D_{g^2, \xi, \alpha}(z)
= \sum_{i \in \mathbb{N}} \frac{g_i^2}{ \xi_i-z}
- \frac{\chi_{\alpha}}{z},
\end{equation}
where $\chi_{\alpha}$ denotes a chi-square random variable with $\alpha$ degrees of freedom. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary eq:zero-rate-localized-complement of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[corollary]{cor:nonnegative-bulk}
\leavevmode\par\noindent
In the setting of (thm:conditional-transfer of the paper), suppose that both
de-regularization defects vanish and \(\Phi\ge0\).  If
\begin{equation}
 \overline\Lambda_L^J(V)\le0,
\end{equation}
then the full exact-complexity limit exists and equals \(\Phi\).

[Proposition prop:cavitylower of arXiv:2606.11248, 'Persistent Homology of the Planar Wiener Sausage: Brownian Scaling and a Logarithmic Expec'] For every compact connected $A\subset\mathbb{R}^{2}$ and every $r>0$,
\begin{equation}
N_{A}(r)\le\beta_{1}\bigl(A^{(r)}\bigr).
\end{equation}

[Definition Prop_BundleOfAdmissibleZModTwoZSpinors of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Consider the tame Fréchet space bundle
  \begin{equation*}
    {\mathbf{F}}_{00} \coloneq w_{\log}^{-1}{\mathbf{E}}_{0}.
  \end{equation*}
  The \defined{universal bundle of admissible $\mathbb{Z}/2\mathbb{Z}$ spinors} is the tame Fréchet subbundle
  \begin{equation*}
    {\mathbf{E}}_{00}
    \coloneq
    {\mathbf{E}}_{0} \cap {\mathbf{D}}^{-1}{\mathbf{F}}_{00}
    \subseteq
    {\mathbf{E}}_{0};
  \end{equation*}
  indeed, the preceding discussion and direct inspection show that the atlas constructed in (Def_UniversalBundles_Atlases of the paper) induces an atlas for ${\mathbf{E}}_{00}$;
  cf.~(Rmk_BundleOfSingularSpinors of the paper)~(Rmk_BundleOfSingularSpinors_Robust of the paper).
  Of course, the tame Fréchet space structures on the fibres of ${\mathbf{E}}_{00}$ is the one defined in (Prop_K_Tame of the paper).
  Denote by
  \begin{equation*}
    {\mathbf{E}}_{00}^* \subseteq {\mathbf{E}}_{00}
  \end{equation*}
  the open subset of \defined{non-degenerate} admissible $\mathbb{Z}/2\mathbb{Z}$ spinors;
  that is: the subset consisting of those admissible $\mathbb{Z}/2\mathbb{Z}$ spinors $({\mathbf{p}},[{\mathfrak l}];\Phi) \in {\mathbf{E}}_{00}$ for which ${\mathbf{L}}_\Phi$ is injective.

[Lemma lem:nonlinear_est of arXiv:2606.28575, 'Global smooth solutions by high mode Lie-Transport noise for Logarithmically Hyperdissipat'] For all $g$ verifying (hp_correction of the paper) and every $\xi, \omega \in H^{-1/4}_g$, denoting $v=K[ \xi], \ u = K[\omega]$ it holds 
    \begin{equation}
        \|\nabla \times (\operatorname{div} (u\otimes v))\|_{H^{-2}_g}\le \|\omega \|_{H_g^{-1/4}}\|\xi \|_{H_g^{-1/4}}. 
    \end{equation}
    As a consequence, it holds 
    \begin{equation}
        \|\mathcal{L}_u\omega - \mathcal{L}_{v}\xi\|_{H^{-2}_g}\le C( \|\omega\|_{H_g^{-1/4}} + \|\xi\|_{H_g^{-1/4}})\|\omega - \xi\|_{H^{-1/4}_g}.
    \end{equation}

