body:
[Thm 1 of arXiv:2607.14674, 'On the entropy of the log-normal distribution'] The entropy $H[g_r]$ of the family of densities \eqref{eq:SC} is given as the power series
\begin{equation}
H[g_r]=H[g]+\alpha r -\sum_{k=1}^\infty \frac{\beta_k}{2k(2k-1)}r^{2k},\quad -1\le r\le 1,
\end{equation}
where
\begin{eqnarray}
\alpha&=&\frac{1}{\sqrt{2\pi}}\int_{-\infty}^\infty \exp(-t^2/2) t\sin(2\pi t)\,dt,\\
\beta_k&=&\frac{1}{\sqrt{2\pi}}\int_{-\infty}^\infty\exp(-t^2/2)\sin^{2k}(2\pi t)\,dt, k=1,2,\ldots.
\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Feller's lemma of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] Let $X_t,X$ be a family of $[0,\infty]$-valued random variables such that $\mathbb{P}\left(X <\infty\right) = 1$. Assume that for all $\rho>0$,
    \begin{equation}
        \mathbb{E}[e^{-\rho X_t}] \longrightarrow \mathbb{E}[e^{-\rho X}] \quad \text{as} \quad t\to\infty.
    \end{equation}
    Then, 
    \begin{equation}
        \mathbb{P}\left(X_{t} = +\infty\right) \to 0 \quad \text{as} \quad t\to\infty,
    \end{equation} 
    and conditioned on the event $\{X_{t}<\infty \}$, $X_{t}$ converges weakly to $X$. In particular, for all $x \in [0,\infty)$ which is a point of continuity for  $\mathbb{P}(X\leq x)$, $\mathbb{P}\left(X_{t}\le x\right) \to \mathbb{P}\left(X\le x\right)$ as $t\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 44 (Bulk stability) of arXiv:2606.24887, '2606.24887'] For every $\delta >0$, there exist constants 
		$C$, $\mathfrak{c} >0$ depending only on $\delta$ such that for all $q \in \C$ and $r \in \C$ satisfying 
		\begin{equation} 
			q^3 + 2\ii\eta q^2 + \left(1-\eta^2 - |w|^2 \right) q +\ii \eta =r~\text{and}~ \left|q - \ii v(w,\eta) \right| \le \mathfrak{c}
		\end{equation}
		for some $(w,\eta) \in (\mathrm{D}_{1-\delta} \times (0,\infty))\cup (\C \times [1,\infty))$ we have 
		\begin{equation*}
			\left|q - \ii v(w,\eta) \right| \le \frac{C|r|}{1 + \eta^2}.
		\end{equation*}

