[Theorem 17 of arXiv:2608.28198, 'Performative Privacy: When Differential Privacy Maximizes Utility'] Assume $\Sigma\succ0$, $C_1(\gamma)>1$ which by theorem \ref{theo:noise_threshold_mia} is true when $\gamma \ge \gamma_c$, and also assume by mean field approximation, $N_t\ge N_0\bigl(C_1(\gamma)\bigr)^t$.
Define
\begin{align*}
M
&\triangleq
\sqrt{\|\mu\|_2^2+\operatorname{Tr}(\Sigma)},~~
\mathcal B(R)
\triangleq
\sqrt{\lambda_{\max}(\Sigma^{-1})}\,
M
\exp\left(
-\frac{(R-M)^2}
{4\lambda_{\max}(\Sigma)}
\right),\\
\mathcal V_{\delta/2}
&\triangleq
2R
\sqrt{
2\lambda_{\max}(\Sigma^{-1})
\ln\frac{4}{\delta}
},~~
\mathcal K_{\delta/2}
\triangleq
d
+2\sqrt{d\ln\frac{2}{\delta}}
+2\ln\frac{2}{\delta}.
\end{align*}
For any $\delta\in(0,1)$ and $\epsilon>\mathcal B(R)$, if
\begin{equation} 
t\ge
\frac{1}{\ln C_1(\gamma)}
\ln\left(
\frac{
\left(
\mathcal V_{\delta/2}
+\gamma\sqrt{
\lambda_{\max}(\Sigma^{-1})
\mathcal K_{\delta/2}}
\right)^2
}{
N_0\left(\epsilon-\mathcal B(R)\right)^2
}
\right),
\end{equation}
then $D_M\triangleq\|o_t-\mu\|_{\Sigma^{-1}}\le\epsilon$ with probability at least $1-\delta$.

