			\\ &=-\int_0^{t_1} \nabla f_1(u_{j_1})\,\nabla  f_2(u') \cdot z^{[1]}\, {\mathrm d} t', \qquad u':=z_1+t' z^{[1]}\,.
		\end{split}
		\]
		Then, resorting to (equation Eq: int exchange 1 of the paper) for $F_2:=f_2$, $F_1:=\nabla f_1 \cdot f_2$,
		\[
		\begin{split}
			& \int_{[0,1]_\geq^k}\left[\nabla f_1(u_{j_1})\, F_2(z_1) -F_1(u_{j_1})\right] \, {\mathrm d} \mathbf{t}_{k-1}=-\sum_{j=j_1+1}^{k}\int_{[0,1]_\geq^{k+1}}	\nabla f_1(u_{j_1})\,\nabla  F_2(u_{j}) \cdot z^{[1]}\, {\mathrm d} ...","release_manifest_digest":"sha256:76440b31e38ce331b560410ec8855915006ab58686f1a809d1caca330c5a3dcf","revision_digest":"sha256:9a4c3de7030e9fd5cc7da868bbabca7b88d916d955a5e8d24a32913efbd0125a","source_id":"arxiv:2607.18635","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

