    \begin{equation}
                \mathbb{P}(Z(t)\geq j)
             = \frac{b-d}{b-de^{-(b-d)t}}\cdot\Big(1-\frac{b-d}{be^{(b-d)t}-d}\Big)^{j-1}.
    \end{equation}

