body:
[Prop Proposition 8.5 of arXiv:2411.02541, 'The hockey-stick conjecture for\\ activated random walk'] \thlabel{prop:driven.dissipative.lower}
  Let $S_n$ be distributed as the number of sleeping particles under the invariant
  distribution of the driven-dissipative Markov chain on $\ii{1,n}$.
  For any $\rho<\crist(\lambda)$,
  \begin{align*}
    \mathbf{P}( S_n\leq\rho n) \leq Ce^{-cn}
  \end{align*}
  for constants $c,C$ depending only on $\lambda$ and $\rho$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 11 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $a>0$, $M=a|\mathbb{B}_R|$ and consider $u\in \Sigma_a$. Then
\begin{equation}
	|\partial_r \phi'(u(r))| \le \frac{\|u\|_\infty}{d}r\,,\quad r\in (0,R]\,,
\end{equation}
and
\begin{equation}
	|\phi'(u(r))-\langle\phi'(u)\rangle| \le \frac{M}{\sigma_d(m-1)}\left(\frac{r^{2-d}}{d}+\frac{R^{2-d}}{2}\right)\,,\quad r\in (0,R]\,.
\end{equation}
Moreover,
\begin{equation}
	0<u(r)\le  \left( a R^d + \frac{a^2 R^d r^2}{d^2 m}\right) r^{-d}\,,\quad r\in (0,R]\,,
\end{equation}
and
\begin{align}
	\partial_r u(r)\le  \frac{a}{dm} u(r) r\,,\quad r\in (0,R]\,.
\end{align}
In fact,
\begin{equation}
	|\partial_r u(r)| \le \min\{u(r),u(r)^{2-m}\}\|u\|_\infty\frac{r}{dm}\,,\quad r\in (0,R]\,,
\end{equation}
and 
\begin{equation}
	|\partial_r u(r)| \le \frac{M}{m\sigma_d}\min\{u(r),u(r)^{2-m}\}r^{1-d}\,,\quad r\in (0,R]\,.
\end{equation}

