[Lemma 6 of arXiv:2604.12233, 'An upper bound on the smallest singular value of dense random combinatorial matrices'] \cite[Lemma 2.1]{KwanSudakovTran}
    Let $w\in \R^n$ be a positive vector and $f: \{0,1\}^n\to \R$ be a function  such that 
    \begin{equation}
        |f(x_1, \dots, x_{i-1}, 1, x_{i+1}, \dots, x_n)-f(x_1, \dots, x_{i-1}, 0, x_{i+1}, \dots, x_n)|\le w_i,
    \end{equation}
    for all $x\in \{0,1\}^n$ and all $i\in [n]$. Suppose that $\eta$ is a random vector uniformly distributed over $\{0,1\}^n$ with exactly $d$ ones, where $1\le d \le n$.  Then
    \begin{equation*}
    \forall t \ge 0\qquad     \P(|f(\eta)-\E f(\eta)|\ge t)\le 2\exp\lr{-\frac{t^2}{8\sum_{i=1}^n w_i^2}}.
    \end{equation*}

[Corollary cor:local_hajek_norho of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Define
\begin{equation}
    \widehat{\mathsf{N}}_G^v(x) \coloneqq \mathsf{N}_G^v(x) - 2 \mathsf{e} p^{\mathsf{e}-1} n^{\mathsf{v}-2} \mathsf{deg}_v(x).
\end{equation}
Then for all $\zeta \in (0,\frac{3}{4})$, there is some $c > 0$ such that
\begin{equation}
    \mathbb{P} \mleft[
        \mleft|
            \widehat{\mathsf{N}}_G^v(X) - \mathbb{E}\mleft[\widehat{\mathsf{N}}_G^v(X)\mright]
        \mright| > n^{\mathsf{v}-1.75+\zeta}
    \mright] \leq \Exp{-c n^{\frac{4}{3}\zeta}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 3 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $\phi\in\mathcal{S}([G])$. Then $\phi_P$ is a smooth function on $U(\A)M(F)\bs G(\A)$ with
		\begin{equation*}
			\phi_P(g) \ll_{\lambda,\phi} e^{\left\langle\lambda, H_{P_0}(g)\right\rangle},\quad g\in \mathbb{S},
		\end{equation*}
		for any $\lambda\in\a^\ast_{P_0}/\a^\ast_G$. Moreover, the same bounds hold for $\mathcal{D}\phi$, for any differential operator $\mathcal{D}$ of $G(F_\infty)$ (with implied constant allowed to depend on $\mathcal{D}$). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 28 of arXiv:2506.20146, 'Parabolic Anderson Model in the Hyperbolic Space. Part I: Annealed Asymptotics'] There exists a universal constant $C>0,$ such that
\begin{equation}
\langle u_{R(t)}(t,o)\rangle\leqslant C(2+R(t))^{1/2}\big(\langle(u_{R(t)}(t,\cdot),{\bf 1})\rangle+|Q_{R(t)}|\big)+e^{-1}\cdot e^{H(t+1)}
\end{equation}
for all $t>1,$ where $|Q_{R(t)}|$ denotes the volume of $Q_{R(t)}$.

