body:
[Theorem thm:ht-bdd tree of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $h_n$ be such that $4\leq h_n\ll\sqrt{n}$.
    Then, for any $4\leq m\leq h_n$, we have
    \begin{align*}
        H_{n,m}&=\frac{4^n}{m+1}\frac{\tan^2\left(\frac{\pi}{m+1}\right)}{\left(1+\tan^2\left(\frac{\pi}{m+1}\right)\right)^n}+O\left(\frac{4^n}{m^3}\frac{1}{\left(1+\tan^2\left(\frac{2\pi}{m+1}\right)\right)^n}\right)\\
        &=\big(1+o(1)\big)\frac{4^n}{m+1}\frac{\tan^2\left(\frac{\pi}{m+1}\right)}{\left(1+\tan^2\left(\frac{\pi}{m+1}\right)\right)^n}
    \end{align*}
    where the $o(\cdot)$ and $O(\cdot)$ terms only depend on $h_n$, and are uniformly bounded over all such $m$.
    Moreover, the second asymptotic equality trivially holds when $m\in\{2,3\}$.

[Proposition Limiting point process of arXiv:2411.13972, 'The Stochastic Bessel operator at high temperatures'] There is a random variable $M_0$ valued in the Borel sets of $]0,\infty[$, such that, for all fixed $\mu_1 < \ldots < \mu_k$,
	\begin{align*}
		M_0[\mu_i,\infty[ = \nu^0_{\mu_i}(\mathbb{R}_+)\,.
	\end{align*}
Almost surely, the measure $M_0$ is unique, discrete, bounded from above and has an accumulation point at $0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:ZIMsurvivalZd1 of arXiv:2607.29409, 'The Zombie Infection Model'] If $\lambda<1.25$, then $\sup_{\Delta \Subset {\mathbb{Z}}^2}\phi(\lambda, {\mathbb{Z}}^{2}, \Delta
		)=0$ and, if $\lambda>6.92$, then $\inf_{\Delta \Subset {\mathbb{Z}}^2}\phi(\lambda, {\mathbb{Z}}
		^{2}, \Delta)>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma petites vitesses of arXiv:2412.00865, 'On the spectral problem and fractional diffusion limit for Fokker-Planck with(-out) drift '] \item 1.  For all $\gamma \in(\frac{d+1}{2},\frac{d+4}{2})$,  the following estimate holds
\begin{equation} \int_{\{|v_1|\leqslant R\}}  \bigg|\frac{  M_{0,\eta} - c_\eta M}{\langle v \rangle}\bigg|^2 \mathrm{d}v \lesssim \eta . 
\end{equation}
2.  For all $\gamma \in (\frac{d}{2},\frac{d+1}{2})$, one has
\begin{equation}
\underset{\eta \to 0}{\mathop{\rm lim}} \ \eta^{1-\alpha}  \int_{\{|v_1|\leqslant R\}} v_1 M_{0,\eta}(v)M(v) \ \mathrm{d}v = 0 .
\end{equation}
3.  For all $\gamma \in [\frac{d+1}{2},\frac{d+4}{2})$, one has
\begin{equation}
\underset{\eta \to 0}{\mathop{\rm lim}} \ \eta^{1-\alpha}  \int_{\{|v_1|\leqslant R\}} v_1 [M_{0,\eta}(v)- c_\eta M(v)]M(v) \ \mathrm{d}v = 0 .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:tailrl-harmonic-decomposition of arXiv:2609.02987, 'Tail Likelihood Reinforcement Learning'] The population-level TailRL{} objective decomposes as a harmonic mixture of Best-of-$k$ objectives
\begin{align}
J_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{\infty}
\frac{\text{Best-of-}k(\theta;x)-1}{k}.

\end{align}
And under (lem:tailrl-regularity of the paper) the gradient $\nabla_\theta J_{\mathrm{TailRL{}}}(\theta;x)$ is a harmonic combination of Best-at-$k$ gradients,
\begin{align}
\nabla_\theta J_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{\infty}
\frac{1}{k}
\nabla_\theta\text{Best-of-}k(\theta;x).

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defin Modified admissibility of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] For $d\geq1$ and $s\in\{0,1,\dots,d-1\}$, we call $(d,s)$-\textit{admissible} the $(d,s)$-non-degenerate weight pairs $({\mathbf{a}},{\mathbf{b}})$ for which the random compositions $(C_{nd+s})_{n\geq 0}$  with distributions $(\PComp{{\mathbf{a}},{\mathbf{b}}}{nd+s})_{n\geq 0}$ can be coupled in such a way that
	\begin{align*}
	C_s\covered[d] C_{d+s}\covered[d] C_{2d+s}\covered[d] \dots\covered[d] C_{nd+s}\covered[d] C_{(n+1)d+s}\covered[d]\dots.
	\end{align*}

[Proposition 15 of arXiv:2511.12623, 'The eigenvector bead process'] Fix \(E\in(-2,2)\) and, for each \(N\), let \(i_N(E):=\min\{k:\,\lambda_k^{(N)}\ge E\sqrt{N}\}\).
For fixed offsets \(u\in\mathbb{Z}\), set \(i:=i_N(E)+u\).
Assume that the random family \(\bigl(\mu_{j}^{(N)},\,g_{j}^{(N)}\bigr)_{j\in\mathbb{Z}}\) converges almost surely, as \(N\to\infty\), to \(\bigl(\mu_{j}^{(0)},\,g_{j}^{(0)}\bigr)_{j\in\mathbb{Z}}\).
Then, almost surely,
\begin{equation}
\lim_{N\to\infty}
\left(\frac{\Delta_{i,i}^{(N)}}{\upsilon_{i}^{(N)}}\right)^{2}
=
\bigl(\mu_i^{(1)}-\mu_i^{(0)}\bigr)^{2}
\sum_{j\in\mathbb{Z}}
\left(\frac{|g_j^{(0)}|}{\mu_i^{(1)}-\mu_j^{(0)}}\right)^{2},
\end{equation}
By Proposition~\ref{prop:as-convergence}, the variables \(\{g_j^{(0)}\}_{j\in\mathbb{Z}}\) are independent Gaussian random variables (independent of \(\{\mu_j^{(0)}\}_{j\in\mathbb{Z}}\)). \(\mu_i^{(1)}\) denotes the \(i\)-th solution \(z\) of the secular equation
\(
S_{\mu^{(0)},\,(g^{(0)})^{2}}(z)\;=\;-\frac{E}{2\sqrt{4-E^{2}}}\,.
\) (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def.Meyers of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Given three constants ${\varepsilon \in (0,1)}$, ${\mathsf{r} > \frac{4}{3}}$, ${C \in (0, \infty)}$, we denote by $\mathcal{M}(\mathbf{a}, \mathsf{r}, \varepsilon, C) \subseteq \mathcal{T}$ the collection of cubes ${\scaleobj{1}{\square}}$ satisfying the following property under $\mathbf{a}$
		\begin{enumerate}
			\item ${\scaleobj{1}{\square}}, \frac{4}{3}{\scaleobj{1}{\square}}, \mathsf{r} {\scaleobj{1}{\square}}$ are very-well connected;
			\item For every cube ${\scaleobj{1}{\square}}' \supseteq {\scaleobj{1}{\square}}$ and function $v: \mathsf{r} {\scaleobj{1}{\square}} \cap {\scaleobj{1}{\square}}' \rightarrow \mathbb{R}$ satisfying 
			\begin{equation}
				\left\{
				\begin{array}{cc}
					-\nabla \cdot (\mathbf{a} \nabla v) = -\nabla\cdot \mathbf{w}  &\text{ in }  {\mathrm{int} \mathscr{C}_{**}(\mathsf{r} {\scaleobj{1}{\square}} \cap {\scaleobj{1}{\square}}')}, \\
					v = 0 & \text{ on } \mathsf{r} \cap \partial {\scaleobj{1}{\square}}'.
				\end{array}
				\right.
			\end{equation}
			with  $\mathbf{w}$ an anti-symmetric vector field supported on $\overrightarrow{E_d^{\mathbf{a}}}$, one has the estimate
			\begin{multline}

				\left(\frac{1}{\left|\frac{4}{3}{\scaleobj{1}{\square}}\right|} \sum_{e\in \mathcal{E}(\mathscr{C}_{**}(\frac{4}{3} {\scaleobj{1}{\square}} \cap {\scaleobj{1}{\square}}'))}|\nabla v(e)|^{2+\varepsilon}\right)^{\frac{1}{2+\varepsilon}} \\
				\leqslant C\left(\frac{1}{\left|\mathsf{r} {\scaleobj{1}{\square}}\right|} \sum_{e\in \mathcal{E}(\mathscr{C}_{**}(\mathsf{r} {\scaleobj{1}{\square}} \cap {\scaleobj{1}{\square}}'))}|\nabla v(e)|^2\right)^{\frac{1}{2}}+C\left(\frac{1}{\left|\mathsf{r} {\scaleobj{1}{\square}}\right|} \sum_{e\in \mathcal{E}(\mathscr{C}_{**}(\mathsf{r} {\scaleobj{1}{\square}} \cap {\scaleobj{1}{\square}}')}|\mathbf{w}(e)|^{2+\varepsilon}\right)^{\frac{1}{2+\varepsilon}}.
			\end{multline}
		\end{enumerate}

[Definition of arXiv:2512.06640, 'Existence and sharpness of the phase transition for the frog model on transitive graphs'] A graph $G=(V,E)$ satisfies the \textbf{volume doubling} condition if there exists $C > 0$ such that for all $x\in V$ and $n\geq1:$
\begin{equation}
g_{x}(2n) \leq C g_{x}(n) \, .
\end{equation}

