[Prop prop4Xeps of arXiv:2603.29711, 'Strong Feller property, irreducibility,\\ and uniqueness of the invariant measure\\ for st'] Under the assumptions of Theorem~(th:wp of the paper),
for every $\ell \ge 1$, $\rho\in(0,\frac12)$, and $T>0$
there exists a constant $C>0$,
only depending on $\alpha, \delta, \sigma, \ell,\rho,T$,
such that, for every $\varepsilon\in(0,1)$,
\begin{align*}
\|G_{\alpha,\varepsilon}(X^x_\varepsilon)\|_{L^{\ell}(\Omega; 
L^\infty(0,T; \mathscr{L}^2(H,H))\cap L^2(0,T; \mathscr{L}^2(H,V_{2\sigma})))}
&\le  
C,

\end{align*}
and
\begin{align*}
\norm{\int_0^\cdot
G_{\alpha,\varepsilon}(X^x_\varepsilon(s))\,{\mathrm d} W(s)}_{
L^{\ell}(\Omega; W^{\rho,\ell}(0,T;H))
\cap L^2(\Omega; W^{\rho,2}(0,T; V_{2\sigma}))} &\le  
C,

\end{align*}

[Lemma 11 of arXiv:2607.04012, 'Hölder regularity for backward stochastic Volterra integral equations and applications to '] Let $t\in[0,T]$ and $u\in[0,t)$. Let $1\leq \lambda<2$ and $2< \eta<q$. Then there exists a constant $C>0$, independent of $\pi$, $t$ and $u$, such that
\begin{flalign}
\mathbb{E}\bigg[\bigg(\sum_{k = 0}^{N-1} \Delta_k
\sum_{j=k+1}^{N-1} 
\frac{1}{\Delta_j} 
\mathbb{E}_u \big[
\sup_{v \in [t, T]}
|D_u U^\pi(t,v)_{k,j}|^\lambda
\big]^{\frac{2}{\lambda}}
\bigg)^{\frac{\eta}{2}} \bigg]^{\frac{1}{\eta}}
 \leq
C \Big\{
\mathfrak p_2^\Pi
+
\gamma_1^\Pi
+
\gamma_y^\Pi
+
\gamma_z^\Pi
\Big\}.

\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)

