[Theorem thm:three-observables of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] Under the two-mode approximation, as $k\to\infty$,
\begin{align}
I_k &= \tfrac{1}{2}x_k + O(x_k^2), \\
R_k &= (\lambda_3-\lambda_2)\,x_k + O(x_k^2), \\
\Lambda_k &= \tfrac{\lambda_2}{2}(\rho_\star^2-1)\,x_k + O(x_k^2). 
\end{align}

[Prop circulation of arXiv:2608.29914, 'Fixed points in abstract provability structures'] Let $S$ be an APS and let $\triangle_0 v$ and $\triangle_1 v$ be one-variable APS terms. 
\begin{enumerate}
    \item $\mathsf{E}_S(\triangle_0 \triangle_1) \iff \mathsf{E}_S(\triangle_1 \triangle_0)$. 

    \item $\mathsf{U}_S(\triangle_0 \triangle_1) \iff \mathsf{U}_S(\triangle_1 \triangle_0)$. 
\end{enumerate}

[Defi 11 of arXiv:2608.28148, 'Flows and homotopies of Banach Lie algebroids'] ${}$
Let $N$ be a Banach manifold which we identify with the zero section in $p_N\colon TN\to N$. A local addition on $N$ is a smooth map $\Sigma\colon \mathcal{U}\subset TN\to N$  where $\mathcal{U}$ is an open neighbourhood of $N\subset TN$ such that:
\begin{itemize}
\item[1.] the map $\theta = (p_N, \Sigma) \colon  TN \to N\times N$ is a diffeomorphism from  $\mathcal{U}$ onto an open neighbourhood $\mathcal{V}$ of the diagonal;
\item[2.]  $\Sigma(x,0)=x$ for all $x\in N$.
\end{itemize}

[Proposition 5 of arXiv:2506.11799, 'Quenched limit for diffusive biased random walks in random environment'] Let $f, g, h$ be bounded function measurable, respectively, with respect to $\mathcal{A}, \mathcal{B}, \Sigma_k$, then, for all $x, y \in \mathbb{Z}^d$
	\begin{equation*}
		\mathbb{E}_{x, y} \left[ f\left(X_{\mu^{(1)}_k + \cdot}^{(1)}, X_{\mu^{(2)}_k + \cdot}^{(2)}\right) g \circ \theta_{\mu^{(1)}_k, \mu^{(2)}_k} h \right] = \mathbb{E}_{x, y} \left[ h \mathbb{E}_{X^{(1)}_{\mu_k}, X^{(2)}_{\mu_k}} \left[ f\left(X_{\cdot}^{(1)}, X_{\cdot}^{(2)} \right) g \mid \mathcal{D}^\bullet = \infty\right] \right].
	\end{equation*}

[Thm rank, det, definitness subcrit of arXiv:2509.15790, 'Covariance matrices of volume power functionals of random simplicial complexes -- an asymp'] Let $\Sigma_n $ be as in ((Eq: Kov.matrix Laengen Potenz Funktional of the paper)) in the subcritical regime for $n\geq2$. Then 
(i) $\emph{rank}(\Sigma_n) = n$;
(ii) $\Sigma_n$ is positive definite;
(iii) $\det \Sigma_n>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

