[Lemma lem:vd-l2-localized-leading-layer of arXiv:2609.00698, 'Kinetic Wedge Layers and Diffusive Limit of Neutron Transport in Polygonal Domains'] Let $0<\varepsilon\leq\varepsilon_0(\Omega)$, and let $S_{\rm sl}^\varepsilon:=\mathscr L_\varepsilon\mathcal U_{\rm sl,0}^\varepsilon$ be the transport source of the total localized layer (equation eq:vd-l2-global-leading-layer of the paper). For every exponent $1\leq p_{\rm P}<\infty$, here still a free parameter and not yet the fixed exponent of (equation eq:vd-l2-poisson-p-range of the paper), the layer itself obeys
\begin{align}
 \nm{\mathcal U_{\rm sl,0}^\varepsilon}_{L^\infty(\Omega\times\mathbb S^1)}
 \leq C_\Omega\mathcal G_{\rm vd},
 \qquad
 \nm{\mathcal U_{\rm sl,0}^\varepsilon}_{L^{p_{\rm P}}(\Omega\times\mathbb S^1)}
 &\leq
 C_{\Omega,p_{\rm P}}\mathcal G_{\rm vd}\varepsilon^{\frac{1}{p_{\rm P}}}.

\end{align}
The source lies in $L^1(\Omega\times\mathbb S^1)\cap L^2(\Omega\times\mathbb S^1)$, with
\begin{align}
 \nm{S_{\rm sl}^\varepsilon}_{L^1(\Omega\times\mathbb S^1)}
 \leq C_\Omega\mathcal G_{\rm vd}\varepsilon,
 \qquad
 \nm{S_{\rm sl}^\varepsilon}_{L^2(\Omega\times\mathbb S^1)}
 &\leq C_\Omega\mathcal G_{\rm vd}.

\end{align}
On every open side the second normal moment of the trace of the layer vanishes,
\begin{align}
 \int_{\mathbb S^1}(w\cdot n_j)^2
 \mathcal U_{\rm sl,0}^\varepsilon(x,w)\big|_{\gamma}\,\mathrm d\nu(w)
 &=0
 \quad(x\in E_j),

\end{align}
and the incoming discrepancy $h^\varepsilon:=g^\varepsilon-\bigl(\rho_0+\mathcal U_{\rm sl,0}^\varepsilon\bigr)\big|_{\gamma_-}$ is small:
\begin{align}
 \abs{h^\varepsilon}_{2,-}
 &\leq C_\Omega\mathcal G_{\rm vd}\varepsilon^{\frac12}.

\end{align}

