body:
[Theorem 12 (Rigidity of eigenvalues) of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] Suppose the assumptions of Theorem \ref{local_law} hold. Then, outside the spectrum, we have the following stronger averaged local law:
\begin{equation}
|m_1(z)-m_{1c}(z)|+|m_2(z)-m_{2c}(z)|+|m(z)-m_c(z)|\prec
\frac{1}{N(\kappa+\eta)}
+\frac{1}{(N\eta)^2\sqrt{\kappa+\eta}},
\end{equation}
uniformly in
\(
z\in S(c_0,C_0,\varepsilon)
\cap \{z=E+\ii\eta:E\geq \lambda_+,\, N\eta\sqrt{\kappa+\eta}\geq N^\varepsilon\}
\)
for any fixed $\varepsilon>0$. 

The local laws \eqref{average} and \eqref{eq:averaged_outside} imply the following rigidity estimate for any constant $0<c_1<c_0$. Define the classical location $\gamma_j$ of the $j$-th eigenvalue of $\mathcal Q_1$ by
\begin{equation*}
\gamma_j:=\sup_x\left\{\int_x^{+\infty}\rho_c(x)\dd x>\frac{j-1}{p}\right\}.
\end{equation*}
In particular, $\gamma_1=\lambda_+$. Then, for any $j$ such that $\lambda_+-c_1\leq \gamma_j\leq \lambda_+$, we have
\begin{equation}
|\lambda_j(\cal Q_1)-\gamma_j|\prec j^{-1/3}n^{-2/3}.
\end{equation}

[Lemma lemmafinaltwomoments of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] There exists a function $V_{(lemmafinaltwomoments of the paper)}(B,c_0)>0$ depending only on $B>1$ and $c_0\in(0,1)$ such that the following holds. Fix some $c\in[-2,2]$ and two integers $N\geq N_1\geq 2$ and $n\in\mathbb{N}$ satisfying 
    $N\leq \exp(L^{-64/c_0^2}V_{(lemmafinaltwomoments of the paper)}(B,c_0)n)$. Let $X,Y$ be uniformly sampled from a $(N,N_1,\kappa,\kappa',D_1,D_2,D_3)$ box. Then whenever $n$ is sufficiently large relative to $L,c_0$,
    $$\begin{aligned}
\mathbb{P}_{X,Y}& \left(\mathbb{P}_{M_n}(\|(M_nX,M_n(cX+Y))\|_2\leq n)\geq(\frac{L^2}{NN_1})^n,|\sin(X_D,Y_D)|\geq \frac{c_{\rho,\delta}^2c_0^2}{128}\right)\\&\leq (\frac{R_2}{L^2})^{2n}
 \end{aligned}   $$ where $R_2=C_Bc_0^{-16}$ and $C_B>0$ is a constant depending only on $B$.

[Theorem theo:untied-SGD of arXiv:2609.03858, 'High-Dimensional Learning Dynamics of \\ Attention-Indexed Models'] Suppose that Assumptions (assum:untied of the paper) and (assum:untied_convex of the paper) hold for a fixed slow-time horizon \(T>0\). Assume furthermore that $\max_{1\le k\le K}d_k\le d^{c_w}$ for some fixed \(c_w<\infty\), and that the learning rate satisfies $\alpha_d\le\frac{c_0}{d\log d}$ and $\alpha_d=\Omega(d^{-\iota})$ for some constants \(\iota>0\) and sufficiently small \(c_0>0\) independent of \(d\).

Then the online SGD trajectory exhibits the following two-timescale limit. Fix any $\epsilon>0$. For every finite fast-time horizon \(\widetilde T>0\),
\begin{equation}
\lim_{d\to\infty}\mathbb P\left(\sup_{t\in[0,\widetilde T]}\left\|\tilde m^{(d)}(t)-\tilde m(t)\right\|_\infty>\epsilon\right)=0,

\end{equation}
where \(\tilde m\) is the unique solution of (equation eq:m-fast of the paper).

On the slow timescale, let \((\bar m(\tau),\bar\mu(\tau))\) denote the unique admissible solution
of (equation eq:untied-slaving of the paper)--(equation eq:slow_tau_mu of the paper). Then for every \(0<T_1<T_2\le T\),
\begin{equation}
\lim_{d\to\infty}\mathbb P\left(\sup_{\tau\in[T_1,T_2]}\left\|\tilde m^{(d)}(\tau d)-\bar m(\tau)\right\|_\infty>\epsilon\right)=0

\end{equation}
and, for every word \(\alpha\),
\begin{equation}
\lim_{d\to\infty}\mathbb P\left(\sup_{\tau\in[0,T_2]}\left|\tilde\mu_\alpha^{(d)}(\tau)-\bar\mu_\alpha(\tau)\right|>\epsilon\right)=0.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma cor of arXiv:2412.09471, 'On the moderate deviation principles in the sparse multi-type Erd\H{o}s R\'enyi random gra'] \hfill
\begin{itemize}
\item[-] When $\Sigma(\kappa,\mu)>1$, let $c$ be the solution to the characteristic function~(equation cha of the paper). 
\item[-] When $\Sigma(\kappa,\mu)<1$, set $c=\mu$. 
\end{itemize}
Then $h(k)$ is given by
\begin{equation}
    h(k)=\tau(k)\prod_{s\in{\mathcal S}}\frac{(e^{-(\kappa c)_s}c_s)^{k_s}}{k_s!}.
\end{equation}
Furthermore, the following properities hold for $\{h(k)\}$:
\begin{enumerate}[label=(\roman*)]
    \item Total mass:
    \begin{equation}
  \sum_{k\in{\mathbb N}^d}h(k)=|c|-\frac{1}{2}c^T\kappa c,
\end{equation}
\item First moments: for any $r\in \mathcal{S}$,
\begin{equation}
\sum_{k\in{\mathbb N}^d}k_rh(k)=c_r.
\end{equation}
\item Second moments: let $\Phi$ be a symmetric matrix with entries $\Phi_{rs}=\sum_{k\in\mathbb{N}^d}k_rk_sh(k)$ for all $r,s\in\mathcal{S} $. Then $\Phi$ is positive definite, and its inverse is
\begin{equation}
  \Phi^{-1}=(D_{c})^{-1}-\kappa.
\end{equation}
\item High-order moments: for any $\gamma\in{\mathbb N}^d$, the $\gamma$-moment is finite:
\begin{equation}
    \sum_{k\in{\mathbb N}^d}h(k)\prod_{s\in{\mathcal S}}k_s^{\gamma_s}<\infty.
\end{equation}

\end{enumerate}

[Thm 2 (\rm{\cite[Theorem 5.10) of arXiv:2607.03360, 'Smoluchowski-Kramers Approximation Meets Khasminskii Averaging Principles in Nonequilibriu'] {KP91}}]
Assume that the following conditions hold:
\begin{itemize}
\item[(KP1)] (Convergence condition): $(\CU_t^m, \CH_t^m) \to (0,\CH)$ in probability with respect to the sup-norm in $C([0,T]; \rr^{d_1} \times \rr^n)$, i.e., for all $\dl>0$,
\beq{cond-1}
\PP\bigg[\sup_{s\in [0,T]}\Big(|\CU_s^m-0|+ |\CH_s^m - \CH_s|\Big) > \dl \bigg] \to 0, \quad \text{as } m \to 0.
\eeq
\item[(KP2)] (Tightness condition): the total variations $\{\CV_t(\CA^m)\}$ are stochastically bounded for each $t>0$, i.e., $\PP[\CV_t(\CA^m) > K] \to 0$ as $K \to \infty$, uniformly in $m$.
\end{itemize}
Suppose that there exists a unique global solution $x$ to \eqref{xt-fH}. Then as $m\to 0$, $x^m$ converges to $x$ in probability with respect to $C([0,T];\rr^{d_1})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 60 of arXiv:2608.20252, '2608.20252'] For $f\in {\rm Dom}(\rho)$, we have that
\begin{equation}

D_\rho(f) \ = \ \frac{1}{2}\sum_{x,y} s(x,y)E_{\nu_\rho}\big[g(\eta(x))\big(f(\eta^{x,y}) - f(\eta)\big)^2\big].
\end{equation}

[Lemma eq:Haar-entry-tail of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:Haar-incoherent}
There are universal constants \(c,C>0\) such that, for Haar \(O\in\mathbb O(N)\),
\begin{equation}
 \mathbb P(\abs{O_{ij}}>t)\le C e^{-cNt^2},
 \qquad 0<t<1.
\end{equation}
Consequently, if \(L>L_0:=\sqrt{3/c}\), then
\begin{equation}
 \nu_N(\mathcal O_{N,L})\longrightarrow1,
 \qquad
 \frac1N\log\nu_N(\mathcal O_{N,L})\longrightarrow0.
\end{equation}
For the point cutoff, however, every fixed \(L>0\) has zero
exponential cost:
\begin{equation}
 \frac1N\log\overline\sigma_{N-1}(D_{N,L})
 \longrightarrow0.
\end{equation}

[Lemma 18 of arXiv:2608.02319, 'Averaging Principle for Ordinary Differential Equations in a Multiscale Random Environment'] Let $0<s_1<s_2$, $0<t_1<t_2$, $x\in E$, $z\in\mathbb R^d$, then, for all $L,M>0$, $n,j\geq1$ and $j\geq k+1$ we have
\begin{align*}
\big\lvert\phi_{s_1,t_1}^{n,k}(z,x)-\phi_{s_2,t_2}^{n,k}(z,x)\big\rvert&\leq\|f_1'\|_\infty\,\|f_2\|_\infty\,(s_2-s_1)\,\Big(L\,\big(\lvert z\rvert+TM)\,e^{TL}+M\Big)\\
&+2\,\|f_1\|_\infty\,\|f_2\|_\infty\,\big(\mathbf P_x(s_2\leq\tau_j^n,L_{s_2}^n>L)+\mathbf P_x(s_2\leq\tau_j^n,M_{s_2}^n>M)\big)\\
&+\|f_1\|_\infty\,\|f_2\|_\infty\,\big(\mathbf P_x(\tau_{j-1}^n<s_1\leq\tau_j^n)+\mathbf P_x(\tau_{j-1}^n<s_2\leq\tau_j^n)\big)\\
&+\|f_1\|_\infty\,\|f_2\|_\infty\,(t_2-t_1)\,\Big(L\,\big(\lvert z\rvert+TM)\,e^{TL}+M\Big)\\
&+2\,\|f_1\|_\infty\,\|f_2'\|_\infty\,\big(\mathbf P_x(t_2\leq\tau_k^n,L_{t_2}^n>L)+\mathbf P_x(t_2\leq\tau_k^n,M_{t_2}^n>M)\big)\\
&+\|f_1\|_\infty\,\|f_2\|_\infty\,\big(\mathbf P_x(\tau_{k-1}^n<t_1\leq\tau_k^n)+\mathbf P_x\big(\tau_{k-1}^n<t_2\leq\tau_k^n)\big)
\end{align*}
where for all $t>0$ and $n\geq1$
\begin{align*}
M_t^n:=\sup_{s\in[0,t]}M_{\mathbf I_s^n}.
\end{align*}

