body:
[Definition def.WIP of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] List $E_d({\scaleobj{1}{\square}}_m \setminus \Gamma_m)$ in an deterministic order $\{e_1,\dots, e_K\}$ and run the following algorithm under the canonical coupling space defined in Definition~(def.Coupling of the paper): 
			\begin{enumerate}
				\item Let $\widetilde{\mathbf{a}}^{\delta,(0)}_{m} := \mathbf{a}^\delta_m, \mathcal{E}_m^{(0)} := \emptyset$.
				\item For $1\leqslant i \leqslant K$, 
				\begin{itemize}
					\item if $e_i = \{x, y\}$ such that $ x,y\overset{\widetilde{\mathbf{a}}^{\delta,(i-1)}_{m}}{\longleftrightarrow} \partial {\scaleobj{1}{\square}}_m$, then $\widetilde{\mathbf{a}}^{\delta,(i)}_{m} := \widetilde{\mathbf{a}}^{\delta,(i-1)}_{m}$ and $\mathcal{E}_m^{(i)} := \mathcal{E}_m^{(i-1)}$; 
					\item otherwise, let $\mathcal{E}_m^{(i)} = \mathcal{E}_m^{(i-1)} \cup \{e_i\}$, and 
					\begin{equation}
						\widetilde{\mathbf{a}}^{\delta,(i)}_{m}(e) := \widetilde{\mathbf{a}}^{\delta,(i-1)}_{m}(e) + (1-\widetilde{\mathbf{a}}^{\delta,(i-1)}_{m}(e))\Ind{e=e_i, U(e_i)\leqslant \frac{\delta}{1-\mathfrak{p}}}.
					\end{equation}
				\end{itemize}
				\item The output is $\widetilde{\mathbf{a}}^\delta_{m} := \widetilde{\mathbf{a}}^{\delta,(K)}_{m}, \mathcal{E}_m := \mathcal{E}_m^{(K)}$.
			\end{enumerate}

[Lemma lem:ubound of arXiv:2411.13430, 'Optimal subelliptic super-Poincar\'e and isoperimetric inequalities on stratified Lie grou'] Under the assumptions of Theorem (thm1 of the paper), the measure $\mu$ satisfies the $U$-bound 
    \begin{equation}
        \int \left\lvert f \right\rvert^qU_qd\mu \vcentcolon= \int \left\lvert f \right\rvert^q\left\lvert x \right\rvert^{q\alpha}N^{q(p-\alpha-1)}d\mu \lesssim \int \left\lvert \nabla f \right\rvert^qd\mu + \int \left\lvert f \right\rvert^qd\mu
    \end{equation}
    for each $q \in [1, 2]$.

