body:
[Theorem 2dsubcriticalSHE of arXiv:2511.08479, '\Large From disordered systems to the Critical 2D Stochastic Heat Flow'] Let $u^\varepsilon(t, x)$ be the solution of the mollified 2D SHE  (equation eq:mollSHE of the paper) with disorder strength
\begin{equation}
\beta_\varepsilon :=(\hat\beta +o(1))\sqrt{\frac{2\pi}{\log\frac{1}{\varepsilon}}}.
\end{equation}
Then for every $(t, x)\in (0, \infty)\times \mathbb{R}^2$, we have
 \begin{equation} 
	u^\varepsilon(t, x) \xrightarrow[\,N\to\infty\,]{dist}
	\begin{cases}
	\exp\big( \sigma_{\hat\beta} \, {\ensuremath{\mathcal N}} -
	\frac{1}{2} \sigma_{\hat\beta}^2
	\,\big)
	& \text{if } \hat \beta < 1 \\
	0 & \text{if } \hat\beta \ge 1
	\end{cases} \,.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let~\eqref{co:6} hold and $\rho > 0$ be such that
\begin{equation}
\int_{0}^{\infty}\frac{l(s,N(s))^{2}}{1 + s^{2\rho}}\,\mathrm{d}s < \infty.
\end{equation}
Then any solution $I$ to~\eqref{eq:SIS epidemic model} with positive paths satisfies
\begin{align*}
\liminf_{t\uparrow\infty}\frac{1}{t^{\rho}}\log(I_{t}) &= \liminf_{t\uparrow\infty} \frac{1}{t^{\rho}}\int_{0}^{t}h\big(s,I_{s},N(s),\mathcal{L}(I_{s})\big)\,\mathrm{d}s\\
 &\leq \limsup_{t\uparrow\infty} \frac{1}{t^{\rho}}\int_{0}^{t}h\big(s,I_{s},N(s),\mathcal{L}(I_{s})\big)\,\mathrm{d}s = \limsup_{t\uparrow\infty}\frac{1}{t^{\rho}}\log(I_{t})\quad\text{a.s.}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2506.10817, 'On the Weak Error for Local Stochastic Volatility Models'] Let $h,T>0$ such that $\frac Th\in \mathbb{N}$.  For $k\in \{1,\dots,\frac Th\}$ let $\tilde \beta_k$ and $\beta_k$ be $\mathcal{F}_{kh}$ adapted and uniformly bounded by some $b>0$.
    Assume that a recursion scheme is given by
    \begin{align*}
        X_{kh+t}=X_{kh}+\beta_k \bigl(B_{kh+t}-B_{kh}\bigr)+\tilde\beta_k \bigl(\bB_{kh+t}-\bB_{kh}\bigr) \qquad t \in [0,h].
    \end{align*}
    Then it holds that
    \begin{align*}
        \Prob\bigl( \sup_{t \in [0,T]} |X_t| >M \bigr) \le \exp\Bigl(-\frac{M^2}{4b^2T}\Bigr).
    \end{align*}
    In particular for any $\lambda>0$ 
    \begin{align*}
        \E\Bigl[\exp(\lambda |X_T|)\Bigr]<\infty.
    \end{align*}

[Theorem 97 of arXiv:2601.16377, '2601.16377'] Take two variational data satisfying Assumptions~\ref{Assumption_A} and \ref{Assumption_B}. Assume that for any $h \in [H]$ the complex domain $\amsmathbb{M}_h$ in Assumption~\ref{Assumption_B} is common to the two variational data. Then, there exists $\eps > 0$ depending only on the constants in the assumptions such that, if the variational datum $\textnormal{I}$ satisfies the off-criticality Assumption~\ref{Assumption_C} and for any $g,h \in [H]$ the inequalities
\begin{equation*}
\begin{split}
\max\big(|\hat a_h^{\prime\,\textnormal{I}}-\hat a_h^{\prime\,\textnormal{II}}|\,,\,|\hat b_h^{\prime\,\textnormal{I}}-\hat b_h^{\prime\,\textnormal{II}}|\,,\,|\hat n_h^{\textnormal{I}}-\hat n_h^\textnormal{II}|\,,\,|\theta_{g,h}^{\textnormal{I}} - \theta_{g,h}^{\textnormal{II}}|\big) & \leq \eps, \\
 \int_{\max (\hat a_h^{\prime\,\textnormal{I}},\hat a_h^{\prime\,\textnormal{II}})}^{\min(\hat b_h^{\prime\,\textnormal{I}},\hat b_h^{\prime\,\textnormal{II}})} \big|V_h^{\textnormal{I}}(x)-V_h^\textnormal{II}(x)\big| \dd x & \leq \eps, \\
\sup_{z\in \amsmathbb{M}_h} \big|\phi^{\pm,\textnormal{I}}_h(z)-\phi^{\pm,\textnormal{II}}_h(z)\big| & \leq \eps,
\end{split}
\end{equation*}
then the variational datum $\textnormal{II}$ also satisfies Assumption~\ref{Assumption_C}.

[Theorem thm:idla-heavy-tail of arXiv:2411.10113, 'Long-range one-dimensional\\ internal diffusion-limited aggregation'] Suppose that~(equation ass:irreducible of the paper) holds, 
and that~(equation ass:stable-alpha of the paper) holds with $\alpha \in (1,2)$. Then, there exist
constants $c_\alpha, c'_\alpha$
with $0 < c_\alpha \leq c'_\alpha < 1/2$, such that, 
\begin{equation}

 c_\alpha \leq  \liminf_{m \to \infty} \frac{r_m}{m} \leq \limsup_{m \to \infty} \frac{r_m}{m} \leq c'_\alpha, 
  \ \text{a.s.}
\end{equation}
Moreover, one may take for the constant $c_\alpha$ in~(equation eq:r-m-heavy of the paper) the expression
\begin{align}

    c_\alpha & =  \frac{(\alpha -1)  (2-\alpha)^{2-\alpha}}{(4-\alpha)(3-\alpha)^3} .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma le:laplace-IG of arXiv:2411.06195, 'Restrictions of some reinforced processes to subgraphs'] If $X\sim \operatorname{IG}(\frac{a}{2},\frac{a^2}{2})$ for some $a>0$, then
  \begin{align}
    E[e^{(1-s)X}]=e^{a(1-\sqrt s)}, \quad s\ge 0. 
  \end{align}

[Defi 1 of arXiv:2606.19925, 'Asymptotic properties for fully coupled delayed forward-backward stochastic differential e'] \begin{itemize}
\item [(a)] A triple of stochastic processes $(X^{t,x,\varepsilon},Y^{t,x,\varepsilon},Z^{t,x,\varepsilon})$ is said to be an adapted solution of the delayed FBSDE \eqref{Eq1} if, $(X^{t,x,\varepsilon},Y^{t,x,\varepsilon},Z^{t,x,\varepsilon})\in \mathcal{S}^2(\R)\times\mathcal{S}^{2}(\R)\times \mathcal{H}^2(\R)$and if equation \eqref{Eq1} is satisfied $\P$-almost surely.
\item [(b)] A pair of deterministic functions $(\mathcal{X}^{t,x},\mathcal{Y}^{t,x})$ is called a solution of the delayed system of ordinary differential equations \eqref{u} if, $(\mathcal{X}^{t,x},\mathcal{Y}^{t,x})\in L_{-T}^{\infty }\times L_{-T}^{\infty}$ and if system \eqref{u} is satisfied. 
\end{itemize}

