body:
[Lemma 7 of arXiv:2603.28170, 'Stabilization time of finite configurations with a second class particle in discrete TASEP'] \begin{enumerate}
\item
In the symmetric case $p=1/2$, we have that
\begin{align}
\P_2\left(V_1<m\bigm|V_0>m\right)&\to\frac12\\
\E_2\left(V_1\mathbbm{1}_{\{V_1\leq m\}}\bigm|V_0>m\right)&\sim\sqrt{\frac{\pi}{2}}\sqrt{m}
\end{align}
as $m\to\infty$.
\item
If $p=\frac12\left(1-\frac\lambda{\sqrt n}\right)$ then there are constants $c_1>0$ and $c_2$ finite which depend on $\lambda$ such that
\begin{align}
c_1<\P_2\left(V_1<m\bigm|V_0>m\right)&<1-c_1\\
\E_2\left(V_1\mathbbm{1}_{\{V_1\leq m\}}\bigm|V_0>m\right)&\le c_2\sqrt{m}
\end{align}
holds for all $m\le n$.
\end{enumerate}

