[Prop partial answer of arXiv:2505.11700, 'Distribution of the cokernels of determinantal row-sparse matrices'] Suppose that the following hold:  
\begin{enumerate}
\item 
$2 \nmid k_n$ for all sufficiently large $n$;
\item 
$k_n = O(n^{\frac{1}{30}-\delta})$ for some $\delta>0$;
\item 
$\lim_{n \to \infty} k_n = \infty$.
\end{enumerate}
Then
\begin{equation*}
\lim_{n \to \infty} \mathbb{E}(\#\mathrm{Sur}(\mathrm{cok}(A_n), \mathbb{Z}/2\mathbb{Z})) = 1.     
\end{equation*}

[Theorem Berry-Esseen bound GUE/GOE Main result 1 of arXiv:2411.11341, 'Ultra high order cumulants and quantitative CLT for polynomials in Random Matrices'] Let $\mathcal{X}\sim GUE$ or GOE. Consider the polynomial $P(\mathcal{X},\mathcal{D})$ in ((def of P of the paper)) and the random variable $\mathfrak{X}$ defined in ((object_normalized of the paper)). Suppose that $\mathbf{C}_1-\mathbf{C}_3$ are satisfied. Then we have the following three conclusions

(i) ({\it CLT with Cram\'{e}r correction}) For  any $x\in [0,\tilde{\theta}_1 N^{1/(M-1)})$ with sufficiently small constant $\tilde{\theta}_1\equiv \tilde{\theta}_1(K, M, \mathfrak{c},t)>0$,
we have 
\begin{align}
\mathbb{P}(\mathfrak{X}\geq x) = e^{{L(x)}}\mathbb{P}(Z\geq x)\left( 1+ O\left( \frac{x+1}{N^{1/(M-1)}}\right) \right).

\end{align}
Here ${L(x)}$ satisfies $$|{L(x)}|= O(x^3/N^{1/(M-1)}). $$

(ii) ({\it Berry-Esseen bound}) There exists a constant $C_{1}\equiv C_1(K,M,\mathfrak{c},t)>0$, such that
$$\Delta(\mathfrak{X},Z)\leq \frac{C_{1}}{N^{1/(M-1)}}.$$

(iii) ({\it Concentration}) There exist constants $C_2\equiv C_2(K, M, \mathfrak{c},t)>0$, $\hat{\theta}_1\equiv \hat{\theta}_1(K,M,\mathfrak{c},t)>0$,  and a constant $A>0$ that does not depend on $K, M, \mathfrak{c}, t$, such that
\begin{align}
\mathbb{P}(\mathfrak{X}\geq x) \leq A \exp\left( -\frac{1}{2}\frac{x^2}{C_2+x^{2-\frac{2}{M}}(\hat{\theta}_1N)^{-\frac{2}{M}}}\right)

\end{align}
for all $x\geq 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 of arXiv:2608.28964, '2608.28964'] For any $g$ satisfying \eqref{eq g}, there exists a constant $\mathcal C_g>0$ such that the following holds. For any $N\in\N^+$, $\delta\in(0,1/4)$ and $V_0=(v_0,p_0)\in \mathcal X$, there exists $h_{N,\delta}\in L^2(0,1;L^2(\omega;\R^2))$such that the solution $(v_{N,\delta},p_{N,\delta})$ of \eqref{eq V} by replacing $\mathsf P_N\Lambda h$ with $\mathsf P_Nh_{N,\delta}$ satisfies that $\mathsf P_Np_{N,\delta}(1)=0$,
	\begin{align}
	\|(v_{N,\delta}(1),p_{N,\delta}(1))\|_{\mathcal X}&\leq\mathcal C_g\left(\lambda_{N+1}^{-1/4}+\delta^{1/2}\right)\|V_0\|_{\mathcal X},\\
	\|h_{N,\delta}\|_{L^2(0,1;L^2(\omega))}&\leq\mathcal C_g(\lambda_N+\delta^{-1/2})\|V_0\|_{\mathcal X}.
	\end{align}

