[Proposition prop:sobolev_curvature of arXiv:2608.24963, 'Why and When Neural Networks Improve Local Approximation in Optimization'] (Adapted from Proposition~3.1 in [Taminiau2025Arxiv2502].)
Let $m_\theta:\mathbb{R}^n\to\mathbb{R}$ be twice continuously differentiable. Fix $z\in\mathbb{R}^n$ and $h>0$ such that
\begin{equation}
m_\theta(z)=f(z),\qquad m_\theta(z+h e_\ell)=f(z+h e_\ell),\ \ell=1,\dots,n.
\end{equation}
Define $g_h(z)$ by forward differences (equation eq:fd_forward of the paper). Then there exist $\zeta_1,\dots,\zeta_n\in[0,1]$ such that
\begin{equation}
\left\lVert g_h(z)-\nabla m_\theta(z) \right\rVert_2^2=\frac{h^2}{4}\sum_{\ell=1}^n\left([\nabla^2 m_\theta(z+h\zeta_\ell e_\ell)]_{\ell\ell}\right)^2.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 (Averaged off-diagonal gain on a fixed contour) of arXiv:2608.07820, 'Linear Spectral Statistics for Entrywise-Transformed Spiked Wigner Matrices under Shifted '] Let \(A=A^{\mathsf T}\) and assume
\(\operatorname{dist}(\Gamma,\spec(A))\ge c_\Gamma>0\).  For every fixed
\(r\ge1\) and \(z_1,\ldots,z_r\in\Gamma\),
\begin{equation}
 \frac1{N^2}\sum_{a\ne b}
 \left|
 \bigl((A-z_1I)^{-1}\cdots(A-z_rI)^{-1}\bigr)_{ab}
 \right|^2
 \le\frac{C_{\Gamma,r}}{N}.
\end{equation}
The same estimate holds in expectation when the spectral separation event has
probability \(1-o(N^{-D})\) for every fixed \(D\), with the complement
controlled by a standard resolvent cutoff.

[Theorem 2 of arXiv:2608.09419, 'Left-tail expansions for Schr\"oder branching processes with explicit convergence rates'] \lb{mainT} The following expansion holds
\[\lb{009}
w(x)=x^{-1}\sum_{n=1}^{+\iy}\sum_{m=-\iy}^{+\iy}\frac{\phi_n\k_{m}^{\ast n}x^{-\frac{n\ln p+2\pi\mathbf{i}m}{\ln E}}}{\Gamma(-\frac{2\pi\mathbf{i}m+n\ln p_1}{\ln E})}
\]
and
\[\lb{010}
 \lt|\frac{\phi_n\k_m^{*n}x^{-\frac{n\ln p+2\pi\mathbf{i}m}{\ln E}}}{\G(-\frac{n\ln p+2\pi\mathbf{i}m}{\ln E})}\rt|\le Ae^{({\log_Ep}+\ve)n\ln n+\frac{2\pi(\frac{\pi}2-\vt+\ve)}{\ln E}|m|},
\]
where, for any fixed $\ve>0$, the value $A=A(\ve,x)>0$ is uniformly bounded when $x$ belongs to any compact subset of $(0,+\iy)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 28 of arXiv:2506.10817, 'On the Weak Error for Local Stochastic Volatility Models'] Let $(\alpha_k)_{k=1}^n,(\beta_k)_{k=1}^n,(\gamma_k)_{k=1}^n$ and $(\Delta_k)_{k=1}^n$ be positive sequences and assume that $\alpha_k \le A$ as well as $a\le \gamma_k \le b$ for some $a\le 1\le A,b$. 

    Let $\delta > 0$ and assume that $|\alpha_k-\beta_k|\le C \max\bigl\{\alpha_k^p,\beta_k^p \bigr\} \Delta_k$ for some $C>0$ and $1/2\le p\le 1$. Then it holds that
   {
    \begin{align*}
    \Bigl|\frac{\frac1n\sum_{k=1}^n \alpha_k +\delta}{\frac1n\sum_{k=1}^n \alpha_k\gamma_k +\delta}-\frac{\frac1n\sum_{k=1}^n \beta_k +\delta}{\frac1n\sum_{k=1}^n \beta_k\gamma_k +\delta}
        \Bigr|
        \lesssim C \max_{j=1,\dots,n}\max\{\alpha_j,\beta_j\}^{p-\frac1{2}} \delta^{-1/2} \sqrt{\frac1n \sum_{k=1}^n \Delta_k^2}
        \end{align*}
    }

