        \AxiomC{$H[\ttX]\fCenter{\ttOmega+m+1}{\alpha_1}  \Gamma,\ \lnot A$}
        \RightLabel{(Cut)}
        \BinaryInfC{$H[\ttX]\fCenter{\ttOmega+m+1}{\alpha} \Gamma$}
    \end{mathprooftree}
    \end{equation*}
    with $\alpha_0,\alpha_1<\alpha$ and $\rk^{\bfL(u)}_{H(\ttX)}(A)<\ttOmega+m+1$. By applying the coinductive hypothesis to the premises, we get
    $H[\ttX]\sststile{\ttOmega+m}{\omega^{\alpha_0}} \Gamma,\ A$ ...","release_manifest_digest":"sha256:fabc10e78e67c19b04576f19599c9dea8f0e48cf83cc96d28b18c1fe39f22aa2","revision_digest":"sha256:9f2a4d63d375cab59d8087534f05febda52c27b52f390693b404e798215b480a","source_id":"arxiv:2608.29157","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

