body:
[Corollary 9 of arXiv:2605.03182, 'Exponential integrability of the solution to the stochastic Burgers equation driven by whi'] With the same hypotheses and notation of Theorem \ref{theorem:apriorigamma}, suppose that we consider the random variable
\begin{equation}
	\alpha_0(\omega)=\frac{1}{\varepsilon'}\left( c_T\left({K}_{\varepsilon_1, 4}(\omega)\right)^{\left(\frac{1}{4}-\varepsilon_1-\gamma\right)^{-1}}  + 1+ F(\omega) \right),
\end{equation}
	where $0 < \varepsilon' \leq 1$ is small enough such that $C_P \delta - c_{\varepsilon} \bar{c}_T (\varepsilon')^{8 \theta_{\gamma}/3} - \frac{\varepsilon}{2} =: \delta' > 0$ (the ``upper bound'' on $\varepsilon'$ does depend only on $\gamma$ and $\varepsilon_1$) and $F:\Omega \rightarrow \R_+$ is a square integrable random variable.	

	Then there are some constants $c_{1,\varepsilon',T},c_{2,\varepsilon',T}>0$ (depending on $\varepsilon'$ and $T$ but not on $F$) and a constant $c_{\gamma, \varepsilon_1} > 0$ (depending on $\gamma$ and $\varepsilon_1$ but not on $F$) such that, for any $\omega$ $\P$-a.s.,
\begin{equation}
\| Y_t^{n,x_n,u,\alpha_0(\omega)} (\omega)\|_{L^2_{\xi}}^2 \leqslant e^{-\delta_1 t} \|x_n\|_{L^2_{\xi}}^2+ c_{1,\varepsilon',T}\Big (1+F^{2}(\omega)+({K}_{\varepsilon_1,  4}(\omega))^{\theta}+ \| u(\omega)\|_{L^2_tL^2_{\xi}}^2\Big),
\end{equation}
\vskip -6mm 
\begin{multline}  
\int_0^T\|\nabla Y_s^{n,x_n,u,\alpha_0(\omega)} (\omega)\|_{L^2_{\xi}}^2\mathd s \\
\leqslant	c_{\gamma, \varepsilon_1} \|x_n\|_{L^2_{\xi}}^2 + c_{2,\varepsilon',T} \Big(1+  F^{2}(\omega)+ (	{K}_{\varepsilon_1,  4}(\omega))^{\theta}+ \| u(\omega)\|_{L^2_tL^2_{\xi}}^2 \Big). 
\end{multline}

