[Lemma 13 of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] Let $\alpha \subset \partial \BD$ be a deterministic connected arc. Let $\tau$ be a stopping time for the filtration generated by 
	\begin{equation*}
		\left(\SCB_t(\alpha; D_{\Gamma_\BD}^\BD), \Gamma_\BD|_{\SCB_t(\alpha; D_{\Gamma_\BD}^\BD)}\right)_{t \ge 0}. 
	\end{equation*}
	Let $\{V_j\}_j$ denote the connected components of $\BD \setminus \SCB_\tau(\alpha; D^\BD_{\Gamma_\BD})$.
	Then, there is a coupling $\{(\Gamma_\BD\vert_{V_j}, D^{V_j}_{\Gamma_\BD \vert_{V_j}})\}_j$ such that, conditionally on $\SCB_\tau(\alpha; D^\BD_{\Gamma_\BD})$, the $(\Gamma_\BD\vert_{V_j}, D^{V_j}_{\Gamma_\BD \vert_{V_j}})$'s are independent and have the law of $(\Gamma_{V_j}, D^{V_j}_{\Gamma_{V_j}})$ respectively. Moreover,
		\begin{itemize}
	\item For all $j$, for all $\SCL_1, \SCL_2 \in \Gamma_\BD|_{V_j}$, we have $D_{\Gamma_\BD}^\BD(\SCL_1, \SCL_2)\le D_{\Gamma_\BD|_{V_j}}^{V_j}(\SCL_1, \SCL_2)$.
	\item For all $j$, for all $\SCL \in \Gamma_\BD|_{V_j}, \ t \in [0, D_{\Gamma_\BD}^\BD(\SCL, \partial V_j)]$, we have $\SCB_t(\SCL; D_{\Gamma_\BD}^\BD) = \SCB_t(\SCL; D_{\Gamma_\BD|_{V_j}}^{V_j})$.
	\end{itemize}

[Lem elemlemma of arXiv:2506.15500, 'On extinction and survival of the Bak-Sneppen model on arbitrary graphs'] Let $X_n$ be an ergodic Markov chain on a finite state space $\mathcal{S}$ with the stationary distribution $\pi$; assume that $0$ is one of the states. Suppose there is a non-negative function $f:\mathcal{S}\to{\mathbb R}$ such that 
\begin{align}
\begin{split}
f(0)&=0;\\    
\max_{x\in\mathcal{S}: \ p_{0x}>0} f(x)&=c_0;\\
|f(X_{n+1})-f(X_n)|&\le C;\\
{\mathbb E}(f(X_{n+1})-f(X_n)\mid X_n=x)&<-\varepsilon,\quad x\ne 0,
\end{split}
\end{align}
for some $\varepsilon>0$, $c_0>0$, and $C>0$.
Then for some $c_1,c_2>0$ depending on $c_0,C,\varepsilon$ only,
\begin{align}
\pi(A_k)\le c_1 e^{-c_2 k},
\quad\text{where }A_k=\{x\in\mathcal{S}:\ f(x)>k\},\ k>0.  
\end{align}

[Lem l:8.2 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] For all $n$ large enough, $x \in {\rm D}_n^\circ$ and $y \in \partial {\rm B}(x; r_n)$, 
	\begin{equation}
		\mathbb{P}_y \big(\tau_{\partial} < \widecheck{{\mathbf T}}_{{\rm B}(x;r_n)} \big) \leq n^{-\eta_0/3}\,,
	\end{equation}
	where $\eta_0$ is as in~(equation e:2.3 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 18 of arXiv:2604.01978, 'Homogenized Transformers'] Let $X^n = §(x^{n}_1,\ldots, x^{n}_1)$ solve 
\begin{equation*}
\de x^{n}_i(t)=\int_{\Uptheta}G_{\mu^{n}(t)}(x_{i}^n(t);\bm{\theta})\mathsf{W}(\de \bm{\theta}, \de t),
\end{equation*}
with $\mu^n = \mu_{X^n}$. 
Let $(\bar x_1,\ldots,\bar x_n)$ be conditionally i.i.d., given $(\mathscr{F}^{\mathsf W}_t)_{t\geq0}$, copies of the unique solution $x$ of \eqref{eq:non_linear_SDE_common}, driven by the same common noise $\mathsf{W}$, and let $\bar\mu$ be their empirical measure. Then for every $T>0$ there exists $C_T>0$ such that 
\begin{align*}
    \max_{i\in[n]} \E \sup_{t\in[0, T]} \left\|x^{n}_i(t)-\bar x_i(t)\right\|^2 &+ \E \sup_{t\in[0, T]} W_2^2(\mu^n(t), \bar\mu^n(t)) \\
    &\leq  \frac{C_T}{n} \sum_{i=1}^n \E \left\|x^{n,i}(0)-\bar x^i(0)\right\|^2.
\end{align*}
In particular, after choosing an optimal coupling of the initial data, the right hand side may be written as $C_T \E W_2^2(\mu^n(0), \bar \mu^n(0))$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2506.17045, '\LARGE{On bivariate Archimax copulas: Level sets, mass distributions and related results}'] Let $\psi \in \mathbf{\Psi}$, $A \in \mathcal{A}$, $C_{\psi,A} \in \mathcal{C}_{am}$ and let $L$, $R$ be defined according to eq. \eqref{eq:definition_L_R}. Then 
    \begin{equation}
    \mathrm{supp}(\mu_{C_{\psi,A}}) \subseteq S_{L,R}
    \end{equation}
    holds.

[Cor unshuffling-cor of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $\mathbb{X}$ be a set and let $\psi$ be an $\mathbb{X}$-shuffling rule.
	If $\psi$ is $\mathfrak{S}$-equivariant, then for every $T,T'\in\trees$, ${\boldsymbol{x}}\in\mathbb{X}^T$, and ${\boldsymbol{\uppi}}\in\mathfrak{S}_{T'}$, we have
	\begin{align}
	\begin{cases}
	{\boldsymbol{\sigma}}^\psi_{T,{\boldsymbol{x}}}\cdotT=T',\\
	{\boldsymbol{\sigma}}^\psi_{T,{\boldsymbol{x}}}={\boldsymbol{\uppi}}^{-1}
	\end{cases}
	\qquad\iff\qquad
	\begin{cases}
	T={\boldsymbol{\uppi}}\cdotT',\\
	{\boldsymbol{\sigma}}^\psi_{T',{\boldsymbol{\uppi}}^{-1}_*{\boldsymbol{x}}}=\overline{\boldsymbol{\uppi}}.
	\end{cases}
	\end{align}

