[Proposition 116 of arXiv:2609.03875, 'Measure theory without infinities'] Let $\mf A$ be a regular HTM, $I$ and $J$ be sets, and $K = I\times  J$. Let $\sm{\mf A}{k\in K}{f(k)}$ and $x = \sum_{k\in K} f(k)$.
  \begin{enumerate}
  \item [(i)] Let $\sm{\mf A}{j\in  J}{f(i,j)}$ for every $i\in I$. Then $x = \sum_{i\in I}\sum_{j\in J}f(i,j)$.
  \item [(ii)] Let $\sm{\mf A}{i\in  I}{f(i,j)}$ for every $j\in J$. Then $x = \sum_{j\in J}\sum_{i\in I}f(i,j)$.
  \end{enumerate}

[Lemma lem_lozenge of arXiv:2608.09105, 'Longest convex chains with i.i.d.\ points'] Let $\lozenge\subset\mathbb{R}^2$ be a parallelogram.
Let $\wh\mathfrak{p}$ be a probability density function on $\lozenge$ such that
\eeq{ 
\frac{\sup_{(x,y)\in\lozenge}\wh\mathfrak{p}(x,y)}{1/\mathrm{Area}(\lozenge)} \leqslant R\in[1,\infty).
}
Let $\mathcal{S}_n^\lozenge$
be a set of $n$ independent samples from $\wh\mathfrak{p}$, and define
\eq{
\mathscr{L}_n^\lozenge \coloneqq \max\{\#\mathcal{C}:\, \mathcal{C}\subseteq\mathcal{S}_n^\lozenge \text{ and $\mathcal{C}$ is in convex position}\}.
}
Then for every $n\geqslant 1$ and $t\geqslant0$, we have the tail bound
\eeq{ 
\mathbb{P}\big(\mathscr{L}_n^\lozenge \geqslant (32R\e^3 n)^{1/3}+t\big)
\leqslant
2^{-(32R\e^3 n)^{1/3}-t}.
}

