[Defn def:Spectral_NS+NStable of arXiv:2606.29829, ''] Let $\{(X_n(t),\Omega_n,\pi_n)\}_n$ be a sequence of reversible and irreducible continuous-time Markov chains. Here $\Omega_n$ is the state space, and $\pi_n$ is the stationary distribution of the $n$th chain $X_n(t)$. Also, let $t_{\rel}^n$ be the \emph{relaxation time} (will be defined) of the $n$th chain $X_n(t)$. A sequence $\{\mathfrak{f}_n\}_n$ of Boolean functions,
 	$\mathfrak{f}_n : \Omega_n \longrightarrow \{0, 1\}$, is said to be
 	\begin{itemize}
 		\item \emph{Noise sensitive} with respect to $(X_n(t),\Omega_n,\pi_n)$ if for all $\alpha>0$,
 		\begin{equation}
 			\lim_{n\rightarrow\infty}\cov\left(\mathfrak{f}_n(X_n(0)),\;\mathfrak{f}_n(X_n(\alpha t^n_{\rel}))\right)=0,\text{ where }X_n(0)\sim \pi_n.
 		\end{equation}
 		\item \emph{Noise stable} with respect to $(X_n(t),\Omega_n,\pi_n)$ if
 		\begin{equation}
 			\lim_{\alpha\rightarrow0}\sup_n\mathbb{P}\left(\mathfrak{f}_n(X_n(0))\neq \mathfrak{f}_n(X_n(\alpha t^n_{\rel}))\right)=0,\text{ where }X_n(0)\sim \pi_n.
 		\end{equation}
 	\end{itemize}

