[Corollary cor order OmegamN of arXiv:2511.05223, 'Kac's Program and Relative Entropy Decay for Nonlinear Spin-Exchange Dynamics'] Let \(\nu \in \mathcal{P}(\Omega)\) be irreducible and assume that $\r\in\ensuremath{\mathcal D}_{\ensuremath{\mathcal A},N}$ satisfies the condition
\begin{align}
\langle \r - \r_\mathcal{A}(\nu), \r - \r_\mathcal{A}(\nu) \rangle = O\left( 1/N \right),
\end{align}
where $\r_\mathcal{A}(\nu)=(1+m_\ensuremath{\mathcal A}(\nu))/2$ is the density profile associated to $\nu$. 
Then,
\begin{align*}
\nu^{\otimes N} \left( \Omega_{N,\r}\right) \ge \frac{c}{N^{|\mathcal{A}|/2}},
\end{align*}
where $c=c(\nu)>0$ is a constant independent of $N$. In particular, 
\begin{align*}
\lim_{N \to \infty} \frac{1}{N} \log \left( \nu^{\otimes N} \left( \Omega_{N,\r}\right) \right) = 0.
\end{align*}

[Proposition prop:polybound of arXiv:2604.20327, 'Persistent Homology of the Wiener Sausage II: A Central Limit Theorem for Drifted Planar B'] There exists $C < \infty$ such that for every $t \geq 0$,
  \begin{equation}
    \mathbb{E}[H_t^2] \leq C(1 + t^3).
  \end{equation}
  Equivalently, for every bounded Borel $\psi$ supported in $[r_0, r_1]$,
  \begin{equation}
    \mathbb{E}\!\left[\left(\int_{r_0}^{r_1} \beta_1^t(r)\, \psi(r)\, dr\right)^{\!2}\right]
    \leq C_\psi (1 + t^3).
  \end{equation}

