[Prop 25 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] For $T>0$ and $\delta >0$, let $(X_t, W_t)_{0 \le t \le T}$ be a weak limit in $\mathbb{D}([0,T], \mathcal{H}^{-1}_{\mathrm{Sym}}(\mathbb{S})\times L^2_{\mathrm{Sym}}(\mathbb{S})
    )$ of the family $\{(X_t^{(h)},W_t)_{0 \le t \le T}\}_{{h \in T/{\mathbb N}^*}}$ when $h\searrow 0$. Then, almost surely, the following equation holds in a weak sense:
\begin{align}
\mathrm{d}X_t(\mathbf{x}) = -\frac{1}{2}D_{\mathbf{x}}\Big(\frac{1}{D_{\mathbf{x}}X_t(\mathbf{x})}\Big)\mathrm{d}t + \Delta_{\mathbf{x}} X_t(\mathbf{x})\mathrm{d}t +\mathrm{d}\nu_t(\mathbf{x}) + \mathrm{d}W_t(\mathbf{x}), \quad \forall \mathbf{x}\in \mathbb{S}, \ t \in  [0,T], 
\end{align}
where $(\nu_t)_{0 \le t \le T}$ stands for a process with values in ${\mathcal H}^{-2}_{\rm Sym}({\mathbb S})$ that is non-decreasing in the sense that, for any function $\varphi \in {\mathcal H}_{\rm Sym}^2({\mathbb S})$, 
$(\langle \varphi,\nu_t\rangle)_{0 \le t \le T}$ is non-decreasing. Moreover, for all $t \in [0,T]$,
\begin{equation*}
\lim_{\epsilon \searrow 0}
\mathbb{E}\int_{0}^{t} \mathrm{e}^{\epsilon \Delta}  X_r\cdot\mathrm{d}{\nu}_r =0,
\quad 
\lim_{\epsilon \searrow 0}
\mathbb{E} \biggl[ \biggl\vert \int_{0}^{t} \int_{\mathbb S} \frac{ \mathrm{e}^{\epsilon \Delta} 
D_{\mathbf{x}} X_r({\mathbf x})}{D_{\mathbf{x}} X_r({\mathbf x})} \mathrm{d}{\mathbf x} - t
\biggr\vert \biggr]=0.
\end{equation*}

In addition, the process $(X_t)_{0 \le t \le T}$ has time-continuous trajectories with respect to the norm $\|\cdot\|_2$.

[Theorem THM:1 of arXiv:2412.09790, 'Critical threshold for weakly interacting log-correlated focusing Gibbs measures'] Let $\{\lambda_N\}_{N\in \mathbb{N}}$ be 
a non-increasing sequence of positive numbers
tending to $0$ as $N \to \infty$, 
and 
let $\{K_N\}_{N\in \mathbb{N}}$ be a non-decreasing sequence
of positive numbers.
Then, there exist $\lambda^*\ge \lambda_*>0$ such that the following statements hold\textup{:}

\smallskip
\noindent
\textup{(i) (weakly coupling regime).}
Suppose that 
\begin{equation}
 \lambda_N\le \lambda_* (K_N+\log N)^{-1}

\end{equation}

\noindent
for any $N \in \mathbb{N}$.
Then, 
given any $p\geq 1$ we have
\begin{align}

    \sup_{N\in\mathbb{N}}
    \Big\|
    \mathbf 1_{\{|\int_{\mathbb{T}^d} \, : (\pi_N u)^2: \, dx| \, \leq K_N\}}  
    e^{ \lambda_N R_N (u)}
    \Big\|_{L^p(\mu)}<\infty.

\end{align}

\noindent
In particular, we have
\begin{align}
    \lim_{N\rightarrow\infty}
    \mathbf 1_{\{|\int_{\mathbb{T}^d} \, :(\pi_N u)^2: \, dx| \, \leq K_N\}}  
    e^{\lambda_N  R_N (u)}
    =
\mathbf 1_{\{|\int_{\mathbb{T}^d} \, :u^2: \, dx| \, \leq K\}}  
\quad     \text{in}\ L^p(\mu), 

\end{align}

\noindent
where 
$K = \lim_{N \to \infty}K_N \in (0, \infty]$.
Here, 
\[\int_{\mathbb{T}^d} :\!u^2\!:dx = \lim_{N \to \infty}
\int_{\mathbb{T}^d} :\!(\pi_N u)^2\!:dx,\]

\noindent
where the limit is understood in 
$L^p(\mu)$ and $\mu$-almost surely
as in Lemma (LEM:conv0 of the paper).
As a consequence, 
we have

\smallskip
\begin{itemize}
\item[(i.a)] 
 If $K  =  \lim_{N \to \infty}K_N  = \infty$, 
then the truncated Gibbs measure $\rho_N$
in (equation GibbsN1 of the paper)
converges in total variation to the base Gaussian measure $\mu$ in (equation gauss0 of the paper)
as $N \to \infty$.

\smallskip
\item[(i.b)]
 If $K = \lim_{N \to \infty}K_N < \infty$, 
then the truncated Gibbs measure $\rho_N$
in (equation GibbsN1 of the paper)
converges in total variation to the base Gaussian measure
with a renormalized $L^2$-cutoff\textup{:}
\begin{align*}
\mathbf 1_{\{|\int_{\mathbb{T}^d} \, :u^2: \, dx| \, \leq K\}}  d\mu, 

\end{align*}

\noindent
as $N \to \infty$.

\end{itemize}

\smallskip
\noindent
\textup{(ii) (strongly coupling regime).}
Suppose that 
\begin{equation}
\lambda_N\ge \lambda^{*}(K_N+\log N)^{-1}
 \end{equation}

\noindent
for any sufficiently large $N \gg 1$.
Then, we have 
\begin{align}
\sup_{N\in\mathbb{N}}Z_{N}:=
\sup_{N\in\mathbb{N}}\mathbb{E}_{\mu}
\Big[ \mathbf 1_{\{|\int_{\mathbb{T}^d} \, : (\pi_N u)^2: \, dx| \, \leq K_N\}}
e^{ \lambda_N R_N (u)} \Big]
=\infty.
\end{align}

\noindent
As a consequence, 
the truncated Gibbs measure $\rho_N$ in (equation GibbsN1 of the paper)
does not converge   to any  limit in total variation, even up to a subsequence. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:residual of arXiv:2608.30888, 'Three-term asymptotics for discrete\\ Hardy--Rellich constants in high dimension'] For every fixed $\ell\geq1$,
\begin{equation}
 \norm{(K_{\ell,N}-\mu_{\ell,N})w_{\ell,N}}
 =O_\ell(N^{\ell-3/2}).
\end{equation}

[Prop PRO73 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Assume that the assumptions of Theorems~(THM61-2 of the paper) and (THM61 of the paper) are both satisfied, and that the transition density function of $X$ satisfies the two-sided sub-Gaussian estimate (equation eq:71 of the paper). Let $x\in E$ and $B\in \mathscr{B}^n(E)$ satisfy $\tilde{d}(x,B)>0$. Then
 \begin{equation}
     \lim_{t\downarrow 0}\frac{\mathbb{P}^x[\sigma_B\leq t]}{\exp\left\{-\gamma_1 t^{-\frac{1}{\beta -1}}\right\}}=\lim_{t\downarrow 0}\frac{\exp\left\{-\gamma_2 t^{-\frac{1}{\beta -1}}\right\}}{\mathbb{P}^x[\sigma_B\leq t]}=0
 \end{equation}
 for any constants $\gamma_1,\gamma_2>0$ such that
\[
    \gamma_1<c_2\cdot \widetilde{d}(x,B)^{\beta/(\beta-1)}\leq C_2\cdot \widetilde{d}(x,B)^{\beta/(\beta-1)}<\gamma_2.
\]
In particular, if $x_1,x_2\in E$ and $B_1,B_2\in \mathscr{B}^n(E)$ satisfy
\begin{equation}
    c_2\cdot \widetilde{d}(x_1,B_1)^{\beta/(\beta-1)}>C_2\cdot \widetilde{d}(x_2,B_2)^{\beta/(\beta-1)},
\end{equation}
then
\begin{equation}
    \lim_{t\downarrow 0}\frac{\mathbb{P}^{x_1}[\sigma_{B_1}\leq t]}{\mathbb{P}^{x_2}[\sigma_{B_2}\leq t]}=0. 
\end{equation}

[Corollary eq:curve_evolution of arXiv:2512.17808, 'Zeros of polynomial powers under the heat flow'] Let us consider the setting of Corollary (cor:density of the paper), i.e.~let $D\subset \mathbb{C}\setminus B$ be a fixed simply connected domain such that $\Gamma_{i,j}^D(t)=\{z\in D:G(z,u_t^i(z))=G(z,u_t^j(z))\}\neq \emptyset$ for exactly one pair $1\leq i <j \leq d+1$, where $\Gamma_{i,j}^D(t)$  is a real analytic curve that separates $D=D_i\cup D_j\cup \Gamma_{i,j}^D(t)$ into two simply connected open domains $D_i$ and $D_j$ at time $t=t_0$. Further, for $z\in D$ we denote the two Stieltjes branches as $m_t^i(z)=\frac{z-u_t^i(z)}{t}$ and $m_t^j(z)=\frac{z-u_t^j(z)}{t}$ respectively. Then, for each $t_0$ such that $z(t_0)\in\Gamma_{i,j}^D(t_0)$ there exists $\varepsilon>0$ such that  \begin{align}
		\partial_t z(t)=\frac{m_t^i(z(t))+m_t^j(z(t))}2,\quad t\in[t_0-\varepsilon,t_0+\varepsilon],
		\end{align} 
with initial datum $z(t_0)$, has a unique solution that satisfies $z(t)\in\Gamma_{i,j}^D(t)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2512.19517, 'Spiking and Resetting'] For any $s>0$ and $\eta>0$, we have that 
\begin{equation}

\begin{split}
\Big( {\bf 1}_{e^\varepsilon_1 \ge s} \, {\bf 1}_{ \xi_{s}^\varepsilon - s \, \ge \,  \eta} \Big)_{\varepsilon>0} 
\end{split}
\end{equation}
converges, as $\varepsilon$ vanishes, to zero, in $\mathbb L^1$.

[Lemma lem:summed-cut-kernel of arXiv:2609.03532, 'Airy limit for the Jack process and topological expansion'] There are constants $C,c>0$ such that, uniformly in
$L\in\mathbb Z_{\geq0}$ and $d\in\mathbb Z_{\geq1}$,
\begin{equation}
  \mathcal K_L^\pm(d)
  \leq \frac{C}{(L+1)^{1/2}}
       \exp\!\left\{-\frac{c d^2}{L+d+1}\right\}.

\end{equation}
Expanding the two partition functions in each summand into paths, and let
$\mathcal K_{L,\geq R}^\pm(d)$ denote the restriction to pairs of raw
walks $(W^{\mathrm l},W^{\mathrm r})$ satisfying
\[
  \max\{\max W^{\mathrm l},\max W^{\mathrm r}\}\geq R.
\]
Then uniformly in $R\geq0$,
\begin{equation}
  \mathcal K_{L,\geq R}^\pm(d)
  \leq\frac{C}{(L+1)^{1/2}}
  \exp\!\left\{-c\left(
    \frac{d^2}{L+d+1}+\frac{R^2}{L+d+R+1}
  \right)\right\}.

\end{equation}

[Theorem thm:tailrl-harmonic-decomposition of arXiv:2609.02987, 'Tail Likelihood Reinforcement Learning'] The TailRL{} objective decomposes as
\begin{equation}
J_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{\infty}
\frac{\mathrm{Best\text{-}of\text{-}k}(\theta;x)-1}{k},

\end{equation}
and, under the regularity conditions of (lem:tailrl-regularity of the paper), its gradient satisfies
\begin{equation}
\nabla_\theta J_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{\infty}
\frac{1}{k}
\nabla_\theta \mathrm{Best\text{-}of\text{-}k}(\theta;x).

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm cty12pn of arXiv:2507.02518, '{\bf Exponential Ergodicity in Relative Entropy and $L^2$-Wasserstein Distance for non-equ'] Assume {\bf (C)}.
There exist  $K_*,c,\tilde c,\lambda>0$, depending on $d$ and on the constants in {\bf (C)} except on $K_I$, such that, provided $K_I\leqslant K_*$  then, for all $N\geqslant 1$,  (equation Degthp of the paper) has a unique invariant probability measure $\bar{\mu}^N\in\mathscr P_2((\mathbb R^{2d})^N)$,
\begin{align}\mathbb W_2((P_t^N)^\ast\nu^N,\bar{\mu}^N)^2\leq c\text{\rm{e}}^{-2 \lambda t}\mathbb W_2(\nu^N,\bar{\mu}^N)^2+cNR_{d}(N),\ \ t\geq 0, \nu^N\in\mathscr P_2((\mathbb R^{2d})^N),
\end{align}
and

\begin{align} \mathrm{Ent}((P_t^N)^\ast\nu^N|\bar{\mu}^N)\leq \tilde c\text{\rm{e}}^{-\lambda t}\mathbb W_2(\nu^N,\bar{\mu}^N)^2+cNR_{d}(N),~ t\geq 1, \nu^N\in\mathscr P_2((\mathbb R^{2d})^N)
\end{align}
where
\begin{equation*}\begin{split}
R_{d}(N)=
\begin{cases}
N^{-\frac{1}{2}},~~~~~~~~~~~~~~~~~~~~d<2,\\
N^{-\frac{1}{2}}\log (1+N),~~~~ ~~d=2,\\
N^{-\frac{2}{d}},~~~~~~~~~~~~~~~~~~~~d>2.
\end{cases}
\end{split}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 7 of arXiv:2606.10336, 'From Pitman's local times representation to the Gorin-Shkolnikov identity and beyond'] We have on $\{I_a > 0\}$, 
\begin{equation}
\frac{1}{I_a^{3/2}}\left(\int_0^1 (e(t)-a)_{+} - \frac{1}{2} \int_a^\infty \ell_x^2 dx + \frac{1}{4} \ell_a I_a\right) 
\stackrel{d}{=} \mathcal{N}\left(0, \frac{1}{12} \right),
\end{equation}
which is independent of $\mathcal{F}_a$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 (Evaluation of the quadratic Gau\ss\, sum) of arXiv:2609.04155, 'The subconvexity problem for symmetric square\\ $L$-functions in Level aspect'] If $q$ is odd,
			\begin{equation}
				G(a, b; q)= \eps_c \left(\frac{a}{q}\right)e\left(-\frac{\overline{4a}b^2}{q}\right) 
			\end{equation}
			where 
			\begin{equation*}
				\eps_c = \begin{cases}
					1, &\text{$c\equiv 1\md{4}$}.\\
					i, &\text{$c\equiv 3\md{4}$}.
				\end{cases}
			\end{equation*}
			If $q=2^k$ then,
			\begin{equation}
				G(a, b; q)=
				\begin{cases}
					\sqrt{2}\,1_{b\equiv 1\md{2}}, &\text{$k=1$.}\\
					\frac{1}{2^{k/2}}1_{b\equiv 0\md{2}}e\left(\frac{\bar{a}b^2/4}{q}\right)\left(1+e\left(\frac{a}{2^2}\right)\right), &\text{$k>1$ and $k\equiv 0\md{2}$}.\\
					\frac{1}{2^{(k-1)/2}}1_{b\equiv 0\md{2}}e\left(\frac{\bar{a}b^2/4}{q}\right)e\left(\frac{a}{2^3}\right), &\text{$k>1$ and $k\equiv 1\md{2}$.}
				\end{cases}
			\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition $U$-Functionals of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] A function $U: \mathcal{S}(\mathbb{R}) \to \mathbb{C}$ is called a \emph{$U$-functional} iff $U$ meets both of the following two conditions:
	\begin{enumerate}
		\item $U$ is \emph{ray-analytic}, i.e.\ for all $\varphi$, $\psi \in \mathcal{S}(\mathbb{R})$ the function $\mathbb{R} \mathrel{\reflectbox{$\in$}} s \mapsto U(\varphi + s \psi) \in \mathbb{C}$
		is entire analytic and therefore extends to an entire function on $\mathbb{C}$.
		\item $U$ is \emph{uniformly bounded of exponential order 2}, i.e.\ there exist constants $A$, $B\in\mathbb{R}_{\geq 0}$ and $p \in \mathbb{N}_{0}$ s.th.\ for all $z\in\mathbb{C}$, $\varphi \in \mathcal{S}(\mathbb{R})$ it holds
		\begin{equation*}
			|U(z\varphi)| \leq A \exp(B|z|^2\|\varphi\|_{p}^2).
		\end{equation*}
	\end{enumerate}

[Lemma IBW-P-A-1 of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] The building block ${\mathbb{W}_{\xi }}\left( {t,x} \right)$ is real-valued, and admits
\begin{equation*}
\int_{{\mathbb{T}^2}} {{\mathbb{W}_\xi }\left( x \right) \otimes {\mathbb{W}_\xi }\left( x \right)}\ \mathrm{d}x = \mathscr{M} \left( {t,r} \right) {\xi } \otimes {\xi } ,
\end{equation*}
where the function $\mathscr{M} \left( {t,r} \right)$ satisfies the uniform bound ${C_2} \leqslant \left| {\mathscr{M}\left( {t,r} \right)} \right| \leqslant {C_1}$. Furthermore, if $\xi  = \tilde \xi $, one then has
\begin{equation}
\mathrm{div}\left( {{\mathbb{W}_{\xi }} \otimes {\mathbb{W}_{\xi }}} \right) = \left( {{\mathbb{W}_\xi } \cdot \nabla } \right){\mathbb{W}_\xi } + \left( {{\mathbb{W}_{\xi ^ \bot } } \cdot \nabla } \right){\mathbb{W}_{\xi ^ \bot } } - 4{{\tilde \mu }^{ - 1}}a_W^2\xi {\cos ^2}\left( {{\xi ^ \bot }  \cdot x} \right){\partial _t}\left( {\mathfrak{D}_{\tilde \mu }^2} \right) .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

