[Define Definition 4.1 of arXiv:2601.09990, 'Remarks on the convex integration technique applied to singular stochastic partial differe'] Given initial data $u^{\text{in}} \in L^{n} (\mathbb{T}^{d})$, a scalar field $u \in L^{n} (0, \infty; L^{n} (\mathbb{T}^{d}))$ is a weak solution to (equation odd power of the paper) if 
\begin{align}
&\int_{\mathbb{T}^{d}} u(t,x) \psi(t,x) dx - \int_{\mathbb{T}^{d}} u^{\text{in}} (x) \psi(0,x) dx - \int_{0}^{t} \int_{\mathbb{T}^{d}} u(s,x) \partial_{s} \psi(s,x) dx ds  \nonumber \\
& \hspace{30mm} + \int_{0}^{t} \int_{\mathbb{T}^{d}} u^{n}(s,x) \psi(s,x) dx ds = \int_{0}^{t} \int_{\mathbb{T}^{d}} u(s,x) \Delta \psi(s,x) dx ds 
\end{align} 
for all test function $\psi$ in $C_{c}^{\infty} ( (-\infty, T) \times \mathbb{T}^{d})$.

[Definition 1path of arXiv:2606.27844, 'Critical percolation on preferential attachment graphs with infinite variance'] \text{}\\[-5mm]
\begin{itemize}
\item    
    \emph{Let $i,j\in\{1,\dots,\lfloor sn \rfloor\}$ and $K_\gamma:=\lfloor\tfrac{1-\gamma}{2\gamma-1}\big\rfloor$. Write $j\overset{1\text{-path}}{\longleftrightarrow}i$} for the event, that there exists an $l\in\{1,\dots, K_\gamma\}$ and distinct vertices $y_1,\dots,y_{l-1}\in\{m+1,\dots,\lfloor sn\rfloor\}$ and $x_1,\dots,x_{l}\in\{\lfloor sn\rfloor+1,\dots,n\}$ such that $i \sim x_1$, $j\sim x_{l}$ and $x_{k} \sim y_k \sim x_{k+1}$ for all $k\in\{1,\dots,l-1\}$. 
\item \emph{If  $i\in\{1,\ldots, \lfloor sn\rfloor\}$, $x\in\{\lfloor sn\rfloor+1,\dots,n\}$ write $x\overset{1\text{-path}}{\longleftrightarrow}i$ for the event that there exists  $j\in\{m+1,\dots,\lfloor sn\rfloor\}$ such that $x\sim j$ and also \smash{$j\overset{1\text{-path}}{\longleftrightarrow}i$.}}

\end{itemize}

