body:
[Lemma 21 (Range domination) of arXiv:2604.01852, 'The on/off Brownian snake'] As previously, let $(\mathcal{X}_y)_{y \geq 0}$ be the $\text{SBM}(4)$ defined in Theorem \ref{theorem sbm snake}; let $(\mathcal{Y}^{(\rm d)}_s, \mathcal{Y}^{(\rm a)}_s)_{s \geq 0}$ be the $\text{ooSBM}(4, c, \Tilde{c})$ (defined in Corollary \ref{corollary continuous modifications}) which is the continuous modification of the process $(\mathcal{Z}^{(\rm d)}_s, \mathcal{Z}^{(\rm a)}_s)_{s \geq 0}$ (defined in Theorem \ref{theorem ooSBM ffd convergence}); and let $(\Tilde{\mathcal{Y}}_s)_{s \geq 0}$ be the $\text{DSBM}(4, c)$ defined in Corollary \ref{corollary continuous modifications} which is the continuous modification of the process $(\Tilde{\mathcal{Z}}_s)_{s \geq 0}$ defined in Proposition \ref{proposition damped sbm}. Let $\mathcal{Y}_s = \mathcal{Y}^{(\rm d)}_s + \mathcal{Y}^{(\rm a)}_s$ for $s \geq 0$. Note that all these processes are defined on the same probability space $(\Omega, \mathcal{F}, \mathbb{P}_{(\mu_{\rm d},\mu_{\rm a})})$. Then we have
    \begin{equation*}
        \overline{\bigcup_{0 \leq s \leq t} \text{supp}(\Tilde{\mathcal{Y}}_s)} \subseteq \overline{\bigcup_{0 \leq s \leq t} \text{supp}(\mathcal{Y}_s)} \subseteq \overline{\bigcup_{0 \leq s \leq t} \text{supp}(\mathcal{X}_s)} \hspace{0.5cm} \forall t \geq 0 \hspace{0.25cm} \mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}\text{-a.s.}
    \end{equation*}
    \begin{proof}
    Let $t \geq 0$. Firstly by Lemma \ref{lemma supports sbm and oosbm} we have
        \begin{equation*}
            \text{supp}(\Tilde{\mathcal{Y}}_s) = \overline{\bigcup_{i \in I}\{\hat{w}^i_r, r \in [0,\sigma(f^i)], f^i_r = s, s_i = 0, \hat{\Tilde{v}}^i_r=0\}} \hspace{0.25cm} \text{ for all   } s \in \mathbb{Q} \hspace{0.25cm} \mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}\text{-a.s.,}
        \end{equation*}
        and therefore by Proposition \ref{proposition closure of range of continuous process} we have that 
        \begin{equation*}
            \overline{\bigcup_{0 \leq s \leq t} \text{supp}(\Tilde{\mathcal{Y}}_s)} = \overline{\bigcup_{i \in I}\bigcup_{0<s<t, s \in \mathbb{Q}}\hat{w}^i_r, r \in [0,\sigma(f^i)], f^i_r = s, s_i = 0, \hat{\Tilde{v}}^i_r=0\}}.
        \end{equation*}
        Now, we note that for $i \in I$, $r \in [0,\sigma(f^i)]$, if $f^i_r = s$ and $\hat{\Tilde{v}}^i_r=0$ then $H^i_r(s) = s$ and so $f^i_r = H^i_r(s)$. Furthermore as $s<t$ we have that $H^i_r(t) = H^i_r(s) = f^i_r$. Therefore, by Lemma \ref{lemma support sbm interval 2}, we have that $\hat{w}^i_r$ is in the support of $\overline{\bigcup_{0 \leq s \leq t}\text{supp}(\mathcal{Y}_s)}$. As this holds for all such $\hat{w}^i_r$ we have the first inclusion of this lemma.
        \par
        For the second inclusion we note that the age process $H^X_r(y) \leq y$ for any $r$ and any snake $X$ by definition of the age process in Definition \ref{definition age process} and so the result follows by Theorem \ref{theorem sbm snake} and Lemma \ref{lemma support sbm interval 2}. We have this result for all $t \in \mathbb{Q}$ simultaneously but we can extend this to all $t \in [0,\infty)$ simultaneously with Proposition \ref{proposition closure of range of continuous process} which shows us we only need to consider the supports over the rational time points.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Def: J of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] For any $\rho\in{\mathcal T}_b$ with $k+1$ leaves and $\ell\in\{1,\ldots,m_L(\rho)+1\}$ we define recursively a multi-index  
		$J_{\rho,\ell}:\{0,1,\ldots,k\}^\ell_<\to\mathbb{N}$ as follows: 
		\begin{itemize} 
		\item $J_{\bullet_i,1}=\un{(0)}$ and, given 
		$J_{V^-(\rho),m_L(\rho)}: \{0,\ldots,k-1\}^{m_L(\rho)}_<\to\mathbb{N}$, recall (equation V- of the paper),
			\item for $j\in\{0,\ldots,k\}$
			\[
			J_{\rho,1}(\,j) := \sum_{i_1<\cdots <i_{m_L(\rho)}<k} 
			\un{(i_1<j )}\, J_{V^-(\rho),m_L(\rho)}(i_1,\ldots,i_{m_L(\rho)})\,,
			\]
			\item for $\ell\in\{2,\ldots,m_L(\rho)\}$, $\boldsymbol{j}_\ell=(\,j_1,\ldots,j_{\ell})\in\{0,\ldots,k\}^\ell_<$:
			\begin{equation}
			J_{\rho,\ell}(\,\boldsymbol{j}_\ell) := \sum_{i_{\ell}<\cdots <i_{m_L(\rho)}<k} 
			\un{(\, j_\ell \le i_\ell)}\, J_{V^-(\rho),m_L(\rho)}(\,j_1,\ldots,j_{\ell-1},i_{\ell},\ldots ,i_{m_L(\rho)})\,,
			\end{equation}
			\item for $\boldsymbol{j}_{m_L(\rho)+1}=(\,j_1,\ldots,j_{m_L(\rho)+1})\in\{0,\ldots, k\}^{m_L(\rho)+1}_<$:
			\begin{equation}
				J_{\rho,m_L(\rho)+1}(\,\boldsymbol{j}_{m_L(\rho)+1}) := 
				J_{V^-(\rho),m_L(\rho)}(\,j_1,\ldots,j_{m_L(\rho)})\,.
			\end{equation}


		\end{itemize}

[Lem 16 (Weak initial trace condition) of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] Let $(u,\nu)$ be the pair constructed in the proof of Theorem \ref{thm:existence-obstacle-solution}.

Then, we have
\begin{equation*}
\lim_{\tau\downarrow0}\frac1{\tau}\int_0^\tau\Vert u(t)-u^0\Vert_{L^2(\mathbb T^N)}^2\dd t=0,\qquad \mathbb P\text{-a.s.,}
\end{equation*}
and therefore,
\begin{equation*}
\lim_{\tau\downarrow0}\frac1{\tau}\int_0^\tau\Vert u(t)-u^0\Vert_{L^1(\mathbb T^N)}\dd t=0,\qquad \mathbb P\text{-a.s.,}
\end{equation*}
which means that the pair $(u,\nu)$ satisfies the weak initial trace condition in Definition \ref{def:dfn-1}.

[Lem bdlr of arXiv:2608.13084, '\bf Branching random walk in random environment'] There exist constants $C_1,C_2\in(0,\infty)$ such that for any $\delta\in(0,1]$ and any admissible path $(x_j)_{j\le n}\in({\mathbb Z}^d)^n$, one has for any $1\le j\le n$,
\begin{equation}
C_1\widehat{{\mathbb E}}^\omega_{(x_j)_{j\le n}}[ (1-\delta)^{l_j}] \widehat{{\mathbb E}}^\omega_{(x_j)_{j\le n}}[ r_j ] \le \widehat{{\mathbb E}}^\omega_{(x_j)_{j\le n}}[ (1-\delta)^{l_j} r_j ] \le C_2 \widehat{{\mathbb E}}^\omega_{(x_j)_{j\le n}}[ (1-\delta)^{l_j}  ] \widehat{{\mathbb E}}^\omega_{(x_j)_{j\le n}}[ r_j  ] .
\end{equation}
Further, as $\delta\downarrow0+$, uniformly in $j,n$ and $(x_j)_{j\le n}\in({\mathbb Z}^d)^n$,
\begin{equation}
\widehat{{\mathbb E}}^\omega_{(x_j)_{j\le n}} [(1-\delta)^{l_j} r_j ] =  \widehat{{\mathbb E}}_{(x_j)_{j\le n}}^\omega \left[(1-\delta)^{l_j} \right] \widehat{{\mathbb E}}_{(x_j)_{j\le n}}^\omega \left[ r_j \right] + o_\delta(1).
\end{equation}

