[Proposition 3 of arXiv:2604.16795, '2604.16795'] Suppose that Assumption {\rm\ref{A0}} holds. Then the following statements hold.
	\begin{itemize}
		\item[{\rm(i)}] Assume that \begin{equation}\limsup_{|x|\to \infty} \frac{V_-(x)}{|x|^2}=0,\quad \limsup_{|x|\to \infty}\frac{V_-(x)}{\inf_{z\in B(x,|x|/2)}\widetilde K(z)}<\infty.\end{equation}
		Then, for any $c>0$, there are constants $c_1,c_2, r_0>0$ and $T_0\ge1$ such that for all $n\ge0$, $x\in \R^d$ with $|x|\ge r_0$,
		\[ |\va_n(x)|\le c_1e^{\lambda_n T_0/2}\exp\left(-{V_+(x)}\right)\left[\exp\left(-c\inf_{z\in B(x,|x|/2)}\widetilde K(z)\right)+\exp\left(- c_2 |x|^2 \right)\right].\]
		\item[{\rm(ii)}]  Assume that \begin{equation}\limsup_{|x|\to \infty} \frac{|x|^2}{\inf_{z\in B(x,|x|/2)}\widetilde K(z)}<\infty, \quad \limsup_{|x|\to\infty}\frac{V_-(x)}{|x|\inf_{z\in B(x,|x|/2)}\widetilde K(z)^{1/2}}=0.\end{equation} Then, there are constants $c_1,c_2,r_0>0$ and $T_0\ge1$ such that for all $n\ge0$ and $x\in \R^d$ with $|x|\ge r_0$,
		\[ |\va_n(x)|\le c_1e^{\lambda_n T_0/2}\exp\left(-{V_+(x)}\right)\exp\left(-c_2|x|\inf_{z\in B(x,|x|/2)}\widetilde K(z)^{1/2}\right).\]
	\end{itemize}

