[Lemma lemma_RN_infty of arXiv:2411.16452, 'Interface scaling limit for the critical planar Ising model perturbed by a magnetic field'] For $(\delta_m)_m$ as in Lemma (lemma_thinness_gamma of the paper), almost surely, for $\xi \in \{+,-\}$ with $j(\xi)=L$ if $\xi=+$ and $j(\xi)=R$ if $\xi=-1$,
\begin{align} 
    \lim_{m \to \infty} \sum_{k=0}^{\infty} \frac{C_{\sigma}^{-k}h^k}{k!}\delta_m^{\frac{15k}{8}} {\mathbb{E}}_{m,j(\xi)}^{\xi} \big[\big( \sum_{x \in \Omega_{m,j(\xi)}}\sigma_x\big)^k \big]
    = \sum_{k=0}^{\infty} \frac{h^k}{k!} \int_{\Omega_{j(\xi)}^k} f_{j(\xi)}^{(\xi,k)}(x_1, \dots ,x_k) \prod_{j=1}^{k} dx_j < \infty
\end{align}
where the functions $f_{j(\xi)}^{(\xi,k)}:=f_{\Omega_{j(\xi)}}^{(\xi,k)}$ are as in Theorem (theorem_spin_correlations of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem SSK with external field \cite{ChenDeyPanchenko,Baiketal21,landon2020fluctuations} of arXiv:2510.26960, 'Free energy fluctuations in SK and related spin glass models: \\ A literature survey'] For fixed external field strength $h>0$, the free energy of SSK at any inverse temperature $\beta>0$ exhibits the following convergence in distribution as $N\to\infty$:
 \begin{equation} 
N^{1/2}(F_N(\beta,h)-F(\beta,h))\to \mathcal{N}(0,v_{h,\beta})
 \end{equation} 
where formulas for $F(\beta,h)$ and $v_{h,\beta}$ can be found in Results 5.5-5.6 of [Baiketal21]. Note in particular
\begin{itemize}
\item As $h\to0$, the value of $F(\beta,h)$ converges to the formula given in (equation eq:limitingF_SSK of the paper);
\item The value of $v_{h,\beta}$ changes slightly depending on whether one chooses the external field to be random (as in [Baiketal21]) or deterministic (as in [ChenDeyPanchenko,landon2020fluctuations]).  See Section 5.3 of [Baiketal21] for a comparison.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:def_attention of arXiv:2609.03129, 'A Closed-Form Formula for Consistent Lipschitz Regression on Metric Spaces with Sparse Neu'] Let $\lambda>0$, and let $d_{\rm in},d_{{\rm key}},d_{\rm out},N\in \mathbb N$. 
Let
${\bf Q},{\bf K}\in \mathbb{R}^{d_{{\rm key}}\times d_{\rm in}}$
and
${\bf V}\in \mathbb{R}^{d_{\rm out}\times d_{\rm in}}$. 
We define the associated attention mechanism
$\operatorname{Attn}(\cdot|{\bf Q},{\bf K},{\bf V},\lambda):\mathbb{R}^{N\times d_{\rm in}}\to \mathbb{R}^{N\times d_{\rm out}}
$
by
\begin{equation} 
    [\operatorname{Attn}(\mathbf{X}|{\bf Q},{\bf K},{\bf V},\lambda)]_n
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} 
    \sum_{m=1}^N
    \frac{e^{\lambda \langle {\bf Q}[\mathbf{X}]_n, {\bf K}[\mathbf{X}]_m\rangle/\sqrt{d_{{\rm key}}}}}{
    \sum_{l=1}^N e^{\lambda \langle {\bf Q}[\mathbf{X}]_n, {\bf K}[\mathbf{X}]_l \rangle/\sqrt{d_{{\rm key}}}}}
    {\bf V}[\mathbf{X}]_m, \qquad n=1,\dots,N.
\end{equation}
Here $[\mathbf{X}]_j \in \mathbb{R}^{d_{\rm in}}$ denotes the $j$th row of $\mathbf{X}$, interpreted as a column vector when multiplied by ${\bf Q},{\bf K},{\bf V}$.

A transformer network operates by iterating layers, each consisting of a row-wise activation–bias map followed by an attention mechanism.
Concretely, let $d,D,L\in\mathbb{N}$, and let $d_0,d_1,\dots,d_L, H_0,H_1,\dots,H_L\in\mathbb{N}$ such that $d_0=d$ and $d_L=D$.
For $j=0,1,\dots,L-2$ and $\mathtt{h}=1,\dots,H_j$, let $d^{(j)}_{{\rm key}, \mathtt{h}}, d^{(j)}_{{\rm value}, \mathtt{h}}\in\mathbb{N}$ such that $d_{j+1} = \sum_{{\mathtt{h}}=1}^{H_j} d^{(j)}_{{\rm value}, \mathtt{h}}$.
A $j$th \emph{transformer layer with Multi-head attention}, for $j=0,1,\dots,L-2$, is a map
$
\mathcal{T}_j:\mathbb{R}^{N\times d_j}\to \mathbb{R}^{N\times d_{j+1}}
$
that sends an input matrix $\mathbf{X}^{(j)}\in \mathbb{R}^{N\times d_j}$ to
$
\mathcal{T}_j(\mathbf{X}^{(j)})\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}  \mathbf{X}^{(j+1)}\in \mathbb{R}^{N\times d_{j+1}},
$
where 
\begin{alignat}{2} 
    \nonumber \mathbf{Z}^{(j)}
    &\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} 
    \underbrace{
        \bigoplus_{\mathtt{h}=1}^{H_j}
            \operatorname{Attn}\big(
                \mathbf{X}^{(j)}
                |{\bf Q}_{\mathtt{h}}^{(j)},{\bf K}_{\mathtt{h}}^{(j)},{\bf V}_{\mathtt{h}}^{(j)},\lambda
            \big)
    }_{\text{Multi-head attention}} && \\
     [\mathbf{X}^{(j+1)}]_n
    &\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}  

        \sigma\bullet
        \big(
            [\mathbf{Z}^{(j)}]_n + b^{(j)}
        \big),

    &&\qquad n=1,\dots,N.
\end{alignat}
Here $\bigoplus$ denotes concatenation along the second (column) dimension, $
{\bf Q}_{\mathtt{h}}^{(j)},{\bf K}_{\mathtt{h}}^{(j)}\in \mathbb{R}^{d_{{\rm key}, \mathtt{h}}^{(j)}\times d_j}$ and 
$
{\bf V}_{\mathtt{h}}^{(j)}\in \mathbb{R}^{d_{{\rm value}, \mathtt{h}}^{(j)}\times d_j}$, and $b^{(j)}\in\mathbb{R}^{d_{j+1}}$.
Further, the addition in (equation eq:representation_transformer of the paper) is applied row-wise.
A \emph{transformer with Multi-head attention} with depth $L$, obtained by composing the layers $\mathcal{T}_0,\mathcal{T}_1,\dots,\mathcal{T}_{L-2}$, is a map $\mathcal{T}:\mathbb{R}^{N\times d}\to\mathbb{R}^{N\times D}$ sending an input matrix ${\bf X}^{(0)}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} {\bf X}\in\mathbb{R}^{N\times d}$ to $\mathcal{T}({\bf X}) \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} {\bf A}^{(L-1)}{\bf X}^{(L-1)} + b^{(L-1)}\in\mathbb{R}^{N\times D}$, for some ${\bf A}^{(L-1)}\in\mathbb{R}^{D\times d_{L-1}}$ and $b^{(L-1)}\in\mathbb{R}^D$.

[Corollary 9 (Joint distribution of descents, valleys, and cycle type) of arXiv:2606.18047, 'Analysis of the asymmetric shelf shuffle'] For $t\in (0, 1)$, as a formal power series in $u$, one has
\begin{align}
&\frac{t}{1-t}+\sum_{n\ge1}u^n\sum_{\pi\in S_n}\frac{t^{\vl(\pi)+1}}{p^n(1-t)^{n+1}}(p+qt)^{\asc(\pi)-\vl(\pi)}
(q+pt)^{\des(\pi)-\vl(\pi)}X(\pi;\x)

\\
&\qquad=\sum_{m\ge1}t^m\prod_{i\ge1}
\exp\left\{
\sum_{r\ge1}
\frac{x_i^r u^{ir}}{ir}
\sum_{d\mid i}
\mu(d)m^{i/d}
\left(1-\left(-\frac{q}{p}\right)^{dr}\right)^{i/d}
\right\}.
\notag
\end{align}
The same identity holds with \(\vl(\pi)\) replaced by \(\pk(\pi)\).

[Proposition p: d=1 p=2 limit example of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $d=1$. Suppose that $Z$ is not deterministic, that it has a finite second moment, and define $C:\R\to [0,\infty), y\mapsto \BC[Z(0), Z(y)]$. Further, assume that $Z$ and $\Phi$ are independent, and that $\Phi$ is (pseudo-) ergodic and not $\infty$-uniform. Finally, either assume that there is an $a>0$ such that
    \begin{equation}
        \int e^{a|x|} |C(x)|\, dx <\infty,
    \end{equation}
    or assume that the following integral exists for some $n\in\N_0$, and that
    \begin{equation}
        \int x^{2n} C(x)\, dx \neq 0.
    \end{equation}
    Then $Z\cdot \Phi$ is not beyond $0$-uniform, and $\Psi$ is not beyond $2$-uniform.

    \begin{proof}
        First, we notice that~(equation e:counterexample p=2 random field 1 of the paper) implies~(equation e:counterexample p=2 random field 2 of the paper), as $Z$ is not deterministic, and therefore $C\neq 0$. In turn,~(equation e:counterexample p=2 random field 2 of the paper) implies that $\hat{C}$ is integrable and continuous, and that there is some $\varepsilon_0>0$ such that $\hat{C}(k)>0, k\in B_{2\varepsilon_0}\setminus\{0\}$. Further, because $\Phi$ is (pseudo-) ergodic and not\linebreak $\infty$-uniform, $\hat\beta_\Phi(B_{\varepsilon_0}\setminus\{0\}) = \hat\beta_\Phi(B_{\varepsilon_0})>0$, where we used Proposition~(p:pseudo ergodic of the paper). Hence, there is also an $\varepsilon_1\in(0,\tfrac{\varepsilon_0}{2})$ such that $\hat\beta_\Phi(B_{\varepsilon_0}\setminus B_{2\varepsilon_1})>0$. By continuity of $\hat{C}$, there is a $c>0$ such that $\hat{C}(k)\geq c, k\in B_{\varepsilon_0+\varepsilon_1}\setminus B_{\varepsilon_1}$. In total, we obtain that 
        \begin{equation*}
            (\hat{C}\ast\hat\alpha_\Phi)(k) = \int \hat{C}(k-s) \,\hat\alpha_\Phi(ds) \geq c\hat\beta_\Phi(B_{\varepsilon_0}\setminus B_{2\varepsilon_1}) >0, \quad k\in B_{\varepsilon_1}.
        \end{equation*}
        By the formula for $\hat\beta_{Z\cdot\Phi}$ from Proposition~(p: ind random field convolution formula of the paper), we can conclude that $\varepsilon^{-d}\hat\beta_{Z\cdot\Phi}(B_\varepsilon)$ is bounded from below, as $\varepsilon\to0$. Hence, $Z\cdot\Phi$ is not beyond $0$-uniform.

        For the final part of the proof, we can assume that $Z$ is centered, i.e., $\BE[Z(0)]=0$, as centering $Z$ does not change the distribution of $\Psi$. Let $f\in\cC_c^\infty(\R, [0,\infty))$ with $f\neq0$, and recall Definition~(d: f_r of the paper). From the more precise statement in Theorem~(t:main theorem formula of the paper) compared to Theorem~(t: main theorem displacement of the paper), we know that, as $r\to\infty$,
        \begin{align}
            \BV[\Psi(f_r)] &= \BV[\Phi(f_r) + (Z\cdot\Phi)(f_r')] + o(r^{-1})\nonumber\\
            &= \BV[\Phi(f_r)] + 2\BC[\Phi(f_r), (Z\cdot\Phi)(f_r')]  + \BV[(Z\cdot\Phi)(f_r')] + o(r^{-1}).
        \end{align}
        From the first part of the proof and Proposition~(p:asymptotic variance test function zero integral of the paper) we know that\linebreak $\BV[(Z\cdot\Phi)(f_r')]=r^{-2}\BV[(Z\cdot\Phi)(f'(\tfrac{\cdot}{r}))]\neq o(r^{-1})$. Hence, if $\Psi$ was beyond $2$-uniform, whereby $\BV[\Psi(f_r)]=o(r^{-1})$ by Theorem~(t:asymptotic variance test function of the paper), the covariance term on the right-most side of~(equation e: covariance equation p=2 counterexample random field of the paper) would need to cancel the part which is not $o(r^{-1})$ since a variance cannot be negative. However, since $Z$ is centered and independent of $\Phi$, we know that the intensity of $Z\cdot\Phi$ is $0$, and
        \begin{align}
            \BC[\Phi(f_r), (Z\cdot\Phi)(f_r')] = \BE[\Phi(f_r) (Z\cdot\Phi)(f_r')]\nonumber
            =\BE[Z(0)]\BE[\Phi(f_r) \Phi(f_r')] = 0,\quad r>0.
        \end{align}
        Actually, one can even show that both factors on the right-most side are $0$.
        Thus, the cancellation is impossible, and $\Psi$ cannot be beyond $2$-uniform.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:main of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] Let $\lambda=7/8$. Then, we have the following convergence in law
	\begin{equation}
		\ensuremath{\mathcal Y}_{\lambda,N}
		\xLongrightarrow[N\to\infty]{}
		\ensuremath{\mathcal Y}\; \text{,}\;\;
		\qquad
		\text{in}\  \ensuremath{\mathcal D}([0,\infty);\mathscr M_f(\mathbb{R}))\; \text{.}
	\end{equation}
	Here, $\ensuremath{\mathcal Y}=\ensuremath{\mathcal Y}(t,z)$ is the unique continuous It\^o--Walsh solution to the
	multiplicative SHE
	\begin{equation}
		\partial_t\ensuremath{\mathcal Y}(t,z)
		=
		\tfrac12\partial_z^2\ensuremath{\mathcal Y}(t,z)
		+
		{\tfrac{1}{\sqrt 2}}\,\ensuremath{\mathcal Y}(t,z)\,\xi(t,z)\; \text{,}\;\;
		\qquad
		\ensuremath{\mathcal Y}(0,{\,\cdot\,})=\delta_0\; \text{,}\;\;
	\end{equation}
	where $\xi=\xi(t,z)$ is a standard space-time white noise on
	$\mathbb{R}_+\times\mathbb{R}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

