[Lemm prop:BVP_general0 of arXiv:2606.06187, 'How to Study Reflected Brownian Motion in a Quadrant via Kernel Functional Equations?\\ \m'] The Laplace transform $\widehat \pi_1$ satisfies the following boundary value problem:
\begin{enumerate}[label={\rm (\roman{*})},ref={\rm (\roman{*})}]
     \item $\widehat \pi_1$ is meromorphic on $\mathcal{D}_\mathcal{R}$ with at most a simple pole $p$ and is bounded at infinity;   
     \item $\widehat \pi_1$ is continuous on $\overline{\mathcal{D}_\mathcal{R}}\setminus \{p\}$ and
\begin{equation}

     \widehat \pi_1(\overline{y})=G(y)\widehat \pi_1({y}), \qquad \forall y\in \mathcal{R}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:extinct_1dep of arXiv:2607.16911, 'Multipartite random graphs with given degrees: local limit, revisiting the giant, distance'] Consider the multi-type branching process $\mathrm{BP}(\boldsymbol{p},\boldsymbol{D},\Tilde{\boldsymbol{D}})$ from Definition (def:BP of the paper), and denote its extinction probability by $\eta$. With the convention that the maximum over an empty set is $0$,  we have $\eta=1$ if and only if
    \begin{align*}
        \max_{\{s\in S:p_s>0\}}\max_{\{s'\in S:p^{(s,s')}_0<1\}} \max_{v \in V(s,s')}\max_{u \in \mathcal C_D(v)}\max_{c \in \mathcal L(u)}\mathscr{M}(c)\leq 1. \addtocounter{equation}{1}\tag{\theequation} 
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2605.02430, '\textbf{Scaling limit of the range of tree-valued branching random walks in random environ'] Let $\lambda\ino(1,\infty)$ and let $\overline{x}\eqo (T,x) \ino \obbT^\bullet\! $, whose depth $\bbn T\bbn_-$ is possibly infinite. Let $\overline{X}_n\eqo (T, X_n)$, $n\ino \bbN$, be a $\lambda$-biased RW with initial state $(T,x)$. We assume that 
\begin{equation}

 \forall x\ino T \backslash \{ \varnothing \}, \quad P_{(T,x)} \big(  \mathtt{H}_{\overleftarrow{x}} \leko \infty \big) \eqo 1 \; .  
\end{equation}
Let $\boo \ino T \backslash \{ \varnothing \}$. Recall from (\ref{ancestral}) that $L_\boo$ stands for 
the ancestral line of $\boo$ and let us denote by $ \boo(p)$ the vertex of $L_\boo$ at distance $p$ from $\boo$, which makes sense if and only if $0\leq p \leqo \bbn o\bbn -\bbn T\bbn_{ -}$. Namely 
\begin{equation}

 \boo(p)\! = \! \boo_{\lll_{\mathbf{(}  -\infty\, ,\,   \bbn \boo \bbn -p \mathbf{]} }}, \quad   0\leqo p \leqo \bbn \boo\bbn\!  -\! \bbn T\bbn_{ -} 
\end{equation}
We also introduce the successive times of visit of $\overline{X}$ in $L_\boo$ that are recursively defined for all $k\ino \bbN$ by $\mathbf{r}^\boo_{k}\! = \! \inf \big\{ n \! >\! \mathbf{r}^\boo_{k-1} : X_n \ino L_\boo \big\}$, 
with the convention that $\mathbf r^\boo_{-1}\eqo -1$ and $\inf \emptyset \eqo \infty$.  
Then, the following holds true. 
\begin{compactenum}

\smallskip

\item[$(i)$] For all $x\ino T$, $P_{(T, x)}$-a.s.~for all $k\ino \bbN$, $\mathbf{r}^\boo_k \! < \! \infty$ and  
there exists a birth-and-death Markov chain $(Z_k)_{k\in \bbN}$ that takes its values in $\bbN \cap [0, \bbn \boo\bbn\!  -\! \bbn T\bbn_{ -} ]$ and such that $\boo (Z_k)\! = \! X_{\mathbf{r}_k}$, $k\ino \bbN$. 
If $T$ has a finite depth, then it is reflected at $\bbn \boo\bbn\!  -\! \bbn T\bbn_{ -}$; otherwise, its transition probabilities are given for all $1\leqo p\leko \bbn \boo\bbn\!  -\! \bbn T\bbn_{ -}$ by 
\begin{equation}

\rho_{p, p+1} \! = \! \frac{\lambda }{\lambda  +  k_{\boo (p) } (T)  } , \; \,  \rho_{p, p-1}\! = \! \frac{1}{ \lambda + k_{\boo (p) } (T)}, \; \,  \rho_{p, p}\! =\! 
\frac{k_{\boo (p) } (T)\! -\! 1 }{ \lambda +  k_{\boo (p) } (T)} \; ,
\end{equation}
and $\rho_{0, 0}\!= \! 1\! -\! \rho_{0, 1} \eqo\frac{k_{\boo} (T)}{ \lambda  + k_{\boo  } (T)}$.  
Moreover, if $T$ has an infinite depth, then $Z$ is transient which implies that $\bbn \boo  \wedge \! X_n \bbn \! \rightarrow \! -\infty$ and that $(X_n)_{n\in \bbN}$ is transient. 

\smallskip

\item[$(ii)$] Let $x,y, z\ino T$ such that $z \preceq y$. Then 
\end{compactenum}
\begin{equation}
P_{(T \!\!, \,  x)} \big(\mathtt H_{y} \! <\! \mathtt H_{z}  \big)\! =  \! 
\frac{(\lambda^{\bbn x\wedge y\bbn }\! -\! \lambda^{\bbn z\bbn })_+}{\lambda^{\bbn  y\bbn }\!  -\! 
\lambda^{\bbn z \bbn }} \; .
\end{equation}
\begin{compactenum}
\item[$(iii)$]  We assume now that $T$ has an infinite depth. For all $x,y\ino T$, we first get 
\end{compactenum}
\begin{equation}

P_{(T \!\!, \,  x)} \big(\mathtt H_{y} \! <\! \infty  \big) \! = \! \lambda^{- (\bbn y \bbn -\bbn x\wedge y\bbn) }  \quad  \textrm{and} \quad P_{(T \!\!, \,  x)} \big(\mathtt H^+_{x} \! <\! \infty  \big) \! = \! \tfrac{1+k_x(T)}{\lambda + k_x (T)} \; .
\end{equation}
\begin{compactenum}
\item[] We denote 
the Green function by $G_T(x,y)\! = \! E_{(T,x)} \big[ \sum_{n\in \bbN}\un_{\{ X_n =  y\} } \big]$. Then 
\end{compactenum}

\begin{equation}

G_T(x, y) = G_T(x\wedge y, y)= \tfrac{\lambda + k_y (T)}{\lambda  -1} \, \lambda^{- (\bbn y \bbn -\bbn x\wedge y\bbn) }.
\end{equation}
\begin{compactenum}
\item[] If $x\preceq y$, we also get $E_{(T,x)} \big[ \sum_{0\leq n < \mathtt H_{\overleftarrow{x}}} \un_{\{ X_n =  y\} } \big]\eqo (\lambda \! + \! k_y (T)) \lambda^{- (\bbn y \bbn- \bbn x \bbn +1)}$. 
\end{compactenum} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:chapman_kolmogorov of arXiv:2608.11603, 'Continuous-time directed polymers to the Critical SHF via moments'] {}
	For $h, h' \in C_{c}(\mathbb{R}^2),m \geqslant 1$ and $s < t < u$, the following holds:
	\begin{equation*}
		\lim_{\ell \to \infty}\lim_{\varepsilon \to 0}\mathbf{E}\Big[\Big\langle h, \Big(\mathcal{Z}^{\theta,\varepsilon}_{s,t} \bullet_{\ell} \mathcal{Z}^{\theta,\varepsilon}_{t,u} - \mathcal{Z}^{\theta,\varepsilon}_{s,u}\Big) h' \Big\rangle^{2m} \Big] = 0 \, .
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm-generalized KB of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Suppose (Hypo-generalized KB of the paper) holds. Let $\nu_{T}^{x_0}$ be defined by (equation eq:approx_measures of the paper) for the fixed initial point $x_0 \in E$ given in Definition (Locally Feller definition of the paper). Assume the following conditions are satisfied:
		\begin{enumerate}[label={{\bf (\arabic*)}},leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item \textbf{$($Weak Convergence$)$} There exist a sequence $T_n\to\infty$ and a probability measure $\nu\in\mathbf{P}(E_{\widetilde{d}_E})$ such that $\nu_{T_n}^{x_0} \to \nu$ weakly in $\mathbf{P}(E_{\widetilde{d}_E})$ as $n\to\infty$. 		
			\item \textbf{$($Uniform Tail Control$)$} The time-averaged measures satisfy the following uniform tail estimate
			\begin{equation*}
				\lim_{R\to\infty} \sup_{n\ge 1} \nu_{T_n}^{x_0}\big(E \setminus B^{d_E}_R(x_0)\big) = 0,
			\end{equation*}
			where $B^{d_E}_R(x_0)$ is the closed ball defined in (equation eq: ball B-E-R of the paper).

			\item \textbf{$($Restricted Feller Property under Mismatched Metrics$)$} The semigroup $\{\mathscr{P}_t\}_{t\ge 0}$ satisfies the restricted Feller property under mismatched metrics (cf.\ Definition (Locally Feller definition of the paper)).
		\end{enumerate}
		Then $\nu\in\mathbf{P}(E)$ is an invariant probability measure for $\{\mathscr{P}_{t}\}_{t\ge0}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma a_binomial_identity of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] We have for all $n\in \tfrac12\mathbb{Z}_{\ge0}$:
	\begin{equation}

		\sum_{i=-n}^n\sum_{j=-n}^n
		\frac{(-1)^{2n+i+j}q^{(i-j)^2/2+(i+j)/2}}
		{(q;q)_{n-i} (q;q)_{n+i} (q;q)_{n-j} (q;q)_{n+j}}=\frac{1}{q^n(q;q)_{2n}},
	\end{equation}
	where the sums are over $i,j$ of the same half-parity as $n$.

