body:
[Lemma 57 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\bfx = (X,\bbx) \in \scrc^{\alpha}([0,T],V)$ be a rough path for some index $\alpha \in (\frac{1}{3},\frac{1}{2}]$, let $f_0 : [0,T] \times W \to W$ be continuous, and let $f : [0,T] \times W \to L(V,W)$ be of class $C_b^{2\alpha,2}$. Moreover, let $0 \leq q \leq r \leq s \leq T$ and $\xi \in W$ be arbitrary. Let $(Y(q,r,\xi),Y(q,r,\xi)') \in \scrd_X^{2\alpha}([q,r],W)$ be a solution to the equation $Y(q,r,\xi)' = f(Y(q,r,\xi))$ and
\begin{align}
Y(q,r,\xi)_t = \xi + \int_q^t f_0(u,Y(q,r,\xi)_u) \, du + \int_q^t f(u,Y(q,r,\xi)_u) \, d \mathbf{X}_u \quad t \in [q,r].
\end{align}
Furthermore, we set $\eta := Y(q,r,\xi)_r$ and let $(Y(r,s,\eta),Y(r,s,\eta)') \in \scrd_X^{2\alpha}([r,s],W)$ be a solution to the equation $Y(r,s,\eta)' = f(Y(r,s,\eta))$ and
\begin{align}
Y(r,s,\eta)_t = \eta + \int_r^t f_0(u,Y(r,s,\eta)_u) \, du + \int_r^t f(u,Y(r,s,\eta)_u) \, d \mathbf{X}_u, \quad t \in [r,s].
\end{align}
We define the concatenated path $Y(q,s,\xi) : [q,s] \to W$ as
\begin{align}
Y(q,s,\xi)_t :=
\begin{cases}
Y(q,r,\xi)_t, & t \in [q,r],
\\ Y(r,s,\eta)_t, & t \in [r,s],
\end{cases}
\end{align}
and we define the concatenated path $Y(q,s,\xi)' : [q,s] \to L(V,W)$ as
\begin{align}
Y(q,s,\xi)_t' :=
\begin{cases}
Y(q,r,\xi)_t', & t \in [q,r],
\\ Y(r,s,\eta)_t', & t \in [r,s].
\end{cases}
\end{align}
Then we have $(Y(q,s,\xi),Y(q,s,\xi)') \in \scrd_X^{2\alpha}([q,r],W)$, and this path is a solution to $Y(q,s,\xi)' = f(Y(q,s,\xi))$ and
\begin{align}
Y(q,s,\xi)_t &= \xi + \int_q^t f_0(u,Y(q,s,\xi)_u) \, du + \int_q^t f(u,Y(q,s,\xi)_u) \, d\mathbf{X}_u, \quad t \in [q,s].
\end{align}

