[Definition Locally Feller definition of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $x_0 \in E$ be a given reference point and define the strong closed ball
		\begin{equation}
			B^{d_E}_R(x_0) \triangleq \big\{x \in E : d_E(x, x_0) \le R\big\}.
		\end{equation}
		A Markov semigroup $\{\mathscr{P}_t\}_{t\ge 0}$ on $E$ satisfies the \textbf{restricted Feller property under mismatched metrics} (with respect to $\widetilde{d}_E$ and $d_E$, anchored at $x_0$) if the following two conditions hold:
		\begin{enumerate}[label={\rm(\roman*)}, leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item for every bounded Borel-measurable function $\phi \in \mathscr{M}_B(E)$ and $x \in E$, the map $t \mapsto [\mathscr{P}_t \phi](x)$ is Borel measurable on $[0, \infty)$;
			\item for any $t\ge 0$, $R>0$, and $\varphi \in C_B(E_{\widetilde{d}_E})$, the restriction 
			$\mathscr{P}_{t}\varphi\big|_{B^{d_E}_R(x_0)}$
			is continuous with respect to the metric $\widetilde{d}_E$.
		\end{enumerate}

