[Theorem thm:stability_downscaling of arXiv:2608.29448, '\method: Self-Scaled Adaptive Preconditioning for Physics-Informed Learning'] Let $\mathcal{H}_t, \mathcal{H}_{t+1} \in \mathbb{S}_{++}^d$ be Hessian operators at steps $t, t+1$ with spectral decompositions $\mathcal{H}_t = \mathbf{Q}_t \mathbf{\Lambda}_t \mathbf{Q}_t^\top$ and $\mathcal{H}_{t+1} = \mathbf{Q}_{t+1} \mathbf{\Lambda}_{t+1} \mathbf{Q}_{t+1}^\top$, where $\mathbf{Q} \in \mathrm{O}(d)$. Let $\mathbf{V}_t = \operatorname{diag}(\mathbf{v}_t)$ be the accumulated second moment in basis $\mathbf{Q}_t$. Let $\mathcal{U} = \mathbf{Q}_{t+1}^\top \mathbf{Q}_t$ be the unitary transition operator. Furthermore, we define the variance estimators in the new basis $\mathbf{Q}_{t+1}$ as
\begin{align}
    \mathbf{V}_{\text{proj}} &:= \operatorname{diag}(\mathcal{U} \mathbf{V}_t \mathcal{U}^\top) \quad \text{(Exact Reprojection)} \\
    \mathbf{V}_{\text{scale}} &:= \gamma \mathbf{V}_t, \ \gamma \in (0, 1) \quad \text{(Scalar Downscaling)}.
\end{align}
Let $\mathbf{V}^*_{t+1}$ be the optimal oracle variance estimator aligned with $\mathcal{H}_{t+1}$. Then, the following hold:

\begin{enumerate}
    \itemsep 0em
    \item \textbf{Instability of Reprojection:} The relative error of $\mathbf{V}_{\text{proj}}$ is lower-bounded by the condition number $\kappa(\mathbf{V}_t) = {\lambda_{\max}(\mathbf{V}_t)}/{\lambda_{\min}(\mathbf{V}_t)}$. Specifically, there exists a rotation $\mathcal{U}$ such that
    \begin{equation}
        \sup_{\mathcal{U} \in \mathrm{O}(d)} \frac{\| \mathbf{V}_{\text{proj}}^{-1/2} - (\mathbf{V}^*_{t+1})^{-1/2} \|_\infty}{\| (\mathbf{V}^*_{t+1})^{-1/2} \|_\infty} \geq \sqrt{\kappa(\mathbf{V}_t)} - 1.
    \end{equation}

    \item \textbf{Boundedness of Downscaling:} Assuming Lipschitz continuity of the Hessian spectrum with constant $L_{\mathcal{H}}$, the error of $\mathbf{V}_{\text{scale}}$ is bounded linearly by the subspace misalignment. If the gradient distribution satisfies sub-Gaussian tail bounds, then with high probability
    \begin{equation}
        \| \mathbf{V}_{\text{scale}} - \mathbf{V}^*_{t+1} \|_F \leq (1-\gamma)\| \mathbf{V}_t \|_F + L_{\mathcal{H}} \| \mathbf{I} - \mathcal{U} \|_F.
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2 (Inhomogeneous $p$-variation norm) of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $p\geq 1$. For any path $\mathbf{x}:[0,T]\rightarrow G^{\lfloor p\rfloor}(\mathbb{R}^k)$,
    the inhomogeneous $p$-variation norm of $\mathbf{x}$ is defined as
    \begin{equation*}
        \lVert \mathbf{x}\rVert_{\textup{inhom $p$-var};[0,T]} := \max_{1\leq m\leq \floor{p}}\sup_D \left(\sum_{i=0}^{n-1}\lVert\mathbf{x}^{(m)}_{t_i,t_{i+1}}\rVert^{p/m}_{(\mathbb{R}^k)^{\otimes m}}\right)^{m/p},
    \end{equation*}
    where $D=D_{[0,T]}$ is a partition of the time interval $[0,T]$ and $\mathbf{x}_{t_i,t_{i+1}}:=\mathbf{x}_{t_i}^{-1}\bullet \mathbf{x}_{t_{i+1}}$. Then, for any $\mathbf{x},\mathbf{y}:[0,T]\rightarrow G^{\lfloor p\rfloor}(\mathbb{R}^k)$, the inhomogeneous $p$-variation distance between $\mathbf{x}$ and $\mathbf{y}$ is defined as
    \begin{equation*}
        d_{\textup{inhom $p$-var};[0,T]}(\mathbf{x},\mathbf{y}) := \max_{1\leq m\leq \floor{p}}\sup_D\left(\sum_{i=0}^{n-1}\lVert\mathbf{x}^{(m)}_{t_i,t_{i+1}}-\mathbf{y}^{(m)}_{t_i,t_{i+1}}\rVert^{p/m}_{(\mathbb{R}^k)^{\otimes m}}\right)^{m/p}.
    \end{equation*}

[Lemma 28 (KL approximation error of sparse GP) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] \label[lemma]{lem:gp-KL}
Under \cref{ass:gp-true,ass:gp-eigenvalues}, if $J\ge J_t^\dag$, then
    \begin{align}
    \E[\KL(Q_t^{(J)}\|\Pi_t)]&\lesssim t^{d/(d+2\fs)}.
    \end{align}

