[Proposition prop:asympvarspeedup of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $P \in \mathcal{L}(\pi)$ and $Q \in \mathcal{I}(\pi) \cap \mathcal{L}$ be an isometric involution transition matrix. Fix $\alpha \in (0,1)$ and recall that $\overline{P}_{\alpha}(Q)$ is introduced in (equation eq:PbaralphaQ of the paper). We have 
	\begin{itemize}
		\item(worst-case asymptotic variance) \begin{align*}
			V(\overline{P}_\alpha(Q)) \leq V(P), 
		\end{align*}
		where the equality holds if and only if $\lambda_2(\overline{P}_\alpha(Q)) = \lambda_2(P)$ if and only if there exists a common eigenvector $g$ such that $\overline{P}_{\alpha}(Q)g = \lambda_2(\overline{P}_{\alpha}(Q))g$, $Pg = \lambda_2(P) g$ and $QPQg = \lambda_2(QPQ) g$.

		If $P$ is further assumed to be positive-semi-definite, then
		\begin{align*}
				\max\{\alpha,1-\alpha\} V(P) &\leq V(\overline{P}_\alpha(Q)) \leq V(P).
		\end{align*}

		\item(average-case asymptotic variance) \begin{align*}
			\overline{v}(\overline{P}_\alpha(Q)) \leq \overline{v}(P).
		\end{align*}
	\end{itemize}
	Consequently, this leads to
	\begin{align*}
		\min_{\alpha \in [0,1]} V(\overline{P}_\alpha(Q)) &= V(\overline{P}(Q)), \\
		\min_{\alpha \in [0,1]} \overline{v}(\overline{P}_\alpha(Q)) &= \overline{v}(\overline{P}(Q)).
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

