[Thm 6.5 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Assume that every $d$-bounded closed subset of $E$ is compact, and that $X$ satisfies one of the following sets of assumptions:
(i) the symmetry assumptions (H1a) and (H1b);
(ii) the duality assumptions (H2a) and (H2b);
(iii) the sector condition (H3), and the associated semi-Dirichlet form $({\mathcal{E}},{\mathcal{F}})$ of $X$ is regular. Let $\alpha>0$, $\beta>1$ and $T>0$ be given constants. 
\begin{itemize}
\item[(1)] If the volume growth condition (equation eq:41 of the paper) holds  with the given $\alpha$, and the transition density function of $X$ satisfies the following short-time sub-Gaussian upper bound estimate: 
\begin{equation}
p(t,y,z)\leq  \frac{C_1}{t^{\alpha/\beta}}\exp\left\{-C_2\left(\frac{d(y,z)}{t^{1/\beta}}\right)^{\beta/(\beta -1)}\right\}, \quad \forall  0<t\leq T, \, y,z\in E,
\end{equation}
for some $C_1>0$ and $C_2>0$, then for any $x\in E$ and $B\in \mathscr{B}^n(E)$,
\begin{equation}
        \liminf_{t\downarrow 0}\frac{-t^{1/(\beta-1)}\cdot \left(\log \mathbb{P}^x[\sigma_B\leq t]\right)}{C_2}\geq  \widetilde d(x,B)^{\beta/(\beta-1)},
\end{equation}
    where $\widetilde{d}(x,B)$ is defined as (equation eq:63 of the paper). 
\item[(2)] If the transition density function of $X$ satisfies the following short-time sub-Gaussian lower bound estimate: 
\begin{equation}
p(t,y,z)\geq  \frac{C'_1}{t^{\alpha/\beta}}\exp\left\{-C'_2\left(\frac{d(y,z)}{t^{1/\beta}}\right)^{\beta/(\beta -1)}\right\}, \quad \forall  0<t\leq T, \, y,z\in E,
\end{equation}
for some $C'_1>0$ and $C'_2>0$, then for any $x\in E$ and $B\in \mathscr{B}^n(E)$,
\[
        \limsup_{t\downarrow 0}\frac{-t^{1/(\beta-1)}\cdot \left(\log \mathbb{P}^x[\sigma_B\leq t]\right)}{C'_2}\leq  \widetilde d(x,B)^{\beta/(\beta-1)}.
\]
\end{itemize} 
