[Thm prop48 of arXiv:2412.08497, 'Time discretization of Quadratic Forward-Backward SDEs with singular drift'] Let Assumption (assum 4.8 of the paper) be in force. Then for $l=1,\cdots, L$ there exist measurable $u_l:(\mathbb{R}^d)^{l-1}\times [s_{l-1},s_l)\times \mathbb{R}^d \rightarrow \mathbb{R}$ and $\omega_l:(\mathbb{R}^d)^{l-1}\times [s_{l-1},s_l)\times \mathbb{R}^d \rightarrow \mathbb{R}^{1\times d}$ and Borel sets $D_l \subseteq (\mathbb{R}^{d(l-1)}, l=2,\cdots,L$, such that $D_l^{c}$ is of Lebesgue measure zero, and such that
				\begin{itemize}
					\item[(i)] $u_l(\bar{x}_{l-1};\cdot,\cdot): [s_{l-1},s_l)\times \mathbb{R}^d \rightarrow \mathbb{R}$ is continuously differentiable w.r.t. the space variable with $\nabla_x u_l(\bar{x}_{l-1};t,x)= \omega_l(\bar{x}_{l-1};t,x)$, where $\bar{x}_{l-1} = (x_1,\cdots,x_{l-1})$
					\item[(ii)] there is a constant $C>0$ independent of $l$ such that
					\begin{align*}
						\sup_{t\in[s_{l-1},s_l)}|u_l(\bar{x}_{l-1};t,x)| + \sup_{t\in[s_{l-1},s_l)}\sqrt{s_l-t}|\omega_l(\bar{x}_{l-1};t,x)| \leq C.
					\end{align*}
					\item[(ii)] for all $l=1,\cdots,L,$ $x_1,\cdots,x_{l-1},x \in \mathbb{R}^d$ and $s_{l-1}\leq s< s_l$ the triplet 
					\[  \left( X_t^{s,x}, u_l(\bar{x}_{l-1};t,X_t^{s,x}), \omega_l(\bar{x}_{l-1};t,X_t^{s,x}) \right)_{t\in [s,s_l)}.\]
					solves the FBSDE with generator $g$ and terminal condition 
					\[ u_l(\bar{x}_{l-1};s_l,X_{s_l}^{s,x}),   \]
					where 
					\begin{equation*}
						u_l(\bar{x}_{l-1};s_l,x):=
						\begin{cases}
							u_{l+1}(\bar{x}_{l-1},x;s_l,x)\mathcal{X}_{D_l}(\bar{x}_{l-1}): 2\leq l < L,\\
							\varphi(\bar{x}_{l-1},x)\mathcal{X}_{D_l}(\bar{x}_{l-1}): l = L,
						\end{cases}
					\end{equation*}
					and $u_1(r_1,x):= u_2(x;r_1,x)$.
				\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:HWILSq of arXiv:2507.08692, 'Some notes on higher order concentration of measure'] Let $\mu$ be a probability measure on ${\mathbb R}^n$ which satisfies an $\mathrm{LS}_q$-inequality as well as $\int x_i d\mu = 0$ for any $i=1, \ldots,n$, and define $f\colon {\mathbb R}^n \to {\mathbb R}$ by $f(x) := x^TAx$, where $A=(a_{ij})_{ij}$ is a symmetric $n \times n$ matrix. Then,
    \[
    \mu(|f - {\mathbb E} f| \ge t) \le 2\exp\Big\{-c_p\min \Big(\Big(\frac{t}{\sigma^2\lvert A \rvert_{\mathrm{HS}(q)}}\Big)^p, \Big(\frac{t}{\sigma^2\lvert A \rvert_{\mathrm{op}(q)}}\Big)^{p/2}\Big)\Big\}
    \]
    for any $t \ge 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem.Walpha of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] For any $\alpha \in (0,1)$, the following two properties hold for $\mathcal{W}_{\alpha}$.
			\begin{enumerate}
				\item Given ${\scaleobj{1}{\square}} \in \mathcal{W}_{\alpha}$, it admits a maximal cluster $\mathscr{C}_{*}({\scaleobj{1}{\square}})$ and any cluster $\mathscr{C} \subseteq {\scaleobj{1}{\square}}$ satisfying $\diam(\mathscr{C}) > \sqrt{d}\size({\scaleobj{1}{\square}})^\alpha$ is part of $\mathscr{C}_{*}({\scaleobj{1}{\square}})$.
				\item For every $\mathfrak{p} \in (\mathfrak{p}_c, 1]$, there exist two finite positive constants $C(d,\mathfrak{p})$ and $c(d,\mathfrak{p})$ such that 
				\begin{align}
					\forall {\scaleobj{1}{\square}} \in \mathcal{T}, \qquad \mathbb{P}_\mathfrak{p}[{\scaleobj{1}{\square}} \in \mathcal{W}_{\alpha}] \geqslant 1 - C \vert {\scaleobj{1}{\square}} \vert \exp(-c\size({\scaleobj{1}{\square}})^\alpha).
				\end{align}
			\end{enumerate}

[Lemma 5 of arXiv:2604.24677, 'Local Limit of Random Regular Bipartite Planar Maps'] The generating functions satisfy the following relations:
\begin{equation*}
	\rW(z)= (1+ \rB(z))^{d-1} \text{,}\quad \rB(z) = z(d-1)\rW(z) \text{,}\quad {M}^{d,\brf}(z) = zd\,\rW(z),
\end{equation*} 
and $\rB(z)$ is characterized by the Lagrangian equation:
\begin{equation}
	\rB(z) = z(d-1)(1+ \rB(z))^{d-1}.
\end{equation} 
Moreover, these generating functions share the common radius of convergence
\begin{equation*}
	\rho_d=(d-2)^{(d-2)}/(d-1)^d
\end{equation*}

[Defn def_weak_sol of arXiv:2608.30548, 'Finite speed of propagation and waiting time phenomena for stochastic porous media equatio'] A 
    weak solution to (equation Eq_viscous_reg of the paper) is a continuous $L^{\alpha+1}(\mathbb{T}^d)$-valued adapted non-negative process $u$ satisfying $u, u^{(\alpha+m)/2}\in L^2([0,T]; H^1(\mathbb{T}^d))$ such that for any $\varphi\in C^\infty(\mathbb{T}^d)$, a.s. for every $t\in [0,T]$:
    \begin{align*}
        \int_{\mathbb{T}^d} u_t \vp \,\mathrm{d} x \,=\,& \int_{\mathbb{T}^d} u_0 \vp \,\mathrm{d} x \,-\, m \int_0^t \int_{\mathbb{T}^d} u^{m-1} \nabla u \cdot \nabla \vp \,\mathrm{d} x\mathrm{d} s
        \,-\,\kappa \int_0^t \int_{\mathbb{T}^d} 
        \nabla u \cdot  \nabla \vp  \,\mathrm{d} x\, \mathrm{d} s
        \\& -\,\frac{1}{2}\int_0^t \int_{\mathbb{T}^d}
        \Psi_1(\sigma_l'(u))^2 \nabla u \cdot \nabla \vp \,+\,
        \sigma_l\sigma_l'(u)\Psi_2 \cdot\nabla\vp
        \, \mathrm{d} x\,\mathrm{d} s\\&+\, \sum_{k=1}^\infty\int_0^t \int_{\mathbb{T}^d}
        \sigma_l(u)\psi_k \nabla \vp \, \mathrm{d} x \cdot  \,
        \mathrm{d} \beta_k(s).
    \end{align*}

[Lemma 33 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] For every $n\geq 1$, the following polynomial identity holds:
\begin{equation}

Q_{n}(x_{1}+x_{2}, u_{1}+u_{2}) = 
\sum_{j=0}^{n} \dfrac{n!}{j! (n-j)!} Q_{n-j}(x_{1},u_{1})Q_{j}(x_{2},u_{2}).
\end{equation}

