[Lemma disjoint_wiring_new of arXiv:2607.07616, '\vspace{-5cm}The End of the Double Random Current'] Suppose $(\eta^1,\eta^2, \delta) \in \mathtt{DoubleEvenFlow}_{n,N}$, and $\omega = \eta^1 \cup \eta^2 \cup \delta \in 2\mathtt{EndsCross}_{r,n,N}$ . Denote the two infinite components of $\omega_{\Lambda_n^c}$ by $\mathfrak{e}$ and $\mathfrak{f}$. Then, for any $r<n<N,$
 \begin{align*}
     \ell^{\partial(\eta^1_{\Lambda_n^c})}_{\Lambda_n} \otimes \ell^{\partial(\eta^2_{\Lambda_n^c})}_{\Lambda_n}  \otimes \mathbb{P}_{\Lambda_n}[\mathfrak{e} \overset{\mathbf{n}_{\Lambda_n}\hspace{-1pt}\cup \hspace{1pt}\omega_{\Lambda_n^c}}{ \leftrightarrow} \mathfrak{f}] < 1.
 \end{align*}

[Theorem thm:gaussian.multicausal.optimizer of arXiv:2604.22453, 'Adapted Wasserstein Barycenters of Gaussian Processes'] For centered filtered Gaussian processes $\mathbb{X}^1 = \mathbb{G}^{L^1},\dots,\mathbb{X}^K = \mathbb{G}^{L^K}\in\mathcal{FG}(T,d)$, the following statements hold:
\begin{enumerate}
\item The barycenter value is given by
\[
\inf_{\mathbb{Y}\in\mathrm{FP}_2}\sum_{k=1}^K \lambda_k\mathcal{AW}_2^2(\mathbb{X}^k,\mathbb{Y})=\sum_{t=1}^T\min_{\mathbf P_t\in\mathscr{P}_+(K,d)}\Phi_t(\mathbf P_t),
\]
and each local minimum is attained. 
\item For any local minimizers $\mathbf P^\star_1,\dots,\mathbf P^\star_T\in\mathscr{P}_+(K,d)$ and factors $\mathbf Q_t\in\mathbb{R}^{Kd\times Kd}$ satisfying $\mathbf P^\star_t=\mathbf Q_t\mathbf Q_t^\intercal$, the ensemble filtered Gaussian process $\mathbb{G}_K^{0,
\accentset{\overline{\hphantom{\mathbf L}}}{\mathbf L}
}$, with block columns
\[
\widebar{\mathbf{L}}_{\cdot, t}=\mathbf{L}_{\cdot, t}\Lambda\mathbf Q_t,
\]
for $t\in[T]$, is an adapted barycenter of $\mathbb{X}^1,\dots,\mathbb{X}^K$. In particular, a minimizer of (equation eq:AWbar of the paper) can be selected as an ensemble filtered Gaussian process. Its path covariance is $\sum_{t=1}^T
\accentset{\overline{\hphantom{A}}}{A}
_t$, where the innovation covariance contributions are
\begin{equation}

\accentset{\overline{\hphantom{A}}}{A}
_t:=
\accentset{\overline{\hphantom{\mathbf L}}}{\mathbf L}
_{\cdot,t}
\accentset{\overline{\hphantom{\mathbf L}}}{\mathbf L}
_{\cdot,t}^\intercal=\mathbf L_{\cdot,t}\Lambda\mathbf P_t^\star\Lambda\mathbf L_{\cdot,t}^\intercal.
\end{equation}
\end{enumerate}

[Lemma lem_lem of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let the polynomials $P_n^{(1)}(r)$ and $P_n^{(2)}(r)$ be as in ((poly_1 of the paper)) and ((poly_2 of the paper)), respectively. Then $P_n^{(1)}(1)<P_n^{(2)}(1)$ for every even integer $n\ge8$, i.e., 
\begin{eqnarray}

\Big(1+\frac{1}{n}\Big)^{\frac{n}{2}}<\frac{1}{\sqrt{e}}\sum_{i=0}^{\frac{n}{2}-1}\frac{1}{i!},\,\,\,\,\,n\geq 8.
\end{eqnarray}

