[Thm 5 (Conditional Local Law for $H(w)$) of arXiv:2606.24887, '2606.24887'] Let $ 0 < \delta \le 1/2$ be fixed and $X$ be a sparse matrix as in  \cref{defiX}. 
		Let $\# \in \{\mathrm{l}, \mathrm{b}, \mathrm{e}\}$.    
		We define $M$ as in \cref{eq:def_M_X_plus_f} for some (deterministic) $f$ such that $0 \le \abs{f} \le N^{\delta/6}$, and define $G$ and $g$ as in \cref{Greenfunction} and \cref{eq:def_g} respectively. 
		If $d$ satisfies $d_\# \ll d \leq N^{\delta/4}$ then, with very high probability, for all $w \in \mathrm{S}_\#$ and all $ N^{-1 + \delta} \le \eta \le 1$ we have
		\begin{equation}
			\chi_\# \max_{x \in [N]} \Big( \absb{G_{xx}(w,\ii \eta) - \ii v_{\beta_x}(w,\eta)} +
			\absb{G_{\ubarr{x}\ubarr{x}}(w,\ii \eta) - \ii v_{\ubarr{\beta}_x}(w,\eta)}
			\Big) =o(1) ,
		\end{equation}
		\begin{equation}
			\chi_\# \max_{x \in [N]} \Big(
			\absb{G_{x\ubarr{x}}(w,\ii\eta) + w u_{\beta_x}(w,\eta)} 
			+ \absb{G_{\ubarr{x}x}(w,\ii\eta) + \overline{w} u_{{\beta}_x}(w,\eta)} \Big)  =o(1),
		\end{equation}
		\begin{equation}
			\chi_\#  \max_{\stackrel{x,y \in [2N]}{x \neq y \neq \ubarr{x}}}\absb{G_{xy}(w, \ii \eta)}  =o(1),
		\end{equation}
		\begin{equation}
			\chi_\#  \absb{g(w,\ii \eta) - \ii v(w,\eta)}  =o(1).
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2608.10415, 'Continuous random variables'] Let $A$ be a $C^*$-algebra, with a trace $tr$, and consider an element $a\in A$ which is normal, in the sense that $aa^*=a^*a$.
\begin{enumerate}
\item $\mu_a$ is a complex probability measure, satisfying $supp(\mu_a)\subset\sigma(a)$.

\item In the self-adjoint case, $a=a^*$, this measure $\mu_a$ is real.

\item Assuming that $tr$ is faithful, we have $supp(\mu_a)=\sigma(a)$.
\end{enumerate}

