[Proposition 7 of arXiv:2605.17328, 'Transportation cost inequalities for mean reflection SPDEs with white noise'] {\rm (\cite[Theorem 3.3]{DuanJTP2025} and \cite[Theorem 4.4]{DuanJTP2025})}
\begin{itemize}
\item[(i)]{\rm
Under Assumptions (I) and (II), Eq.\,\eqref{SPDE} with the linear mean reflection admits a unique deterministic flat solution $u$.  Moreover, $\mathbb E\left[\left(|u|_{\infty}^T\right)^p\right]<\infty$ for any $p\geq1$. }
\item[(ii)]{\rm Under Assumptions (I), (II) and (H), Eq.\,\eqref{SPDE} with the general mean reflection admits a unique deterministic flat solution $u$.  Moreover, $\mathbb E\left[\left(|u|_{\infty}^T\right)^p\right]<\infty$ for any $p\geq1$. }
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

