[Definition 1 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {Bounded Differences Property}

    A function $f : \mathcal X^n \to \R$ fulfills the bounded differences property if for $c_1,...,c_n \geq 0$ and all $i \in [n]$: 
    \begin{align*}
        \sup_{y, x_1,...,x_n \in \mathcal X} |f(x_1,...,x_n) - f(x_1,...x_{i-1} y, x_{i+1},...,x_n)| \leq c_i.
    \end{align*}

[Proposition 15 (Jabin and Wang {\cite[Theorem 4) of arXiv:2608.25772, 'Propagation of Chaos and Gaussian Fluctuations for Mean-field Coupled Maps'] {JW18}}]
    Let $E$ be a Polish space and $\rho\in\mathcal{P}(E)$ be a probability measure on $E$. Suppose that $\phi:E\times E\to\R$ is a measurable function satisfying the following two cancellation rules:
    \begin{equation}
        \int_E\phi(x,y)\dd\rho(x)=0,\quad\forall y\in E;\qquad
        \int_E\phi(x,y)\dd\rho(y)=0,\quad\forall x\in E.
    \end{equation}
    Then there exists a constant $C_1>0$, such that when $\|\phi\|_{L^{\infty}}\leq C_1$, one has
    \begin{equation}
        \sup_{N\geq 2}\int_{E^N}   \rho^{\otimes N}(X_N)\exp{\left(\frac{1}{N}\sum_{i,j=1}^{N}\phi(x_i,x_j)\right)}\dd X_N\leq C<+\infty,
    \end{equation}
    where $X_N=(x_1,x_2,\dots,x_N)$ for $N\geq 2$ and $C$ is a generic constant independent of $N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 23 (Specific vorticity) of arXiv:2609.01589, 'Uniform stability of expanding simple waves for Euler--Poisson--Boltzmann: a singular comp'] Every classical solution of \eqref{eq:EP-mass}--\eqref{eq:EP-poisson}
satisfies
\begin{equation}
  (\pa_t+u\cdot\nabla)\zeta=0. 
\end{equation}
Consequently,
\begin{equation}
  \sup_{t_0\le t\le T}\norm{\zeta(t)}_{H^{s-1}}
  \le C_{t_0,T}\norm{\zeta(t_0)}_{H^{s-1}}. 
\end{equation}
The constant is independent of $\eps$.

[Lemma 22 (Regular spectral design) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] {lem:gp-design}
Under \cref{ass:gp-true}, there are absolute constants $c>0$ and $C>0$ such that
    \begin{equation}
    \Pr\del{ \cE_t}
    \ge 1- C N_t^\dag\exp\{-ct/N_t^\dag\}.
    \end{equation}
Since $N_t^\dag\asymp t^{d/(2\fs)}$, the probability of the complement tends to 0 faster than $t^{-b}$ for any $b>0$.

[Theorem main-th of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Given the above definition of a bivariate \textit{Lorenz
curve} and its associated operator, if for $n=0,1,..$we consider the
sequence $L_{n+1}^{F}(x_{1},x_{2}),$ defined by
\begin{equation}
L_{n+1}^{F}(x_{1},x_{2})=\frac{\int_{0}^{L_{1}^{n,-1}(x_{1})}
\int_{0}^{L_{2}^{n,-1}(x_{2})}u_{1}u_{2}dL_{n}^{F}(u_{1},u_{2})}{
\int_{0}^{1}\int_{0}^{1}u_{1}u_{2}dL_{n}^{F}(u_{1},u_{2})},  
\end{equation}

where
\begin{equation}
L_{1}^{n}(x)=L_{n}^{F}(x,1),\qquad L_{2}^{n}(x)=L_{n}^{F}(1,x),  
\end{equation}

or equivalently by
\begin{eqnarray}
L_{0}^{F}(x_{1},x_{2}) &=&L_{F}^{0}(x_{1},x_{2})=\mathcal{L(}F(x_{1},x_{2}))
\notag \\
L_{1}^{F}(x_{1},x_{2})
&=&L_{F}^{1}(x_{1},x_{2})=L^{L_{0}^{F}}(x_{1},x_{2})=L^{F}(x_{1},x_{2})=L_{F}(x_{1},x_{2})=
\mathcal{L(}L_{0}(x_{1},x_{2}))  \notag \\
&&...  \notag \\
L_{n+1}^{F}(x_{1},x_{2}) &=&L_{F}^{n+1}(x_{1},x_{2})=L^{L_{n}^{F}}(x)=
\mathcal{L}(L_{n}(x_{1},x_{2})),  
\end{eqnarray}

where in $L$ the subscript $n$ denotes the iteration step, while the
superscript indicates starting distribution $F$, then the functions $
L_{n}^{F}(x_{1},x_{2})$ are themselves distribution functions on $[0,1]^{2}$
. When extended to $R^{2}$, this extension is understood in the usual
distribution function sense, namely 
\begin{equation*}
L_{n}^{F}(x_{1},x_{2})=L_{n}^{F}(\pi (x_{1}),\pi (x_{2})),\qquad \pi
(x)=\min \{1,\max \{0,x\}\}.
\end{equation*}

Assume additionally the existence of a strictly positive density for $
X=(X_{1},X_{2})$ on $(0,1)^{2}$ which is either totally positive of order $2$
$(TP_{2})$ or strictly reverse regular of order $2$ $(SRR_{2})$ in the sense
of [[36]]. Then $L_{n}^{F}(x_{1},x_{2})$ converges uniformly to the
distribution function $G(x_{1},x_{2})$, where 
\begin{equation}
G(x_{1},x_{2})=\pi (x_{1})^{\frac{1+\sqrt{5}}{2}}\pi (x_{2})^{\frac{1+\sqrt{5
}}{2}},\qquad \pi (x)=\min \{1,\max \{0,x\}\}.  
\end{equation}

