[Theorem 10 (Asymptotics for $\alpha \to \alpha_0,$ $\alpha_0 \in [0,2\pi\textnormal{) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] }\backslash \mathcal M$, or $\alpha \to 0, \pi$ with $\alpha \in [0,2\pi\textnormal{]}\backslash \mathcal M$] 
Assume $x^+_{max} > x^-_{max}$ (cases A and D of Figure~\ref{anglesalphab}). Let $z_0 \in \R^2$ and let $0 \leq \alpha_0 < \alpha_b$. Then:
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop\alpha\to\alpha_0, \alpha \geq 0}{\sim} C'_{br}(\alpha_0) f_0(z_0)\frac{e^{-r(\cos(\alpha)x(\alpha_b) + \sin(\alpha)y(\alpha_b))}}{r^{3/2}
}
\end{equation}
where $C'_{br}(\alpha_0) = \left(\frac{\sin(\alpha_b)}{\sin(\alpha_b - \alpha_0)}\right)^{3/2}C_0$ (see \eqref{eq:C_0}) and where $f_0(z_0)$ is given by \eqref{f(z_0)branch}. 

Assume now $x^+_{max} < x^-_{max}$ (cases B and C of Figure~\ref{anglesalphab}) and let $\alpha_b < \alpha_0 \leq 2\pi$. Then,
\begin{equation}
 g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop\alpha\to\alpha_0, \alpha \leq 2\pi}{\sim}  C'_{br}(\alpha_0)f_0(z_0)\frac{e^{-r(\cos(\alpha)x(\alpha_b) + \sin(\alpha)z(\alpha_b))}}{r^{3/2}}
\end{equation}
where $C'_{br}(\alpha_0)$ has the same expression and where $f_0(z_0)$ is given by \eqref{f(z_0)col}.

The symmetric results hold for $\tilde\alpha_b< \alpha_0 \leq\pi$ in the cases A and B and for $ \pi\leq \alpha_0 < \tilde\alpha_b$ in the cases C and D. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 78 (Identities involving the double-null frame and the null-geometry scalars) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $\ReciprocalLunitAppliedtoTimeFunction, \ReciprocaluLunitAppliedtoTimeFunction, \ingoingmu, \MagnitueofinnerproductofnewLandnewuL$ be the double-null acoustic geometry scalar functions defined in Sect.\,\ref{SSS:NULLVECTORFIELDS}.  Then the following identities hold:
	\begin{subequations}
		\begin{align}
			\muX \ubar & = \frac{\upmu}{\ingoingmu} - \frac{\upmu}{\ReciprocalLunitAppliedtoTimeFunction},  \\
			0  & = \frac{\ReciprocaluLunitAppliedtoTimeFunction}{\ReciprocalLunitAppliedtoTimeFunction} + \frac{\upmu}{\ingoingmu} - \frac{\upmu}{\ReciprocalLunitAppliedtoTimeFunction}  - \MagnitueofinnerproductofnewLandnewuL |\angD \ubar|^2_{\gtorus},  \\
			\ReciprocaluLunitAppliedtoTimeFunction & = \frac{1}{2}\upmu + \frac{1}{2}\ReciprocalLunitAppliedtoTimeFunction^2 \upmu |\angD \ubar|^2_{\gtorus}.
		\end{align}
	\end{subequations}

	Moreover, the vectorfields $\uLunit, \newuL$ can be decomposed in terms of $L,\muX$, and $\geop{x^A}$ as follows, where $\angD^A = \gtorus^{-1}(\mathrm{d} x^A,\mathrm{d} x^B) \geop{x^B}$:
	\begin{align}
		\uLunit = \Lunit + \frac{1}{\ReciprocaluLunitAppliedtoTimeFunction} \muX - \ingoingmu \angD^A \ubar \geop{x^A} & & \newuL = \ReciprocaluLunitAppliedtoTimeFunction \Lunit + \muX- \MagnitueofinnerproductofnewLandnewuL \angD^A \ubar \geop{x^A}.   
	\end{align}	Next, define:  
	\begin{equation}
		\ToriTangentVectorfieldAssociatedToDoubleNullFolliations \eqdef \angD^A \ubar \gtorusdoublenullCOV^B_A \nullgeop{x^B}, 
	\end{equation}
	where  $\gtorusdoublenullCOV^B_A$ is as in \eqref{E:CHOVCOEFFICIENTSSMOOTHANGULARDERIVATIVESINTERMSOFDOUBLENULLONESANDL}. Then the following identities hold:
	\begin{align}
		\newuL & = -\frac{\upmu}{\ingoingmu} \newL  + \upmu \Transport - \MagnitueofinnerproductofnewLandnewuL \ToriTangentVectorfieldAssociatedToDoubleNullFolliations = -\frac{\MagnitueofinnerproductofnewLandnewuL}{\ingoingmu} \Lunit  + \upmu \Transport - \MagnitueofinnerproductofnewLandnewuL \ToriTangentVectorfieldAssociatedToDoubleNullFolliations,   \\
		& = \left( -\frac{\MagnitueofinnerproductofnewLandnewuL}{\ingoingmu} + \upmu\right)\Lunit + \muX - \MagnitueofinnerproductofnewLandnewuL \ToriTangentVectorfieldAssociatedToDoubleNullFolliations. 
	\end{align}
In addition, we have the following for $\alpha = 0,1,2,3$:
	\begin{subequations}
		\begin{align} 
			\p_\alpha & = -\frac{1}{\MagnitueofinnerproductofnewLandnewuL} \newuL_\alpha \newL - \frac{1}{\MagnitueofinnerproductofnewLandnewuL} \newL_\alpha \newuL  + \nullangpartial_\alpha, \\
			& =  -\frac{1}{\MagnitueofinnerproductofLunitanduLunit} \uLunit_\alpha \Lunit - \frac{1}{\MagnitueofinnerproductofLunitanduLunit} \Lunit_\alpha \uLunit  + \nullangpartial_\alpha, 
		\end{align}
	\end{subequations}
where $\nullangpartial_\alpha \eqdef \nulltorusproject \cdot \partial_\alpha$.\footnote{Note that $\nullangpartial_{A} = \nullgeop{x^A}$ for $A = 2,3$.}

[Prop correlation of arXiv:2606.08325, 'Digit Mixing under Polynomial Maps'] Let \(M>0\). If the exponent $\Gamma$ in (equation eq:sharp of the paper) is sufficiently large in terms of degree $d$ and $M$, then for every  base $b\ge2$ and every nonzero integer \(h\in\mathbb Z\setminus\{0\}\),
			\begin{equation}
				\left| \mathbb E e\!\left(h(b^n-b^m)P(X)\right)
				\right| \ll_{P,b,h,M} (\log n)^{-M}
			\end{equation}
			uniformly for $0\le m<n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

