[Theorem 14 of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] Given $\eps>0$, let $(Q^2_t,P^2_t)$  solve~\eqref{eq:Q2P2} with initial datum $(Q^2_0,P^2_0)$, and let  
    $(q_t,p_t)$ solve~\eqref{eq:limit-gen} with initial datum $(q_0,p_0)$. Recall the definition of the potential $V$ from~\eqref{eq:Valpha} and the parameter $\alpha\geq0$.  
    We have the $L^2$-estimate
    \begin{align}
        \E \biggl[ \sup\limits_{t \in [r,T]} \biggl| 
        \begin{pmatrix}
           q_t - Q^{2}_t \\ p_t - P^{2}_t
        \end{pmatrix} \biggr|^2 \biggr] &\leq 
        \begin{dcases}
        C e^{\tilde C T}  \biggl( \left| \begin{pmatrix}
            q_0 - Q^2_0 \\ p_0 - P^2_0
        \end{pmatrix} \right|^2 + T\int_0^T  \E\bigl[|\hat q - Q^{1}_s|^2 \bigr]ds \biggr) 
        \ \ &\text{if $\alpha=0$},\\
        \tilde C \biggl(e^{-\eta r} \biggl|\begin{pmatrix}
           q_0 - Q^{2}_0 \\ p_0 - P^{2}_0
        \end{pmatrix} \biggr|^2+ \eta^{-1} \int_0^T  \E\left[|  \hat q - Q^{1}_s |^2\right] ds \biggr) &\text{if $\alpha>0$}. 
        \end{dcases}
    \end{align}
    Additionally  for $\alpha >0$  we have $L^1$ estimates 
    \begin{align} 
   \E\biggl[ \sup\limits_{t \in [r,T]} \biggl| \begin{pmatrix}
        q_t - Q^2_t \\ p_t - P^2_t    \end{pmatrix} \biggr| \biggr] &\leq C  \biggl(e^{- \frac{\eta}{2} r} \biggl| \begin{pmatrix}
            q_0 - Q^2_0 \\ p_0 - P^2_0
        \end{pmatrix} \biggr| +  \int_0^T e^{-\frac{\eta}{2}(T-s)} \E\left[|\hat q - Q^{1}_s|\right] ds \biggr) \,,
    \end{align}
Here $\eta\in (0,\gamma]$ defined in Lemma~\ref{lem:matrixexp-b} and $C, \tilde C>0$ is independent of $t,\eps$.

