[Lemma 25 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] Let $ M>0$, $\epsilon_0>0$ and $v \in \mathcal{A}_M$. Assume that the conditions {\rm [A1-A5]} hold for any $0 \leq \epsilon < \epsilon_0$, then for any two $\mathcal{F}_{t_0}$ measurable initial datas $\xi_1,\xi_2\in H$, the difference between solutions $X^{\epsilon,v}_{t;t_0,\xi_1}$ and $X^{\epsilon,v}_{t;t_0,\xi_2}$ to Eq. \eqref{eq: controlled equation truncated} satisfies the uniform estimate
\begin{align}
   & \max \Big\{ \E \big[\sup_{s\in [t_0,t]} e^{- \gamma (t-s)} \| X^{\epsilon,v}_{s;t_0,\xi_1}-X^{\epsilon,v}_{s;t_0,\xi_2} \|_{H}^2 \big]^{\frac{1}{2}}, \E \big[ (\gamma_0 -\tilde{\gamma}_0) \int_{t_0}^{t} e^{- \gamma (t-s)}   \| X^{\epsilon,v}_{s;t_0,\xi_1}-X^{\epsilon,v}_{s;t_0,\xi_2} \|_{V}^2 \, \d s \big]^{\frac{1}{2}} \Big\}  \nonumber \\
    & \leq 2 (\E \| \xi_1-\xi_2 \|_{H}^2 )^{\frac{1}{2}}  e^{\frac{  C_{\rho_1}}{\gamma_0} \big( \| \xi_2 \|_{H}^{2} + \| \xi_2 \|_{H}^{2+\beta} + \big(2+\frac{\beta}{2} \big) \frac{ 2 C_{A,\rho} + 4C_B M+ \beta C_{B} \tilde{\epsilon}  }{\lambda_1 \gamma_0} \big)+ \frac{C_B M}{\lambda_1(\gamma_0-\tilde{\gamma}_0)}} e^{-\frac{\gamma }{2}(t-t_0)}, 
\end{align}
for any $\epsilon<\frac{\tilde{\epsilon}}{4} \vee \epsilon_0$ and $\gamma \in [0,\frac{\lambda_1 (\gamma_0-\tilde{\gamma}_0) }{2}]$.

