[Corollary cor: rand_series_ample of arXiv:2412.07690, 'A law of large numbers concerning the distribution of critical points of random Fourier se'] Suppose that $E\to M$ is a smooth real vector bundle over the compact smooth manifold $M$. Fix a smooth  Riemann metric $g$ on $M$,  a smooth metric $h$ on $E$ and a smooth connection  on $E$ compatible with $h$. Let $k\in {{\mathbb N}}$ and suppose that $(\phi_n)_{n\in {{\mathbb N}}}$ is a sequence  of $C^k$ sections of $E$ that span  a dense subset of $C^k(E)$. Suppose that
 \begin{equation}
 \Vert \phi_n\Vert_{C^k(E)}= O(n^\alpha)\;\;\mbox{as $n\to\infty$},
 \end{equation}
 for some $\alpha>0$.  Fix a sequence of positive numbers $(\lambda_n)_{n\in{{\mathbb N}}}$ satisfying ((poly_eval of the paper)). Let $(X_n)_{n\in {{\mathbb N}}}$ be a sequence of $\mathrm{i.i.d.}$ standard normal random variables and suppose that $\mathfrak{a}\in \EuScript{S}({\mathbb R})$ is an even Schwartz function such that $\mathfrak{a}(0)=1$. Then the following hold.

 \begin{enumerate}

\item For any $R >0$ the random series  
\begin{equation}
\sum_{n\in {{\mathbb N}}} \mathfrak{a}\big(\,  \lambda_n/R\,\big) X_n \phi_n
\end{equation}
converges  $\mathrm{a.s.}$ in $C^k(E)$. Denote by $\Phi^R$ the resulting $C^k$  Gaussian section  of $E$.

\item There exists $R_0>$ such that $\forall R>R_0$ the  Gaussian section $\Phi^R$ is $J_k$-ample, i.e., for any ${\boldsymbol{x}}\in M$ the Gaussian vector
\[
J_k\Phi^R({\boldsymbol{x}})=\bigoplus_{j=0}^k \nabla^j\Phi^R({\boldsymbol{x}})
\]
is nondegenerate.

\end{enumerate}

[Prop link-with-compositions-new-2 of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Under the assumptions of Proposition (prop:link-with-compositions-new-1 of the paper), we have for $n\geq 0$ the identity $\PFtrees{\mathbf{w}} {nd+1}=\PFComp{{\mathbf{w}},{\mathbf{b}}}{nd}$, and for $T\in\trees[d]_{nd+1}$ if we write $c(T)=\underline{n}_1 \cdots  \underline{n}_i$ and $\varphi(T)=(T^{[1]},\dots,T^{[i]})$, then
	\begin{align}
	\SimpGen{{\mathbf{w}}}{nd+1}(T)=\PComp{{\mathbf{w}},{\mathbf{b}}}{n-1}\bigl(c(T)\bigr)\cdot\left(\SimpGen{{\mathbf{w}}}{n_1}\bigl(T^{[1]}\bigr)\cdots \SimpGen{{\mathbf{w}}}{n_i}\bigl(T^{[i]}\bigr)\right).
	\end{align}

[Proposition Compact injections local versions. of arXiv:2602.08591, 'The Yang--Mills measure on compact surfaces as a \\ universal scaling limit of lattice gau'] Let $\alpha\in (\frac{1}{3},\frac{1}{2})$. 
Then the linear map 
$$T\in\mathcal{W}^{\alpha,\alpha-1,p}_{loc}(\mathbf{Cyl}\setminus \Psi(\mathrm{Crit}(f)_1)) \mapsto T\chi\in  H^{\alpha-\frac{3}{2}-\varepsilon}(\mathbf{Cyl})$$ is \emph{compact} for all $\varepsilon>0$.
Let $\square_1\subsetneq \square_2\subset \mathbf{Cyl}$ a strict inclusion of rectangles in our cylinder $\mathbf{Cyl}$ and for all $\chi\in C^\infty_c(\square_2)$ such that $\chi=1$ on $\square_1$. Then for any $T\in \mathcal{C}^{\alpha,\alpha-1}$, we have the upper bound of the form   
\begin{equation}
\Vert T\chi \Vert_{H^{\alpha-\frac{3}{2}-\varepsilon}(\mathbf{Cyl})} \leqslant C \Vert T\Vert_{\mathcal{W}^{\alpha,\alpha-1,p}(\square_2)}   
\end{equation}
where the norm on the l.h.s. is defined in terms of the \emph{Fourier coefficients}
of $T\chi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 12 of arXiv:2512.05687, '$L^p$-Boltzmann-Gibbs principle \\ via Littlewood-Paley-Stein inequality'] (cf.\ Theorem 5.1 of \cite{BFS})
Let $p\ge 4$ 
and let $f$ be a local $L^{p'}(\mu_{u_0})$ function on $\mathcal{X}_N = \R^N$
for some $p'>p$, depending only on $\eta_{\La_{\ell_0}} = 
(\eta(x))_{x\in \La_{\ell_0}}$, such that 
$\tilde f(u_0) = E^{\mu_{u_0}}[f]=0$ and $\tilde f'(u_0)=0$.  Then,
there exists a constant $C= C(u_0,\ell_0)$ (which is uniform in $u_0: |u_0|\le K$
for any $K>0$)
such that for $\ell\geq\ell_0$ we have
\begin{align}  
\Big\| E^{\mu_{u_0}}\big[f| \eta^{(\ell)}\big] 
 - \frac12\Big\{(\eta^{(\ell)}-u_0)^2- \frac{{\rm var} (u_0) }{2\ell +1}\Big\} 
\tilde f''(u_0)
\Big\|_{L^p(\mu_{u_0})} 
\leq \ \frac{C\|f\|_{L^{p'}(\mu_{u_0})}}{\ell^{3/2}},
\end{align}
where ${\rm var} (u_0)$ is defined below \eqref{eq:3.2-A}.
On the other hand, when only $\tilde f(u_0)=0$ is known, we have
\begin{align}  
&\Big\| E^{\mu_{u_0}}[f| \eta^{(\ell)}]  - (\eta^{(\ell)} - u_0)\tilde f'(u_0)  
\Big\|_{L^p(\mu_{u_0})} \ \leq \ \frac{C\|f\|_{L^{p'}(\mu_{u_0})}}{\ell}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

