\gamma W^{(\gamma)}(r)
-
\bigl(Z^{(\gamma)}(r)-1\bigr)
\dfrac{W^{(\gamma)\prime}(r)}{W^{(\gamma)}(r)}
\right]^2
}{
\gamma W^{(\gamma)}(r)
}
\,dr
\nonumber\\
&\qquad+
\frac{
\left[
\gamma W^{(\gamma)}(d)
-
