[Proposition prpexpmart of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] Let $\{\hat{M}(t)\}_{t\ge0}$ be a point process such that $\hat{M}(0)=0$. Then, $\{\hat{M}(t)\}_{t\ge0}$ is IGCP iff the process
		\begin{equation*}
		Y(t)=\exp\Big(u\hat{M}(t)-\sum_{j_0=1}^{k_0}\mu_{j_0}t\Big(\exp\Big(-j_0\sum_{j=1}^{k}\lambda_{j}(1-e^{uj})\Big)-1\Big)\Big), \ u\in\mathbb{R},\  t\ge0
		\end{equation*}  
is a $\{\mathcal{F}_t\}_{t\ge0}$-martingale, where $\mathcal{F}_t=\sigma(\hat{M}(s),\, s\le t)$.

[Proposition proposition-uniqueness-law-curve of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] There exists a unique law $\nu_{W,\lambda}^{(D,a,b)}$ such that the following holds. ${\mathbb{P}}$-almost surely, the Radon-Nikodym derivative of $\nu_{W,\lambda}^{(D,a,b)}$ with respect to $\nu_{SLE_{3}}^{(D,a,b)}$ is given by
        \begin{equation}
            \frac{{\operatorname{d}} \nu_{W,\lambda}^{(D,a,b)}}{{\operatorname{d}} \nu_{\operatorname{SLE}_{3}}^{(D,a,b)}}(\gamma) := \frac{S_{L}^{W,\lambda}S_{R}^{W,\lambda}}{\mathcal{Z}_{D}^{\pm,W,\lambda}}
        \end{equation}
        with for $j=L,R$,
        \begin{equation*}
            S_{j}^{W,\lambda}:= 1 + \sum_{k \geq 1} \frac{C_{\sigma}^k}{k!} \int_{D_{j}^{k}} f_{D_{j}}^{(\xi_j,k)}(z_1,\dots,z_k) \prod_{p=1}^{k}\lambda(z_p)W(dz_p)
        \end{equation*}
        and for any sequence $(\delta_n)_n$ such that $(\nu_{\delta_n}^{\pm,\lambda,h})_{n}$ converges weakly as $n \to \infty$ in the topology (topo_4 of the paper), 
        \begin{equation*}
            (W_{\delta}^{h} ,\tilde{\mathcal{Z}}_{\delta_{n}}^{\pm,h}, \nu_{\delta_n}^{\pm,\lambda,h})_{n} \to (W, \mathcal{Z}_{D}^{\pm,W,\lambda}, \nu_{W,\lambda}^{(D,a,b)})
        \end{equation*}
        weakly as $n \to \infty$. Above, the process $W_{\delta}^{h}$ is defined via, for $\phi \in L^2(\mathbb{R}^2)$, $W_{\delta}^{h}(\phi)=\delta\sum_{x \in D_{\delta}}h_{x}\phi(x)$, and under ${\mathbb{P}}$, $W$ is a two-dimensional white noise while $\mathcal{Z}_{D}^{\pm,W,\lambda}$ is the limiting partition function of Theorem (theorem-cvg-RFIM-partition-function of the paper). The domain $D_{L}$, respectively $D_{R}$, is the connected component of $D \setminus \gamma$ on the left, respectively right, of $\gamma$, $\xi_{L}=+$, $\xi_{R}=-$ and the constant $C_{\sigma}$ and the functions $(f_{D_{j}}^{(\xi_j,k)})_{k,j}$ are as in Theorem (theorem_spin_correlations of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 10 of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] _distributions}
Assume $g\in\mathcal{C}^{(2)}(\mathcal{S})$ and \eqref{contraction_criterion_g} holds. Then the conclusion drawn in each of Theorem~\ref{thm:main_2_special}, the second part of Theorem~\ref{thm:a.s._convergence_C_{n}}, and Theorem~\ref{thm:main_6} remains true for 
\begin{enumerate*}
\item $K_{n}$ that is distributed as discrete uniform over $\{1,2,\ldots,n\}$;
\item $K_{n}=\min\{n,G_{n}\}$, where $G_{n}$ follows Geometric$(p_{n})$ with probability of success $p_{n}=c n^{-\alpha}$ for $\alpha>1/2$;
\item $K_{n}=1+T_{n-1}$, where $T_{n-1}$ follows Binomial$(n-1,p_{n})$ with $p_{n}=c n^{-\alpha}$ for $0<\alpha<1/2$;
\item $K_{n}=\min\{n,1+P_{n}\}$, where $P_{n}$ follows Poisson$(\lambda_{n})$ with $\lambda_{n}=c n^{\alpha}$ for $\alpha>1/2$.
\end{enumerate*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:hankel_irm of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] Let $\Lambda_L = \mathbb{T}_L^d$ be the $d$-dimensional discrete torus. An inhomogeneous random matrix $X_N$ is said to be of  \textbf{Hankel-type profile} if its variance profile $\Sigma_N = (\sigma_{xy})$ satisfies
\begin{equation}
\sigma_{xy}^2 = \frac{1}{M} \sum_{k \in \mathbb{Z}^d} f\left(\frac{x+y-x_0+kL}{W}\right), \quad  M:=\sum_{k\in \mathbb{Z}^d} f\big(\frac{k}{W}\big),
\end{equation}
where $f$ is a non-negative integrable and  symmetric function, and  $x_0 \in \mathbb{T}_L^d$ is a fixed center of reflection.

[Lemma 13 ($a+b=1$, stationary distribution) of arXiv:2606.00781, '2606.00781'] If $a+b=1$, then the stationary distribution $\mu$ of the process $X$ has a density $f_\mu$ with respect to the Lebesgue measure on $(0,1)$, which is given by
   \begin{equation} 
      f_\mu(x)\ =\ \frac{\textcolor{black}{b}}{\pi i x^2}
      \int_C \frac{1}{(1+w)^{1-\textcolor{black}{b}}(1+\frac{w}{x})^{1-\textcolor{black}{b}}\big(1+(1+\frac{w}{x})^{\textcolor{black}{b}}\big)^2}
      \,{\rm d}w,\qquad x\in(0,1),
   \end{equation}
   where $C$ is a counterclockwise contour that starts and ends at the point $w=-1$ and encloses the origin. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 4 (Bures-Wasserstein Distance, \cite{petric2019got}) of arXiv:2608.27500, 'Optimal Transport for Network Comparison: \\ A Review with Machine Learning Applications'] The Bures-Wasserstein distance between the graph signal distributions $\mu=\mathcal{N}(0,L^\dagger)$ and $\nu=\mathcal{N}(0,(L')^\dagger)$ is
\begin{align}
    BW(\mu,\nu)^2=\text{tr}\bigg[L^\dagger+(L')^\dagger-2\bigg((L^\dagger)^\frac{1}{2}(L')^\dagger(L^\dagger)^\frac{1}{2}\bigg)^\frac{1}{2}\bigg].
\end{align}

