[Definition 74 of arXiv:2601.16377, '2601.16377'] Let $\mathcal A_\eps\subseteq \W_\N$ denote the set of configurations such that
\begin{itemize}
\item there are at most $C \N^{\frac{1}{2}}(\log\N)^2$ particles $\ell_i$ in $[\N(\mathfrak{a}+\eps),\N\mathfrak{b}]\cup \big(-\infty,-\frac{\N D}{2}\big]\cup\big[\frac{\N D}{2},+\infty\big)$;
\item the event studied in Lemma~\ref{Lemma_tail_bound_general} with $t =\N^{-\frac{1}{2}}\log\N$ does not hold, \textit{i.e.}
\[
\forall f \in \mathscr{H}_{\textnormal{Lip},\frac{1}{2}} \quad \exists h \in [H] \qquad \bigg|\int_{\amsmathbb{R}} f(x)\dd(\mu_{\N,h} - \mu_h)(x)\bigg| \leq \frac{\log\N}{\N^{\frac{1}{2}}}\cdot |\!|f|\!|_{\frac{1}{2}} + \frac{C}{\N}\cdot \big(|\!|f|\!|_{\textnormal{Lip}} + |\!|f|\!|_{\infty}\big).
\]
\end{itemize}
For $0<\eps_1<\eps_2$, let $\mathcal{E}\big[\begin{smallmatrix} K_1 & K_2 \\ \eps_1 & \eps_2 \end{smallmatrix}\big] \subseteq \W_\N$ be the set of configurations with exactly $K_1$ particles in $[\mathfrak{a}+\eps_1, \mathfrak{b}]$ and $K_2 \leq K_1$ particles in $[\mathfrak{a}+\eps_2,\mathfrak{b}]$.

[Theorem T:one-point-bds of arXiv:2604.10020, 'The directed landscape in half-space'] For any $\alpha_0>0$, there exists a constant $c>0$, such that whenever the boundary parameter satisfies $\alpha\ge \alpha_0$ we have the following bounds. 
\begin{enumerate}
    \item (Upper tail) For all $n \in \mathbb{N}, \epsilon \in (0, n^{-1/3}]$ we have
$$
\mathbb{P}(X(1, 1; n, n) \ge \mu_\alpha(n) + \epsilon n) \le 2\exp\left(-c \epsilon^{3/2} n \left(1 \wedge \frac{\epsilon^{1/2}}{(1/2 - \alpha)\vee 0}\right) \right).
$$
    \item (Shallow lower tail when $\alpha < 1/2$) For all $n \in \mathbb{N}, \epsilon \in (0, 1]$ such that $\alpha \le 1/2 - n^{-1/3}$ and $\epsilon n \le \mu_\alpha(n) - 4n$, we have
\begin{align}

	\mathbb{P}\Big(X(1, 1; n, n) \le \mu_\alpha(n) - \epsilon n\Big) \le 2\exp\left(- \frac{c\epsilon^2 n}{1/2 - \alpha} \right).
\end{align}
\item (Full lower tail for $\alpha \ge 1/2$, deep lower tail for $\alpha < 1/2$) For all $n \in \mathbb{N}, \epsilon \in (0, 1]$ we have
\begin{align}

	\mathbb{P}\Big(X(1, 1; n, n) \le 4n - \epsilon n\Big) \le 2\exp\left(- c \epsilon^3 n^2\right).
\end{align}	
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 20 of arXiv:2608.10992, '2608.10992'] For every \(t_0<t_*\), there exists \(\lambda_{t_0}>0\) such that
\[
        \sup_{0\leq t\leq t_0}\mathbb{E}[e^{\lambda_{t_0}X_t}]<\infty.
\]
If \(t_0>0\), one may take
\begin{equation}

        \lambda_{t_0}
        =
        \log\left(1+\frac{e^{-2t_0m(t_0)}}{2t_0}\right).
\end{equation}

[Lemma 33 (Negligibility of remaining integrals) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Suppose $x_{max}^+ < x_{max}^-$ (i.e., $\alpha_b \in (0, \pi)$). Let $0 \leq \alpha_0 < \alpha_b$. Then, for $\delta > 0$ small enough, there exist constants $D > 0$, $\e' > 0$, $\eta > 0$, and $r_0 > 0$ such that for all $r \geq r_0$ and all $\alpha \geq 0$ satisfying $|\alpha - \alpha_0| < \eta$, the following estimates hold:
\begin{equation}
\Big|\int_{R^\pm_{\delta}}\phi^{z_0}(x)\frac{\gamma(x,Y^+(x),Z^+(x))}{\partial_y\gamma_+(x,Y^+(x))}e^{-r(\cos(\alpha)x+\sin(\alpha)Y^+(x))}
 dx\Big| \leq De^{-r(\cos(\alpha)x(\alpha_b) + \sin(\alpha)y(\alpha_b) + \e')},
\end{equation}
and:
\begin{itemize}
    \item If $b_0 > 0,$ then \begin{equation}I_2(r\cos(\alpha),r\sin(\alpha)) \leq De^{-r(\cos(\alpha)x(\alpha_b) + \sin(\alpha)y(\alpha_b) + \e')}
    \end{equation}
    \item If $b_0 \leq 0,$ then
    \begin{equation}
\Big|\int_{R^\pm_{\delta}}\frac{e^{(a_0-a)x+b_0Z^+(x) - bY^+(x)}}{\partial_y\gamma_+(x,Y^+(x))}e^{-r(\cos(\alpha)x+\sin(\alpha)Y^+(x))}
 dx\Big| \leq De^{-r(\cos(\alpha)x(\alpha_b) + \sin(\alpha)y(\alpha_b) + \e')}
\end{equation}
\end{itemize}

