    \begin{align*}
     \vb = \frac{(\ub \cdot \vb)}{\|\ub\|} \frac{\ub}{\|\ub\|} + \left(\vb - \frac{(\ub \cdot \vb )}{\|\ub\|} \frac{\ub}{\|\ub\|} \right)    ,
