[Lemma lem:D12 of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] If $m\ge40$ and there are two large spokes, then
\begin{equation}
  D_1=|C(\zeta)-1|\le m-\frac34,
\end{equation}
\begin{equation}
  D_2=|C(\zeta^2)-1|\le m+\frac12.
\end{equation}

[Lemma 37 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $(X,d,\mu)$ be a Polish probability space. Suppose it admits a continuous isoperimetric function $I:(0,1)\to(0,\infty)$. Define
\begin{equation}

\Phi(v):=
\begin{cases}
    \int_{\frac{1}{2}}^v\frac{dr}{I(r)},
    & v\in(\frac{1}{2},1),
    \\
    0, & v=\frac{1}{2},
    \\
    -\int_{v}^\frac{1}{2}\frac{dr}{I(r)}, & v \in (0,\frac{1}{2}),
\end{cases}
\end{equation}
and set $a:=\inf \Phi((0,1))$ and $b:=\sup \Phi((0,1)),$ where $-\infty \leq a \leq 0 <b\leq \infty$. Define the distribution function $\Psi:\mathbb R\to[0,1]$ by
\begin{equation}

\Psi(t):=
\begin{cases}
    0, & t\leq a,\\
    \Phi^{-1}(t), & t\in(a,b),\\
    1, & t\geq b.
\end{cases}
\end{equation}
Then $\Psi$ is continuous and non-decreasing with $\Psi(0)=\frac{1}{2}$. For each $s\geq0$, define
$R_s^I:[0,1]\to[0,1]$ by
\begin{equation}

    R_s^I(0):=0,
    \qquad
    R_s^I(1):=1,
\quad \text{and }
    R_s^I(v):=\Psi\bigl(\Phi(v)+s\bigr),
    \qquad v\in(0,1).
\end{equation}
Then $R_s^I$ is an enlargement function for $(X,d,\mu)$ in the
sense of Definition~\ref{d:enlargement}. Conversely, if $(X,d,\mu)$ has $R_s^I$ of the above form as an enlargement function, then it satisfies isoperimetry with isoperimetric function $I$.

Moreover, if $A\subset X$ is a Borel set with $0<\mu(A)<1$ and, for some
$s>0$ such that $R_s^I(\mu(A))<1$, equality holds in
\eqref{eq:enlarge_ineq}, then
\begin{equation}

    \mu(A_t)=R_t^I(\mu(A)),
    \qquad 0\leq t\leq s.
\end{equation}
In particular, $\mu(A_0)=\mu(A)$ and $A$ is an extremal set for the
isoperimetric inequality \eqref{eq:extremal_iso}.

[Lemma lem:0.1 of arXiv:2608.30848, '\huge \bf Limit Laws of the Iterated Logarithm Under Sub-linear Expectations'] The following are equivalent:
 \begin{description}
          \item[\rm (i)] Condition (CC) holds for some $\mathscr{P}$;
          \item[\rm (ii)] Condition (CC) holds for $\text{core}(\widehat{\mathbb E})$;
          \item[\rm (iii)] $\widehat{\mathbb E}$ is regular on $\mathscr{H}_b$, i.e., whenever $\mathscr{H}_b\ni \varphi_n\searrow 0$, we have $\widehat{\mathbb E} [\varphi_n]\searrow 0$.
        \end{description}
        Moreover, condition (CC) holds for $\mathscr{P}$ if and only if $\mathscr{P}$ satisfies ((eqexpressbyP of the paper)), and for any $Y_i\in \mathscr{H}$, $i=1,2,\ldots$, $\mathscr{P}\bm Y^{-1}$ is a weakly compact family of probability measures on $\mathbb R^{\mathbb N}$, where $\bm Y=(Y_1,Y_2,\ldots)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 11 of arXiv:2607.06242, 'Exponential mixing and Freidlin--Wentzell large deviation principle for Markov cocycles'] For any 
      \[0<\lambda<-\frac{m(G)\log(hr)}{\ell+1},\]
      there is a measurable $C_{\l}(\s)<\infty$ $m$-a.s. such that we have 
      \begin{itemize}
        \item Pullback contraction:
        \begin{align*}
          \W_{D_{\s}}\left(\mu Q_{\Theta^{-n}\s}^{(n)}, \nu Q_{\Theta^{-n}\s}^{(n)}\right)\leq C_{\l}(\s) e^{-\l n} \W_{D_{\Theta^{-n}\s}}(\mu,\nu), \quad n\geq 0;
        \end{align*}
        \item Forward contraction: 
        \begin{align*}
          \W_{D_{\Theta^{n}\s}}\left(\mu Q_{\s}^{(n)}, \nu Q_{\s}^{(n)}\right)\leq C_{\l}(\s) e^{-\l n} \W_{D_{\s}}(\mu,\nu), \quad n\geq 0,
        \end{align*}
      \end{itemize}
      for all $ \mu,\nu\in\mathcal{P}_V(E)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2604.17973, 'Schauder estimates and classical solutions of the Dirichlet problem for stochastic parabol'] Let $p,q\in(2,\infty)$, and let $Q_T^+=\R^n_+\times(0,T]$. Assume that \eqref{eq:flat-compatibility} holds. Then the following assertions are valid.
\begin{enumerate}[label=\rm(\roman*)]
\item If $f=D_i f^i$ with $f^i\in L_\omega^qL_t^qL_x^p(Q_T^+)$ and $g\in L_\omega^qL_t^qL_x^p(Q_T^+;\elltwo)$, then the problem \eqref{eq:model-half-space}--\eqref{eq:model-half-space-bc} admits a unique solution
\[u\in L_\omega^qL_t^qW_x^{1,p}(Q_T^+)
\]
and
\begin{equation}
\|u\|_{L_\omega^qL_t^qW_x^{1,p}(Q_T^+)}
\le C\Bigl(\sum_{i=1}^n\|f^i\|_{L_\omega^qL_t^qL_x^p(Q_T^+)}
+\|g\|_{L_\omega^qL_t^qL_x^p(Q_T^+;\elltwo)}\Bigr).
\end{equation}

\item If $f\in L_\omega^qL_t^qL_x^p(Q_T^+)$ and $g\in L_\omega^qL_t^qW_x^{1,p}(Q_T^+;\elltwo)$ with $g=0$ on $\Sigma_T$, then the problem \eqref{eq:model-half-space}--\eqref{eq:model-half-space-bc} admits a unique solution
\[u\in L_\omega^qL_t^qW_x^{2,p}(Q_T^+)
\]
and
\begin{equation}
\|u\|_{L_\omega^qL_t^qW_x^{2,p}(Q_T^+)}
\le C\Bigl(\|f\|_{L_\omega^qL_t^qL_x^p(Q_T^+)}
+\|g\|_{L_\omega^qL_t^qW_x^{1,p}(Q_T^+;\elltwo)}\Bigr).
\end{equation}
\end{enumerate}
Here $C$ depends only on $n$, $p$, $q$, $T$, $\kappa$, and $K$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:OY-trace-defect of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $F_a \vcentcolon= \det_H(I + K_a)$ and
$\mathcal{B} \vcentcolon= \mathcal{A}_a - \mathcal{A}_{S_3a}$.
Then
\begin{equation}
\frac{
\left(D_\tau - \frac{1}{2}D_r^2\right)
F_{S_3a} \cdot F_a
}{
F_{S_3a} F_a
}
=
\frac{1}{2}\operatorname{tr}_E(\mathcal{B}^2)
- \frac{1}{2}(\operatorname{tr}_E\mathcal{B})^2
+ \operatorname{tr}_E(\mathcal{B} M_p).
\end{equation}

