[Proposition 9 of arXiv:2604.11921, 'Replica symmetry up to the de Almeida--Thouless line in the Sherrington--Kirkpatrick model'] \label[proposition]{prop:m-diffusion}
On $[q,1]$, 
\begin{equation}
dm_t=\beta(1-m_t^2)\,dW_t.
\end{equation}
Further, if
\begin{equation}
f(t)=\E[m_t^2]-t,
\end{equation}
then
\begin{equation}
f'(t)=\beta^2\E\big[(1-m_t^2)^2\big]-1,
\qquad
f(q)=0,
\qquad
f'(q)=\alpha-1,
\end{equation}
where $f'(q)$ is understood as a one-sided derivative.

[Corollary 9 of arXiv:2506.17470, 'The coalescent of a sample from a linear-fractional branching process'] Let $k\in \mathbb{N}$. The law of $H_{k,0},H_{k,1}, \dots, H_{k,k-1}$ can be obtained as follows:
\begin{enumerate}
    \item Select $Y$ with the probability distribution $\mu_k$ defined in \eqref{eq:muk}.
\item Conditioned on $Y=y$, select $H_{y,0}, \dots, H_{y, k-1}$, where $H_{y,0}=T$ and $H_{y,1}, \dots, H_{y, k-1}$ are i.i.d. random variables with distribution 
$$\mathbb{P}(H_{y,i}\leq j\mid H_{y,i}\leq T)= \frac{(m^j-1)}{(m^T-1)}\ \frac{r-p+y(1-p)(m^T-1)}{r-p+y(1-p)(m^j-1)}, \qquad 1\leq j\leq T,\  1\leq i < k,$$
where $m=r/p$.
\end{enumerate}
Furthermore, let $\tau$ be an ultrametric, oriented tree with node depths $x_0=T$ and $x_1, \dots, x_{k-1}  \in  \{1,\ldots, T\}$, the likelihood function of the parameters $(p,r)$ given the outcome $\{\mathbf{T}_k=\tau\}$ is
   \begin{equation*}
    \mathcal{L}(p, r,\mid  \tau,k) = \mathbb{P}(\mathbf{T}_k=\tau)=
       \int_0^1 \mu_k(\mathrm{d}y) \prod_{i=1}^{k-1} \frac{\mathbb{P}(H_{y,i} = x_i)}{\mathbb{P}(H_{y,i}\le T)}.
   \end{equation*}

