[Definition 1 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] Let $(\mathcal{P}(\X), \tau)$ be a topological space, where $\tau$ is a topology on $\mathcal{P}(\X)$.
    \begin{enumerate}[label=(\roman*)]
        \item $\Phi$ is called \textit{$\tau$-asymptotically stable} if there exists a unique invariant measure $\mu \in \mathcal{P}(\X)$ such that:
        \begin{equation*}
            \lim_{t \to \infty} P_t(x, \cdot) = \mu \quad \text{in } (\mathcal{P}(\X), \tau), \quad \forall\, x \in \X.
        \end{equation*}
        \item $\Phi$ is called \textit{$\tau$-mean ergodic} if there exists a unique invariant measure $\mu \in \mathcal{P}(\X)$ such that:
        \begin{equation*}
            \lim_{t \to \infty} \frac{1}{t} \int_0^t P_s(x, \cdot) \d s = \mu \quad \text{in } (\mathcal{P}(\X), \tau), \quad \forall\, x \in \X.
        \end{equation*}
    \end{enumerate}

[Lemma 12 of arXiv:2608.05842, 'Asymptotic Expansion of the Kallianpur–Striebel Formula under Perturbations of Linear Mode'] Let $X.$ and $\xi.0$ be the paths of $\{X_s\}_{0\leq s\leq t}$ and $\{\xi_{s,t}\}_{0\leq s\leq t}$, and $\mu_X$ and $\mu_{\xi}$ be their distributions on $P$. 
  \begin{align*}     
    \frac{d\mu_{\xi}}{d\mu_X}(X.)=\exp\biggl( &-\frac{1}{2}\int_0^t X_s^\top S(s) X_sds\\
    &-\frac{1}{2}\int_0^t b(s)^\top \phi(s;t)b(s)ds-\frac{1}{2}X_0^\top \phi(0;t) X_0\biggr).
  \end{align*}

