    \sum_{\substack{x_{2} \in \hcV^{(m i)}_{
u}\x_{2} 
eq x_{1}}} \left<   1_{\Sdu(x_{1})},   1_{\Sdu(x_{2})} ight> \leq 2
u  rac{\log N}{\log\log N}
  \end{equation*}
  with $
u$-high probability. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:CT-TASEP-multipoint of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The dressed edge weights satisfy the mixed diamond
equation
\begin{equation}
\begin{aligned}
\mathcal{M}_{t,\mathbf{a}+\mathbf{1},
\mathbf{n}+\mathbf{1}}^{-1}
\partial_t \mathcal{M}_{t,\mathbf{a}+\mathbf{1},
\mathbf{n}+\mathbf{1}}
&- \mathcal{M}_{t,\mathbf{a}+\mathbf{1},
\mathbf{n}}^{-1}
\partial_t \mathcal{M}_{t,\mathbf{a}+\mathbf{1},
\mathbf{n}} \\
\qquad + \mathcal{M}_{t,\mathbf{a}+\mathbf{2},
\mathbf{n}}^{-1}
\mathcal{M}_{t,\mathbf{a}+\mathbf{1},
\mathbf{n}+\mathbf{1}}
&- \mathcal{M}_{t,\mathbf{a}+\mathbf{1},
\mathbf{n}}^{-1}
\mathcal{M}_{t,\mathbf{a},\mathbf{n}+\mathbf{1}} = 0
\end{aligned}
\end{equation}
for every $t > 0$, $\mathbf{a} \in \mathbb{Z}^m$, and
$1 \leq n_1 < \cdots < n_m$.

[Cor fmar of arXiv:2604.24061, 'A characterization of ruin-inducing probability measures in a renewal risk model'] Let \(u{\,\in\,}\mathbb R_+\) and \(r{\,\in\,}[0,r_{X_1})\), where \(r_{X_1}{\,>\,}0\). The following assertions hold:
\begin{enumerate}
\item for every $Q^{(r)}{\,\in\,}\hyperlink{ms}{\mathcal M_S}$ with  	
\[
Q_{X_1}^{(r)}(F):=\frac{\int_F e^{r\cdot x}\, P_{X_1}(dx)}{M_{X_1}(r)}\,\, \text{ and } \,\, Q_{W_1}^{(r)}(E):=\frac{\int_E e^{-y(r)\cdot w }\, P_{W_1}(dw)}{M_{W_1}\big(-y(r)\big)}
\]
for any $F,E{\,\in\,}\mathfrak B(0,\infty)$, there exists an essentially unique pair $(\gamma_r,\delta_r){\,\in\,}\hyperlink{fp}{\mathcal F_P}{\,\times\,}\hyperlink{gp}{\mathcal G_P}$ with  
\[
\gamma_r(x)=r\cdot x-\ln M_{X_1}(r)\,\,\text{ for all } x\in(0,\infty)
\] 
and  
\[
\delta_r(w)=-y(r)\cdot w-\ln M_{W_1}\big(-y(r)\big)\,\text{ for each } w\in(0,\infty),
\]
such that the conditions 
\begin{gather*}
\frac{dQ^{(r)}}{dP}{\upharpoonright}{\mathcal H}_t=M_{X_1}(r)\cdot e^{-r\cdot(R^u_t-u) -y(r)\cdot V_{t} -\theta(r)\cdot t}=:L_t^{(r)}\quad P{\upharpoonright}{\mathcal H}_t\text{-a.s.} 

\end{gather*}
and 
\begin{gather}
\frac{dQ^{(r)}}{dP}{\upharpoonright}\mathcal F_t=M_{X_1}(r)\cdot   e^{-r\cdot(R^u_t-u) +y(r)\cdot J_t -\theta(r)\cdot t} \cdot \frac{\int^{\infty}_{J_t} e^{-y(r)\cdot w} \, P_{W_1}(dw)}{{\int_{J_t}^\infty \,P_{W_1}(dw)}}
\quad P{\upharpoonright}\mathcal F_t\text{-a.s.} 

\end{gather}
hold for all $t{\,\in\,}\mathbb R_+$;
\item 
conversely, for any pair $(\gamma_r,\delta_r)$ of real-valued $\mathfrak B(0,\infty)$-measurable functions as in (i), there exists a unique probability measure $Q^{(r)}{\,\in\,}\hyperlink{ms}{\mathcal M_S}$ determined by (equation mq of the paper), namely  
\[
Q^{(r)}(A)=\mathbb E_P\big[\1_A\cdot L_t^{(r)}\big]\,\,\text{ for all } t\in\mathbb R_+\text{ and } A\in{\mathcal H}_t, 
\]
and satisfying condition (equation sch2 of the paper).
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] Let $p_1,p_2,q_1,q_2\in[1,\infty]$ and $\mu,\mu'\in\R$ such that $p_1\le p_2,q_1\le q_2$ and $\mu_1\ge\mu_2$. For all $\alpha\in \R$, one has the Besov embeddings
\begin{equation*}
\mathcal{B}^\alpha_{p_1,q_1,\mu_1}(\R^d) \subset  \mathcal{B}^{\alpha-d\left(\frac{1}{p_1}-\frac{1}{p_2} \right)}_{p_2,q_2,\mu_2}(\R^d).
\end{equation*}
as well as the Sobolev embeddings
\begin{equation*}
\forall\alpha\ge \frac{d}{2}-\frac{d}{p},\quad \CH^\alpha_{\mu}(\R^d) \subset  L^p_{\mu}(\R^d)
\end{equation*}
for $p\in[2,\infty]$. Finally, the embedding
\begin{equation*}
\CH_{\mu_1}^{\alpha_1}(\R^d)\hookrightarrow\CH_{\mu_2}^{\alpha_2}(\R^d)
\end{equation*}
is compact for $\alpha_1>\alpha_2$ and $\mu_1>\mu_2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

