[Definition d.AV of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Let $\kappa$ be a probability measure on $(0 , \infty)$ and $\beta \in (0 , \infty)$ be an inverse temperature. We define the annealed Villain interaction associated with the measure $\kappa$ and with inverse temperature $\beta$ to be the function $F_{\kappa , \beta} : [0 , 2 \pi) \to \ensuremath{\mathbb{R}}$ given by the formula
    \begin{equation*}
        F_{\kappa, \beta}(\theta) = \int_0^\infty v_{\beta J}( \theta) \kappa(d J).
    \end{equation*}
    Given a finite set $\Lambda \subseteq \ensuremath{\mathbb{Z}^d}$, we define the spin system with annealed Villain interaction associated with the measure $\kappa$ and at inverse temperature $\beta$ in the set $\Lambda$ to be the probability distribution on the set of configurations $[0 , 2\pi)^{\Lambda}$
    \begin{equation} 
        \mu^{\mathrm{Ann-Vil}}_{L, \kappa, \beta}(d \theta) := \frac{1}{Z^{\mathrm{Ann-Vil}}_{L, \kappa, \beta}} \prod_{\substack{x , y \in \Lambda \\ x \sim y}} F_{\kappa, \beta}(\theta_x - \theta_y) \prod_{x \in \Lambda} d\theta_x.
    \end{equation}
    We denote by $\mu^{\mathrm{Ann-Vil}}_{\kappa, \beta}$ the limit as $\Lambda \uparrow \ensuremath{\mathbb{Z}^d}$ of the finite-volume measures $\mu^{\mathrm{Ann-Vil}}_{\Lambda, \kappa, \beta}$ and by $\left\langle \cdot \right\rangle_{\kappa, \beta}^{\mathrm{Ann-Vil}}$ the corresponding expectation.

[Lemma 35 of arXiv:2608.17374, '\textbf{On the Pseudo-Mixing of Kac's Walk}'] Let $I\subseteq[d]$ be nonempty and fix $x\in\mathbb{T}^d$ such that $x[i]=x[j]$ for all $i,j\in I$.
Then for all $t\ge 0$,
\begin{equation}

\bigl\|\mathcal{L}_x(X_t[I])-\pi_{|I|}\bigr\|_{\mathrm{TV}}
\;\ge\;
\mathbb{P}\Bigl(\exists i\neq j\in I:\;H_i(t)=H_j(t)\Bigr).
\end{equation}

[Lemma lem:f^ER_Bass-bounds of arXiv:2411.12076, 'Explicit solutions of the SI and Bass models on sparse Erd\H{o}s-R\'enyi and regular netwo'] Consider the Bass/{\rm SI} model~{\rm ((eqs:Bass-SI-models-ME of the paper),(eqs:ER-network of the paper))} on infinite sparse {\rm ER}~networks. 
	\begin{enumerate}
		\item 
		When $\lambda=0$, the expected/infection adoption level is the same as on networks of isolated nodes,
		i.e., 
		\begin{equation}

			f^{\rm ER}(t;p,q,I^0,\lambda=0) = f^{\rm isolated}(t;p,I^0),
			\qquad 	f^{\rm isolated}:=I^0 + (1-I^0)(1-e^{-pt}).
		\end{equation}


		\item  



		$\lim_{\lambda \to \infty} f^{ \text{\rm ER}}(t;p,q,I^0,\lambda) = f^{\rm compart}(t;p,q, I^0)$,

		where $ f^{\rm compart}$ is the expected adoption/infection level
		in the  compartmental Bass/{\rm SI} model
		\begin{equation}

			\frac{df}{dt} = (1-f)(p+qf), \qquad f(0) = I^0.
		\end{equation}

	\item  For $0<\lambda<\infty$,
		\begin{equation}

			f^{\rm isolated}(t;p,I^0)  < f^{\rm ER}(t;p,q,I^0,\lambda)  < f^{\rm compart}(t;p,q,I^0), \qquad t>0.
		\end{equation}
	\end{enumerate}

[Lemma 13 (Young / entropy inequality) of arXiv:2605.22445, 'Generalized specific entropy on Wiener space with application to Martingale Optimal Transp'] For all $x\ge 0$ and all $y\in\R$,
\begin{equation}
xy \le x\log x + e^{y-1}.
\end{equation}

[Def Random cluster representation of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] The generalised random cluster representation on a finite subset $\Lambda \subset \mathbb Z^d$ with parameters $\beta\geq  0$ and $\mathsf h\in (\mathbb R^+)^\Lambda$, and boundary conditions $(\xi,\mathsf{b})$ is the probability measure $\Psi^{(\xi,\mathsf{b})}_{\Lambda,\beta,\mathsf h}$ on $ \{0,1\}^{\overline E(\Lambda[\mathsf h])}\times (\mathbb R^+)^{\overline \Lambda} $ defined by
\begin{equation}
\mathrm{d}\Psi^{(\xi,\mathsf{b})}_{\Lambda,\beta,\mathsf h}[(\omega,\mathsf a)] = \phi^\xi_{\Lambda, \beta, \mathsf h, \mathsf a}[\omega] \mathrm{d}\mu^{(\xi,\mathsf{b})}_{\Lambda, \beta, \mathsf h}[\mathsf a].
\end{equation}
We write $\Phi^{(\xi,\mathsf{b})}_{\Lambda,\beta,\mathsf{h}}$ for the distribution of the $\omega$-marginal of $\Psi^{(\xi,\mathsf{b})}_{\Lambda,\beta,\mathsf h}$.

[Corollary cor:f with a root at 0 of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $\tilde{f}_n(z)=z^{m_n}f_n(z)$ for a sequence of $f_n\in\mathcal{LP}$ satisfying  Assumption (assump:main assumption of the paper). If $\{p_n\}_{n\geq 1}$ is a sequence of real-rooted polynomials indexed by their degree such that $\llbracket p_n\rrbracket\Rightarrow\mu$ and $\frac{m_n}{n}\rightarrow t\in [0,1)$, then \begin{equation}
		\llbracket \tilde{f}_{n}(\partial_z)p_{n}\rrbracket\Rightarrow\mathcal{D}_{1-t}\left(\mu\boxplus\mu_{c,\Sigma} \right)^{\boxplus\frac{1}{1-t}}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2606.09904, 'Non-explosion principles for branched rough differential equations with unbounded coeffici'] For any \(f \in \CF_{N - 1}\), we have the estimate
  \begin{equation}
    \begin{split}
      &\ \|R^{\phi(\mathbf{Y}), f}\|_{(N - |f|)\gamma}\\
      \lesssim\ & \|R^{\sharp, f}\|_{N\gamma} |t - s|^{|f|\gamma}
      + \frac{|\CT_{N - 1}|^{N - |f| - 1}}{(N - |f|)!} C_{[s, t]}^f
        \|R^{\mathbf{Y}, \mathbf{1}}\|_{N\gamma}^{N - |f|} |t - s|^{(N - 1)(N - |f|)\gamma}\\
      & + \frac{|\CT_{N - 1}|^{N - |f| - 1}}{(N - |f|)!} C_{[s, t]}^f \sum_{\tau \in \CT^+_{N - 1}}
        (\|\partial^\tau_X Y\|_{\infty; [s, t]}\|\<\mathbf{X}, \tau\>\|_{|\tau|\gamma} |t - s|^{(|\tau| - 1)\gamma})^{(N - |f|)}.
    \end{split}
  \end{equation}
  where for any \(I \subseteq \mathbb{R}\), we have denoted
  \begin{equation}
    C_{I}^f := \sup_{\substack{u < v \in I\\ \lambda \in [0, 1]}}
    \|D^{N - |f|} [\partial^f_X \phi(\lambda \mathbf{Y}_u + (1 - \lambda) \mathbf{Y}_v)]\|.
  \end{equation}

