 \item $\forall k \in [K] \quad \hat n_k(\boldsymbol{Q}^{\boldsymbol{\mu}}) = \mu([\hat a'_k(\boldsymbol{Q}^{\boldsymbol{\mu}}),\hat b'_k (\boldsymbol{Q}^{\boldsymbol{\mu}})])$.
 \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

