[Lemma lem:N9-energy of arXiv:2608.30831, 'Sharp discrete Hardy constants in dimensions three and four\\ and strict upper bounds from'] The function in (equation eq:phi-m of the paper) satisfies
\begin{equation}
 \mathcal E_9[u_9]<4\,060\,000.
\end{equation}

[Lemma 13 of arXiv:2604.05234, 'Quantitative propagation of chaos and universality for asymmetric Langevin spin glass dyna'] Suppose $X$ is a weak solution to \eqref{eq: intro quenched dynamics} with Gaussian disorder $\bfJ=\bfG$. Then $X$ satisfies the following SDE, which admits a unique strong solution:
\begin{equation}
\begin{aligned}
dX_t^i &= - U'(X_t^i) dt + \frac{\beta^2}{N} \bigg[X_t^{\top} \int_0^t Q_s X_s dW^i_s \bigg] dt + dW^i_t, \quad i =1,\ldots, N, \quad t \in (0, T), \\
Q_t&=\Big(I+\frac{\beta^2}N \int_0^t X_sX_s^\top \,ds\Big)^{-1},\\
    X_0 &\sim P_0^N,
\end{aligned}

\end{equation}
where $W = (W^i)_{i = 1}^N$ is a standard $N$-dimensional Brownian motion with respect to the filtration generated by $X$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:relEntropyDensity of arXiv:2601.19630, 'Mass generation for the two dimensional O(N) Linear Sigma Model in the large N limit'] The following bound holds
 \begin{equation}
    \sup_{N,L \in \mathbb{N}}\frac{1}{L^{2}}\mathcal{H}(\nu^{N }_{L} \mid \mu^{\otimes N}_{m,L} ) \lesssim C_{r.e.}(\lambda,\beta).  \nonumber 
\end{equation}
Furthermore, there exists $\lambda_{1}=\lambda_{1}(\beta)$ such that for $\lambda \geq \lambda_{1}(\beta)$ it holds
\begin{equation}
\text{log} \big (C_{r.e.}(\lambda,\beta) \big ) \lesssim  \lambda (\log \lambda)^{2}.
\end{equation}

[Proposition 20 of arXiv:2608.27372, 'Universality and sharp thresholds for ellipsoid fitting'] Assume the hypotheses of
	Theorem~\ref{thm:positive-barrier-row-universality}. Then, uniformly over
	$i\in[n]$,
		\begin{equation}

			\E(S^{(i)})^2\le C\Lambda_{\rm ref}^2.
		\end{equation}
	For each
	$i\in[n]$ and $Z_i\in \{W_i,G_i\}$, we have conditionally on $\mathcal{F}^{(i)}$,
		\begin{equation}

			\E_i|r_i(Z_i)|^4\le C(S^{(i)})^2.
		\end{equation}
		Moreover, provided $n\gamma\ge n_0$,
		\begin{equation}

			\E_i\left|
			\Delta_i(Z_i)-\frac{r_i(Z_i)^2}{2(n+\ell_i(Z_i))}
			\right|
			\le C\gamma^{-1/2}n^{-3/2}
			\bigl(1+(S^{(i)})^2\bigr).
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 5 of arXiv:2510.24562, 'Hard wall repulsion for the discrete Gaussian free field in random environment on $\mathbb'] Recall $L \geq 1$, $K \geq 100$. Let $r=r(L)>0$ such that $r(L)\to \infty$ as $L \to \infty$, $b=b(L)>0$ bounded sequence, and $\beta \geq 0$. Then, for every $\Delta, \Theta > 0$ it holds that
    \begin{equation}
        \begin{aligned}

        & \varlimsup_{L \to \infty} \sup_{\omega\in\Omega_{\lambda,\Lambda}} \sup_{\cS} \sup_{x\in\bbZ^d} \Bigg\{ \bbP^\omega \Big[ \sup_{f \in \cF} Z^\omega_{f,\beta,b} \geq b \Delta -\beta \Theta \Big] \\
        & \quad - 2   \exp \Bigg[ -\frac{1}{2} \bigg( b \bigg( \Delta - \frac{c_7}{K^{c_8}}\sqrt{\frac{|\cS|}{\capa^\omega(S)}} \bigg) -\beta \Theta \bigg)_+^2 \frac{\capa^\omega(S)}{c_6\beta^2 r^{2-d}\capa^\omega(S)+\alpha^\omega_{K,L,\beta,b}} \Bigg] \Bigg\} \leq 0 \,,
        \end{aligned}
    \end{equation}
    where $\alpha^\omega_{K,L,\beta,b}$ is defined in Theorem~\ref{thm:ZfbetabBounds}. When $\beta = 0$, and $b = 1$ this bound simplifies to
      \begin{equation}

        \begin{aligned}
            & \varlimsup_{L \to \infty} \sup_{\omega\in\Omega_{\lambda,\Lambda}} \sup_{\cS} \sup_{x\in\bbZ^d} \Bigg\{ \bbP^\omega \Big[ \sup_{f \in \cF} Z^\omega_{f} \geq \Delta \Big] \\
            & \quad - 2 \exp \Bigg[ -\frac{1}{2} \bigg( \Delta - \frac{c_7}{K^{c_8}}\sqrt{\frac{|\cS|}{\capa^\omega(S)}} \bigg)_+^2 \frac{\capa^\omega(S)}{1+U(K,L)} \Bigg] \Bigg\} \leq 0\,,
        \end{aligned}
    \end{equation}
    with $U(K,L)$ as in Theorem~\ref{thm:ZfbetabBounds}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem CT UB of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] For all $t \in (0, 1 \wedge t_*)$ and $n \in \mathbb{N}$, 
  \begin{equation}
    \sup_{\bm{x} \in M^k} \hat{E}_{\bm{x}}[C_t^n] \leq (n!)^{\hat{d}_{\mathrm{s}}^*/2} \bigl( \tilde{c}\, t^{d_{\mathrm{ct}}} \bigr)^n.
  \end{equation}

