[Theorem thm:codiff of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Under Assumption~(ass:params of the paper), for any $s, t \in \mathbb{R}$:
\begin{equation}

\tau\!\bigl(X^{(n)}_H(s),\, X^{(n)}_H(t)\bigr)
= \int_\mathbb{R}
\bigl[|f_n(s,u)|^\alpha + |f_n(t,u)|^\alpha
- |f_n(s,u) - f_n(t,u)|^\alpha\bigr]\,du.
\end{equation}

[Lemma 21 of arXiv:2609.03830, 'Parabolic Poincar\'e inequalities and maximal function estimates for systems of partial di'] Let $2< p<\infty$.
    Assume that $|F|\in L^{p-1}_{\loc}(\Omega_T)$ and that $u\in  L^{p-1}_{\loc}(0,T;W^{1,p-1}_{\loc} (\Om;\mathbb{R}^N))$ satisfies \eqref{p_weak_sol}
 for every $\varphi\in C_0^\infty(\Om_T;\mathbb{R}^N)$. Moreover, assume that there exist a parabolic cylinder $2Q=2\Qla=B_{2\rho}\times I_{2\rho}^\la \Subset\Omega_T$ and a constant $\gamma>1$ such that
\[
   \gamma^{-1}\la\le \biggl(\fiint_{2Q} (|\na u|+|F|)^{p-1}\, dz\biggr)^\frac{1}{p-1}\le \la.
\]
Then there exists a constant $c=c(n,p,L,\gamma)$ such that 
\begin{equation*}
    \begin{split}
        \frac{|u(x,t)-u(x,s)|}{|t-s|^\frac{1}{2}}
    &\le c  ( M^*((|\na u|+|F|)^{p-1} 1_{2Q})(x,t) \\
    &\qquad + M^*((|\na u|+|F|)^{p-1} 1_{2Q})(x,s)+1  )^\frac{p}{2(p-1)}
    \end{split}
\end{equation*}
for almost every $x\in B_\rho$ and $t,s\in I_\rho^\la$.

[Lem 6 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] Let $X\sim \Hyp(n_1,n,m)$ with $\mathbb EX=\frac{n_1m}{n}\geq 10$. There exists absolute constants $C,c$ such that for all $\delta<1/2$,
		\begin{equation} 
			\mathbb P(|X-\mathbb E X|\geq (\mathbb EX)^{1/2+\delta})\leq C\exp(-c(\mathbb EX)^{2\delta}).
		\end{equation}

[Thm 13 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] For all $f\in C(\mathscr{C}^{1-\kappa};\R)$ with linear growth there exists a finite constant $C$ such that
    \begin{align*}
        \sup_T|W_T(f)|\leq C.
    \end{align*}

[Definition 6 (\cite{paper1}) of arXiv:2609.01114, 'Unbalanced spectral Tur\'an problem for color-critical graphs with prescribed large maximu'] For a graph $F$ with $\chi(F)=r+1\geq 3$, define
	\begin{equation*}
		a(F):=\min\{|I|: I\subseteq V(F)\text{ is independent and }\chi(F-I)\le r\}.
	\end{equation*}
	If $a(F)=1$, the graph $F$ is called singleton-boundary.

[Theorem 7 of arXiv:2608.30561, '\Large Informative Label Missingness in Multiclass Classification: Information Geometry an'] Under the conditions above,
\begin{equation}
