\end{equation}
    Then we can find some $x\in S$ such that
    \begin{equation}
        (\Gamma_{2\sqrt{k},16}\setminus\Gamma_{2\sqrt{k},\mathbf{s},t}+x)\cap S\neq\emptyset.
    \end{equation}

