[Lem 52 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] Suppose that $\widehat{\mathbf a}_i^m$ contains at least $y$ strings equal to $s_i$.
        Under the assumption of Lemma~\ref{lem:cond-resam}, and with $\overline{F}^{m}_i$ defined as in \eqref{eq:def-typ-remstr}, there exists a constant $C_4(\mu,m,\chi)>0$ not depending on the sequences of strings $\widehat{\mathbf a}^m_i$, $\mathbf a_i$ and $\widetilde{\mathbf a}$, such that
        \begin{equation}
            \nu_{\mathbf a_i, \widehat{\mathbf a}^m_i}(\widetilde{\mathbf a}) \geq C_4(\mu,m,\chi)  \prod_{j=1}^{m} \lambda_{\widetilde{s}_j}
        \end{equation}
        for all $\widetilde{\mathbf a}\in (\mathsf{PM}(B_x))^m$.

[Lem 62 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] We have
	    \begin{equation} 

        \gamma \geq \frac{1}{2}\lt(1+\sum_{(i,l)\in T} \alpha_l^{(i)} \log(p_l^{(i)}) + \alpha_{\tot}\sum_{i=0}^{z}h_iH\lt(\{\alpha_l^{(i)}\}_{l:(i,l)\in T}\rt) \rt) + \Omega(\eps).
	\end{equation}

