			\mathbb{E} \bigl[\| q_\epsilon \|_{ \mathcal{M}([0,T]\times \mathbb{T}^3) }\bigr]\,\le\, 	\biggl(1 \,+\, \frac{4F_2 +G_2 }{8}T \biggr)  \biggl(
			\frac{1}{2}\int_{\mathbb{T}^3}|u_0|^2 +|\psi_0|^2 \,\mathrm{d} x\,+\,2 \epsilon T
			\biggr)^{1/2}.
		\end{equation}

