[Lemma Taylor of arXiv:2411.15881, 'Stable Approximation for Call Function Via Stein's method'] Let $X$ have a distribution of the form ((px of the paper)) and $B(x)$ satisfy ((bound of the paper)) with $\gamma\in(0,2-\alpha]$. Let
$Y$ be an integrable random variable, which is independent of $X$. For any $0<a<(2A)^{-\frac{1}{\alpha}}\wedge1$, denote
\begin{align*}
T=&\left|
\mathbb{E}[Xf_{g_{M}}'(Y+aX)] -\mathbb{E}[X]\mathbb{E}[f_{g_{M}}'(Y)]-\frac{2A\alpha^{2}}{d_\alpha}\,a^{\alpha-1}\mathbb{E}\left[\big(\mathcal{A}^{\alpha,\delta}f_{g_{M}}\big)(Y)\right]
\right|.
\end{align*}
Then:
\begin{enumerate}
\item[i)] When $\gamma=2-\alpha,$ we have
\begin{align*}
T\leq\frac{2\alpha(2A)^{\frac{2}{\alpha}}\eta_{3,\alpha,\delta}}{(2-\alpha)M^{\frac{\alpha^{2}-1}{\alpha^{2}+2\alpha-1}}}a
+&\eta_{3,\alpha,\delta}\Big[\Big(2(2A)^{\frac{2}{\alpha}}+\frac{8L}{\alpha-1}\Big)+q_{1}\Big]\frac{2(\alpha-1)a\,|\log a|\log M}{(3\alpha-1)M^{\frac{2(\alpha-1)}{3\alpha-1}}}.
\end{align*}
\item[ii)] When $\gamma\in(0,2-\alpha),$ we have
\begin{align*}
T\leq\eta_{3,\alpha,\delta}\Big[\Big(\frac{4(2A)^{\frac{2}{\alpha}}}{2-\alpha}+\frac{8L}{2-\alpha-\gamma}\Big)+q_{1}\Big]a^{\frac{1-\alpha}{\gamma-1}}M^{-\frac{2(\alpha-1)^{2}}{(3\alpha-1)(1-\gamma)}}.
\end{align*}
\item[iii)] When $\gamma=0,$ we have
\begin{align*}
T\leq&\frac{2\alpha(2A)^{\frac{2}{\alpha}}\eta_{4,\alpha}}{(2-\alpha)M^{\frac{\alpha^{2}-1}{\alpha^{2}+2\alpha-1}}}a
+4\eta_{3,\alpha,\delta}aM^{-\frac{2(\alpha-1)^{2}}{(3\alpha-1)(1-\gamma)}}\int_{-a^{-1}}^{a^{-1}}\frac{|B(x)|}{|x|^{\alpha-1}}dx\\
&+\eta_{3,\alpha,\delta}\Big[\Big(\frac{8}{2-\alpha}+2(2A)^{\frac{2}{\alpha}}\Big)+q_{1}\Big]a^{\alpha-1}\big(\sup_{|x|\geq a^{-1}}|B(x)|\big)^{\alpha-1}M^{-\frac{2(\alpha-1)^{2}}{(3\alpha-1)}},
\end{align*}
\end{enumerate}
where $q_{1}$ is defined by (equation q1 of the paper) above. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 11 of arXiv:2609.02385, 'Kinetic Fokker--Planck Equations with Drifts in a Supercritical Range'] Under Assumption {\bf (${\text{H}}$)}, the Cauchy problem \eqref{kineticpde} with $u|_{t\leq0}=0$ admits a unique global weak solution $u$ in the sense of Definition \ref{weaksubsol}, satisfying
\begin{align}
\|u\cI_T\|_{\mL^\infty}+\nor u\cI_T\nor_{\wt\sV_T}<\infty,\quad T>0.
\end{align}
Moreover, for every $T>0$, there exists a constant $C_T=C(T,d,q_1,\bbp_1,q_0,\bbp_0,\b,\|b\cI_{T+4}\|_{\mL_t^{q_1}\mL_z^{\bbp_1}})>0$ such that
\begin{align}
\|u\cI_t\|_{\mL^\infty}+\nor u\cI_t\nor_{\wt\sV_T}\lesssim_{C_T}\|f\cI_t\|_{\mL_t^{q_0}\mL_z^{\bbp_0}},\quad t\in[0,T].
\end{align}

