[Definition SDSSS of arXiv:2603.12774, 'Synchronization by noise for stochastic differential equations driven by fractional Browni'] Let $\left(\mathcal{B}, \{P_t\}_{t \geq 0}, \mathbf{P}, \{\vartheta_t\}_{t \geq 0}\right)$ be a stationary noise process, and let $\mathcal{X}$ be a Polish space. 
	A map
	\begin{align}
		\begin{split}
			&\varphi: \mathbb{R}^+ \times \mathcal{X} \times \mathcal{B} \to \mathcal{X},\\
			&(t, x, \omega) \mapsto \varphi^t_{\omega}(x),
		\end{split}
	\end{align}
	is called a {continuous stochastic dynamical system} if
	\begin{itemize}
		\item For every $T > 0$, $\omega \in \mathcal{B}$, and $x \in \mathcal{X}$,
		\[
		\tilde{\varphi}_T(x,\omega)(t) := \varphi^{t}_{\vartheta_{T - t}\omega}(x), \quad t \in [0, T],
		\]
		lies in $C([0, T], \mathcal{X})$, and $(x,\omega) \mapsto \tilde{\varphi}_T(x,\omega)$ 
		is continuous from $\mathcal{X} \times \mathcal{B}$ to $C([0, T], \mathcal{X})$.

		\item For all $t,s \geq 0$, $\omega \in \mathcal{B}$, and $x \in \mathcal{X}$,
		\begin{align}
			\begin{split}
				&\varphi^{0}_{\omega}(x) = x,\\
				&\varphi^{t+s}_{\omega}(x)
				= \varphi^{s}_{\omega}\big(\varphi^{t}_{\vartheta_{s}\omega}(x)\big).
			\end{split}
		\end{align}

		\item If $\mathcal{X}$ is a separable Banach space, the SDS is called $C^k$ if for all $k \geq 1$, $t \geq 0$, and $\omega \in \mathcal{B}$, 
		the map $x \mapsto \varphi^t_{\omega}(x)$ is $C^k$-Fr\'echet differentiable.
	\end{itemize}

