[Lem 30 of arXiv:2609.03821, 'Condensation and Metastability in the Supercritical Two-Species Zero-Range Process via Res'] For each $x\in S_{\star}$,
\begin{equation}
\langle\!\langle F_{N},-\mathcal{L}^{*}_{N}\mathbb{W}_{x}\rangle\!\rangle_{\mathcal{A}^{{\rm bulk}}_{N-1}}=o(\theta^{-1}_{N}).
\end{equation}

[Definition 108 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Recalling the definition of $k$ from \eqref{eq:h0new}, set 
	\begin{flalign*}
		x^{\pm} =\bar{x} \pm N^{B\delta/9} \td_{\bar{z}}
	\end{flalign*} 

	\noindent and let ${\bf L}^{\pm}$ denote the line parallel to the $y$-axis and with $x$-coordinate $x^\pm$.

[Lem lemma: weight of all possible pinchings is 1 of arXiv:2411.11676, 'Surface sums for lattice Yang--Mills in the large-$N$ limit'] Fix a blue face $B$ with disjoint vertices. 
Then
\begin{equation}
	\sum_{B'\in \AF(B)}w_{\infty}(B')=1,
\end{equation}
where if $B'$ has multiple faces $\{B'_i\}_{i=1}^k$, we set $w_{\infty}(B'):= \prod_{i=1}^kw_{\deg(B'_i)/2}$.
As a consequence, if $M\in\mathcal{N}\mathcal{P}\mathcal{M}(s,K)$ is a non-separable planar embedded map and $B$ is one of its blue faces, then 
\begin{equation}
	\sum_{M'\in \AM(M,B)}w_{\infty}(M') = \prod_{f\in \BF(M)\setminus \{B\}}w_{\deg(f)/2},
\end{equation}
where we recall $\BF(M)$ is the set of blue faces of $M$.

