[Theorem MAIN0 of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] Suppose that $\mathrm{\mathbf{A}}_p(b,\alpha,\varepsilon)$ is verified with $\overline{b}:=b-\alpha >0$ and $\delta_{h,r,k}=\gamma_r^\varepsilon$ in~(equation New6 of the paper).  Let also (equation na1a of the paper) hold with the
		same parameters $p$, $b$ and $\varepsilon$. Moreover, suppose that, for some $p'>p$,  $\sup_{k\ge r}\|\Theta^\pi_{t_r,t_k}(\mu) \|_{p'}<\infty$ for any $\mu\in\mathcal{P}_{p'}({\mathbb R}^d)$.
		Let $\hat{p}=\frac{p(p^{\prime }-p)}{(d+p+1/2)(p^{\prime
			}-p)+(d+p)p}$.

		We also assume that there exists $\eta >0$ such that $\gamma
		_{k}=O(t_{k}^{-\eta })$. Then, for any $\zeta \in (0,1-\frac{\alpha }{b}
		)\cap \big(0,\min \left( \frac{\hat{p}}{2} ,\varepsilon \eta \right) \big]$ and $Y_0$ with law $\mu$, we have 
		\begin{equation}
			\mathbb{E}[W_{p}^{p}(\rho _{k}(Y),\mu _{\ast })]\leq Ct_{k}^{-\zeta },

		\end{equation}
		where $\mu _{\ast }$ is the $(\psi ,p)$-stationary measure.

		Finally, suppose that $\gamma _{k}=\frac{1}{(1+k)^{\beta }}$ with $
		1\geq\beta >\frac{1}{1+\varepsilon }$. Then, for every 
		\begin{equation*}
			\zeta \in (0,1-\frac{\alpha }{b})\cap \big(0,\frac{\hat{p}}{2}\big],
		\end{equation*}
		one has 
		\begin{align}
			\mbox{if $\beta=1$:}&\quad \mathbb{E}[W_{p}^{p}(\rho _{k}(Y),\mu _{\ast
			})]\leq \frac{C}{(\ln k)^\zeta},   \\
			\mbox{if $1>\beta>\frac 1{1+\varepsilon}$:} &\quad \mathbb{E}[W_{p}^{p}(\rho
			_{k}(Y),\mu _{\ast })]\leq \frac{C}{k^{(1-\beta)\zeta}}.  
		\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 7 of arXiv:2607.12384, '2607.12384'] Suppose that \(d=1\). There exists a constant \(C>0\) such that, for all
	\(t,s>0\) and \(h\in\mathbb R\),
	\begin{equation}
		\int_{\mathbb R}G_t(h-\xi)^2G_s(\xi)\,d\xi
		\le
		Ct^{-\beta/\alpha}G_{t+s}(h).
	\end{equation}
	Similarly,
	\begin{equation}
		\int_{\mathbb R}G_t(h-\xi)G_s(\xi)^2\,d\xi
		\le
		Cs^{-\beta/\alpha}G_{t+s}(h).
	\end{equation}

[Corollary c:brownian-maximum of arXiv:2607.24640, 'The Yang-Mills measure on surfaces via Morse theory'] The stochastic process $t\in\mathbb{R}_+\mapsto \widetilde{\mathfrak{W}}_0(t)\in\mathfrak{g}$ verifies the following properties:
\begin{itemize}
\item the one dimensional processes $\widetilde{W}_{0,\ell}:t\mapsto \operatorname{Re}\langle\widetilde{\mathfrak{W}}_0(t),\mathfrak{b}_\ell\rangle$, $\ell=1,\ldots, L$, are independent;
\item it has a modification $\mathfrak{W}_{0}(t)=\sum_{\ell}W_{0,\ell}(t)\mathfrak{b}_\ell$ which is almost surely in $\mathcal{C}^\alpha$ (for every $0<\alpha<\frac{1}{2}$);
\item for every $0\leq s\leq t<\infty$, $W_{0,\ell}(t)-W_{0,\ell}(s)$ follows a centered normal law with variance $\|[\blacktriangle_0(t)-\blacktriangle_0(s)]\|_{L^2_\upsilon(\Sigma)}^2$;
\item for every $p\geq 1$ and for every $0=t_0<t_1<t_2 <\ldots<t_n\leq 1$, $W_{0,\ell}(t_1)$, $W_{0,\ell}(t_2)-W_{0,\ell}(t_1)$,$\ldots$, $W_{0,\ell}(t_p)-W_{0,\ell}(t_{p-1})$ are independent.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Lem: construction binary trees of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] For any fixed $k\in\mathbb{N}_\ast$ let us consider $I_k:=\{1,\ldots,k\}$ and $F:{\mathcal T}_b^{I_k}\to\mathbb{R}$. Then 
		\begin{align*}
			\sum_{\rho'\in{\mathcal T}_b^{I_k}} F(\rho')&=\sum_{\rho\in{\mathcal T}_b^{I_{k-1}}}\sum_{\ell=1}^{m_L(\rho)+1} F( \bullet_k\to_\ell\rho),
		\end{align*}
		where $\bullet_k\to_\ell$ is the insertion operator of Definition (Def: insertion of the paper).

[Proposition of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] Let $(\mathbb{S}^n , h_0 )$ be the round sphere with $n\geq 3$. Then, there exists a constant $C>0$ such that for all $w \in H^{\gamma}(\mathbb{S}^n)$
    \begin{align*}
        I_\gamma [w,h_0] - \Lambda_\gamma (\mathbb{S}^n, [h_0] ) \geq C d(w,\mathcal{M}_{\mathbb{S}^n })^2,
    \end{align*}
    where $\mathcal{M}_{\mathbb{S}^n}$ is the set of minimizers of $I_\gamma [-, h_0]$, and
    \begin{align*}
        d(w,\mathcal{M}_{\mathbb{S}^n}) := \frac{\inf \{\|w - v \|_{H^{\gamma} (\mathbb{S}^n) } : \mathcal{P}v \in \mathcal{M}_{\mathbb{R}^n} \}}{\|w\|_{ H^{\gamma} (\mathbb{S}^n)  }}.
    \end{align*}

