[Theorem 41 (Asymptotics as $\alpha \to \alpha^*_\pm$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Suppose that $x^* \in (0, \M).$
Then, the following asymptotics hold: 
\begin{itemize} 

\item[$(i)$] If $\alpha > \alpha^*_+$ and $r(\alpha -\alpha^*_+)^2 \to \infty$, then
\begin{equation}
     g^{z_0}(r\cos(\alpha), r\sin(\alpha)) \underset{r\to+\infty\atop \alpha\to \alpha^*_+}{\sim}C_*'f_*(z_0) \frac{e^{-r(\cos(\alpha)x(\alpha) + \sin(\alpha)y(\alpha))}}{\sqrt{r}  (x(\alpha)-x^*)}
\end{equation}
where $$C_*'= -C^+(\alpha^*_+)\frac{\gamma(x^*,Y^+(x^*),Z^+(x^*))}
{\frac{d}{dx}\gamma(x,Y^-(x), Z^+(x))\big|_{x=x^*}} > 0$$   
and where $C^+(\alpha^*_+)$ is given by~\eqref{C(alpha)}.

\item[$(ii)$]  If $\alpha >\alpha^*_+$ and $r(\alpha -\alpha^*_+)^2 \to c>0$, then 
\begin{equation}
    g^{z_0}(r\cos(\alpha), r\sin(\alpha)) \underset{r\to+\infty\atop \alpha\to \alpha^*_+}{\sim} \frac{1}{2}C_*^+ \Big(1-\textnormal{erf}\Big(\sqrt{c} A(\alpha^*_+ )\Big)\Big) f_*(z_0)e^{ -r(\cos(\alpha)x^* + \sin(\alpha) y^*)} .
\end{equation}
where $C^+_*$ is given by \eqref{eq:C+*}, $A(\alpha^*_+) = \frac{-x'(\alpha^*_+)}{x'_\omega(0,\alpha^*_+)}$ and where $x'_\omega(0,\alpha^*_+)$ is defined in \eqref{zop}.

\item[$(iii)$] If $r (\alpha -\alpha^*_+)^2 \to 0$, then 
\begin{equation}
    g^{z_0}(r\cos(\alpha), r\sin(\alpha)) \underset{r\to+\infty\atop \alpha\to \alpha^*_+}{\sim} \frac{1}{2}C_*^+ f_*(z_0)e^{ -r(\cos(\alpha)x^* + \sin(\alpha) y^*)} .
\end{equation}

\item[$(iv)$]  If $\alpha <\alpha^*_+$ and $r (\alpha -\alpha^*_+)^2 \to c>0$, then 
\begin{equation}
    g^{z_0}(r\cos(\alpha), r\sin(\alpha)) \underset{r\to+\infty\atop \alpha\to \alpha^*_+}{\sim} \frac{1}{2}C_*^+ \Big(1+\textnormal{erf}\Big(\sqrt{c} A(\alpha^*_+ )\Big)\Big) f_*(z_0)e^{ -r(\cos(\alpha)x^* + \sin(\alpha) y^*)} .
\end{equation}

\item[$(v)$]  If  $\alpha<\alpha^*_+$ and $r (\alpha -\alpha^*_+)^2 \to \infty$, then
\begin{equation}
    g^{z_0}(r\cos(\alpha), r\sin(\alpha)) \underset{r\to+\infty\atop \alpha\to \alpha^*_+}{\sim} C_*^+ f_*(z_0)e^{ -r(\cos(\alpha)x^* + \sin(\alpha) y^*)} .
\end{equation}
\end{itemize} 
The symmetric asymptotics hold as $\alpha \to \alpha^*_-$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 (Deterministic nonlinear reservoir kernel) of arXiv:2608.20998, 'Free-Probability Kernels for Zero-Rollout Hyperparameter Selection in Reservoir Computing'] Let $\psi\in C_b^1(\mathbb{R})$. For fixed $L,t,s$ and a deterministic
bounded input sequence $(u_r)_r$, as $n\to\infty$,
\begin{equation}
  K_{\psi,n,\theta}^{(L)}(t,s)
  \xrightarrow{\mathbb{P}}
  K_{\psi,\theta}^{(L)}(t,s),

\end{equation}
where
\begin{equation}
\begin{aligned}
  K_{\psi,\theta}^{(L)}(t,s)
  &:=\mathbb{E}\!\left[\psi(g_t)\psi(g_s)\right], \\
  (g_t,g_s)
  &\sim\mathcal{N}\!\left(
    0,\Sigma_{\theta}^{(L)}(t,s)
  \right).
\end{aligned}

\end{equation}
The convergence is in probability with respect to the joint randomness
of $W_r$ and $W_{\rm in}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem15 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Assume ((h of the paper)), ((f0 of the paper)) and ((f1 of the paper)) 
  with some $\lambda>1$,
  and let $p\ge 2$ and $r\ge \max\{p,2\lambda\}$ be such that $p>n$ and
  \begin{equation} \label{15.1}
	p\ge n(\lambda-1)
  \end{equation}

  as well as
  \begin{equation} \label{15.01}
	r>2\lambda
	\qquad \mbox{if } n=2
  \end{equation}
  and
  \begin{equation} \label{15.02}
	\frac{np\lambda}{n+p-2} \le r < \frac{np}{n-2}
	\qquad \mbox{if } n\ge 3.
  \end{equation}
  Then there exist $b_1=b_1(p,r,a,h,f)>0, b_2=b_2(p,r,a,h,f)>0$, $\kappa_1=\kappa_1(p,f)>1$ and $\kappa_2=\kappa_2(p,h,f)>1$
  as well as $\Gamma_{10}=\Gamma_{10}(p,r,a,h,f)>0$
  and $\Gamma_{11}=\Gamma_{11}(p,r,a,h,f)>0$ such that whenever ((init of the paper)) and ((uut of the paper)) hold with some $T\in (0,T_{max}]$,
  the function defined by
  \begin{equation} \label{F}
	{\mathcal{F}}(t)
	:= \int_\Omega |\nabla v|^p
	+ b_1 \cdot \bigg\{ \int_\Omega |\nabla u|^r \bigg\}^\frac{p}{r}
	+ b_2 {\mathcal{F}}_1^\frac{p}{2}(t)

	\qquad t\in [0,T_{max}),
  \end{equation}
  with ${\mathcal{F}}_1$ taken from ((F1 of the paper)) satisfies
  \begin{equation} \label{15.2}
	{\mathcal{F}}'(t) + \Gamma_{10} {\mathcal{F}}(t)
	+ \Big\{ \Gamma_{10} - \Gamma_{11} {\mathcal{F}}^{\kappa_1}(t) \Big\} \cdot \int_\Omega |\nabla v|^{p-2} |D^2 v|^2
	\le \Gamma_{11} {\mathcal{F}}^{\kappa_2}(t)
	\qquad \mbox{for all } t\in (0,T).
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq.hole_separation_id of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] For every $E \subseteq E_d({\scaleobj{1}{\square}}_m)$, we have 		
		\begin{align}
			V_m(F,j) = \sum_{\ell=0}^j \sum_{\substack{|G|= \ell \\ G\subseteq E \setminus F}} V_m(F \cup G,j-\ell \vert E),
		\end{align}
		thus it satisfies
		\begin{align}
			\vert V_m(F,j) \vert^2 \leqslant (j+1)\sum_{\ell=0}^j \vert E \vert^\ell \sum_{\substack{|G|= \ell \\ G\subseteq E \setminus F}} \vert V_m(F \cup G,j-\ell \vert E) \vert^2.
		\end{align}

