[Corollary cor:crlfncreform of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Under (equation asmp:obsRG of the paper) and $\alpha \le 1$,
\begin{align}
	\lambda^{(\emptyset)}_{0, {\sf o}} \lambda^{(\emptyset)}_{0, {\sf x}}	\frac{\E_{C^{(\vec{\textbf{a}})}} [ \varphi_{\sf o}^{(1)} \varphi_{\sf x}^{(1)} e^{-V_{0,\varnothing} (\Lambda, \varphi)  }  ] } {\E_{C^{(\vec{\textbf{a}})}} [ e^{-V_{0,\varnothing} (\Lambda, \varphi) }  ]}
		&=  - u_{N,{\sf ox}} (\Lambda) + A_{N,{\sf ox}} + B_{N,{\sf ox}} ,   
\end{align}
where $\delta u_{N} = u_{N} - u_{N-1}$ and
\begin{align}
	A_{N}  &= \frac{{\sf m} [  K_{N} (\Lambda,  z h'_N \one ) ] }{e^{u_{N,\varnothing} |\Lambda|}  \,  {\sf m} [ Z_{N,\varnothing} ( z h'_N \one) ]},\qquad
	B_{N} =  \frac{{\sf m} [ I_N^{\Lambda} ( z h'_N \one ) ]  }{e^{u_{N,\varnothing} |\Lambda|} \,  {\sf m}[ Z_{N,\varnothing} (z h'_N \one ) ]} .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 (Well-posedness of the SDE to transition path process) of arXiv:2506.09462, 'Transition Path Theory For L\'{e}vy-Type Processes: SDE Representation and Statistics'] Let \((\widehat{W}, \mathcal{F}_t^{\widehat{W}})\) be a standard Brownian motion in \(\mathbb{R}^d\), and let \(\widehat{N}\) be an independent Poisson random measure on \([0, \infty) \times (\mathbb{R}^d \setminus \{0\}) \times [0, \infty)\) with intensity measure \(m \times \nu \times m\). Both are defined on a probability space \((\widehat{\Omega}, \widehat{\mathcal{F}}, \mathbb{Q})\).  Let \(\xi : \widehat{\Omega} \to \bar{A}^c \cap (A + 1)\) be a random variable defined on the same probability space and independent of \(\widehat{W}\) and \(\widehat{N}\). Then, there exists a unique c\`{a}dl\`{a}g process \(Y_t : [0, \infty) \to \mathbb{R}^d\), adapted to the augmented filtration \(\widehat{\mathcal{F}}_t\), which satisfies the following equation \(\mathbb{Q}\)-almost surely:
    \begin{equation*}
        \begin{aligned}
            Y_t = &\ \xi + \int_0^{t \wedge \tau_B} K(Y_{s-}) \d s 
            + \int_0^{t \wedge (\tau_A \wedge \tau_B)} \sigma(Y_{s-}) \d \widehat{W}_s \\
            &\ + \int_0^{t \wedge (\tau_A \wedge \tau_B)} 
            \int_{[0, \infty) \times \{|r| < 1\}} 1_{[0, \lambda(Y_s, r)]} F(Y_{s-}, r) \widetilde{\widehat{N}}(\d v, \d r, \d s), \quad t \geq 0,
        \end{aligned}
    \end{equation*}
    where \(\tau_B = \inf\{t \geq 0 \mid Y_t \in \bar{B}\}\) and \(\tau_A = \inf\{t \geq 0 \mid Y_t \in \bar{A}\}\). Moreover, \(Y_t \notin \bar{A}\) for all \(t > 0\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Pro:LIL of arXiv:2411.04778, 'Coupling between Brownian motion and random walks on the infinite percolation cluster'] Given $d$-dimensional standard Brownian motion $(B_t)_{t \geqslant 0}$, we have
		\begin{align}
			\mathbb{P}\Big(\limsup_{t\to \infty}\frac{\vert B_t\vert_p }{\sqrt{2t\log\log t}}= \gamma_{d,p}\Big)=1.
		\end{align}
		Here the constant $\gamma_{d,p}$ is defined in (equation eq.defLIL_para of the paper) and is characterized by 
		\begin{align}
			\gamma_{d,p} = \sup_{x \in \mathbb{R}^d: \vert x\vert_2=1}\vert x\vert_p .
		\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 9 of arXiv:2608.21787, 'Stability of extremal hyperplane projections of balls in $\ell_p^n(\R)$'] Let $0 \le x < y \le 1$. Then
        \begin{align*}
            \int_x^y\frac{y - t}{t^{\frac 3 2}}dt \ge \int_x^y\frac{t - x}{t^{\frac 3 2}}dt \ge \frac{(y-x)^2}{4y^{\frac 3 2}}.
        \end{align*}

