[Lemma 19 of arXiv:2506.17045, '\LARGE{On bivariate Archimax copulas: Level sets, mass distributions and related results}'] Let $\gamma \in \mathcal{P}_\mathcal{W}$, $\psi$ be the corresponding generator, $\varphi$ be its pseudo-inverse, $A \in \mathcal{A}$ and $x \in (0,1)$. Furthermore, let $H_x$ be defined according to eq. \eqref{eq:function_H_x} and $\nu_{H_x}$ be its corresponding probability measure. Then the following assertions hold:
\begin{itemize}
    \item[$(i)$] If $\gamma$ is absolutely continuous, then $\nu_{H_x}$ is absolutely continuous.
    \item[$(ii)$] If $\gamma$ is discrete, then $\nu_{H_x}$ is discrete.
    \item[$(iii)$] If $\gamma$ is singular, then $\nu_{H_x}$ is singular.
    \end{itemize}

[Theorem energy_estimate_LDP of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] Fix a sequence $\{H_j:j\geq 1\}$ of functions in $C^{0,1}(\Omega_T)$ with compact support in $[0,T]\times(0,1)$ and a sequence $\{\eta^N:N\geq 1\}$ of configurations. There exists a finite constant $C=C(R^{\pm},l)$ such that 
    \begin{equation}
    \limsup_{\varepsilon\to0}\limsup_{N\to\infty}\frac{1}{N}\log\mathbb{P}_{\eta^N}^N\Big(\max_{1\leq j\leq k}Q_{H_j}(\rho^{N,\varepsilon})\geq m\Big)\leq -m +C(T+1),
    \end{equation}
    for all $k,m\geq1.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Coro 31 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $\alpha\in\mathbb R$ and $h\in Z\hat C^{1}(\Delta^3_T;B_\alpha)$. Assume that $B\in C(\Delta^2_T;B_\alpha)$ and $\hat\delta B = h$. Then, for every $\tau\in[0,T]$, 
\begin{equation*}
\bigl(\hat\Lambda_{S,1,\alpha}^{\mathrm q}h\bigr)^\tau=[\Theta_\tau B]_\tau\in \mathfrak C^{1}_{\mathrm{log}}(\Delta^2_{\tau};B_\alpha).
\end{equation*}
Moreover, for every $\varepsilon\in(0,1)$, the same underlying class satisfies
\begin{equation*}
\bigl(\hat\Lambda_{S,1,\alpha}^{\mathrm q}h\bigr)^\tau=[\Theta_\tau B]_\tau\in \mathfrak C^{1-\varepsilon}(\Delta^2_{\tau};B_\alpha).
\end{equation*}
In particular,
\begin{equation*}
\bigl(\hat\Lambda_{S,1,\alpha}^{\mathrm q}h\bigr)^\tau=[b^\tau(h)]_\tau, \quad b^\tau(h)_{ts}:=-h^\tau_{ts0}.
\end{equation*}
Consequently, the critical quotient class is independent both of the chosen semigroup increment $B$ and of the dyadic normalization used in Section~\ref{sec:dyadic-frozen}.

[Corollary boundedness of arXiv:2606.29352, 'Exponential Mixing for 2D Stochastic Damped Euler Equation Driven by Bounded Noise'] Let $\gamma>0$ and $2<p \leq \infty$, there exists $\epsilon^\star(\gamma,w_0)>0$ such that for any $0\leq \epsilon < \epsilon^\star $
 \begin{equation}
     \sup_{t\geq0}\|\nabla w_\epsilon(t)\Vert_{p} < \infty,\; \mathbb{P}-a.s.. \end{equation}

[Lemma 34 of arXiv:2608.05931, 'Effective Lagrangian regularity and the uniqueness threshold for random H\"older velocity '] There exists $C(d)>0$ such that the following holds. Let $V,v : [0,1] \times \R^d \to \R^d$ be random vector fields such that $V \in L^1_\omega\mathcal{C}^0_t\mathcal{C}^1_x$ and $v \in \mathcal{C}^0([0,1] \times \R^d)$. Let $\mathcal{F}_t$ be a filtration such that for all $t \in [0,1]$, $V|_{[0,t] \times \R^d}, v|_{[0,t] \times \R^d}$ are $\mathcal{F}_t$-measurable. Let $h \in (0,1]$ and suppose that for all $t \in [0,1]$, 
    \begin{equation}

    v|_{[t+h,1] \times \R^d} \indep \mathcal{F}_t \quad\text{and}\quad \E v|_{[h,1] \times \R^d} =0.
    \end{equation}
    For a fixed $y \in \R^d,$ let $Z_t$ be the (random, almost surely uniquely defined) solution to 
    \[\begin{cases}\dot Z_t = V(t,Z_t),\\ Z_0 =y.\end{cases}\]
    We split
    \begin{equation}

        \int_0^t v(r,Z_r+x)\,dr = M(t,x) + F(t,x),
    \end{equation}
    with
    \begin{equation}

        F(t,x):= \sum_{\ell=2}^{\infty} \E\Big[\int_{(\ell-1) h}^{\ell h \land t} v(r,Z_r+x)\,dr \,\Big|\, \mathcal{F}_{(\ell-2)h}\Big],
    \end{equation}
    where $\int_a^b f(r)\,dr$ is taken to be zero when $b<a$. Then $M$ and $F$ obey the following estimates: for all $\nu \in [0,1)$ there exists a constant $C(\nu)>0$ such that for all $p \geq 2$, sigma algebras $\mathcal{G} \subseteq \mathcal{F}_0$, $\lambda \in [0,1],$ and $n \in \N$,
    \begin{align}

        \|M\|_{\mathcal{C}^{1/2}_t \mathcal{C}^0_x L^p_\omega} &\leq  C h^{1/2} \|v\|_{L^p_\omega \mathcal{C}^0_{t,x}} +  C h^{1/2} \min\big(p^{1/2} \|v\|_{L^p_\omega \mathcal{C}^0_{t,x}}, p^{\lambda \lor 1/2} \sup_{q \geq 2} q^{-\lambda} \|v\|_{L^q_\omega \mathcal{C}^0_{t,x}}\big),
        \\

        \|F\|_{\mathcal{C}^1_t \mathcal{C}^0_x L^p_\omega} &\leq C h \|\nabla v\|_{L^{2}_\omega \mathcal{C}^0_{t,x}}\Big(  \big\|V - \E[V \mid \mathcal{G}]\big\|_{L^{p}_\omega \mathcal{C}^0_{t,x}} \lor h^{\frac{\nu}{1-\nu}} \|V\|_{L^{\frac{p}{1-\nu}}_\omega \mathcal{C}^0_t \mathcal{C}^\nu_z}^{\frac{1}{1-\nu}} \Big),\\
          \|M\|_{L^p_\omega \mathcal{C}^1_t \mathcal{C}^n_x }&\leq C \|\nabla^n v\|_{L^p_\omega \mathcal{C}^0_{t,x}},
          \\\|F\|_{L^p_\omega \mathcal{C}^1_t \mathcal{C}^n_x }&\leq C \|\nabla^n v\|_{L^p_\omega \mathcal{C}^0_{t,x}}.

    \end{align}

