[Lem 25 of arXiv:2607.06745, 'Regularization and asymptotic behaviour of Ornstein-Uhlenbeck evolution operators in infin'] Let $\left\{ B\left(t\right)\mid t\in\mathbb{R}\right\} \subseteq\mathcal{L}\left(X\right)$
be a family of bounded operators such that $B\left(\cdot\right)f$
is measurable for every $f\in X$. Then
\begin{equation}
trQ\left(t,s\right)=\int_{s}^{t}e^{-2\left(t-r\right)}\int_{\Omega}\left|B\left(r\right)^{*}k_{A}\left(x,\cdot,t,r\right)\right|_{X}^{2}dxdr,
\end{equation}
where $k_{A}:\Omega^{2}\times\left\{ \left(t,s\right)\mid s\leq t\right\} \to\mathbb{R}$
is a function depending only on $\left\{ U\left(t,s\right)\right\} _{s\leq t}$
such that $k_{A}\left(\cdot,\cdot,t,s\right)\in L^{\infty}\left(\Omega^{2}\right)$
for every $s\leq t$ and
\begin{align}
\left|k_{A}\left(x,y,t,s\right)\right| & \leq C\left(t-s\right)^{-\frac{N}{2}}e^{-\frac{\left|x-y\right|^{2}}{t-s}}\quad\forall t>s,\ x,y\in\Omega.
\end{align}

