[Theorem thm:main of arXiv:2609.03855, 'A Fejér--Riesz inequality for Dirichlet series'] There is a constant $C_0 >0$ such that 
\begin{equation}
 \int_0^1 |f(1/2+\sigma)|\,d\sigma\le C_0\|f\|_{\mathscr H^1}, \qquad f \in \mathscr H^1.
\end{equation}
Therefore, there is a constant $C_0' > 0$ such that
\begin{equation}
 \left|a_1+\sum_{n=2}^\infty \frac{a_n}{\sqrt n\log n}\right|
 \le C_0' \|f\|_{\mathscr H^1}, \qquad f \in \mathscr H^1.
\end{equation}
The sum in (equation eq:hardy of the paper) is convergent. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 41 (Intrinsicity of the four-copy functional) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] The quantity in \eqref{bridge:eq:four-copy-functional} is finite,
nonnegative, and independent of the bounded representative $(f_n)$.
It is continuous on bounded subsets of $\cH_q$.  If
$
 T=\mathbb U_q^{-1}\xi
$
is the primitive--Fock terminal, then
\begin{equation}
 \boxed{\mathfrak Q_q(\xi)=\kappa_4(T).}

\end{equation}

[Lemma 12 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] Let $\widetilde{W}(t)$ be a $\mathbb{F}$-Brownian motion with values in $\mathbb{R}^{r}$, $n \in \mathbb{N}$, and let $A$ be a family of $\mathbb{F}$-adapted $(\K, k)$-stable processes where $\K$ is $\mathbb{F}$-adapted  and $k$ is  some family of deterministic positive and  locally bounded  functions. We suppose that $\x(t)$ is a family of $\mathbb{R}^{n}$-valued semi-martingales satisfying
				\begin{equation}
					d\x(t)=A(t)\x(t)dt + F(t)dt + D(t)d\widetilde{W}(t), 
				\end{equation}
				where $F(t)$ and $D(t)$ are  $\mathbb{F}$-adapted processes satisfying   for some $ \a \in [0,1/2) $ 
				\begin{align} 
					\x^{\top}(t)\K^{-1}(t)F(t) &\leq           ~   \a k(t)\x^{\top}(t)\K^{-1}(t)\x(t) + \mathcal{O}(k(t)), \\
					D^{\top}(t)\K^{-1}(t)D(t) &=~ \mathcal{O}(k(t)).
				\end{align}	
				If $\x^{\top}(0)\K^{-1}(0)\x(0)$ is bounded in $L^{q}$, 		
				then for any $q\geq 1$ and $\eps$ small enough,  the process\\ $\x^{\top}(t)\K^{-1}(t)\x(t)$ is  bounded in $L^{q}$.

[Prop Prop_K_Estimate of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] For every ${\mathbf{p}} \in \mathbf{Dir}$, $(Z,[{\mathfrak l}]) \in \mathbf{Ram}$,
  $\phi \in K^\infty\paren{X{\backslash} Z,S\otimes{\mathfrak l};{\mathbf{p}}}$, and $k \in {\mathbf{N}}_0$
  \begin{equation*}
    \Abs{w_{\log} \phi}_{H_b^{k+2}} + \Abs{r^{-1}w_{\log} \phi}_{H_b^{k+1}} + \Abs{w_{\log} \nabla \phi}_{H_b^{k+1}}
    \lesssim_k
    \Abs{\phi}_{K^k}.    
  \end{equation*}

