[Lemma lem:displacement2 of arXiv:2608.26765, 'Beyond Client Averaging: A Client-Independent Second-Order Stationary-Bias Component in St'] For every $h\in\{0,\ldots,H\}$,
\begin{equation}

  \frac1N\sum_{c=1}^N\mathbb{E}[(\theta_{c,h}-x)^2]\le C_H\gamma^2.
\end{equation}

[Theorem thm:qua of arXiv:2412.05142, 'Strong convergence of the Euler scheme for singular kinetic SDEs driven by $\alpha$-stable'] For any $\beta\in(1-\frac{\alpha}{2},(\alpha-1)(1+\alpha))$ and any $0<\epsilon<\frac{1}{2}+\frac{(\beta-1)}{\alpha}$ there exists a constant $N=N(\alpha,\beta,d,\|b\|_{{\mathbb C}_{\boldsymbol{a}}^{\beta}},\epsilon)$ independent of $n$ so that for any $n\in{\mathbb N}$ and $k=0,1,\ldots,n$,  $(s,t)\in[\frac{k}{n},1]_\leqslant^2$ the following holds
     \begin{align}
          &\|\int_s^tb(Z_r)-\Gamma_{r-k_n(r)}b(Z_{k_n(r)}^n)dr\|_{L_2(\Omega)|{\mathcal F}_{\frac{k}{n}}} \nonumber\\& \leqslant N|t-s|^{\frac{1}{2}+\epsilon}(n^{-(\frac{1}{2}+\frac{\beta}{(1+\alpha)\alpha}\wedge\frac{1}{2})+2\epsilon}+[Y-Y^n]_{C_p^{\frac{1}{2}}|{\mathcal F}_{\frac{k}{n}},[s,t]}+[Y-Y^n]_{C_p^0|{\mathcal F}_{\frac{k}{n}},[s,t]}).
     \end{align}

[Prop 12 of arXiv:2604.24624, 'Limit distributions of the threshold radius for the maximum degree and the associated poin'] Assume that $n^{k+1}r_n^{dk} \to \infty$.
    Let $\{\Gamma_i\}_{i=1}^m$ be as in Theorem~\ref{MainResult.06}.
    Assume that $\{C_j\}_{j=1}^s \subset \CC_{\widetilde{\CH}_{x_0}}$ is mutually disjoint.
    Then, the joint distribution of
    \begin{equation*}
        \left(\left(D_{n^{(k+1)/d}r_n^k}(T_{-x_0} \widetilde{\Phi}_{n,\Gamma_i})\right)(C_j)\right)_{i,j} = \left(\widetilde{\Phi}_{n,\Gamma_i}\left(n^{-(k+1)/d}r_n^{-k}C_j + x_0\right)\right)_{i,j}
    \end{equation*}
    converges weakly to those of $(Z_{i,j})_{i,j}$ which is a set of independent Poisson random variables with
    \begin{equation*}
        E[Z_{i,j}] = \frac{f(x_0)^{k+1}}{(k+1)!} \int_{(\BR^d)^k} h_{\Gamma_i}\left(\delta_{\bm{0}} + \sum_{\ell=1}^k \delta_{x_{\ell}}\right) \,\prod_{\ell=1}^k dx_{\ell} \times \text{Leb}(C_j).
    \end{equation*}

