body:
[Theorem 68 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume the assumptions stated in Section \ref{Ass-Abstract formulation}. 
Suppose that for all $s \in [0,T]$ and $\bv,\,\bw \in \StokesH$, there exists $\tilde{c}_g>0$ such that
   \begin{equation}
       \Vert \bG_0(s,\bv) - \bG_0(s,\bw)\Vert_{\ell^2(\StokesH)}^2
      \leq \tilde{c}_g \lvert \bv - \bw \rvert_{\StokesH}^2.
    \end{equation}
Let $(\upxi_1,\chi_1)$ and $(\upxi_2,\chi_2)$ be two $\mathbb{H}$-valued initial variables. Assume that on some probability space $(\Omega,\mathscr{F},\mathbb{P})$, with a right-continuous filtration of $\sigma$-fields $\mathbb{F}=(\mathscr{F}_t)_{t \in [0,T]}$ and $\mathrm{Y}$-valued cylindrical Wiener process $W$, we have two solutions 
$$(\bu_1(\cdot,\upxi_1),\phi_1(\cdot,\chi_1)) \mbox{ and } (\bu_2(\cdot,\upxi_2),\phi_2(\cdot,\chi_2))$$ 
to the problem \eqref{eqn-compact-modified-stochastic-CHNSEs-3} corresponding to the initial conditions $(\upxi_1,\chi_1)$ and $(\upxi_2,\chi_2)$, respectively, and such that $\mathbb{P}$-a.s.
\begin{align}
\sup_{s \in [0,T]} \Vert (\bu_i(s,\upxi_i),\phi_i(s,\chi_i)) \Vert_{\nHB}^2 + \int_0^T \Vert (\bu_i(s,\upxi_i),\phi_i(s,\chi_i)) \Vert_{\mathbb{V}}^2\,\d s< \infty,  \quad i=1,2.
\end{align}
Then, for every $t \in [0,T]$, there exists a constant $C>0$ such that
   \begin{equation}
     \mathbb{E }\left[e^{-\int_0^t \mathcal{Y}_2(s)\, \d s} \Vert (\bu_1(t,\upxi_1),\phi_1(t,\upxi_1)) - (\bu_2(t,\upxi_2),\phi_2(t,\upxi_2)) \Vert_{\nHB}^2\right]
     \leq C \Vert (\upxi_1,\chi_1) - (\upxi_2,\chi_2) \Vert_{\nHB}^2,
   \end{equation}
where
\begin{equation}
\begin{aligned}
\mathcal{Y}_2(t)
\coloneqq & C_0 \bigl(1 + \Vert \bu_1(t) \Vert_{\StokesV}^2 + \Vert \phi_1(t) \Vert_{\zero{H}{2}}^2 + \Vert \phi_2(t) \Vert_{\zero{H}{2}}^2 + \lvert \phi_1(t) \rvert_{\newone{H}}^2  \Vert \phi_1(t) \Vert_{\zero{H}{2}}^2 
 \\
&\qquad + \lvert \phi_2(t) \rvert_{\newone{H}} ^2 \Vert \phi_2(t) \Vert_{\zero{H}{2}}^2  + \lvert \bu_2(t) \rvert_{\StokesH}^2 \Vert \bu_2(t)\Vert_{\StokesV}^2  
   \\
&\qquad + \lvert \phi_2(t) \rvert_{\newone{H}}  \Vert \phi_2(t) \Vert_{\zero{H}{2}} \lvert \phi_1(t) + \phi_2(t) \rvert_{L^2} \Vert \phi_1(t) + \phi_2(t) \Vert_{\zero{H}{2}}\Bigr).
\end{aligned}
\end{equation}
Here $C_0$ is a positive constant depending on $\domO$ and the parameters of the problem, but is independent of time. \newline
Moreover, if $(\upxi_1,\chi_1)= (\upxi_2,\chi_2)$, then for every $t \in [0,T]$ we have $\mathbb{P}$-a.s.
\begin{equation}
(\bu_1(t,\upxi_1),\phi_1(t,\chi_1))= (\bu_2(t,\upxi_2),\phi_2(t,\chi_2)).
\end{equation}

[Thm threpr1 of arXiv:2412.08497, 'Time discretization of Quadratic Forward-Backward SDEs with singular drift'] Suppose $\xi = \varphi(X_{t_1},X_{t_2},\ldots,X_{t_n})$, satisfies (equation 2.6 of the paper)--(equation 2.7 of the paper), where $t\leq t_1<t_2<\ldots<t_n\leq T$ is any partition of $[t,T]$. Suppose Assumption (assum2.1 of the paper) holds and let $(X,Y,Z)$ be the solution to the corresponding FBSDE (equation 2.1 of the paper)-(equation 2.2 of the paper). Then, on each interval $(t_{i-1},t_i),  i=1,\ldots,n$ the following holds $\mathbb{P}\text{-almost surely}$
				\begin{align}
					Z_t = \mathbb{E}\Big[ \varphi(X_{t_1},X_{t_2},\cdots,X_{t_n})N_{t_i}^t + \int_t^T g(v,X_v,Y_v,Z_v)N_{v\wedge t_i}^t\mathrm{d}v\Big/\mathfrak{F}_t^s \Big],
				\end{align}
				and \begin{equation}
					N^t_v = \frac{1}{v-t}(M_v^t)^{\bold{T}}(\nabla X_t)^{-1}, \quad 0\leq s \leq t < v \leq T ,
				\end{equation}
				and the two parameters process $M_v^s$ is given by 
				\begin{equation}
					M_v^t = \int_t^v (\nabla X_{\tau} )^{\bold{T}}\mathrm{d}W_{\tau}.
				\end{equation}
				$\nabla X = (\nabla^1 X,\cdots,\nabla ^d X)$ stands for the first variation of the diffusion $X$ as defined in Definition (defi 2.8 of the paper). There exists a version of $Z$ that satisfy the following properties
				\begin{itemize}
					\item[(i)] the mapping $t\mapsto Z_t$ is a.s. continuous on each interval $(t_{i-1},t_i)$, $i=1,\cdots,n$;
					\item[(ii)] both limits $Z_{t_i-}:= \lim_{s \uparrow t_i}Z_s$ and $Z_{t_i+}:= \lim_{s \downarrow t_i}Z_s$ exist;
					\item[(iii)] for all $p>0$, there is a constant $C_p>0$ such that 
					\begin{align}
						\mathbb{E}|\Delta Z_{t_i}|^p \leq C_p.
					\end{align}
				\end{itemize}
				Consequently, the process $Z$ has both c\`adl\`ag and c\`agl\`ad versions, with discontinuities $t_0,\ldots,t_n$ and jump sizes satisfying (equation jump of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 2 of arXiv:2606.18877, 'Ergodic Properties of Non-Linear Density-Dependent Perturbations of the Ornstein--Uhlenbec'] Under the same assumptions as in Theorem~\ref{thm:wellposednessMV}, assuming also \(b_0>\Xi(0)\), it holds that, moreover, 
\begin{equation}
    p_t(x)\leq c\exp\{-\Xi(0)\Vert x\Vert_2^2\},
    \quad \forall\,(t,x)\in(0,T)\times\R^d,
    \end{equation}
    with some constant \(c:=c(b_0, c_0, \Xi(0))>0\) independent of \(T\). (Proof in the paper; no proof environment follows the statement in the TeX.)

