[Definition def:positive-cells of arXiv:2608.29719, 'Persistence Pairing Graphs: Tracking Changes of Selected Homology Bases'] A cell $\sigma_i$ is called \emph{positive} if the $i$-th reduced column satisfies $R_i=0$, and \emph{negative} if $R_i\neq0$. If $\sigma_i$ is a positive $q$-cell, its \emph{selected birth cycle} is the $q$-chain
\begin{equation}

z_i := \sum_{\substack{\ell\leq i\\dim\sigma_\ell=q}}V_{\ell i}\sigma_\ell.
\end{equation}

[Definition def:specular of arXiv:2608.17022, 'Sharp hypocoercive convergence estimates for underdamped Langevin dynamics with specular r'] Let $\mathscr C$ denote the set of functions $f\in C^2(\overline\Omega\times\mathbb{R}^d)$ such that
\begin{equation}
|\partial^\alpha f(x,v)|\le C_\alpha(1+|v|)^{N}
\quad\text{for all }(x,v)\in\overline\Omega\times\mathbb{R}^d\text{ and all multi-indices }\alpha\text{ with }|\alpha|\le2,
\end{equation}
where $\partial^\alpha$ ranges over all mixed derivatives in $(x,v)$, for some $N\in(0,\infty)$ and constants $C_\alpha<\infty$ depending on $f$, and
\begin{equation}
f(x,v)=f(x,R_xv)\qquad\text{for all }x\in\partial\Omega,\ v\in\mathbb{R}^d.
\end{equation}
We write $\mathscr C_0:=\mathscr C\cap\Lmuz$.

[Proposition 10 (Volume doubling) of arXiv:2609.01098, 'Gaussian upper bounds for averaged heat semigroups on graphs'] Let $x\in X$,   {$R_2\geq R_1\geq 4S$}, $n>2$ and $\phi\geq 1$. If for all $r\in[R_1,R_2]$ {and $u\in\cC_{c}(B_x(r))$}, we have
\begin{equation*}
\frac{m(B_x(r))^{\frac{2}{n}}}{\phi r^2}
\Vert u\Vert_{\frac{2n}{n-2}}^2
\leq \cE(u)+\frac{1}{r^2}\Vert u\Vert_2^2,
\end{equation*}
then we have
{\[
\frac{m(B_x(R))}{R^{n}}
\leq {A(n)} \Phi_x(n,r,R)\ \frac{m(B_x(r))}{r^{n}}, \quad R_1\leq r\leq R\leq R_2,
\]
}
where
{
\[
\Phi_x(n,r,R)=\left[1\vee  r^n
{\frac{m(B_x(R))}{m(B_x(R_1))R^n}}
\right]^{ 4\sqrt[n]{S/r}},\quad\mbox{and}\quad A(n)=2^{ 8n^2}\phi^{\frac{n}{2}}(1\vee S)^{4n}.
\]
}
In particular, if $R_2= 2R_1$, we obtain 
\begin{align*}
	m(B_x(R_2))
\leq {A'(n)} \Phi_x(n,R_2) m(B_x(R_2/2)),\qquad A'(n)=2^{ 9n^2}\phi^{\frac{n}{2}}(1\vee S)^{4n}
\end{align*}
where $\Phi_x(n,R_2)=\left[
{\frac{m(B_x(R_2))}{m(B_x(R_2/2))}}
\right]^{ 6\sqrt[n]{S/R_2}}\geq \Phi_x(n,R_2/2,R_2)$.

