[Corollary cor:ordinary-BE-kernel of arXiv:2605.16244, 'Analysis of a twisted Bose--Einstein Markov chain with applications to sampling Catalan st'] Let $K_{\mathrm{BE}}$ and $\pi_{\mathrm{BE}}$ be the transition kernel and the stationary distribution of the Bose--Einstein Markov chain on $[k]^n$. Then for all $x,y \in [k]^n$,
\begin{equation}
 K_{\mathrm{BE}}(x,y)
 =\frac{1}{\prod_{a=1}^k i_a(x)!}
 \prod_{a,b=1}^k
 \left(\frac1k\right)_{(m_{a,b}(x,y))}
\end{equation}
and
\begin{equation}
 \pi_{\mathrm{BE}}(x)
 =\frac{\prod_{a=1}^k i_a(x)!}
 {n!\binom{n+k-1}{k-1}}
 =\frac{\prod_{a=1}^k i_a(x)!}{(k)_{(n)}}.
\end{equation}

[Proposition 19 (Uniform-in-time first Malliavin derivative bounds) of arXiv:2605.03057, 'Uniform-in-time quantitative fluctuations of large scale interacting particle systems'] Let $p\in\left\{4,8\right\}$. Assume
Assumptions~\ref{ass:smooth}, \ref{ass:second-malliavin-uniform}(i),
\ref{ass:coeff-level-new}(i)(ii), and
\ref{ass:first-malliavin-uniform}. Then, there exists a constant
$C_p>0$ such that, for all $N\ge 1$, all $0\le s\le u$, and all
$i,j\in\left\{1,\dots,N\right\}$,
\begin{equation}

\E\left(
\norm{D_s^j X_u^{i,N}}^p
\right)^{1/p}
\le
C_p e^{-\kappa_p \left( u-s \right)/8}
\left(
\mathbf{1}_{\left\{ i=j \right\}}
+
\frac{1}{N}\mathbf{1}_{\left\{ i\ne j \right\}}
\right).
\end{equation}
In particular,
\begin{equation}

\frac{1}{N}\sum_{i=1}^N
\E\left(
\norm{D_s^j X_u^{i,N}}^p
\right)^{1/p}
\le
\frac{C_p}{N} e^{-\kappa_p \left( u-s \right)/8}.
\end{equation}

[Proposition 60 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] The following conditions are equivalent:
\item[(i)] $F$ is $\sigma$-semicontinuous;
\item[(ii)] $\Ba_{F}$ is $\sigma$-order closed;
\item[(ii')] $\Ba_{F}$ is $\mathrm{u\sigma o}$ closed;
\item[(iii)] If $f_{p}\toso f$, then $\|f\|\le\liminf\|f_{p}\|$;
\item[(iii')] If $f_{p}\touso f$, then $\|f\|\le\liminf\|f_{p}\|$;
\item[(iv)] If $f_{n}\toso f$, then $\|f\|\le\liminf\|f_{n}\|$;
\item[(iv')] If $f_{n}\touso f$, then $\|f\|\le\liminf\|f_{n}\|$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 17 of arXiv:2606.08115, '2606.08115'] Let $\{S_n\}$ be a random walk with increments $X_j$, $\ex X_j = 0$, $\ex X_j^2 = \sigma^2 \in (0, +\infty)$. Then for any $\alpha > 0$ there exists a parameter $C$ such that for every sufficiently large natural $n$ the inequality
\begin{equation*}

\pr \left( S_j < \alpha \ln n, j \le n \right) \le \frac{C\ln n}{\sqrt n}
\end{equation*}
holds.

[Prop 3 (Proposition 5.2 in \cite{BV93}) of arXiv:2606.29683, 'Scaling limit theorem for mixed free and Boolean convolution powers'] For any $\mu\in\calP$, there exist unique $b\in \R$ and a finite measure $\tau$ on $\R$ such that 
    \begin{align}
        F_{\mu}(z) 
        =  b+ z - \int_\R \frac{1+xz}{z-x}\,\tau(\mathrm{d} x).
    \end{align}
    Conversely, if an analytic function $F:\C^+\to\C^+$ admits a representation of the form \eqref{PN}, then there exists a unique $\mu \in \calP$ such that $F=F_{\mu}$ on $\C^+$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:slepian of arXiv:2607.20956, 'Sharp moduli of continuity for Gaussian fields and stochastic PDEs via correlation bounds'] Let $Y$ and $Z$ be centered $\mathbb{R}^m$-valued Gaussian random variables.
If $\mathbb{E}[Y_i^2]=\mathbb{E}[Z_i^2]$ and $\mathbb{E}[Y_iY_j] \le \mathbb{E}[Z_i Z_j]$ for all $i,j\in \{1,\dots, m\}$, then
\begin{align*}
    \textstyle
    \mathbb{P}\left( \bigcup_{j=1}^m \{ Y_j > a_j \} \right) \le \mathbb{P}\left( \bigcup_{j=1}^m \{Z_j > a_j\} \right)
\end{align*}
for any non-random numbers $a_1,\dots, a_n \in \mathbb{R}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 9 (Lower bound on balls) of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] Let
$B(\mu, \delta)$ be as in \eqref{definition boule BL de rayon delta en mu}
and let $B_{\mathsf{c}}(\mu, \delta) = B(\mu, \delta) \cap \mathcal{M}_{1,\mathsf{c}}(\mathbb{R})$,
\textit{c.f.} \eqref{definition espace probas contraint}. Then, for any $\mu \in \mathcal{M}_1(\mathbb{R})$, we have

\begin{align}

\liminf_{\delta \searrow 0} \liminf_{N \to +\infty} \frac{1}{N} \ln \overline{\Pi}_{N}[B(\mu,\delta)] \geq - I[\mu] \, .

\end{align}

Similarly, for any $\mu \in \mathcal{M}_{1,\mathsf{c}}(\mathbb{R})$, we have

\begin{align}
    \liminf_{\delta \searrow 0} \liminf_{N \to +\infty} \frac{1}{N} \ln \overline{\Pi}_{N,\mathsf{c}}[B_{\mathsf{c}}(\mu,\delta)] \geq - I[\mu] \, .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

