[Lemma 2-l18 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] There exists a finite constant $C_0$, depending only on $V$, such that
\begin{equation*}
\max_{x\in {\mathbb T}^d_N} \big|\, (\Delta^{(1)}_N {\boldsymbol u}_N)(x) + K\,
E_{\nu^N}[\tau_x h_0] \,\big|\;\le\; \frac{C_0 \, K^2}{N^2}
\end{equation*}
for all $N\ge 1$.

[Lemma lemma_bound_EEplus of arXiv:2411.16452, 'Interface scaling limit for the critical planar Ising model perturbed by a magnetic field'] There exists a constant $C>0$ such that for any $k \geq 1$ and any $x_1, \dots , x_k \in \Omega_{\delta}$, 
\begin{equation*}
    {\mathbb{E}_{\delta}^{+}}[\prod_{j=1}^{k}\sigma_{x_j}] \leq C^k\delta^{\frac{k}{8}}\exp\bigg( \frac{1}{8}\sum_{j=1}^{k} \log \frac{1}{\frac{1}{2}L(x_j) \wedge \text{d}(x_j, \partial \Omega_{\delta})} \bigg)
\end{equation*}
where for each $j$, $L(x_j) = \min_{p:p \neq j} \vert x_p - x_j \vert$. Above, for $x \in \Omega_{\delta}$, $\text{d}(x, \partial \Omega_{\delta})$ is the Euclidean distance between $x$ and $\partial \Omega_{\delta}$.

[Theorem thm:Lyapunov-exponential-ergodicity of arXiv:2507.09421, 'Stability of randomly switching stochastic reaction networks with asymptotically linear tr'] Let $X$ be a continuous-time Markov chain on a countable discrete state space $\mathbb S$ with generator $\mathcal L$. Suppose that there exists a function $V:\mathbb S\to[0,\infty)$ and constants $c\in(0,\infty)$ and $d\in\mathbb R$ such that $\{x\in\mathbb{S}\,:\,V(x)\leq R\}$ is finite for all $R\in [0,\infty)$ and
    \[
    \mathcal LV(x)\le -cV(x)+d
    \]
    for every $x\in\mathbb S$. Then $X$ converges exponentially fast.
\begin{proof}
    The continuous-time Markov chain restricted to a closed communicating class can be regarded as an irreducible Markov chain. Hence, $X$ restricted to a closed communicating class is exponentially ergodic by Theorem~7.1 in [Meyn_Tweedie_1993]. Let $A$ be the union of closed communicating classes and let $\tau=\inf\{t\in[0,\infty)\,:\,X(t)\in A\}$. By Theorem~7.3 in [Anderson_Cappelletti_Kim_Nguyen_2020] we have that $\mathbb{E}_x[\tau]<\infty$ for all $x\in\mathbb{S}$. Let $Q$ be the transition rate matrix of $X$ and let $\mu$ be a probability measure on $\mathbb{S}\setminus A$. Define a continuous-time Markov chain $\hat{X}$ on $\mathbb{S}$ with transition rate matrix $\hat{Q}$ given by
    \[
    \hat{Q}(i,j)=\begin{cases}
    \mu(j)\min\left\{1, \dfrac{1}{V(j)}, \dfrac{1}{\mathbb{E}_j[\tau]}\right\}&\text{if }i\in A, j\notin A\\
    Q(i,j) &\text{otherwise}
    \end{cases}
    \]
    for all $i,j\in\mathbb{S}$ with $i\neq j$, where we set $1/0=\infty$. Since $\mathbb{E}_x[\tau]<\infty$ for all $x\in\mathbb{S}$ and there is a positive transition rate from any state $i\in A$ to any state $j\notin A$, the Markov chain $\hat{X}$ is irreducible. Moreover, we can couple the two processes $X$ and $\hat{X}$ in a way that $X(t)=\hat{X}(t)$ for all $t\leq \tau$. With this choice of coupling, we can write $\tau=\inf\{t\in[0,\infty)\,:\,\hat{X}(t)\in A\}$. Finally, let $\hat{\mathcal{L}}$ be the generator of $\hat{X}$. For all $x\notin A$ we have $\hat{\mathcal{L}} V(x)=\mathcal{L}V(x)\leq -cV(x)+d$, and for all $x\in A$
    \begin{align*}
        \hat{\mathcal{L}} V(x)&=\mathcal{L}V(x)+\sum_{j\notin A}\mu(j)\min\left\{1, \dfrac{1}{V(j)}, \dfrac{1}{\mathbb{E}_j[\tau]}\right\}(V(j)-V(x))\\
        &\leq \mathcal{L}V(x)+\sum_{j\notin A}\mu(j)\dfrac{V(j)}{V(j)}-V(x)\sum_{j\notin A}\mu(j)\min\left\{1, \dfrac{1}{V(j)}, \dfrac{1}{\mathbb{E}_j[\tau]}\right\}\\
        &\leq \mathcal{L}V(x)+1\leq -cV(x)+d+1.
    \end{align*}
    Hence, Theorem~7.1 in [Meyn_Tweedie_1993] applies and we can conclude that $\hat{X}$ is exponentially ergodic. Hence, due to [kingman1964stochastic], stated as Theorem 1.1 and rigorously proved in [kim2025path], there exists $\gamma\in\mathbb R_{>0}$ such that for all $x\in\mathbb S$ we have $\mathbb E_x[e^{\gamma\tau_x}]<\infty$, where
    \begin{equation*}
        \tau_x=\inf\{t\in\mathbb R_{>0}\,:\,\hat{X}(t)=x, \hat{X}(s)\neq x \text{ for some } 0\leq s<t\}.
    \end{equation*}
   Let $y\in A$. By irreducibility, given any $x\in \mathbb S$ we have $P_y(\tau_x<\tau_y)>0$. Hence, by strong Markov property
   \begin{align*}
       \infty>\mathbb E_y[e^{\gamma\tau_y}]&\geq P_y(\tau_x<\tau_y)\;\mathbb E_y[e^{\gamma\tau_x}|\tau_x<\tau_y]\;\mathbb E_x[e^{\gamma\tau_y}]\\
       &\geq P_y(\tau_x<\tau_y)\;\mathbb E_y[e^{\gamma\tau_x}|\tau_x<\tau_y]\;\mathbb E_x[e^{\gamma\tau}]
   \end{align*}
   It follows that $\mathbb E_x[e^{\gamma\tau}]<\infty$ for every $x\in \mathbb S$, and the proof is complete.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

