[Defn 12 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] For $\alpha_1$ and $\alpha_2$ such that $h\leq \alpha_1,\alpha_2\leq 1$, we denote $\Tilde{h}:=\frac{h}{\sqrt{\alpha_1\alpha_2}}$. We define $\mc{H}^d_{\Tilde{h},\alpha_1,\alpha_2}$ as the set of $u\in \mathscr{S}'(\R^d)$ such that for all $n\in \Z^d$, 
    \begin{equation*}
        u(x+\alpha_1^{-1/2}n)=u(x)\m\m\m\m\m\text{and} \m\m\m\m\m\mc{F}_{\Tilde{h}}(u)(\xi+\alpha_2^{-1/2}n)=\mc{F}_{\Tilde{h}}(u)(\xi) .
    \end{equation*}

[Prop 70 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] The following holds if the constant $L$ entering \Cref{yy} is chosen to be sufficiently large. Let the constants $A,B,R$ satisfy
			\begin{eqnarray}

				B \ge 1000R \ge 1000A  \ge 30000. 
			\end{eqnarray}
			Let $q$ satisfy \eqref{eq:condizq}; let $\md,\omega > 0$ satisfy \eqref{condizd} and \eqref{domega}; and let the point $w_0$ around which the cell $\mathcal Y$ is centered satisfy the assumptions in \Cref{def:w0}. Also suppose that
			\begin{align}

				\begin{aligned} 
                                        \omega \ge \mathfrak{d}^{-1/3} N^{1/3-R\delta}.
				\end{aligned}
			\end{align}
			Further assume:
			\begin{enumerate}
				\item [(i)]   For all $w \in \mathcal{Y}$, we have 
				\begin{eqnarray}

					H_0 (w) \le \cH_\mq (w) + N^{R\delta-1}.
				\end{eqnarray}

				\item [(ii)] For all $w \in \mathcal{Y} \setminus  \mathfrak{L}_q^+ (R\delta)$, we have 
				\begin{eqnarray}

					H_0 (w) \le \mathcal{H}_q (w).
				\end{eqnarray}
			\end{enumerate}

			\noindent Apply the Glauber dynamics restricted to $\mathcal Y$, with ceiling constraint $\cH_q$ on $\mathcal{Y} \setminus  \mathfrak{L}_q^+ (R\delta)$ and $\cH_q+N^{R\delta-1}$ on $\mathcal{Y}\cap \mathfrak{L}_q^+ (R\delta)$. Then, w.o.p., the following two statements hold for each $t \in [\mq^{-1} N^{1+10 B\delta} \omega,N^{5}]$.
			\begin{enumerate} 
				\item   For each $z \in \mathcal{Y}^-$ with $(\mathtt{d}_z \mathtt{e}_{z;q})^{1/2} \le N^{R\delta} \omega^{-1}$ and $\mathtt{d}_z \in (L^{-2} \mathfrak{d}, L^2 \mathfrak{d})$, we have 
				\begin{eqnarray}

					H_t (z) \le \cH_q (z) + N^{\delta-1}.
				\end{eqnarray}

				\item   For each $z \in \mathcal{Y}^- \setminus \mathfrak{L}_q^+ (\delta)$ with $\mathtt{d}_{z} \in (L^{-2} \mathfrak{d}, L^2 \mathfrak{d})$, we have
				\begin{flalign*}
					H_t (z) \le \mathcal{H}_{q} (z).
				\end{flalign*}
			\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:m-OGP of arXiv:2608.09465, 'Balancing fractional Brownian motion'] Let $\{f^{(i)}_1, \ldots, f^{(i)}_n\}_{i=0}^m$ denote $(m+1)$ independent copies of the set of $n$ independent sample paths of fBm on $[0, 1]$ with Hurst exponent $H$. For any $\tau_i\in [0, \pi/2]$, denote the interpolation $g^{(i)}_j(t; \tau_i) = \cos(\tau_i)f_j^{(0)}(t) + \sin(\tau_i)f_j^{(i)}(t)$ for $i=1,\ldots, m$ and $j = 1,\ldots, n$. Fixing $0<\eta_1<\eta_2<1$, let $\mathcal S(\eta_1, \eta_2, m, a_n, \mathcal I)$ denote the set of $m$-tuples $\{\sigma^{(i)}\}_{i=1}^m$ of $\{\pm 1\}^n$ satisfying the following conditions:  
\begin{itemize}
\item (Near-optimality condition) There exist $\tau_1, \ldots, \tau_m\in\mathcal I\subseteq [0, \pi/2]$ such that $\sigma^{(i)}$ balances the set $\{g^{(i)}_1(t; \tau_i), \ldots, g^{(i)}_n(t; \tau_i)\}$ up to order $a_n$, i.e., 
\begin{align*}
\left\|\sum_{j=1}^n\sigma^{(i)}_jg^{(i)}_j(\cdot; \tau_i)\right\|_\infty\leq a_n. 
\end{align*}
\item (Pairwise overlap condition) $\{\sigma^{(i)}\}_{i=1}^m$ have intermediate correlations within $[\eta_1, \eta_2]$: 
\begin{align*}
\frac{1}{n}\left|\sum_{\ell=1}^n\sigma^{(i)}_\ell\sigma^{(j)}_\ell\right|\in [\eta_1, \eta_2], \quad\quad \forall i\neq j.  
\end{align*} 
\end{itemize}
We say that the $m$-OGP with parameters $(\eta_1, \eta_2, m, a_n, \mathcal I)$ holds if $\mathbb{P}\{\mathcal S(\eta_1, \eta_2, m, a_n, \mathcal I)\neq\emptyset\} = \mathcal{O}(e^{-cn})$ for some absolute constant $c>0$.

[Lemma 13 of arXiv:2511.06196, 'Central limit theorem for high temperature spin models via martingale embedding'] Let \(A \subset \{1,\ldots,n\}\) and choose arbitrary \(\epsilon > 0\).
Then, for some \(C_{t,\epsilon}, c_\epsilon > 0\), independent of \(n\), we have
\begin{equation*}
\sup_{\sigma \in \{-1,1\}^{A\backslash \{i\}}}
\E\Big|\sum_{j=1}^{n}\Delta_i m_{jk}^{[A]}\Big|^{2+\epsilon}\leq \frac{C_{t,\epsilon}}{n^{1+\epsilon/2}}
\end{equation*}
for all \(i\in A\), \(k\in \{1,\ldots,n\}\) and \(0 \le t < c_\epsilon\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem_flow_1.5 of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Under the assumptions of (lem_flow_1 of the paper), we have that for all $t\in [t_0,t_m]$,
    \begin{equation}
        \begin{aligned}
            \max _{a \in \llbracket D \rrbracket}\left|\mathbb{E}\left\langle\left(G_t-M_t\right) E_a\right\rangle\right| \prec \frac{t_c-t_0}{t_c-t} \max _{a \in \llbracket D \rrbracket}\left|\mathbb{E}\left\langle\left(G_{t_0}-M_{t_0}\right) E_a\right\rangle\right|+\frac{N^{\varepsilon_g}}{N^2\left(t_c-t\right)^2\left(\operatorname{Im} m_t\right)^3}.
        \end{aligned}
    \end{equation}
Combining this with (equation t_eta of the paper), (equation im_m_t_sim_through_evolution of the paper), and (equation largG_1G of the paper), and using the definition of $t_m$, we obtain that for all $t\in\left[{t_0,t_m}\right]$,
    \begin{equation}
        \begin{aligned}
            \max _{a \in \llbracket D \rrbracket}\left|\mathbb{E}\left\langle\left(G_t-M_t\right) E_a\right\rangle\right| \prec& \frac{N^{-\varepsilon_g}}{N\left({t_c-t}\right)\im m_t}+\frac{N^{\varepsilon_g}}{N^2\left(t_c-t\right)^2\left(\operatorname{Im} m_t\right)^3}\sim \frac{N^{-\varepsilon_g}}{N\left({t_c-t}\right)\im m_t}.
        \end{aligned}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:poisson_properties of arXiv:2606.05377, 'The Clark-Kushner condition for interacting reinforced random walks on finite graphs'] For each $x \in \triangle$:
\begin{enumerate}[(a)]
\item $Q(x)\mathcal{P}(x) = \mathcal{P}(x)Q(x)$;
\item $(I - Q(x))\mathcal{P}(x) = \mathcal{P}(x)(I - Q(x)) = I - \Pi(x)$;
\item $\mathcal{P}(x)\mathbf{1}^T = 0$.
\end{enumerate}

[Lemma 32 of arXiv:2608.12291, 'When should one stop the most exciting game?\\ {\tiny Sequential Inference for win-marting'] Let $T<\infty$. For any $\varepsilon>0$ such that $\mathcal{I}_\varepsilon:=[t_1+\varepsilon,t_2-\varepsilon]$ has nonempty interior, there exists a $K_\varepsilon>0$ uniformly for all sufficiently large $T$ such that
    \begin{equation*}
        \lvert \partial_t a_T^\delta(t)\rvert\leq K_\varepsilon
    \end{equation*}
    for any $t\in\mathcal{I}_\varepsilon$ and $\delta>0$ sufficiently small.

