[Lemma C(a)-def-2 of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] With $f, \phi, u_\phi,  C(f, \alpha)$ given as in Lemma (C(a) definition of the paper), it holds that, as $t\to \infty$\footnote{The range of integration for (equation second-def-C(a) of the paper) in [Lemma 9.10-[Bovier_book]] is given to be $(0,\infty)$. However, since $u_{\phi}(t, \sqrt{2}t + x) \to 0$ as $t\to \infty$ pointwise in $x$ (see Lemma (when-does-u-go-to-zero of the paper)), one can easily change the range of integration to $(-\infty, \infty)$ by invoking the dominated convergence theorem.},
\begin{equation}
\frac{1}{\sqrt{2\pi}} \int_{-\infty}^\infty u_\phi(t, \sqrt{2}t + z) e^{(\sqrt{2}+ \alpha)z - \alpha^2t /2} dz \to C(f, \alpha).     
\end{equation}
In particular, for $\lambda >\sqrt{2}$, $\mu =\lambda + \sqrt{\lambda^2-2}$, and $\alpha(\lambda) := \mu -\sqrt{2}$, by substituting $ z = (\lambda -\sqrt{2})t - x$, 
\begin{equation}
    \frac{1}{\sqrt{2\pi}} \int_{-\infty}^{\infty} u_{\phi}(t, \lambda t -x)e^{-\mu x} dx \to C(f, \alpha(\lambda)). 
\end{equation}
Also, for any fixed $x \in \mathbb{R}$ (see equation (9.50) of [Bovier_book]), 
\begin{equation}
    C(f(x + \cdot), \alpha(\lambda)) = e^{\mu x}C(f, \alpha(\lambda)).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 5 (Common-shape asymptotic relative efficiency) of arXiv:2609.00774, 'Semi-Supervised Classification with Informative Missing Labels in Weibull Mixture Models'] Assume the conditions of \Cref{thm:risk-hessian}. Under a common-shape two-component Weibull mixture, suppose $AB<0$, so that Bayes' rule has the unique simple decision boundary $y_0$. For the $\mathrm{full}$ estimator relative to the estimator based on the completely classified sample,
\begin{equation}
\ARE_{\mathrm{full}:\mathrm{CC}}^{\mathrm{C}}
=
\frac{
g_C(y_0)^\top
\J_{\mathrm{CC},C}^{-1}
g_C(y_0)
}{
g_C(y_0)^\top
\J_{\mathrm{full},C}^{-1}
g_C(y_0)
}.

\end{equation}

[Cor 2 of arXiv:2607.14674, 'On the entropy of the log-normal distribution'] For the family of densities $g_r$ from \eqref{eq:SC} we have 
\begin{equation}
H[g]<\max_{r\in[-1,1]}H[g_r]
\end{equation}
and the maximum is realized for a unique number $0<r_0<\alpha/\beta_1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem comparison-result of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Fix $T > 0$ and assume $f,g: \mathbb{D}([0,T], \mathcal{M}) \to [0,\infty]$ satisfy for all $x \in \mathcal{M}$:
    \begin{gather}
        \mathbb{E}[f(\{X_s^x\}_{s \leq T})] \leq \mathbb{E}[g(\{X_s^x\}_{s \leq T})] \,,
    \\

        \limsup_{t \to \infty} \mathbb{E}\Big[\frac{1}{t}\int_0^t f(\{X_r^x\}_{s\leq r \leq s+T})^2 + g(\{X_s^x\}_{s \leq r \leq s+T})^2ds\Big] < \infty \,.
    \end{gather}
    Then
    \begin{equation}
        \limsup_{t \to \infty} \frac{1}{t}\int_0^t f(\{X_r^x\}_{s\leq r \leq s+T})ds \leq \limsup_{t \to \infty} \frac{1}{t}\int_0^t g(\{X_r^x\}_{s\leq r \leq s+T})ds \,.
    \end{equation}

    Furthermore, if $f$ has the form $f(\phi) = \int_0^T \hat f(\phi(s))ds$ where $\hat f: \mathcal{M} \to [0,\infty]$, $g_2: \mathbb{D}([0,T],\mathcal{M}) \to [0,\infty)$ satisfies $g(\phi) \leq \frac{T}{2}\hat f(\phi(0)) + g_2(\phi)$, and (equation eq-compare-var of the paper) also holds with $g$ replaced by $g_2$, then
    $$\limsup_{t \to \infty} \frac{1}{t}\int_0^t \hat f(X_s^x)ds \leq \frac{2}{T}\limsup_{t \to \infty} \frac{1}{t}\int_0^t g_2(\{X_r^x\}_{s\leq r \leq s+T})ds \,.$$

[Theorem 11 of arXiv:2609.03793, 'Typical martingale diverges on a co-$\sigma$-porous set'] Let $p\in[1,\infty]$ and let $\f\in\M_p$. Then 
\begin{equation*}
    Q\coloneqq\bs{\nu\in2^\N;\osc f_n(\nu)>0}
\end{equation*}
is not co-$\sigma$-porous in $(2^\N,\rhoexp)$.

[Definition def:Lipschitz_width of arXiv:2609.03129, 'A Closed-Form Formula for Consistent Lipschitz Regression on Metric Spaces with Sparse Neu'] {petrova2023lipschitz}}]

Let $(\mathcal{X},\|\cdot\|_{\mathcal{X}})$ be a Banach space, let
$\mathcal K\subseteq \mathcal{X}$ be bounded, let $n\in\mathbb N_+$, and let
$\gamma\ge 0$.  
For each fixed norm $\|\cdot\|_{Y_n}$ on $\mathbb{R}^n$; the $\|\cdot\|_{Y_n}$-Lipschitz width of $\mathcal{K}$ is defined\footnote{We denote the  closed unit ball
$
    B_{Y_n}
\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \{y\in\mathbb{R}^n:\|y\|_{Y_n}\le 1\}
$ if a normed space $(\mathbb{R}^n,\|\cdot\|_{Y_n})$.}~
by
\begin{equation}

    d^\gamma(\mathcal K,Y_n)_{\mathcal{X}}
\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \inf_{\Phi}
        \sup_{f\in\mathcal K}
            \inf_{y\in B_{Y_n}}
                \|f-\Phi(y)\|_{\mathcal{X}},
\end{equation}
where the outer infimum in~(equation eq:def_LipWidth of the paper) is taken over all $\gamma$-Lipchitz maps
$
    \Phi:B_{Y_n}\to\mathcal{X}
$.
The $n$-th Lipschitz width of $\mathcal K$ is obtained by further minimizing over all norms $\|\cdot\|_{Y_n}$ on $\mathbb{R}^n$; i.e.\
\begin{equation}

    d^\gamma_n(\mathcal K)_{\mathcal{X}}
\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \inf\big\{
        d^\gamma(\mathcal K,Y_n)_{\mathcal{X}}
    :
    \,
        \|\cdot\|_{Y_n} 
            \text{ a norm on } 
        \mathbb{R}^n
    \big\}
.
\end{equation}

[Lemma 14 of arXiv:2608.06646, 'Three-dimensional stochastic wave equation with non-Lipschitz coefficients'] Let $f(u)=|u|^{-\beta}$ be the Riesz kernel with $0<\beta<3$. For all positive parameters $a,b$ such that $a+b=3-\beta$, the following statements hold.
\begin{enumerate}
    \item For all $u,\xi\in\mathbb{R}^3$ and $h\in\mathbb{R}$,
    \begin{align}
        f(u+h\xi)-f(u)
        =  |h| ^b \int_{\mathbb{R}^3} |u-hw|^{a-3}
        \bigl(|w+\xi|^{\,b-3}-|w|^{\,b-3}\bigr)\,\mathrm{d}w .
    \end{align}

    \item If, in addition, $|\xi|=1$, then
    \begin{align}
        \bigl|f(u+h\xi)+f(u-h\xi)-2f(u)\bigr|
        \le  |h| ^b \int_{\mathbb{R}^3}& |u-hw|^{a-3}\\
        &\notag \times \bigl||w+\xi|^{\,b-3}+|w-\xi|^{\,b-3}-2|w|^{\,b-3}\bigr|\,\mathrm{d}w .
    \end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 1 of arXiv:2609.02173, 'Bounding Selmer Groups of Superelliptic Jacobians via Class Groups'] Assume Hypothesis~\ref{hyp:local}. Then
\[
\begin{aligned}
\dim_{\mathbb F_p}\operatorname{Cl}(L)[p]_{N\equiv0}
-\sum_{v\mid p}
\left(r_v-1-\dim_{\mathbb F_p}W_v\right)
&\leq
\dim_{\mathbb F_p}\operatorname{Sel}_{\Pi}(J/K) \\
&\leq
\dim_{\mathbb F_p}\operatorname{Cl}(L)[p]_{N\equiv0}
+g[K:\mathbb Q(\zeta_p)].
\end{aligned}
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma saddles of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] Assume that $x>0$. Let
$u_k(x)=-W_{k} \left(\!-\frac{1}{ex}\right)$ and
\begin{align}
z_k(x,u)=1+\frac{1}{u}W_{k}(-xue^{-u})\:.
\end{align}
\begin{itemize}
\item[(a)] If $x>1$ and $u>0$ then the function $f(z)$
has two saddles $z_0(x,u)$ and $z_{-1}(x,u)$. These saddles are complex conjugated if $u_0(x)<u<  u_{-1}(x)$, otherwise they are real; furthermore, $z_0(x,u)=z_{-1}(x,u)$ if $u=u_0(x)$ or $u= z_{-1}(x,u)$.
\item[(b)] If $x=1$ then for every $u>0$ the function $f(z)$ has one saddle given by $z_{-1}(1,u)$ if $0<u\le 1$ and by $z_{0}(1,u)$ if $u\ge  1$.
This saddle is real.
\item[(c)]
For every $0<x<1$ and $u>0$ the function $f(z)$ has two saddles $z_0(x,u)$ and $z_{-1}(x,u)$. These saddles are real.
\end{itemize}

