[Proposition prop:siteperc_dom_ZIM of arXiv:2607.29409, 'The Zombie Infection Model'] Let $G=(V,E)$ be a graph of bounded degree.
		Then, for $\lambda\in (0,\infty)$ and $\Delta \Subset V$, there is a
		coupling $\widehat{\BP}$ of $(\eta_{t}) \sim \BP^{\ZIM}_{\lambda,G,\Delta}$,
		$\widetilde{G}_{u}\sim G_{p}^{\siteperc}$ and $\widetilde{G}_{l}\sim G_{q}^{\siteperc}$
		where $p=\lambda/(\lambda+1)$ and $q=p^{\mathrm{deg}(G)}$, such that
		\begin{equation}
			\widehat{\BP}\!\left( {\mathcal{C}}^{\siteperc}_{\Delta}(\widetilde{G}_{l}) \subset {\mathcal{A}}_{\infty}
			\subset {\mathcal{C}}^{\siteperc}_{\Delta}(\widetilde{G}_{u})\cup \partial_{v}^{o}\big({\mathcal{C}}
			^{\siteperc}_{\Delta}(\widetilde{G}_{u}) \big)\right) =1.
		\end{equation}

[Theorem thm:sa-slln of arXiv:2509.10225, 'Phase Transitions for Elephant Random Walks \\ with Two memory Channels'] For $p \neq 7/8$, $\boldsymbol{\Gamma}_n\stackrel{a.s.}{\to} \boldsymbol{\Gamma}^{(p)}$. For $p < 7/8$, $\boldsymbol{\Gamma}^{(p)}$ is degenerate at $\boldsymbol{\gamma}_0 := \begin{pmatrix} {1}/{3} & {1}/{3}\end{pmatrix}^{\top}$. For $p > 7/8$, $\boldsymbol{\Gamma}^{(p)}$ takes the values $\boldsymbol{\gamma}_p$ and $\widebar{\boldsymbol{\gamma}}_p$, where
\begin{align*}
    \boldsymbol{\gamma}_p = \begin{pmatrix}
       \frac{8p^2-10p+3+\sqrt{32p^2-52p+21
   }}{2(2p-1)^2} & \frac{8p^2-10p+3-\sqrt{32p^2-52p+21
   }}{2(2p-1)^2} 
    \end{pmatrix}.
\end{align*}
Further, for $\boldsymbol{\gamma}$ in the support of $\boldsymbol{\Gamma}^{(p)}$, on the event $\left\{\boldsymbol{\Gamma}^{(p)} = \boldsymbol{\gamma}\right\}$, we have 
\begin{align}
    \mathbb{E}\left(\boldsymbol{e}_{n+1}\boldsymbol{e}^{\top}_{n+1} \mid \mathcal{\boldsymbol{G}}_{n}\right) \stackrel{a.s.}{\to} \boldsymbol{\sigma}\left(\boldsymbol{\gamma}\right) := \begin{pmatrix}
      \gamma_1 - \gamma_1^2  & -\gamma_1\gamma_2\\  -\gamma_1\gamma_2 & \gamma_2 - \gamma_2^2
    \end{pmatrix}.
\end{align}

