    \begin{align*}
        \mathbb{E}(\widetilde{\mathcal{G}}_i,\widetilde{\Omega}_p)&=\frac{4}{n}\sum_{j=1}^p \mathbb{E}(\langle \tilde{s}(i),\tilde{s}(j)\rangle,\widetilde{\Omega}_p)\nonumber\\
        &=\frac{4}{n}\sum_{j=1}^p\sum_{t=1}^n \mathbb{E}(\tilde{s}(i)[t]\tilde{s}(j)[t],\widetilde{\Omega}_p)\nonumber\\
