[Proposition 8 (Wasserstein SN approximation of the Wishart law) of arXiv:2606.28678, '2606.28678'] Let $\alpha\in (d-1,\infty)$ and $\Sigma\in \mathcal{S}_{++}^d$. Let $\mathfrak{W}\sim \mathcal{W}_d(\alpha,\Sigma)$, and let $\mathfrak{Z}_{\alpha,\Sigma}$ be defined as in \eqref{eq:Z.alpha.Sigma}. Let $\mu_{\mathfrak{W}}$ and $\mu_{\mathfrak{Z}_{\alpha,\Sigma}}$ denote the laws of $(\mathfrak{W} - \alpha \Sigma)/\sqrt{\alpha}$ and $(\mathfrak{Z}_{\alpha,\Sigma} - \alpha \Sigma)/\sqrt{\alpha}$, respectively, on $\mathcal{S}^d$. Then
\begin{equation}
d_{\mathrm{W}}^{\mathcal{S}}(\mu_{\mathfrak{W}},\mu_{\mathfrak{Z}_{\alpha,\Sigma}}) \leq \frac{1}{\sqrt{\pi \alpha}} \, \|\Sigma^{-1}\|_2 \, \sqrt{\{(d + 2)\tr(\Sigma)^2 + \|\Sigma\|_F^2\} \{\tr(\Sigma)^2 + \|\Sigma\|_F^2\}}.
\end{equation}
The $\alpha^{-1/2}$ rate in the bound (\ref{eq:Wishart.shifted.symmetric.normal.bound}) is optimal. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2608.17562, '2608.17562'] Let $b \in (0, \alpha)$ and $h_{b}(x) = x^{b}$. The derivative of
  the Stein solution $g_{b}$ associated with $h_{b}$
   is infinitely differentiable on $(0,\infty)$ and satisfies:
\begin{align}
g'_{b}(x) = -\int_0^\infty \frac{bx^{b-1}}{(u+1)^{1+{b}/{\alpha}}}e^{-{u}{x^{-\alpha}}}\dif u,\quad x \in \Rp, 
\end{align}
 and we have 
\begin{align}
  x\vert g'_{b}(x) \vert \leq bx^{b}\min
  ( \alpha / b , x^{\alpha}
  ),\quad x \in \Rp.  
\end{align}
Moreover, the second derivative of $g_{b}$ satisfies: 
\begin{align}

    x\vert g''_{b}(x) \vert &\leq bx^{b-1}
    \big(
    \vert b-1 \vert\min(\alpha / b , x^{\alpha}) + \alpha \min(x^{-\alpha}, x^{\alpha})
    \big),\quad x \in \Rp.
\end{align}

