[Definition 4 of arXiv:2605.15781, 'Mean-Field Backward Stochastic Differential Equations with Nonlinear Resistance and Double'] Let $s\in C[0,T]$, $a\in \mathbb{R}$ and $l,r:[0,T]\times \mathbb{R}\rightarrow \mathbb{R}$ be two functions such that $l\leq r$ and $l(T,a)\leq 0\leq r(T,a)$. A pair of functions $(x,K)\in C[0,T]\times BV[0,T]$ is called a solution of the backward Skorokhod problem for $s$ with nonlinear constraints $l,r$ ($(x,K)=\mathbb{BSP}_l^r(s,a)$ for short) if 
\begin{itemize}
\item[(i)] $x_t=a+s_T-s_t+K_T-K_t$;
\item[(ii)] $l(t,x_t)\leq 0\leq r(t,x_t)$, $t\in[0,T]$;
\item[(iii)]  $K$ has the decomposition $K=K^r-K^l$, where $K^r,K^l\in I[0,T]$ satisfy 
\begin{align}
\int_0^T I_{\{l(s,x_s)<0\}}dK^l_s=0, \  \int_0^T I_{\{r(s,x_s)>0\}}dK^r_s=0.
\end{align}
\end{itemize}

[Prop avargecoh of arXiv:2510.23430, 'On the Martin boundary for discrete TASEP'] Let $\nu$ be a Borel probability measure on $\mathcal F$. Then
\begin{equation}
M_n(\lambda)=\int_{\mathcal F} M^\Phi_n(\lambda)\nu(d\Phi)
\end{equation}
defines a coherent system on $\mathbb{G}^p$.

[Theorem 6 (Exact $\MAX_5$ identity) of arXiv:2608.25221, 'Representing MAX functions using two-hidden-layer ReLU networks'] We have the following identity.

\begin{align}
2\MAX_5={}&-\frac25 G_{\mathcal O[P_0]}
+\frac1{15} G_{\mathcal O[P_3]}
-\frac1{40} G_{\mathcal O[P_{69}]}+\frac1{20} G_{\mathcal O[P_{95}]}
-\frac1{30} G_{\mathcal O[P_{97}]}.
\end{align}
\begin{align*}
 P_0&=[11,11\mid 11,11],\\
 P_3&=[11,11\mid 11,23],\\
 P_{69}&=[11,22\mid 34,35],\\
 P_{95}&=[11,23\mid 24,25],\\
 P_{97}&=[11,23\mid 25,34].
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:spectral_absorption of arXiv:2603.24803, 'Critical Spectral Invariants in Random Walks with Geometric Resetting'] For $k \ge 1$ and $z \in \{1,\dots,a-1\}$, the finite-time absorption 
probabilities admit the spectral decompositions
\begin{align}

u_{z,k} &= \sum_{\nu=1}^{a-1} A_\nu(z)\, \lambda_\nu^{\,k}, \\[6pt]

v_{z,k} &= \sum_{\nu=1}^{a-1} B_\nu(z)\, \lambda_\nu^{\,k},
\end{align}
where $v_{z,k} := \mathbb{P}_z(\tau_a = k, \tau_a < \tau_0)$ is the 
probability of success at time $k$, and the spectral coefficients are given by
\vspace{0.3cm}

{\small 
\begin{equation}

A_\nu(z) = \frac{2}{a} \left( \frac{q}{p} \right)^{z/2}
\sin\!\left( \frac{\pi \nu z}{a} \right)
\sin\!\left( \frac{\pi \nu}{a} \right)
\end{equation}
}

{\small
\begin{equation}

B_\nu(z) = \frac{2}{a} \left( \frac{p}{q} \right)^{(a-z)/2}
\sin\!\left( \frac{\pi \nu (a-z)}{a} \right)
\sin\!\left( \frac{\pi \nu}{a} \right)
\end{equation}
}

[Theorem 37 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] For \(T>R\geq e\),
\begin{equation}
  \widehat{\PP}_T(\sigma_T>R)
  \leq C_H(1+\log R)R^{-H}.

\end{equation}
Consequently, under \(\widehat{\PP}_a\), the families \((U_a)_{a>0}\) and
\((V_a)_{a>0}\) are tight, and, as \(a\to\infty\),
\begin{equation}
  a-U_a\longrightarrow\infty
  \quad\text{in probability}.

\end{equation}

