[Lemme 28 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] One has the upper bound

\beq

\mc{I}(\bs{\la}^+_N ; \veps_N)  \, \leq \,  \pl{\vsg = \pm}{} \Big\{  \f{ \mc{S}^{\vsg}   }{ \Delta(\bs{\lambda}_N^{\vsg}) } \Big\}^{\f{1}{2}}

\enq

with $\mc{S}^{\vsg} $ expressed as a combinatorial sum of determinants

\begin{align}

\mc{S}^{\vsg}\overset{\mathrm{def}}{=} \hspace{-5mm}

\sul{ \bs{\sg}_{N-1} \in \{ 0, 1\}^{N-1} }{} | \det_N\big[ \op{M}_{ \bs{\sg}_{\small N-1} }^{\, \vsg} \big]  |

\end{align}

involving the $N\times N$ matrix  $\op{M}_{ \bs{\sg}_{\small N-1} }^{\, \vsg}$ having entries

\beq

\big( \op{M}_{\bs{\sg}_{N-1}}^{\, \vsg}\big)_{ij} \overset{\mathrm{def}}{=} \left\{ \ba{c c c }

\Int{\mathcal{K}_j^{\sigma_j}}{} \frac{\mu - \lambda_{j+\sigma_j}^{\vsg} }{ \mu - \lambda_i^{\vsg} }

\frac{1}{\big\{ (\mu - \lambda_{j+\sigma_j}^+) (\mu - \lambda_{j+\sigma_j}^-) \big\}^{ 1/2 }  } \, \mathrm{d}\mu   & for & j \leq N-1   \vspace{3mm} \\

1 & for & j = N    \ea \right.  \, .

\enq (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 92 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] The following statements are true:
\begin{enumerate}
\item The orbit map operator
\begin{align*}
\Omega : \big( D(A), |\cdot|_{D(A)} \big) \to \big( \scrd_X^{2\alpha}([0,T],W), \| \cdot \|_{X,2\alpha} \big), \quad \xi \mapsto ( u_{\xi}, 0 )
\end{align*}
is a continuous linear operator between seminormed spaces with operator norm bounded by
\begin{align*}
\| \Omega \| \leq M e^{\omega T} T^{1-2 \alpha}.
\end{align*}
\item The orbit map operator
\begin{align*}
\Omega : \big( D(A), |\cdot|_{D(A)} \big) \to \big( \scrd_X^{2\alpha}([0,T],W), \interleave \cdot \interleave_{X,2\alpha} \big), \quad \xi \mapsto ( u_{\xi}, 0 )
\end{align*}
is a continuous linear operator between Banach spaces with operator norm bounded by
\begin{align*}
\| \Omega \| \leq M e^{\omega T} T^{1-2 \alpha} + 1.
\end{align*}
\end{enumerate}

