$\boldsymbol\varepsilon\in\{0,1\}^m$, with the block lengths in
$\mathfrak C_N(r,\rho)$ replaced by $\widetilde K_p$,
\begin{equation*}
  \mathcal A_N(\boldsymbol\varepsilon;
    \boldsymbol k,\boldsymbol\tau)
  =\sum_{r,\rho\geq0}
    \sum_{\Gamma\in\mathfrak C_N(r,\rho)}w_N(\Gamma).
\end{equation*}

[Definition 32 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {Block-Interaction Matrix}

    Let $\nu$ be a probability measure on $\R^n$ with density $\nu(x) \propto \exp(-V(x))$. Let $x, y \in \R^n$ and $z^{(k)}(x,y) := (x_{I_1},..., y_{I_k},..., x_{I_m})\T$. Define the matrix A via its entries for $k, \ell \in [m]$ and $i \in I_k, j \in I_\ell$
    \begin{align*}
        A_{ij}^\rho(x,y)
        = \frac{1}{\sqrt{\rho_k-\rho} \cdot \sqrt{\rho_\ell-\rho}} \cdot 
        \begin{cases}
            \nabla_x^2 V(z^{(k)})_{ij} & \text{if $k \neq \ell$}, \\
            0 & \text{if $k = \ell$}.
        \end{cases}
    \end{align*}

[Definition def:finiteLE of arXiv:2608.05089, 'Correlation decay in area-tilted line ensembles'] For any $\lambda > 0$, let $\mathcal{L}^{\mathbf{x},\mathbf{y},\lambda}_{n,\ell,r}$ denote the probability distribution
on functions $\mathbf{X}_n=(X^1_n,X^2_n,\ldots, X^n_n) : [\ell,r] \to \mathbb{A}_+^n$ defined by the Radon--Nikodym derivative
\begin{equation}
    \frac{d \mathcal{L}^{\mathbf{x},\mathbf{y},\lambda}_{n,\ell,r}}{d \mathcal{B}^{\mathbf{x},\mathbf{y}}_{n,\ell,r}}(\mathbf{X}_n)
    \propto \Exp{-2 \sum_{i=1}^n \lambda^{i-1} \int_\ell^r X^i_n(t) \,dt}
    \ind{\mathbf{X}_n(t) \in \mathbb{A}_+^n \text{ for all } t \in [\ell,r]}.
\end{equation}

