[Theorem 15 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] Assume that the function $\phi$  satisfies \ref{assphi}, and take $u\in \DD(G)$. Then a pointwise solution to \eqref{eq_over}
		is given by $q^+(x,t)=\mathds{E}^{(x,0)}[u(M({D_t}))]$, $t\ge0$ and a pointwise solution to \eqref{eq_under} is $q(x,t) = \mathds{E}^{(x,0)}u(M(H(t-)))$. 
		Furthermore, these solutions are the unique in the class of jointly continuous functions in $E\times [0,+\infty)$ with property $\lim_{t\to +\infty} q(x,t)=0$, for all $x\in E$.

[Theorem 144 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Suppose that
\index{$S$@Miscelenea!$a_{\pm}$@$\hat a$}
\index{$S$@Miscelenea!$\bar b_{R}$@$\hat b$}
\begin{equation}

a^{\shharp}_{\rho_{a}}\leq 
\hat  a,\quad\hat b_{q\beta,p\beta,\rho_{b}}\leq \hat  b.
\end{equation}
 Then for any $u\in E^{1,2}_{q,p,\beta}$ 
and  $\lambda\geq \lambda_{0}\rho_{b}^{-2}$ 
\begin{equation}

\|\lambda u,\sqrt\lambda Du, \partial_{t}u, D^{2}u\|_{  E_{q,p,\beta}}
\leq N _{1}\rho_{b}^{-\alpha}\|f\|_{  E_{q,p,\beta}}, 
\end{equation}
where   
$$
f=\cL  u-\lambda u:=\partial_{t}u+(1/2)a^{ij}D_{ij}u+b^{i}D_{i}u-\lambda u,\quad \alpha=
d+2+\beta-\frac{d}{p}-\frac{2}{q}.
$$
Furthermore, for any
$f\in E_{q,p,\beta}$ and $\lambda\geq\lambda_{0}\rho_{b}^{-2}$ there exists a unique
$u\in E^{1,2}_{q,p,\beta}$ such that in
$\bR^{d+1}$
\begin{equation}

\cL u -\lambda u=-f. 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 16 of arXiv:2606.18877, 'Ergodic Properties of Non-Linear Density-Dependent Perturbations of the Ornstein--Uhlenbec'] Let \(Y_t\) be the Ornstein-Uhlenbeck process defined in~\eqref{OU_a0}. Then, for any \(p\geq 1\), it holds that
        \[
        \left(
        \E_{\PP^{OU}_y}\left[
        \Vert Y_t\Vert_2^p
        \right]
        \right)^{1/p}
        \leq 2^{1-1/p}\left(
        e^{-2a_0 t} 
