[Lem 11 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let \( \Omega \subset \R^n \) be an open convex subset and $\phi\in\text{\rm SCL}\,(\Omega)$. If $x\in\reg(\phi)$, then \( \phi \) is differentiable at \( x \) and there exists an open neighborhood \( V \) of \( x \) and a \( C^\infty \) function
\begin{align*}
	\psi(y)=\phi(x)+D\phi(x)\cdot(y-x)-\frac{C}{2}|y-x|^2,\quad y\in V,
\end{align*}
where $C>0$ is a constant, such that
\begin{align*}
	\psi(y)<\phi(y), \quad \forall y\in V\setminus\{x\}, \quad \text{and} \quad \psi(x) = \phi(x).
\end{align*}

[Lemma 163 (Differential and integral identities involving $\doublenulltoritwoarg{\ubar}{u}$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $f$ be a scalar function,
	and for 
	$Z \in \{\newuL, \newL\}$, let $\mytr_{\gnulltori} \deform{Z}$ be the $\gnulltori$-trace 
	(see Def.\,\ref{D:TRACEOFDOUBLENULLTORITANGENT02TENSORS})
	of the deformation tensor $\deform{Z}$ of $Z$.
	Then the following integral identities hold:
	\begin{subequations}
		\begin{align}
			\nullgeop{\ubar} 
			\left( 
			\int_{\doublenulltoritwoarg{\ubar}{u}} 
			f 
			\, \voldoublenulltori
			\right) 
			& = 
			\ \int_{\doublenulltoritwoarg{\ubar}{u}} 
			\left\lbrace 
			\newL f 
			+ 
			\frac{1}{2} f \mytr_{\gnulltori} \deform{\newL}
			\right\rbrace \, \voldoublenulltori,

			\\
			\nullgeop{u} \left(  \int_{\doublenulltoritwoarg{\ubar}{u}} f \, \voldoublenulltori\right) & =  \int_{\doublenulltoritwoarg{\ubar}{u}} 
			\left\lbrace 
			\newuL f 
			+ 
			\frac{1}{2} f \mytr_{\gtorusroughfirstfund} \deform{\newuL}
			\right\rbrace \, \voldoublenulltori.

		\end{align}
	\end{subequations}

	Moreover, for $u_1 \leq u_2$, we have:
	\begin{align} 
		\int_{\ingoingcharacteristicsurfacetwoarg{\ubar}{[u_1,u_2]}} 
		\left\lbrace
		\newuL f 
		+ 
		\frac{1}{2} f \mytr_{\gnulltori} \deform{\newuL}
		\right\rbrace
		\, \volingoingnullhypersurface
		& =
		\int_{\doublenulltoritwoarg{\ubar}{u_2}} 
		f 
		\, \voldoublenulltori
		-
		\int_{\doublenulltoritwoarg{\ubar}{u_1}} 
		f 
		\, \voldoublenulltori.
	\end{align}

[Lemma 19 of arXiv:2608.18075, '2608.18075'] Set the one block Ramer threshold $d_{\rm Ram}=(2C_q)^{-1}$. For $R>0$, let $h_n$ denote the proposed feedback displacement, defined by $h_n=\Delta_{X_n}(X'_n)$ on $\{(X_n,X'_n)\in\mathscr U_\Delta\}$ and by $h_n=0$ otherwise, and define
\begin{align*}
 \tau_R=\inf\left\{n\ge0:(X_n,X'_n)\notin\mathscr U_\Delta\ \text{or}\ \|h_n\|>d_{\rm Ram}\ \text{or}\ C_{\rm Ram}\sum_{k=0}^n\|h_k\|^2>R\right\}.
\end{align*}
At the $n$-th step, apply $T_{X_n,h_n}$ to the fresh Wiener input of the second component when $n<\tau_R$, and use the unshifted Wiener input when $n\ge\tau_R$. Denote the resulting generalized coupling by $\mathbf Q^R_{x,x'}$. Then the following conclusions hold.
\begin{itemize}
 \item The first marginal of $\mathbf Q^R_{x,x'}$ is $P_{\tau,[\infty]}\delta_x$, while its second marginal $\mathbf Q^{R,2}_{x,x'}$ satisfies
 \begin{align}
  \mathbf Q^{R,2}_{x,x'}\ll P_{\tau,[\infty]}\delta_{x'},\qquad \operatorname{Ent}\bigl(\mathbf Q^{R,2}_{x,x'}\mid P_{\tau,[\infty]}\delta_{x'}\bigr)\le R.
 \end{align}
 Moreover, $(x,x')\mapsto\mathbf Q^R_{x,x'}$ may be chosen Borel.
 \item Define the countable mixture over integer entropy thresholds
 \begin{align}
  \mathbf Q_{x,x'}=\sum_{m=1}^\infty 2^{-m}\mathbf Q^m_{x,x'}.
 \end{align}
 Then $\mathbf Q_{x,x'}$ is a Borel generalized coupling kernel, its first marginal is $P_{\tau,[\infty]}\delta_x$, and its second marginal is absolutely continuous with respect to $P_{\tau,[\infty]}\delta_{x'}$.
 \item For the corresponding unstopped feedback construction, let
 \begin{align*}
  \mathcal E_\infty=\bigcup_{m=1}^\infty\{\tau_m=\infty\}.
 \end{align*}
 be the event that at least one integer entropy threshold is never reached.
 Let $\mathsf D$ be a Borel event of paired sampled state paths. If there is a measurable event $\mathcal E\subset\mathcal E_\infty$ of positive probability for the unstopped construction such that the unstopped paired path belongs to $\mathsf D$ on $\mathcal E$, then $\mathbf Q_{x,x'}(\mathsf D)>0$.
\end{itemize}

