[Theorem 11 (Generalized Theorem 2, Chapter 2, \cite{borkar2008stochastic}) of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] Consider a stochastic approximation process $\{Z_{n}:n\in\mathbb{N}_{0}\}$, given by
\begin{equation}
Z_{n+1}=Z_{n}+\gamma_{n}\left[G(Z_{n})+\Delta M_{n+1}+\delta_{n}\right],
\end{equation}
where each of $Z_{n}$, $\Delta M_{n+1}$ and $\delta_{n}$ is a random variable taking values in $\mathbb{R}^{d}$ for some $d\in\mathbb{N}$, and the following assumptions are satisfied:
\begin{enumerate}[label=(F\arabic*), ref=F\arabic*]
\item  the \emph{drift function} $G:\mathbb{R}^{d}\rightarrow\mathbb{R}^{d}$ is Lipschitz,
\item  the sequence $\{\gamma_{n}\}$ of \emph{step-sizes}, with each $\gamma_{n}$ a positive scalar, satisfies $\sum_{n}\gamma_{n}=\infty$ and $\sum_{n}\gamma_{n}^{2}<\infty$,
\item  the sequence $\{\Delta M_{n}\}$ is a martingale difference sequence with respect to the filtration $\{\mathcal{F}_{n}\}$, where $\mathcal{F}_{n}$ is the $\sigma$-field generated by the stochastic process up to and including epoch $n$, and the sequence $\{\delta_{n}\}$ is adapted to $\{\mathcal{F}_{n}\}$, and the series 
\begin{equation}
\sum_{n\in\mathbb{N}_{0}}\gamma_{n}\left(\Delta M_{n+1}+\delta_{n}\right) \text{ converges almost surely},
\end{equation}
\item  the iterates of \eqref{sa_general} remain bounded almost surely, i.e.\ $\sup_{n}\left|\left|Z_{n}\right|\right|_{2}<\infty$ almost surely.
\end{enumerate}
Then, almost surely, the sequence $\{Z_{n}\}$ converges to a (possibly sample path dependent) compact connected internally chain transitive invariant set corresponding to the ODE: $\dot{x}(t)=G(x(t))$ for $t\geqslant 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma basicquag of arXiv:2608.28505, 'Quagmires and large Suslin forests'] Let $(T, <, \lhd, Q)$ be a $(\kappa, S)$-quagmire. Then the following hold:
\begin{enumerate}[label={\upshape (\arabic*)}]
\item $|T_\kappa| = \kappa^+$ and every element of $[T_{\kappa}]^{\le \kappa}$ has an $\lhd$-upper bound;
\item for every $x \in T$ and every $\alpha < \mathrm{ht}(x)$, the map $Q(\cdot, x) \upharpoonright T_\alpha$ is an order-embedding;
\item for every $(x, y) \in \mathrm{dom}(Q)$ and $\alpha$ with $\mathrm{ht}(x) < \alpha < \mathrm{ht}(y)$, $\pi_\alpha(Q(x, y)) = Q(x, \pi_\alpha(y))$;
\item for every $x, y$ and $\alpha < \beta < \mathrm{ht}(x)$, if $x = Q(\pi_\alpha(x), y)$, then $x = Q(\pi_\beta(x), y)$.
\end{enumerate}

