[Corollary 20 of arXiv:2506.12632, 'Point process convergence of extremes in $K$-symmetric exclusion'] Let $A, B_1, \ldots, B_n \subset \Z$, and suppose that $B \supset \bigcup_{k=1}^n B_k$. Then for any function $h$ on $\Omega_n^K$ with $0 \le h \le 1$ and $h \equiv 1$ on $\Omega_n^1$, 
\begin{align*}
	0 &\le \sum_{\bx \in A^n} U_n^K(\tfrac{t}{K})1_{B_1 \times \cdots \times B_n}(\bx) - \sum_{\bx \in \Omega_n^K \cap A^n} h(\bx) V_n^K(\tfrac{t}{K})1_{B_1 \times \cdots \times B_n}(\bx) \\
	&\le {n \choose 2} \big(\il 1_B, U_1^1(t)1_A \ir \big)^{n-2} ( \kappa_t(B,A) + \tau_t(B,A) ). 
\end{align*}

[Proposition 2 of arXiv:2506.19272, 'Fully lifted \emph{blirp} interpolation -- a large deviation view'] For $k=\{1,2,3\}$ let components of $G\in\mR^{m \times n},u^{(4,k)}\in\mR^1,\u^{(2,k)}\in\mR^{m\times 1}$, and $\h^{(k)}\in\mR^{n\times 1}$ be independent  zero-mean Gaussians. For vectors $\m=[\m_1,\m_2]$, $\p=[\p_0,\p_1,\p_2,\p_3]$ with $\p_0\geq \p_1\geq \p_2\geq \p_3= 0$ and $\q=[\q_0,\q_1,\q_2,\q_3]$ with $\q_0\geq \q_1\geq \q_2\geq \q_3= 0$, let the variances of the elements of $G$, $u^{(4,k)}$, $\u^{(2,k)}$, and $\h^{(k)}$ be $1$, $\p_{k-1}\q_{k-1}-\p_k\q_k$, $\p_{k-1}-\p_{k}$, $\q_{k-1}-\q_{k}$, respectively.
Let sets ${\mathcal X}, \bar{{\mathcal X}}, {\mathcal Y}$, scalars $\beta$, $p$, $s$, and function $f_{\bar{\x}^{(i_3)}}(\cdot)$ be as in Proposition
\ref{thm:thm1}. Set ${\mathcal U}_k=[u^{(4,k)},\u^{(2,k)},\h^{(2k)}]$
 and consider the following
\begin{equation}
\psi(t)  =  \mE_{G,{\mathcal U}_3} \frac{1}{p|s|\sqrt{n}\m_2} \log \lp \mE_{{\mathcal U}_2}\lp\lp  \sum_{i_3=1}^{l}\lp \mE_{{\mathcal U}_1}  Z_{i_3}^{\m_1}\rp^p\rp^{\frac{\m_2}{\m_1}}\rp\rp,
\end{equation}
where
\begin{eqnarray}
Z_{i_3} & \triangleq & \sum_{i_1=1}^{l}\lp\sum_{i_2=1}^{l}e^{\beta D_0^{(i_1,i_2,i_3)}} \rp^{s} \nonumber \\
 D_0^{(i_1,i_2,i_3)} & \triangleq & \sqrt{t}(\y^{(i_2)})^T
 G\x^{(i_1)}+\sqrt{1-t}\|\x^{(i_1)}\|_2 (\y^{(i_2)})^T(\u^{(2,1)}+\u^{(2,2)}+\u^{(2,3)})\nonumber \\
 & & +\sqrt{t}\|\x^{(i_1)}\|_2\|\y^{(i_2)}\|_2(u^{(4,1)}+u^{(4,2)}+u^{(4,3)}) +\sqrt{1-t}\|\y^{(i_2)}\|_2(\h^{(1)}+\h^{(2)}+\h^{(3)})^T\x^{(i_1)} \nonumber \\
 & & + f_{\bar{\x}^{(i_3)}} (\x^{(i_1)}).
 \end{eqnarray}
Then
\begin{eqnarray}
\frac{d\psi(t)}{dt}  & = &        \frac{\mbox{sign}(s)\beta}{2\sqrt{n}} \lp \phi_1^{(2)}+\phi_{21}^{(2)}+\phi_{22}^{(2)}+\phi_3^{(2)} +\phi_{01}^{(2)} +\phi_{02}^{(2)} \rp,
 \end{eqnarray}
where $\phi$'s are as in (\ref{eq:lev2cpt8}) and $\gamma$'s are as defined in (\ref{eq:lev2genAanal19d2}) and (\ref{eq:lev2genAanal19e}).

[Lemma 8 of arXiv:2604.00642, 'Quantitative central limit theorem for an integrated periodogram via the fourth moment the'] Let $0 \leq \gamma < 1$ and $h(\lambda) = |\lambda|^{-\gamma}L(\lambda)$. Then
\begin{align*}
\int |h(\lambda) D_n(\lambda-\mu)| \dd\lambda \leq C_{\eta}n^{\gamma+\eta-1/2}.
\end{align*}

