[Lemma 15 of arXiv:2608.19832, 'Sharp Convex Concentration for Symmetric Random Tensors with Subgaussian Coordinates'] Under the assumptions of \Cref{thm:main},
\begin{equation}
 \Pp\left\{
 \abs{\norm X^2-n}>C_K(\sqrt{nu}+u)
 \right\}
 \le2e^{-c_Ku}
\end{equation}
for every $u\ge1$.

[Lemma 9 (Uniform normalization and tails) of arXiv:2608.24863, 'Uniform Logarithmic Sobolev Inequalities for the 2D Coulomb Gas at the Diffusive Temperatu'] Set $\mathsf A=\prod_j(1+|y_j|)^{a_j}$.  There are $0<c_{\gamma,Q}\le C_{\gamma,Q}<\infty$ such that
\begin{equation}
 c_{\gamma,Q}\mathsf A\le Z\le C_{\gamma,Q}\mathsf A.
\end{equation}
Moreover,
\begin{equation}
 \nu(|z|>R)
 \le C_{\gamma,Q}\int_{|z|>R}e^{-\gamma|z|^2/2}(1+|z|)^Q\,\D z.
\end{equation}
In particular, $\nu(B_{R_{\gamma,Q}})\ge1/2$ for a radius independent of the point configuration.

