body:
[Lemma 8 of arXiv:2608.25164, 'A time-fractional Kalman filter'] Let the process $N(t)$ be defined as in \eqref{4.21}--\eqref{4.3}. Then the following properties hold
\begin{myenumerate}
    \item
    $N$ is a Gaussian process;
    \item
    $\E[N(t)]=0$ for all $t$;
    \item
    $\E[N^2(t)]= \int_0^t D^2(s) ds$;
    \item 
    $\mathcal{L}(N)=\mathcal{L}(Y)$;
    \item
    $N$ has orthogonal, and hence independent, increments;
    \item
    Define
    \begin{align}
        dM(t)&=\frac{1}{D(t)} dN(t)= \frac{1}{D(t)}dY(t) -\frac{G(t)}{D(t)} \widehat{X}(t)dt \nonumber\\
        &=\frac{G(t)}{D(t)} \big[X(t)-\widehat{X}(t)\big]dt + dB_2(t).
    \end{align}
Then, for all $s,s'\geq0$,
\begin{align*}
\E[M(s)M(s')]=\min(s,s').
\end{align*}
 \item 
 $M$ is a Brownian motion.
    \end{myenumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 26 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma >0$, $0 \leq s \leq t \leq T$, $n \in \mathbb{N}_+$ and $ \widehat{b}_n \in \mathbb{R}$. Moreover, let $(F_x)_{x \in \mathbb{Z}}: \Omega \mapsto \mathbb{R}$ be a sequence of mappings such that 
\begin{align}
 \forall x \in \mathbb{Z}, \; \forall s \in [0,T], \; \forall n \in \mathbb{N}_+, \quad & \mathbb{E}_{\nu_{\rho}} \big[ \big\{ F_x(\eta_s^n) \big\}^{2} \big] \leq \frac{C_1}{L^{2}},  \\
 \forall x,y \in \mathbb{Z}: |y-x| \geq 2 K, \; \forall s \in [0,T], \; \forall n \in \mathbb{N}_+, \quad & \mathbb{E}_{\nu_{\rho}} \big[ F_x(\eta_r^n) \; F_y(\eta_r^n) \big]=0. 
\end{align}	
	for some constants $C_1, L>0$ and $K \in \mathbb{N}_+$. Recall the definition of $\| \cdot \|_{2,n}$ in \eqref{L2discnorm}. It holds
	\begin{align*}
\forall n \in \mathbb{N}_+, \quad		\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \widehat{b}_n \int_s^t \dd r \sum_{x}   \nabla H ( \tfrac{ \lfloor x - r v_n \rfloor }{n}  )    F_x(\eta_r^n)  \Bigg\}^{2} \Bigg] \leq 2 C_1 (t-s)^{2} n \frac{(\widehat{b}_n)^2 K}{L^{2}} \| \nabla H \|^{2}_{2,n}.
	\end{align*}

