[Thm Theorem11 of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] For $0 < \varepsilon \leq 1$, let $u$ and $v^\varepsilon$ be the solutions of systems (equation a1 of the paper) and (equation b2 of the paper), respectively. Then, for every $\omega \in \Omega$, $t > 0$,
		\begin{align*}
			\mathop {lim}\limits_{\varepsilon \rightarrow 0} \|v^\varepsilon(t,\omega,{v_0}^\varepsilon)-u(t,u_0)\|_{L^2}^2=0.
		\end{align*}
		\begin{proof}
			Let $y^\varepsilon=v^\varepsilon-u$. Then from (equation a1 of the paper) and (equation b2 of the paper), we find
			\begin{align}
				\frac{dy^\varepsilon(t)}{dt}-\nu \Delta y^\varepsilon(t)=-\frac{1}{z(t,\omega)}B(v^\varepsilon(t))+B(u(t))+(1-z(t,\omega))\rho \nabla \phi+(z(t,\omega)-1)f.
			\end{align}
			Taking the $L^2$ inner product with $y^\varepsilon$ to the equation (equation e1 of the paper), we get
			\begin{align}
				\frac{1}{2}\frac{d}{dt}\|y^\varepsilon\|_{L^2}^2+\nu \|\nabla y^\varepsilon \|_{L^2}^2=&-e^{\varepsilon \omega(t)}b(v^\varepsilon,v^\varepsilon,y^\varepsilon)+b(u,u,y^\varepsilon)+(1-e^{\varepsilon \omega(t)})\langle \rho \nabla \phi,y^\varepsilon\rangle\notag \\&+(e^{\varepsilon \omega(t)}-1)\langle f,y^\varepsilon \rangle.
			\end{align}
			We can rewrite (equation add1 of the paper) as
			\begin{align*}
				\frac{1}{2}\frac{d}{dt}\|y^\varepsilon\|_{L^2}^2+\nu \|\nabla y^\varepsilon \|_{L^2}^2=&-e^{\varepsilon \omega(t)}b(y^\varepsilon,u,y^\varepsilon)+(1-e^{\varepsilon \omega(t)})b(u,u,y^\varepsilon)+(1-e^{\varepsilon \omega(t)})\langle \rho \nabla \phi,y^\varepsilon\rangle\\&+(e^{\varepsilon \omega(t)}-1)\langle f,y^\varepsilon \rangle.
			\end{align*}
			Applying Holder's, Ladyzhenskaya’s and Young's inequalities, we estimate
			\begin{align*}
				|e^{\varepsilon \omega(t)}b(y^\varepsilon,u,y^\varepsilon)| &\leq Ce^{\varepsilon \omega(t)}\| y^\varepsilon\|_{L^2}\|\nabla y^\varepsilon\|_{L^2}\|\nabla u\|_{L^2}\\ &\leq \frac{\nu}{6}\|\nabla y^\varepsilon \|_{L^2}^2+Ce^{2\varepsilon \omega(t)}\| y^\varepsilon\|_{L^2}^2\|\nabla u\|_{L^2}^2,
			\end{align*}
			and
			\begin{align*}
				|(1-e^{\varepsilon \omega(t)})b(u,u,y^\varepsilon)| &\leq C|1-e^{\varepsilon \omega(t)}|\|u\|_{L^4} \|\nabla u\|_{L^2} \|y^\varepsilon\|_{L^4} \\&\leq C|1-e^{\varepsilon \omega(t)}| \|u\|_{L^2}^{\frac{1}{2}} \|\nabla u\|_{L^2}^{\frac{3}{2}} \|y^\varepsilon\|_{L^2}^{\frac{1}{2}} \|\nabla y^\varepsilon \|_{L^2}^{\frac{1}{2}} \\&\leq C\|\nabla v^\varepsilon\|_{L^2}^2\|y^\varepsilon\|_{L^2}^2+C\|\nabla u\|_{L^2}^2\|y^\varepsilon\|_{L^2}^2+C|1-e^{\varepsilon \omega(t)}|^{\frac{4}{3}}\| u\|_{L^2}^{\frac{2}{3}}\|\nabla u \|_{L^2}^2.
			\end{align*}
			Proceeding as above, we also estimate
			\begin{align*}
				|(1-e^{-\varepsilon \omega(t)})\langle \rho \nabla \Phi,y^\varepsilon \rangle| &\leq |1-e^{-\varepsilon \omega(t)}|\|\rho\|_{L^2}\|\nabla \Phi\|_{L^\infty}\|y^\varepsilon\|_{L^2} \\&\leq |1-e^{-\varepsilon \omega(t)}|\|\rho\|_{L^2}\|\rho \|_{L^4}\|y^\varepsilon\|_{L^2} \\&\leq \frac{3}{2\nu}|1-e^{-\varepsilon \omega(t)}|^2\|\rho\|_{L^3}^2 \| \rho\|_{L^2}^2 +\frac{\nu}{6}\|\nabla y^\varepsilon \|_{L^2}^2,
			\end{align*}
			and
			\begin{align*}
				|(e^{-\varepsilon \omega(t)}-1)\langle  f,y^\varepsilon \rangle| &\leq \frac{3}{2\nu}|1-e^{-\varepsilon \omega(t)}|^2\|f\|_{L^2}^2 +\frac{\nu}{6}\|\nabla y^\varepsilon \|_{L^2}^2.
			\end{align*}	
			Summing the above equalities up, we derive that
			\begin{align*}
				\frac{d}{dt} \|y^\varepsilon\|_{L^2}^2 \leq W_1(t) \|y^\varepsilon\|_{L^2}^2+W_2(t),
			\end{align*}
			where 
