[Lemma lem:sep1 of arXiv:2606.02472, 'Correlated uniform attachment trees'] If $\bclr{ T_n^{1}, T_n^{2}}_{n\in \N}$ is distributed according to the measure $0\text{-CUA}$, then for all $\varepsilon>0$ there exist $m,K,\ell \in \N$ such that for all $n \geq m$
    \ba{
        \mathbb{P} \left( \frac{1}{\ell + 1} \sum_{j=0}^{\ell} \frac{1}{2^j K \log(n)} \left( \sum_{x \in A_{2^j K}^{1}(n)} \deg_{T_n^{1}}(x) -  \sum_{x \in A_{2^j K}^{2}(n)} \deg_{T_n^{2}}(x) \right)^2 > 2-0.05 \alpha \right) > 1-\varepsilon .
    } (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 178 (Coerciveness of the spacetime integrals $\spacetimecoercive{q}$ and $\newspacetimecoercive{q}$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $\xi$ be a scalar function or an $\ell_{t,u}$-tangent one form defined on $\characteristicdiamondtwoarg{[\leftubar,\ubarboot)}{[\moreinterestingu_1,u]}$. Then the following estimate holds:
\begin{align} 
	\spacetimecoercive{q}[\xi](\ubar,u) \ge 0.92 \left\| \xi \right\|^2_{L^2_q\left(\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]} \cap \smallneighborhoodofcreasearg{[\leftubar,\ubarboot]}\right)}. 
\end{align}
Next, let $\xi$ be a scalar function or a $\doublenulltoritwoarg{\ubar}{u}$-tangent one form  defined on $\characteristicdiamondtwoarg{[\leftubar,\ubarboot)}{[\moreinterestingu_1,u]}$. Then the following identity holds:
\begin{align}
	\newspacetimecoercive{q}[\xi](\ubar,u)  =  \left\| \xi \right\|^2_{L^2_q\left(\characteristicdiamondtwoarg{[\leftubar,\ubarboot)}{[\moreinterestingu_1,\moreinterestingu_2]}\right)}. 
\end{align}

[Lemma lem:consequenceM of arXiv:2607.22291, 'Rare subtree patterns in size-conditioned Bienaymé trees: Poisson approximation and declum'] Let $(G_k)$ be a sequence of $\{0,1\}$-valued functions on finite plane trees,
and fix a sequence $(k_n)$. Assume that $(G_k)$ satisfies Assumption
(hyp:S of the paper) along $(k_n)$ with respect to a cutoff sequence $(M_{n})$.   Then
\begin{equation}
 \P(|\mathcal T|>M_n/4 \mid G_{k_n}(\mathcal T)=1)\to0 \quad \textrm{and} \quad 
 \mathbb{E}\left[
\frac{\sup_x\Psi_{n-|\mathcal T|}(x)}{\Psi_n(-1)}
\mathbbm{1}_{\{|\mathcal T|>M_n/4\}} \mid G_{k_n}(\mathcal T)=1
\right]\to0.
\end{equation}

[Lemma Lem_FamilyOfSmoothingKernels of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Let
  $\chi \in C_c^\infty(\mathbb{R},[0,1])$ and $\rho \in C_c^\infty(\mathbb{R},[0,1])$ such that
  \begin{equation*}
    \chi|_{[-1,1]} = 1, \quad
    \supp(\chi) \subseteq [-2,2], \quad
    \rho(0) = 1, \quad\text{and}\quad
    \supp(\rho) \subseteq [-1,1].
  \end{equation*}
  Define the \defined{family of smoothing kernels} $\paren{\sigma_\varepsilon : \varepsilon \in (0,1) }$ by 
  \begin{equation*}
    \sigma_\varepsilon(r) \coloneq \mathscr{M}^{-1}(\chi_\varepsilon)(r) \rho(\log(r))
  \end{equation*}
  with $\chi_\varepsilon(\xi) \coloneq \chi(\varepsilon\xi)$.
  The following hold:
  \begin{enumerate}
  \item

    For every $\varepsilon \in (0,1]$, $k \in {\mathbf{N}}_0$, and $\xi \in \mathbb{R}$
    \begin{align}

      \abs{\mathscr{M}(\sigma_\varepsilon)(\xi)}
      &\lesssim_{\rho,k}
        \varepsilon^{-k}\bracket{\xi}^{-k}, \\


      \abs{\mathscr{M}(\sigma_\varepsilon)(\xi)-1}
      &\lesssim_{\rho,k}
        \varepsilon^k\bracket{\xi}^k, \\


      \abs{\varepsilon\partial_\varepsilon \mathscr{M}(\sigma_\varepsilon)(\xi)}
      &\lesssim_{\chi,\rho,k}
        \varepsilon^{-k}\bracket{\xi}^{-k}, \quad\text{and} \\


      \abs{\varepsilon\partial_\varepsilon \mathscr{M}(\sigma_\varepsilon)(\xi)}
      &\lesssim_{\chi,\rho,k}
        \varepsilon^{k}\bracket{\xi}^{k}.
    \end{align}
  \item












    For every $\varepsilon \in (0,1]$, $k \in \mathbb{Z}$, and $\xi \in \mathbb{R}$
    \begin{equation*}
      \abs{\varepsilon^{-1}\mathscr{M}(w_{\log} \sigma_\varepsilon)}
      \lesssim_{\chi,\rho,k}
      \varepsilon^k\bracket{\xi}^k \quad\text{and}\quad
      \abs{\partial_\varepsilon \mathscr{M}(w_{\log} \sigma_\varepsilon)}
      \lesssim_{\chi,\rho,k}
      \varepsilon^k\bracket{\xi}^k.
    \end{equation*}    

  \end{enumerate}

