body:
[Lemma gNtNlmt of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Following hold for ${\sf g}_N$ when $\textbf{a}^{(\emptyset)} =0$.
\begin{enumerate}
\item $\lim_{N\rightarrow \infty} ({\sf g}_N,   \tilde{\sf g}_N) = 0$.
\item For any $r \in [0,\infty]$,  there is a constant $C_n >0$ such that
\begin{align}
	\norm{\nabla^n \tilde{\sf g}_N}_{\ell^{2+r}} \le C_{n} \tilde{g}_N^{1/4} L^{- (n + \frac{d}{4} ) N} L^{-\frac{d r}{2(2 +r)} N} L^{(2-\eta)N} \norm{\nabla^n f}_{L^{\infty}}
\end{align}
uniformly in $N$,  with $\frac{r}{2+r} = 1$ when $r = \infty$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:4.6-site of arXiv:2607.14993, 'Sharp phase transition for percolation with short-range dependencies'] Let $G = (V, E)$ be a finite subgraph of $\mathbb Z^d$ containing $0$. For $n \in \mathbb N:=\{0,1,2,\ldots\}$ and $x \in V$ we denote $L_n(x) = \Lambda_n(x) \cap V$ and $\partial L_n(x) = \partial \Lambda_n(x) \cap V$. Let $\mu$ be an increasing measure on $\{0, 1\}^V$. For all $n \in \mathbb N^*$ we have
  \begin{equation}
    \sum\limits_{x \in V} \mathrm{Cov}(\mathbf 1_{0 \leftrightarrow \partial L_n}, \omega(x)) \geqslant \frac n 2 \mu(0 \leftrightarrow \partial L_n)(1 - \mu(0 \leftrightarrow \partial L_n)) \min\limits_{y \in L_n} \frac {\mu(\omega(y) = 1)} {\sum\limits_{k=0}^{n-1} \mu(y \leftrightarrow \partial L_k(y))}.

  \end{equation}

