[Lem 45 of arXiv:2507.08909, 'Annealed almost periodic entropy'] Suppose that $\phi \in \B(\A,\rmM_k)_+$, and let
\[\psi(a) := (Q^\rm{T})^\ast \phi(a) Q^\rm{T} \qquad (a \in \A)\]
for some $Q \in \rmM_{\ell,k}$.  For any neighbourhood $O$ of $\psi$ there is a neighbourhood $U$ of $\phi$ such that
\begin{equation}
(I_{H_\pi}\otimes Q)[\X(\pi,U)] \subset \X(\pi,O)
\end{equation}
for any representation $\pi$, recalling the notation from~\eqref{eq:pre-lin-maps-Q}. \qed (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] Assume     $\alpha>0$, $u>0$ and  $\re(v)>0$. Then for any   $N=1,2,\dots$,
     \begin{equation}

      \GG_N (\alpha,u,v)= \II_N (\alpha,u,v),
     \end{equation}
where $ \GG_N (\alpha,u,v)$ is given by \eqref{II-1}.

[Lem hk est of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] Fix $x_0\in M$, $r\in(0, 1 \wedge r_*)$, and $s\in(0, 1 \wedge t_*)$.
We then have
\begin{equation}
  \sup_{(x_1, \ldots, x_k) \in M^k}
  \int_{B(x_0,r)}
  \prod_{i=1}^k p^i_s(x_i,y)\,\mu(dy)
  \leq
  \tilde{c}_1\!
  \left(
    s^{-\hat{d}_{\mathrm{s}}^*/2}
    \wedge
    r^{d_{\mathrm{f}}}s^{-\hat{d}_{\mathrm{s}}/2}
  \right).
\end{equation}
Moreover, if we set $c_1 \coloneqq \max_i (2 c_{\mathrm{LE}}^{-1})^{d_{\mathrm{w}}^{(i)}} \vee 1$, then, for all $s \geq c_1 r^{d^{\mathrm{min}}_\mathrm{w}}$,
\begin{equation}
  \inf_{(x_1,\ldots,x_k) \in \hat{B}_*(x_0,r)}
  \int_{B(x_0,r)}
  \prod_{i=1}^k p^i_s(x_i,y)\,\mu(dy)
  \ge
  \tilde{c}_2\, r^{d_{\mathrm{f}}}s^{-\hat{d}_{\mathrm{s}}/2}.
\end{equation}

