body:
[Theorem 22 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] As \ntoo, for every fixed $j\in{\mathbb Z}_{>0}$,
\begin{equation}
\P[Q_n=j]
=\chi_j(a_n)+o(1)
=\chi_j(c_n)+o(1),
\end{equation}
where $a_n$ and $c_n=\{a_n\}$ are given by \eqref{bt}--\eqref{bc}, and
 $\qx_j$ introduced above is  a continuous, $1$-periodic function,   representable  by the
Fourier series
\begin{align}
  \qx_j(u) =
\frac{\bigpar{1-e^{-1}}^j}{j}
\left(1+
\sum_{k\in{\mathbb Z}\setminus\{0\}}
\frac{\gG({j-2\pi \ii k })
\gG(\ell+1-2\pi (e-1)k\ii)}{(j-1)!\ell!}
e^{2\pi \ii k u}\right).
\end{align}

[Lem 7 of arXiv:2604.25964, 'Strong convergence rate of Euler-Maruyama approximations in temporal-spatial H\"older-norm'] For $s\in [0, T],$ $t, \widetilde{t} \in [s, T],$ $ \delta \in \widetilde{\mathbb{S}}$ and $ x\in \bR,$ let $(X^{\delta,x}_{s,t})_{t\in[s,T]}:[s,T]  \times\Omega\to\mathbb{R} $ 
be an $(\mf_t)_{t\in[s,T]}$-adapted stochastic process with c\`adl\`ag  sample paths satisfying equation \eqref{y01}. 

Then, 
\begin{enumerate}
   \item [\textup{(i)}] we have
\begin{align*}
\mathbb{E}\left[V(X^{\delta, x}_{s,t})\right] \leq e^{2.5 \overline{c}|t-s|}V(x).
\end{align*} 

\item [\textup{(ii)}] for all $p\ge 2,$ there exists a positive constant $C_p=C_p(T, m_2, m_p)$ such that \begin{align*}
\left[\mathbb{E}\left[\left|X^{\delta, x}_{s,\widetilde{t}}-X^{\delta, x}_{s,t}\right|^p\right]\right]^{1/p} 
 \leq C_p |\widetilde{t} -t|^{1/p} (e^{2.5\overline{c}T}V(x))^{1/p}.
\end{align*} 
\end{enumerate}
Here, the constant $\overline{c}$ is given in {\bf A3, A4, A5}.

