[Definition netsandlevels of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] In this definition we always refer to $D=(D_1,D_2,D_3)$ as the collection of three disjoint intervals $D_1,D_2,D_3\subset[n]$ of cardinality $c_0^2n/12$ each, and we also use $D$ to denote the union $D=D_1\cup D_2\cup D_3$.
Fix two constants $\epsilon,\epsilon_1>0$. We define the following sets, threshold functions and discrete approximations:
\begin{enumerate}
    \item 
Subsets indicating the value of $v$ and $r$ on $D$:
$$\begin{aligned}\mathcal{I}(D):=&\{(v,r)\in \mathbb{S}^{n-1}\times\mathbb{S}^{n-1}:\langle v,r\rangle=0,\\&(\kappa_0+\kappa_0/2)n^{-1/2}\leq |v_i|,|r_j|\leq(\kappa_1-\kappa_0/2)n^{-1/2},\forall i\in D_1,\forall j\in D_2,\\&|v_i|,|r_i|\leq \sqrt{\frac{96}{c_0^2n}},\forall i\in D_1\cup D_2\cup D_3,\quad |\sin(v_D,r_D)|\geq c_{\rho,\delta}^2c_0^2/64 \}.\end{aligned}$$

$$\begin{aligned}\mathcal{I}'(D):=&\{(v,r)\in \mathbb{R}^{n+n}:\quad |\langle v,r\rangle|\leq \frac{1}{10},\\&\kappa_0n^{-1/2}\leq |v_i|,|r_j|\leq \kappa_1n^{-1/2},\forall i\in D_1,\forall j\in D_2\\&|v_i|,|r_i|\leq \sqrt{\frac{100}{c_0^2n}}\forall i\in D_1\cup D_2\cup D_3,\quad |\sin(v_D,r_D)|\geq c_{\rho,\delta}^2c_0^2/128 \}.\end{aligned}$$

\item For fixed $D$ and constants $0<\epsilon\leq\epsilon_1$, and any $c\in\mathbb{R}$ define the following sets
$$\begin{aligned}
\mathcal{P}_{\epsilon_1}(c)&:=\{(v,w)\in\mathbb{R}^n\times\mathbb{R}^n:\|v\|_2=1,\frac{9}{10}\leq\|w\|_2\leq\frac{11}{10},\exists r\in\mathbb{S}^{n-1}\text{ such that }\\&w=cv+\epsilon_1r,\quad (v,r)\in\mathcal{I}(D)
\},\end{aligned}$$  
$$\begin{aligned}\mathcal{P}^0_\epsilon(c)&:=\{(v,w)\in\mathbb{R}^{n}\times\mathbb{R}^{n}:\|v\|_2=1,\frac{9}{10}\leq\|w\|_2\leq\frac{11}{10},\exists r\in\mathbb{S}^{n-1},\exists t\in\mathbb{R},|t|\leq\epsilon\\&\text{such that }w=cv+tr,\quad (v,r)\in\mathcal{I}(D)\}.\end{aligned}$$

\item Discrete approximation of $\mathcal{P}_{\epsilon_1}$ and for $\mathcal{P}_\epsilon^0$ at scale $\epsilon:$ when $\epsilon_1\geq \epsilon$,
$$\begin{aligned}
\Lambda_{\epsilon,\epsilon_1}(c):=&\{
(v,w)\in B_n(0,2)\times B_n(0,2): v\in 4\epsilon n^{-1/2}\cdot\mathbb{Z}^n,\\&\text{ there exists } r\in B_n(0,2)\cap \frac{4\epsilon}{ \epsilon_1}n^{-1/2}\cdot\mathbb{Z}^n\text { such that }
w=cv+\epsilon_1r,\\&(v,r)\in \mathcal{I}'(D).\end{aligned}
$$

$$
\Lambda_\epsilon^0:=\{(v,v)\in B_n(0,2)\times B_n(0,2):v\in 4\epsilon n^{-1/2}\cdot\mathbb{Z}^n,v\in\mathcal{I}'(D)\}
$$(For a single vector $v$, we use $v\in \mathcal{I}'(D)$ to mean that $v$ satisfies all the conditions in $\mathcal{I}'(D)$ imposed on $v$, ignoring all the restrictions imposed on $r$.)

In the case when $D=[d]=[c_0^2n/4]$, we further make the following definitions:
\item Threshold: given $L>0$, $\epsilon_1>0$, for $(v,w)\in\mathcal{P}_{\epsilon_1}$(c) or $(v,w)\in{\Lambda_{\epsilon,\epsilon_1}}(c)$ define
\begin{equation}
\tau_{L,\epsilon_1}(v,w):=\sup\{t\in[0,1]:\mathbb{P}(\|(M_nv,M_nw)\|_2\leq t\sqrt{n})\geq(4L^2t^2/\epsilon_1)^{n}\},
\end{equation}
and for $(v,w)\in\mathcal{P}_{\epsilon}^0(c)$ or $(v,w)\in \Lambda_\epsilon^0$, define
$$
\tau_{L,0}(v,w):=\sup\{t\in[0,1]:\mathbb{P}(\|(M_nv,M_nw)\|_2\leq t\sqrt{n})\geq(4L_0^2t)^{n}\}.
$$ where we take \begin{equation}L_0={L}\cdot {\min(\kappa_0/8,c_{\rho,\delta}^4c_0^42^{-22})}.\end{equation}
\item $\mathcal{P}_{\epsilon_1}(c)$ and $\mathcal{P}_\epsilon^0(c)$ stratified by threshold function: we define, for any $\epsilon\leq\epsilon_1$, 
$$
\Sigma_{\epsilon,\epsilon_1}(c):=\{(v,w)\in\mathcal{P}_{\epsilon_1}(c):\tau_{L,\epsilon_1}(v,w)\in [\epsilon,2\epsilon]\},
$$
$$
\Sigma_{\epsilon,0}(c):=\{(v,w)\in\mathcal{P}_\epsilon^0(c)
:\tau_{L,0}(v,w)\in [\epsilon,2\epsilon]\}.$$
\item  Nets: for fixed $\epsilon_1\geq\epsilon$ we define the following nets: 
\begin{equation}\begin{aligned}
\mathcal{N}_{\epsilon,\epsilon_1}(c)&:=\{(v,w)\in\Lambda_{\epsilon,\epsilon_1}(c):(\frac{L^2\epsilon^2}{\epsilon_1})^{
n}\leq \mathbb{P}(\|(M_nv,M_nw)\|_2\leq 4\epsilon\sqrt{n}),\\&\mathcal{L}_{A,op}(v,w,\epsilon\sqrt{n})\leq (2^{18}\frac{L^2\epsilon^2}{\epsilon_1})^{
n}

[Thm of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] Under the neutrality condition $\int \boldsymbol{\sigma}^{+}+ \int \boldsymbol{\sigma}^{-}=-2$, the value of the differential $C_{\mathbb{D}}\left[\boldsymbol{\sigma}^{+}, \boldsymbol{\sigma}^{-}\right]$ in the identity chart of $\mathbb{D}$ is given by
\begin{equation}
C_{\mathbb{D}}\left[\boldsymbol{\sigma}^{+}, \boldsymbol{\sigma}^{-}\right]=\prod_{j<k}\left(z_j-z_k\right)^{2\sigma_j^{+} \sigma_k^{+}}\left(\bar{z}_j-\bar{z}_k\right)^{2\sigma_j^{-} \sigma_k^{-}} \prod_{j, k}\left(1-z_j \bar{z}_k\right)^{2\sigma_j^{+} \sigma_k^{-}} ,
\end{equation}
where the product is taken over finite $z_j$ and $z_k$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:gf-existence of arXiv:2603.28161, 'Boundary four-point connectivities of conformal loop ensembles'] {fakhry2023}}]
For $x_1,...,x_n\in\mathbbm{R}$, the limit
\begin{equation}
\widehat{G}(x_1,...,x_n):=\lim_{r_i\to0}\prod_{i=1}^nr_i^{-h}\cdot\mathbbm{P}[\eta\cap B(x_i,r_i)\neq\emptyset,1\le i\le n]
\end{equation}
exists and is continuous of $x_1,...,x_n$. Furthermore, the convergence is uniform on compact sets. (Proof in the paper; no proof environment follows the statement in the TeX.)

