[Proposition prop:kronecker-coordinate-formula of arXiv:2608.29719, 'Persistence Pairing Graphs: Tracking Changes of Selected Homology Bases'] For every $u\in\mathcal D_t^{(q)}$ and $v\in\mathcal S_t^{(q)}$, the transition coefficient $w_{uv}$ satisfies
\begin{equation}

w_{uv} = \left\langle\alpha_v^t, (i_t)_*[z_u]_{t^-}\right\rangle_t = \left\langle i_t^*\alpha_v^t, [z_u]_{t^-} \right\rangle_{t^-}.
\end{equation}

[Corollary cor:Dn-renewal-results of arXiv:2608.18320, 'Asymptotics for Beta-Splitting Trees via Homogeneous Fragmentations and Meromorphic Potent'] For every $\beta>-2$, as $n\to\infty$,
    \begin{equation}
            \mathsf E D_n\sim\frac{\log n}{\mu_\beta},
            \qquad\text{and}\qquad
            \frac{D_n-\mu_\beta^{-1}\log n}
            {\sqrt{\tau_\beta^2\mu_\beta^{-3}\log n}}
            \xrightarrow{d}\mathcal N(0,1).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] Under the preceding assumptions and notation, as \(\delta\downarrow0\),
\begin{equation}
 \sup_{\substack{\mathbf x,\mathbf y\in[-A,A]^m\\
                   -M\delta^H\leq z\leq0}}
 \left|
  \log\frac{g_{\delta,z}^T(\mathbf y)}
            {g_{\delta,z}^T(\mathbf x)}
 \right|\longrightarrow0

\end{equation}
uniformly in the choices of the finite grids and their cardinalities.
Moreover,
\begin{equation}
 \sup_{\substack{\mathbf x,\mathbf y\in[-A,A]^m\\
                  |z|,|z'|\leq M\delta^H}}
 \left|
  \log\frac{j_T(\mathbf y,z)j_T(\mathbf x,z')}
            {j_T(\mathbf x,z)j_T(\mathbf y,z')}
 \right|\longrightarrow0

\end{equation}
with the same uniformity.

