[Theorem 11 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] Let $(p,q)$ be a Strichartz pair. We have
\begin{equation}
\|S_t^\sharp v_0\|_{L^p([0,1],W^{\gamma,q}(\IR^d))}\lesssim\|v_0\|_{L_\mu^2\cap H^{\frac{d}{2p}+\kappa+\gamma}}
\end{equation}
for any $\gamma\in[0,2-\frac{d}{2p})$ and $\mu\in(\gamma,1)$ with $\kappa>0$ small enough. For the initial flow, we get
\begin{equation}
\|S_t v_0\|_{L^p([0,1],W^{\gamma,q}(\IR^d))}\lesssim\|v_0\|_{L_\mu^2\cap H^{\frac{d}{2p}+\kappa+\gamma}}
\end{equation}
for any $\frac{d}{2p}+\gamma<3-\frac{d}{2}$ and $\mu\in(\gamma,1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop fD-L of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] An orthogonal basis of ${\mathcal V}_n\big({\mathbb R}_\Sigma^d, {\bm W}_{\boldsymbol{\kappa}}^\Sigma\big)$ is given by 
\begin{equation} 
  \hat {\bm L}_{{\bm j},m}^{\boldsymbol{\kappa}}({\bm y}) := 
      {\bm L}_{{\bm j},m}^{\boldsymbol{\kappa}} (y_1,\ldots, y_{d-1}, |{\bm y}|), \qquad |{\bm j}|= n.
\end{equation}
Moreover, the polynomials in ${\mathcal V}_n\big({\mathbb R}_\Sigma^d, {\bm W}_{\boldsymbol{\kappa}}^\Sigma\big)$ are eigenfunctions of ${\mathfrak D}_{\boldsymbol{\kappa}}^\Sigma$ defined by
\begin{align}
{\mathfrak D}_{\boldsymbol{\kappa}}^\Sigma = \sum_{i=1}^d \left(y_i \partial_i^2 + ({\kappa}_i + 1 - y_i) \partial_i \right)  \,& + 2|{\bm y}| \partial_{y_d}^2   - 2 {\langle} {\bm y}, \nabla_{\bm y} {\rangle} \partial_{y_d}\\
  & - (|{\boldsymbol{\kappa}}|-{\kappa}_d +d-1) \partial_{y_d},\notag
\end{align} 
and the eigen equation is given by 
\begin{equation}
   {\mathfrak D}_{\boldsymbol{\kappa}}^\Sigma \, u = - n u, \qquad \forall u \in {\mathcal V}_n\big({\mathbb R}_\Sigma^d, {\bm W}_{\boldsymbol{\kappa}}^\Sigma\big). 
\end{equation}

[Lemma lem:initial-moments of arXiv:2412.01015, 'Classical beta ensembles and related eigenvalues processes at high temperature and the Mar'] Assume that the sequence of limiting moments $\{a_n\}$ satisfies the condition~(equation Gaussian-Carleman-initial of the paper). Then for any $T > 0$, there is a constant $K > 0$ such that 
\begin{equation}
	|m_n(t)| \le (K n)^n, \quad \text{for all $t \in  [0, T]$, and for all $n \ge 0$}.
\end{equation}

