[Definition of arXiv:2608.15923, 'Universality of two-dimensional Markovian holonomy fields'] A \emph{curve} in a topological map ${\mathbb{G}}=(V,E,F)$ is either a single vertex, or a concatenation $e_1\ldots e_k$ of edges $e_1,\ldots,e_k\in E$, where $\overline{e_i}=\underline{e_{i+1}}$ for all $i$. Given a curve $\gamma$, we define its starting point $\underline{\gamma}$ and endpoint $\overline{\gamma}$ as follows:
\begin{enumerate}
\item If $\gamma=v$ is a vertex, then $\underline{\gamma}=\overline{\gamma}=v$.
\item If $\gamma=e_1\ldots e_k$, then $\underline{\gamma}=\underline{e_1}$ and $\overline{\gamma}=\overline{e_k}$.
\end{enumerate}

[Lem 13 (\cite{IM2017}) of arXiv:2609.03869, '\bf Sharp asymptotics for a transport model with a nonlocal condition of the Fisher-KPP ty'] Assume that the Laplace transform $\widetilde f(\lambda)$  of a function $f(t)$ has an isolated pole at $\lambda_0$, with the Laurent series around $\lambda_0$:
	\begin{equation*}
		\widetilde f(\lambda)=\sum_{n=-m}^{+\infty}c_n(\lambda-\lambda_0)^n,~~~~~\lambda\in\mathbb{C}.
	\end{equation*} 
	Also assume  the existence of $\boldsymbol{\delta}< \textnormal{Re}\lambda_0$ such that  $\lambda_0$ is the only  pole of $\widetilde{f}(\lambda)$ with  $\textnormal{Re}\lambda>\boldsymbol{\delta}$ and such that 
	\begin{equation}
		\lim_{|\lambda|\to+\infty, \boldsymbol{\delta}<\textnormal{Re}\lambda}\widetilde f(\lambda)=0,~~~~	\int_{-\infty}^{+\infty} |\widetilde f(\boldsymbol{\delta}+\mathbf{i} y)|\md y<+\infty,
	\end{equation}
	then, 
	\begin{align}
		f(t)&=e^{\lambda_0 t}\sum_{n=1}^mc_{-n}\frac{t^{n-1}}{(n-1)!}+\frac{1}{2\pi \mathbf{i}}\int_{\boldsymbol{\delta}-\mathbf{i}\infty}^{\boldsymbol{\delta}+\mathbf{i}\infty}e^{\lambda t}\widetilde f(\lambda)\md \lambda,~~~~~t>0.
	\end{align}

[Corollary 9 of arXiv:2604.12334, 'On additive averaging kernels for finite Markov chains'] For any $\pi$-reversible $P$, $S \neq \mathcal{X}, \emptyset$ and $\mathcal{X} = S \sqcup S'$, we have that for any fixed $\alpha \in (0,1),$ the non-trivial set $S \subset \mathcal{X}$ that minimises $\| A_\alpha(S) - \Pi\|_{F, \pi}^2$ maximises the function 
     \begin{equation} 
         g(S) = g(S,P) := \frac{1}{\pi(S) \pi(S')} \sum_{\substack{x \in S \\ y \in S'}} \pi(x) P(x,y).
     \end{equation}

     The other direction holds as well. Concretely, we have that 
     \begin{align*}
         \argmin_{S \neq \mathcal{X}, \emptyset} \|A_\alpha(S) - \Pi\|_{F, \pi}^2 &= \argmax_{S \neq \mathcal{X}, \emptyset} g(S),\\
         \argmax_{S \neq \mathcal{X}, \emptyset} \|A_\alpha(S) - \Pi\|_{F, \pi}^2 &= \argmin_{S \neq \mathcal{X}, \emptyset} g(S).
     \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition distribution_prop of arXiv:2412.07258, 'Permuton limit of a generalization of the Mallows and $k$-card-minimum models'] Let $\sigma_n \sim \mathrm{PERM}(g,n)$.
For every $\pi \in S_n$ we have
\begin{align}
    \mathbb{P}(\sigma_n = \pi) =
    \prod_{i=1}^{n} \frac{g\left(V_{\pi}\left( \frac{i-1}{n}, \frac{\pi(i)-1}{n}  \right)  \right) - g\left( V_{\pi}\left( \frac{i-1}{n}, \frac{\pi(i)-1}{n}  \right) +\frac{1}{n} \right)}{g(\frac{i-1}{n})}.
\end{align}

