body:
[Lemma 19 (The transition block) of arXiv:2608.20101, '\bfseries Largest bulk gap of the complex Ginibre ensemble'] Let
\begin{align*}
 \mathcal A={}&\int_{-\infty}^0\log\!\left(\frac{\erfc y}{2}\right)\dd y+\int_0^\infty\left[\log\!\left(\frac{\erfc y}{2}\right)
 +y^2+\log y+\log(2\sqrt\pi)\right]\dd y.
\end{align*}
Uniformly for \(t\in I\),
\begin{equation}
 S_0=E_1N^2+E_2N\log N+E_3N+E_4\sqrt N+E_5\log N+E_6
       +O_I(N^{-1/12}),
\end{equation}
where
\begin{align*}
 E_1={}&\frac{t^4}{4(1+\epsilon)^2}
       \bigl(2\epsilon-\epsilon^2-2\log(1+\epsilon)\bigr), \qquad E_2=-\frac{t^2\epsilon}{2(1+\epsilon)},\\
 E_3={}&\frac{t^2}{1+\epsilon}\left[
 (1+\epsilon-\vartheta)\log(1+\epsilon)
 +\epsilon\vartheta-\epsilon\log(\epsilon t\sqrt{2\pi})\right], \qquad
 E_4=\sqrt2\,t\mathcal A=a_1t,\\
 E_5={}&\frac{2\vartheta-1}{4}, \qquad  E_6=\frac{1-6\vartheta^2}{12}\log(1+\epsilon)+\frac1\epsilon
 +\frac{2\vartheta-1}{2}\log(\epsilon t\sqrt{2\pi})-2J_--2J_+.
\end{align*}

[Lemma log bound for some integral: lemma of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] Let $B \subset \mathbb{D} $ and $\alpha \in \mathbb{C}$. Then there exists an absolute constant $C>0$, such that 
\begin{align}
        \bigintsss_B \frac{1}{|w-\alpha|^2} dA(w) \leq C  \log \left(\frac{\sup_{w\in B}|w-\alpha|}{\inf_{w \in B}|w-\alpha|}\right).
    \end{align}

