[Prop prop5.4 of arXiv:2411.14766, 'Axis-Driven Random Walks on $\Z^2$ \\ (transient cases)'] Assume $0<\alpha<\nicefrac{1}{2}$, for any $z$ and large $i$
   \begin{align} 
  \mathbb{E}_{z}(\overline{Z}_{\rho_{i-1}}) +2 (\mathbb{E}_{z}(\overline{Z}_{\rho_{i-1}}))^{\alpha}+ {\mathbf{c}} -a_{i-1} \leq \mathbb{E}_{z}(\overline{Z}_{\rho_{i}})  \leq \mathbb{E}_{z}(\overline{Z}_{\rho_{i-1}}) +2(\mathbb{E}_{z}(\overline{Z}_{\rho_{i-1}}))^{\alpha}+ {\mathbf{c}},

   \end{align}
