[Corollary e:induction_eq2 of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] The quantity $V_m(F_1, j \vert F_2)$ satisfies the recurrence equation
			\begin{equation}
				\nabla \cdot ({\mathbf{a}}^{F_1} \nabla V_m(F_1,j \vert F_2)) = -\nabla \cdot \mathbf{W}_m(F_1,j \vert F_2) \quad \text{in } \mathrm{int}({\scaleobj{1}{\square}}_m),
			\end{equation}
			where 
			\begin{align}

				&\mathbf{W}_m(F_1,j \vert F_2) \\
				\nonumber &:= \sum_{e\in (E_d({\scaleobj{1}{\square}}_m) \setminus F_2) \setminus F_1}({\mathbf{a}}^{e}-\mathbf{a})\Big(\nabla V_m(F_1,j-1 \vert F_2) - \nabla V_m(F_1\cup \{e\}, j-2 \vert F_2) \\
				\nonumber & \qquad  + \nabla V_m(F_1\cup \{e\}, j-1\vert F_2)\Big) \\
				\nonumber &\qquad +\sum_{e\in F_1}({\mathbf{a}}^{e}-\mathbf{a})\Big(\nabla V_m(F_1\setminus\{e\},j \vert F_2)-\nabla V_m(F_1,j-1\vert F_2)\Big).
			\end{align}

