[Lemma lem-Galerkin_estimates of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] The processes $({u}_{n} {)}_{n \in \mathbb{N} }$ from Lemma (lem-Galerkin_existence of the paper) satisfy the following conditions. 
\begin{trivlist} 
\item[(i)] There exists a positive constant ${C}_{2}>0$ 
\begin{align}
  &   \mathbb{E} \left[ \int_{0}^{T} \normb{ {u}_{n} (s)}{V}{2} \, \mathrm{d}s \right] \le {C}_{2},\;\; \mbox{ for every } n \in \mathbb{N},
  .
\end{align}
\item[(ii)] There exists a positive constant ${C}_{1}$  such that every    $p\in [1,4+\gamma]$ 
\begin{equation} 
  \mathbb{E} \left[ \sup_{0 \le s \le T } \normb{{u}_{n} (s) }{H}{p} \right] \le {C}_{1}^{\frac{p}{4+\gamma}}
 ,\;\; \mbox{ for every } n \in \mathbb{N}.
\end{equation}
\end{trivlist} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:enough_unpaired_o_2_fresh of arXiv:2607.16911, 'Multipartite random graphs with given degrees: local limit, revisiting the giant, distance'] With the same function $g(\epsilon)$ as appearing in Proposition (prop:enough_unpaired_o_1_fresh of the paper), we have
    \begin{align*}
        \lim_{\epsilon \to 0}\liminf_{n \to \infty}\CProb{\tau'(o_2,\epsilon)<\sqrt{\epsilon n},|D_{\overleftarrow{c}}(o_2,\tau'(o_2,\epsilon))|>g(\epsilon)\sqrt{n}}{\mathcal F(o_1)}=1.
    \end{align*}

[Proposition prpcgcp of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] Let $X_1$, $X_2$, $\dots$ be independent and identically distributed (iid) random variables, such that, $X_1\overset{d}{=}M(1)$. Then,
\begin{equation*}
\hat{M}(t)\overset{d}{=}\sum_{n=1}^{M_0(t)}X_n,\ t\ge0.
\end{equation*}

