[Proposition 17 (Off-diagonal heat kernel bound {\cite[Theorem~1.12) of arXiv:2604.21143, 'Quantitative homogenization for the critical long-range random conductance model'] {ChenKumagaiWang2019}}]

		Let $\lambda \in (0,1]$, let $\a = \{\a(x,y)\}$ be symmetric conductances on $\Zd$ satisfying $\lambda \le \a(x,y) \le \lambda^{-1}$, and let $p_t(x,y)$ denote the associated transition kernel.
		Then there exists $C = C(d,\lambda) < \infty$ such that for every $t > 0$ and every $x \ne y$ in $\Zd$,
		\begin{equation}

			p_t(x,y) \le C\left(\frac{1}{\bigl(1 + t\log(2{+}t)\bigr)^{d/2}} \wedge \frac{t\log(2{+}|x-y|)}{|x-y|^{d+2}}\right)\,.
		\end{equation}

[Theorem 28 of arXiv:2607.28614, 'Tampered Memory Elephant Random Walk on one-dimensional integer lattice'] Let $\theta^*$ be an equilibrium point for the mean field function $h$, that is, $\theta^* \in \{\theta: \, h(\theta)=0\}$, where $h$ is as in \eqref{Eq: recursion_general_SA}. Let $\theta_n$, $\Delta M_n$, and $r_n$ be as in \eqref{Eq: recursion_general_SA}, and $\theta_n \longrightarrow \theta^*, \text{ a.s.}$ as $n \to \infty$. Let $\delta>0$ be such that,
\begin{equation}
    \sup_{n \ge 1}\E \left[\lvert \lvert \Delta M_{n+1}\rvert \rvert ^{2+\delta} | \ \FF_{n}\right]< \infty, \text{ a.s.}
\end{equation}
Furthermore, as $n \to \infty$
\begin{equation}
\E \left[ \Delta M_n \left( \Delta M_n \right)^\top | \ \FF_{n}\right] \longrightarrow \Gamma, \text{ a.s.}
\end{equation}
where $\Gamma$ is a deterministic symmetric positive semi-definite matrix and for any $\epsilon>0$, 
\begin{equation}

(n+1)\E\left[\lvert \lvert r_{n+1} \rvert \rvert ^2 \mathbf{1}_{\{\lvert \lvert \theta_n - \theta^*\rvert \rvert \le \epsilon\}} \right] \longrightarrow 0.
\end{equation}
Let us assume that the eigenvalues of $D(-h(\theta^*))$ are all real and positive. Let $\rho^{*}$ be the smallest eigenvalue. If $\rho^{*} >1/2$, then as $n \to \infty$ 
\begin{equation}

\sqrt{n}\left(\theta_n - \theta^*\right)\stackrel{d}{\longrightarrow} N(0, \Sigma),
\end{equation}
where the variance-covariance matrix $\Sigma$ is given by 
\begin{equation}

\Sigma = \int_{0}^{\infty}{\left(e^{-(D(-h(\theta^*)-\frac{1}{2}I_d) u}\right)^\top \Gamma e^{-(D(-h(\theta^*)-\frac{1}{2}I_d) u} \mathrm{d}u},
\end{equation}
where $I_d$ denotes the $d$-dimensional identity matrix. (Proof in the paper; no proof environment follows the statement in the TeX.)

