[Lemma heat of arXiv:2411.15881, 'Stable Approximation for Call Function Via Stein's method'] Let the random variable $Y\sim S_\alpha(1,\delta)$ and denote the density function of $Y$ by $p_{1,\delta}$. Then for any $y\in(-\infty,\infty)$, we have
\begin{align}
p_{1,\delta}(y)\leq\eta_{1,\alpha,\delta}\min\left\{1,\frac{1}{y^{2}}\right\},\qquad
\left|p_{1,\delta}'(y)\right|\leq\frac{\eta_{2,\alpha,\delta}}{{\rm Beta}\left(\frac{2}{\alpha},1-\frac{1}{\alpha}\right)}\min\left\{1,\frac{1}{y^{2}}\right\}.
\end{align}
where $\eta_{1,\alpha,\delta}$ and $\eta_{2,\alpha,\delta}$ are defined by (equation eta1 of the paper) and (equation eta2 of the paper), respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:grafting of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Given $\underline{\tau}_1, \underline{\tau}_2\in \boldsymbol{\mathfrak{T}}$, we define, for any $n \in N(\underline{\tau}_1)$ a new labelled tree $\underline{\tau}_2 \graft_{n} \underline{\tau}_1 \in \boldsymbol{\mathfrak{T}}$ which will be constructed by ``grafting the tree $\underline{\tau}_2$ onto $\underline{\tau}_1$ at the node $n$''. More precisely, we set 
\begin{equs}  
r(\underline{\tau}_2 \graft_{n} \underline{\tau}_1 )\eqdef r(\underline{\tau}_1)\,,\; 
\enskip 
N(\underline{\tau}_2 \graft_{n} \underline{\tau}_1 ) \eqdef N(\underline{\tau}_1) \cup {N}\big(\underline{\tau}_2+ \ell_{\underline{\tau}_1,\underline{\tau}_2} \big)\,,
\end{equs}
and
\begin{equs}   
{E}(\underline{\tau}_2 \graft_{n} \underline{\tau}_1) \eqdef E(\underline{\tau}_1) \cup E\big(\underline{\tau}_2+ \ell_{\underline{\tau}_1,\underline{\tau}_2} \big) \cup \big\{\{{r}\big(\underline{\tau}_2+ \ell_{\underline{\tau}_1,\underline{\tau}_2} 
 \big),n\}\big\}\,.
\end{equs}

[Theorem 5 (Statistical guarantees for the Gibbs posterior) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] Under \cref{ass:design,ass:linear-loss,ass:stationarity,ass:prior}, the exact Gibbs posterior satisfies
    \begin{equation}
    \E\sbr{\W^2(\Pi_t,\delta_{\theta^\star})}\lesssim t^{-1}
    \end{equation}
and
    \begin{equation}
    \fR\del[1]{(\Pi_t)_{t=0}^{T-1}}
    \lesssim \log T+1.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem5 of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] Let $(v^\varepsilon,\sigma,\rho)$ be a solution of system (equation b2 of the paper). Let $v^\varepsilon(t_0)$ $\in$  $H^1$ and $c_i(t_0) \in {L}^{2}$. Then,
		\begin{align}
			\|\sigma\|_{L^2}^{2}\ + \|\rho\|_{L^2}^{2}\ \leq (\|\sigma(t_0)\|_{L^2}^{2}\ + \|\rho(t_0)\|_{L^2}^{2})e^{2D(t_0-t)},~t \geq t_0.
		\end{align}
		\begin{proof}
	We recall $\sigma$  and $\rho$ obey
			\begin{equation}
				\left\{
				\begin{aligned} 
					\partial_{t}\sigma+z^{-1}(v^\varepsilon\cdot\nabla \sigma)=D\Delta \sigma +D\nabla\cdot(\rho\nabla \Phi) \\
					\partial_{t}\rho+z^{-1}(v^\varepsilon\cdot\nabla \rho)=D\Delta \rho +D\nabla\cdot(\sigma\nabla \Phi) \\
				\end{aligned}
				\right.
			\end{equation}
			Taking the ${L}^{2}$ inner product of the first equation in (equation d2 of the paper) with $\sigma$ and of the second equation with $\rho$, we add them and have
			\begin{align*}
				\frac{1}{2}\frac{d}{dt}( \|\sigma\|_{L^2}^{2}\ + \|\rho\|_{L^2}^{2}\ ) =-D (\|\nabla\sigma\|_{L^2}^{2}\ + \|\nabla\rho\|_{L^2}^{2}\ )+ \int \rho\Delta \Phi\sigma.
			\end{align*}
			In view of the fourth equation in (equation b2 of the paper), we know that
			\begin{align*}
				\int \rho\Delta \Phi\sigma=-\frac{1}{\varepsilon_0} \int {\rho}^2\sigma,
			\end{align*}
			where $\sigma > 0$. Then, we get
			\begin{align}
				\frac{d}{dt}( \|\sigma\|_{L^2}^{2}\ + \|\rho\|_{L^2}^{2}\ ) +2D(\|\nabla\rho\|_{L^2}^{2} + \|\nabla\sigma\|_{L^2}^{2}) \leq 0.
			\end{align}
			Thanks to Lemma (lem1 of the paper), we obtain (equation d1 of the paper).
		\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma rbound of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Fix any {\small$\mathrm{D}=\mathrm{O}(1)$} and {\small$\T>0$} independent of {\small$N$}. With high probability, we have 

