body:
[Proposition 49 of arXiv:2609.03875, 'Measure theory without infinities'] Let $\mathbb K$ be an algebraic ring and $\mf A$ be both an HCLM$_{\mathbb{K}}$ and a left $\mathbb K$-module.
  \begin{enumerate}
  \item[(i)]  Let $\mu$ be an $\mf A$-valued measure. If $k\in\mathbb K$ is invertible, then $k\boxdot \mu = k\cdot\mu$.
  \item[(ii)] If $k,l\in\mathbb K$ and $\mu$ is an $\mf A$-valued premeasure, then $(kl)\boxdot\mu=k\boxdot(l\boxdot\mu)$ and $(k+l)\boxdot\mu = (k\boxdot\mu)\boxplus(l\boxdot\mu)$.
  \end{enumerate}

[Proposition Bramson-psi-estimate-for-one-sided-f of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] For a function $f$ of type (equation Form of f of the paper) and $\phi(x) = 1-e^{-f(-x)}$, let $u_{\phi}$ be the solution to the F-KPP equation with initial condition $\phi$. Define for $z\in \mathbb R$ and $t>r>0$,
\begin{equation}
\psi(r,t,z+\sqrt 2t):=\frac{e^{-\sqrt 2z}}{\sqrt{2\pi(t-r)}}\int_0^\infty u_{\phi}(r,y+\sqrt 2r)e^{\sqrt 2y}e^{-\frac{(y-z)^2}{2(t-r)}}\{1-e^{-2y\frac{z+\frac{3}{2\sqrt 2}\log t}{t-r}}\}dy.
\end{equation}
Then, for all $r$ large enough (depending only on the initial condition $\phi$), $t\geq 8r$ and $z \geq 8r-\frac{3}{2\sqrt 2}\log t$,
\begin{equation}
\gamma_r^{-1} \psi(r,t,z+\sqrt 2t) \le u_{\phi}(t,z+\sqrt 2 t) \le \gamma_r \psi(r,t,z+\sqrt 2t),
\end{equation}
where $\gamma_r \downarrow 1$ as $r\to \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:contour_random_narrow_exc_pos of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $\mu=\mu_n$ such that $1/\sqrt{n}\ll\mu\ll n$.
    Then for any $\epsilon>0$, there exists $\delta>0$ such that, for any sequence of events $(A_n)_{n\geq1}$, we have
    \begin{align*}
        \limsup_{n\rightarrow\infty}\frac{1}{(\mu^2n)^{1/3}}\log\left(\frac{\Prob{\mathbf T_n\in A_n,\left|\frac{h(\mathbf T_n)}{(2\pi^2n/\mu)^{1/3}}-1\right|\leq\delta}}{\CProb{\mathbb T_n\in A_n}{\left|\frac{h(\mathbb T_n)}{(2\pi^2n/\mu)^{1/3}}-1\right|\leq\delta}}\right)\leq\epsilon\,.
    \end{align*}

