\begin{equation}
 \begin{aligned}
 &\left\langle
 (-\Delta)^s_pu-(-\Delta)^s_pu_\lambda,
 \varphi_\varepsilon
 \right\rangle\\
 &\quad\ge
 b_*\int_{A_{\lambda,\varepsilon}\cap B_R
 \cap\{\lambda-x_1\ge\rho\}}
 \varphi_\varepsilon\,dx\\
 &\qquad+
 2c_q\int_{A_{\lambda,\varepsilon}\cap\{|x|\ge R\}}
 u^{q-1}\psi
 \varphi_\varepsilon\,dx+2c_q\int_{A_{\lambda,\varepsilon}\cap B_R
       \cap\{\lambda-x_1<\rho\}}
 u^{q-1}\psi
 \varphi_\varepsilon\,dx.
\end{aligned}
\end{equation}

