[Lemma lem:resolvent of arXiv:2608.30888, 'Three-term asymptotics for discrete\\ Hardy--Rellich constants in high dimension'] Fix $C>0$ and assume $|z-\Lambda_N|\leq C N^{\ell-1}$.  For all sufficiently
large $N$, the operators represented by the compressed forms satisfy
\begin{align}
 Q_1(K_{\ell,N}-z)Q_1
 &\geq c_\ell N^\ell Q_1,\\
 Z_3(K_{\ell,N}-z)Z_3
 &\geq c'_\ell N^\ell Z_3.
\end{align}
Moreover, on $P_{11}\mathcal H_{0,N}$,
\begin{equation}
 P_{11}\bigl(Q_1(K_{\ell,N}-z)Q_1\bigr)^{-1}P_{11}
 =\frac{P_{11}}{(2^\ell-1)\Lambda_N}
 +O_\ell(N^{-\ell-1})
\end{equation}
in operator norm.

[Prop Prop_SmoothingOperators of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] There is a family of smoothing operators $\paren{S_\varepsilon : \varepsilon \in (0,1) }$ on $L^2\Gamma\paren{NZ{\backslash} Z, \mathring S \otimes \mathring{\mathfrak l}}$ such that
  for every
  $\varepsilon \in (0,1)$, \ 
  $\phi \in L^2\Gamma\paren{U{\backslash} Z, \mathring S \otimes \mathring{\mathfrak l}}$, and
  $k,\ell \in {\mathbf{N}}_0$ with $k \geqslant \ell$,
  \begin{align}

    \Abs{S_\varepsilon\phi}_{\mathring K^k}
    &\lesssim_{k,\ell}
      \varepsilon^{-k+\ell}
      \Abs{\phi}_{\mathring K^\ell}, \\


    \Abs{(S_\varepsilon-\mathbf{1})\phi}_{\mathring K^\ell}
    &\lesssim_{k,\ell}
      \varepsilon^{k-\ell}
      \Abs{\phi}_{\mathring K^k}, \\


    \varepsilon\Abs{\partial_\varepsilon S_\varepsilon\phi}_{\mathring K^k}
    &\lesssim_{k,\ell}
      \varepsilon^{-k+\ell} \Abs{\phi}_{\mathring K^\ell}, \quad\text{and} \\


    \varepsilon\Abs{\partial_\varepsilon S_\varepsilon\phi}_{\mathring K^\ell}
    &\lesssim_{k,\ell}
      \varepsilon^{k-\ell} \Abs{\phi}_{\mathring K^k}.
  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: bound_int_t-harmonic_by_distance of arXiv:2609.00257, 'Stability estimates for the initial-to-final-state inverse problem'] Let $n\geq2$ and $V_1, V_2\in L^1(\mathbb{R}^n)\cap L^\infty(\mathbb{R}^n)$ with $\|V_j\|_{w_\delta} < \infty$, for $j\in \{1, 2\}$. Let also $\psi_1\equiv \psi_\lambda^{V_1}$ and $\psi_2 \equiv \psi_\lambda^{V_2}$ be the time-harmonic solutions (equation eq: time-harmonic solutions of the paper) to the Schr\"odinger equation, as constructed in subsection (sec: stationary states of the paper) for potentials $V_1$ and $V_2$ respectively. Then, there holds

\begin{equation}
\Big| \int_\Sigma (V_1-V_2) \psi_1 \overline{\psi_2} \Big| \leq T \mathrm{dist}_\delta (\mathcal{U}_T^1, \mathcal{U}_T^2) \|\psi_1\|_{C_TL^2_{-\delta}} \| \psi_2\|_{C_TL^2_{-\delta}}. 
\end{equation}

[Theorem 3 of arXiv:2603.25452, 'New approach to optimal control of delayed stochastic Volterra integral equations'] \textbf{(Representation Theorem for advanced BSVIEs)}\\
	Assume that the generator $\phi: [0, T]^2\times\mathbb{R}\times\mathbb{R}\to \mathbb{R}$ such that $\phi(.,s.,.)$ is $(\mathcal{F}_s)_{s\geq 0}$-adapted. Suppose that there is the couple of process $(p(t), q(t, .))$ solution of  the backward stochastic Volterra integral equation (BSVIE) 
\begin{eqnarray*}
	p(t) = \Phi(t) + \int_t^T \phi(t, s, p(s+\delta), q(t, s))ds 
		- \int_t^T q(t, s)dB(s), \quad t \in [0, T].	
\end{eqnarray*}  
Then, for all $0\leq t<s\leq T$, we have 
\begin{eqnarray}
q(t, s) = \mathbb{E}\left[ D_s p(t) \mid \mathcal{F}_s \right].
\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:usefuldecomp of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $l,m,n \in \mathbb{N}\cup \{0\}$ with $l > n \geq 0$ and $m \geq 1$. Let $P \in \mathcal{L}(\pi)$ and $Q_i \in \mathcal{I}(\pi) \cap \mathcal{L}$ for $i \in \llbracket 0,m-1 \rrbracket$ be a sequence of isometric involution transition matrices. Define $R_n$ as in (equation eq:Rndef of the paper). 
	\begin{itemize}
		\item For $E \in \mathcal{E}$, we have
		\begin{align*}
			D^\pi_{KL}(R_n \| E) 
			&= \sum_{j=n}^{l-1} D^\pi_{KL}(R_j \| R_{j+1}) + D^\pi_{KL}(R_{l} \| E).
		\end{align*}

		\item For $E \in \mathcal{E}$, we have
		\begin{align*}
			\left\lVertR_n - E\right\rVert_F^2 
			&= \sum_{j=n}^{l-1} \norm{R_j - R_{j+1}}_F^2 + \norm{R_{l} - E}_F^2.
		\end{align*}

		\item  We have
		\begin{align*}
			R_\infty(Q_0,\ldots,Q_{m-1},P) = R_\infty(Q_0,\ldots,Q_{m-1},R_l).
		\end{align*}

		\item(Projection is trace-preserving)
		\begin{align*}
			\mathrm{Tr}(R_n) = \mathrm{Tr}(P).
		\end{align*}
	\end{itemize}

