[Definition 4 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] We say that $(u,F)$ is a weak solution to the Vlasov(--Fokker--Planck)--Navier--Stokes system \eqref{eq:PDE} if
\begin{align*}
&  u \in L^\infty([0,T];L^2(\T^d)^d) \cap L^2([0,T];H^1(\T^d)^d),\\
& \dive u_{t} =0  \quad \text{for a.e. } (t,x)\in(0,T)\times\T^d,\\
& F(t,x ,v )\geq0,\quad \text{for a.e. } (t,x ,v)\in(0,T)\times\T^d\times\R^d, \\
& F\in L^\infty([0,T];L^\infty(\T^d\times\R^d)\cap L^1(\T^d\times\R^d)), \\
& |v |^2F \in L^\infty([0,T]; L^1(\T^d\times\R^d)) ;
\end{align*}
and $(u,F)$ satisfy, for all $\phi\in \mathcal{C}^\infty([0,T]\times\mathbb{T}^d\times\mathbb{R}^d)$ with compact support in $v $ and with $\phi(T,\cdot,\cdot)=0$,

\begin{align*}
-\int^T_0 &\int_{\mathbb{R}^d}\int_{\mathbb{T}^d} \bigl[\partial_s\phi+v \cdot\nabla_x \phi+(u-v )\cdot\nabla_v \phi - \frac{\sigma^2}{2} \Delta_v \phi \bigr] F \dd x \dd v \dd s
 =\int_{\mathbb{R}^d}\int_{\mathbb{T}^d} \phi(0,x ,v) F^\circ \dd x \dd v ;
\end{align*}

and for all $\psi\in \mathcal{C}^\infty([0,T]\times\mathbb{T}^d;\R^d)$ with $\nabla \cdot \psi =0 $ and $ \psi(T,\cdot) =0$,
\begin{equation}

\begin{split}
 - \int_0^T\int_{\mathbb{T}^d} u \cdot \partial_s \psi \dd x \dd s
 & +\int_0^T\int_{\mathbb{T}^d} \big((u \cdot \nabla) \psi \cdot u \big) \dd x \dd s +\int_0^T \int_{\mathbb{T}^d}  u \cdot \Delta \psi \dd x \dd s \\
& =-\int_0^T\int_{\mathbb{R}^d}\int_{\mathbb{T}^d} (u-v) F \cdot \psi \dd x \dd v \dd s + \int_{\T^d} u^\circ \psi(0,x)  \dd x.
\end{split}
\end{equation}

[Thm EL_intro of arXiv:2506.12171, 'The multinomial dimer model'] The limit shape flow $\omega$ for $(R,b)$ is the solution to the following system of differential equations:
    \begin{itemize}
        \item the divergence equation, 
        \begin{align*}
            \text{div}(\omega(x)) = \sum_{i=1}^d \pd{\omega_i}{x_i}(x) = 0;
        \end{align*}
        \item a collection of ${d\choose 2}$ equations:
        \begin{align}
            \pd{}{x_i} \pd{}{s_j}\sigma(\omega(x)) - \pd{}{x_j}\pd{}{s_i}\sigma(\omega(x)) =0 
        \end{align}
        for all $i\neq j$ between $1$ and $d$.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Qjbound of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] [FSmap] 

For $(V_j, K_j) \in \mathbb{D}_j (\alpha)$ ($\alpha \le 1$),  we have
\begin{align}
	\norm{Q_j }_{\cL_j (\ell)} \le O_L (1) \tilde{\chi}_j^{3/2} \tilde{g}_j^3 r_j^{{\ka}}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2606.03973, 'A remark on the \\ majorizing measures theorem for general processes'] For any $\pi \in \AllMeasures{T}$, it holds that 
    \begin{equation}

    \sqrt{\klconst(\mu)}
    \int_0^\infty
    \frac{\varepsilon_\mu(\sigma,\pi)^2}{\sigma^2}
    \, \ud \sigma \geq
    \frac{1}{4} \, 
    \int_0^\infty \sqrt{i_\pi(r)} \, \ud r.
    \end{equation}
    Consequently,
     $\sqrt{\klconst(\mu)} \, \BayesOpt{\mu}{T} \gtrsim \LiuFunctional{T}$.

