[Definition 11 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Fix $h\in Z\hat C(\Delta_T^3;B_\alpha)$ and set $h^\tau:=\Theta_\tau h$. A compatible frozen increment family over $h$ is a family $r=(r^\tau)_{\tau\in[0,T]}$
such that
\begin{enumerate}
\item for every $\tau\in[0,T]$, $r^\tau\in C(\Delta_\tau^2;B_\alpha)$;

\item the map $ \mathfrak D_T^3\to B_\alpha, \, (\tau,t,s)\mapsto r^\tau_{ts}$ is continuous;

\item for every $\tau\in[0,T]$, $\delta r^\tau = h^\tau$;

\item for all $0\le s\le t\le \tau'\le \tau\le T$, $r^\tau_{ts}=S_{\tau-\tau'}r^{\tau'}_{ts}$.
\end{enumerate}

[Lemma lem:entropy:symmetry of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $\nu \in \mathcal{M}_{2, d}$ is absolutely continuous with respect to Lebesgue measure. Let $\psi_\nu^n$ be defined as in (equation eq:entropy:2reconstruction of the paper). Then $\psi_\nu^n$ is a 2-MRF on $(\ensuremath{\mathbb{R}}^d)^{V_n}$, and can be formulated equivalently in the following ways:
\begin{equation}
       \psi_\nu^n\big(\mathbf{x}^{(n)}\big) =
\begin{dcases}
    \nu(x_{-1}, x_{0}, x_{1}) \prod_{v =1} ^{n-1} \nu(x_{v+1} | x_v, x_{v-1})\nu(x_{-v-1}|x_{-v}, x_{-v+1}) , & \\
    \nu(x_{n-2}, x_{n-1}, x_{n}) \prod_{v = -n}^{n-3} \nu(x_v|x_{v+1}, x_{v+2}),  & \\
    \nu(x_{-n}, x_{-n+1}, x_{-n+2}) \prod_{v = -n+3}^{n} \nu(x_{v}|x_{v-1}, x_{v-2}). &
\end{dcases}

\end{equation}
Moreover, we have
        \begin{equation}
        \int_{(\ensuremath{\mathbb{R}}^d)^{ \mathbb{T}_2^n}}  f(x_{v-1}, x_v, x_{v+1}) \psi_\nu^{n}(\mathbf{x}^{(n)})d\mathbf{x}^{(n)} = \int_{(\ensuremath{\mathbb{R}}^d)^3} f(\mathbf{x}) \nu(\mathbf{x}) d\mathbf{x}. 

    \end{equation}
    for all $f \in L^1(\nu)$ and $v \in \{-n+1, \ldots, n-1\}$.

[Proposition 10 (Newton inversion) of arXiv:2608.29585, '2608.29585'] Every sequence $f_r\in L$ has a unique expansion
\eqref{eq:abstract-newton-expansion}.  Its coefficients satisfy
\begin{equation}
 h_k=
 \frac{f_k-\sum_{j=0}^{k-1}p_j(x_k)h_j}{p_k(x_k)}
\end{equation}
and
\begin{equation}
 h_k=\sum_{j=0}^{k}\frac{f_j}{D_{k,j}},
 \qquad
 D_{k,j}=\prod_{\substack{0\le i\le k\\i\ne j}}(x_j-x_i).
\end{equation}
For $k\ge1$, put
\begin{equation}
 \Delta_k(f)=\det
 \begin{pmatrix}
 1&x_0&\cdots&x_0^{k-1}&f_0\\
 1&x_1&\cdots&x_1^{k-1}&f_1\\
 \vdots&\vdots&&\vdots&\vdots\\
 1&x_k&\cdots&x_k^{k-1}&f_k
 \end{pmatrix},
 \qquad \Delta_0(f)=f_0,
\end{equation}
and
\begin{equation}
 V_k=\prod_{0\le i<j\le k}(x_j-x_i),
 \qquad V_0=1.
\end{equation}
Then
\begin{equation}
 h_k=\frac{\Delta_k(f)}{V_k}.
\end{equation}

[Corollary prop:exponential-decay of arXiv:2505.02685, 'On the Spectral Expansion of Monotone Subsets of the Hypercube'] Let $f \in L^2(V)$. Then the function $t \mapsto \mathcal{E}^-(P_t f)$ satisfies, for all $t \ge 0$, 
    \begin{equation}

        \odv*{\mathcal{E}^-(P_t f)}{t} \le -2\lambda^-(G)\cdot \mathcal{E}^-(P_t f) \,.
    \end{equation}
    Furthermore, $\lambda^-(G)$ is the largest constant for which
    (equation eq:directed-spectral-gap-decay of the paper) holds for all $f, t$.

