[Lemma lem:Q-A of arXiv:2608.05262, 'The law of $(1+1)$D SOS with an area tilt in a wedge'] We have the identity
 \begin{equation}

\mathbb Q_{\mathfrak h}(\Phi \mid A)= \widecheck \mathbb Q_{\mathfrak h}(\Phi \mid \Gamma)\,,\end{equation}
with the event
\begin{equation}

\Gamma=\{\underline{y}^{(+)}=\underline{y}^{(-)}+\underline{y}^{(o)}\}\,,
\end{equation}
where the $\mathbb Z_+^K$-valued $\underline{y}^{(\pm)} \subset \Phi^\pm$ and the $\mathbb Z^K$-valued $\underline{y}^{(o)}\subset \Phi^o$ are given by 
\begin{align} 

y^{(o)}_r&:=
\widecheck{\phi}_r^o(a_r^+-\Delta)-\widecheck{\phi}^o_r(a_r^-+\Delta),\nonumber\\
y^{(+)}_r&:= \widetilde{\phi}_r(a_r^+-\Delta)\,, \quad 
y^{(-)}_r:=\widetilde{\phi}_r(a_r^-+\Delta)\,, \quad 1 \le r \le K\,. 
\end{align}
\iffalse
That is, for any $\Phi$ satisfying (eq:w-y-pm of the paper) we have that 
\begin{equation}
\mathbb Q_{\mathfrak h}(\Phi \mid A) = \frac{1}{\Gamma} \mathbb Q^I_{\mathfrak h}(\Phi) \quad 
\hbox{where} \quad 
\Gamma := \mathbb Q_{\mathfrak h}^I(\underline{w}=\underline{y}^{(+)}-\underline{y}^{(-)})\,.
\end{equation}
\fi

[Lemma lem:factor-2nd of arXiv:2506.06559, 'Bi-infinite incipient cluster in high dimensions'] For any $\{u_0,v_0\} \not\in E_W$ and $u_1 \in \mathbb{Z}^d$ we have
\eqnspl{e:factor-event}
{ &\widetilde{E}(F;u_0,v_0,x';\omega_0) \cap E'(v_0,u_1,\widetilde{\mathcal{C}}_0;\omega_1) 
   = E''(F;u_0,v_0,u_1,x';\omega_0,\omega_1) \cup \\
   &\qquad \bigcup_{(u'_0,v'_0) : \{u'_0,v'_0\} \not\in E_W \cup \{u_0,v_0\}}
    \Big( \hat{E}''(F;u_0,v_0,u_1,u'_0,v'_0;\omega_0,\omega_1) \cap \big\{ \text{$\{u'_0,v'_0\}$ $\omega_0$-occupied} \big\} \\
   &\qquad\qquad\qquad\qquad\qquad 
   \cap \left\{ \text{$v'_0 \longleftrightarrow_{\omega_0} x'$ in $\mathbb{Z}^d \setminus (\widetilde{\mathcal{D}}_0 \cup \widetilde{\mathcal{C}}(\widetilde{\mathcal{B}}_1))$} \right\} \Big), }
where $\widetilde{\mathcal{C}}_0 = \widetilde{\mathcal{C}}_0(W;u_0,v_0;\omega_0)$, $\widetilde{\mathcal{D}}_0 = \widetilde{\mathcal{D}}_0(W;u_0,v_0,u'_0,v'_0;\omega_0)$ and the union on the right hand side is disjoint. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_loop_measure_crossing of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For $d\ge 3$, there exist $C,c>0$ such that for $N\ge 1$ and $A\subset \widetilde{B}(cN)$, 
	\begin{equation}
			\widetilde{\mu}\big(\{\widetilde{\ell}: \kappa(\widetilde{\ell}; \partial B(N), A)\ge 1 \} \big) \gtrsim N^{2-d} \mathrm{cap}(A), 
	\end{equation}
	\begin{equation}
		\widetilde{\mu}\big(\{\widetilde{\ell}: \kappa(\widetilde{\ell}; \partial B(N), A)\ge j \} \big)\le \big[ CN^{2-d} \mathrm{cap}(A)\big]^{j}, \ \ \forall j\in \mathbb{N}^+.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 42 (Hypercontractivity of the Ornstein--Uhlenbeck semigroup) of arXiv:2605.14630, '2605.14630'] For $p>1$ and $t>0$, let 
\begin{equation}

 q(t) = \e^{2t}(p-1) + 1 > p\;.
\end{equation} 
Then for any $F\in L^p(\Omega,\cF,\fP)$, one has 
\begin{equation}

 \norm{T_tF}_{q(t)} \leqs \norm{F}_p\;.
\end{equation}

