[Lemma 38 (Changing path for directions $\alpha_0 \in [0,\alpha^*_+)$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Suppose $x^* \in (0, \M)$. Let $x^* < x_c < \M$. Then, for $a \in \R$, $b > 0$, and $z_0 \in \R^2$ with $(a,b) \neq z_0$, we have:
\begin{equation}
    I_1^{z_0}(a,b)  = res_{x=x^*}\phi^{z_0}(x)\frac{\gamma(x^*,Y^+(x^*),Z^+(x^*))}{\partial_y\gamma_+(x^*,Y^+(x^*))}e^{-ax^*-bY^+(x^*)}. 
\end{equation}
$$+\,\frac{1}{2i\pi}\int_{x_c + i\R}\frac{\phi^{z_0}(x)\gamma(x,Y^+(x),Z^+(x))e^{-ax-bY^+(x)}}{\partial_y\gamma_+(x,Y^+(x))} dx$$
where $\gamma(x^*,Y^+(x^*),Z^+(x^*)) \neq 0.$
Furthermore,
\begin{equation}
I_2^{z_0}(a,b) = \frac{1}{2i\pi}\int_{x_c + i\R}\frac{e^{(a_0-a)x}\left(
e^{(b_0-b)Y^+(x)}\fc_{b_0>0} 
+ e^{b_0Z^+(x) - bY^+(x)}\fc_{b_0 < 0}
\right)}{\partial_y\gamma_+(x,Y^+(x))} dx \quad \textnormal{if}\; b > b_0
\end{equation}

 and
\begin{equation}
I_2^{z_0}(a,b) = \frac{1}{2i\pi}\int_{Y^+(x_c) + i\R}\frac{e^{(a_0-a)X^+(y) + (b_0-b)y}}{\partial_x\gamma_+(X^+(y),y)} dy \quad \textnormal{if}\; a > a_0.
\end{equation}

[Definition def:well_posed of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] We say that MKV$({\bf b},{\boldsymbol\sigma})$ is:
\begin{itemize}
\item[-] \emph{\textcolor{black}{weakly} well-posed}, if there exists a unique (\textcolor{black}{in law}) solution to MKV$({\bf b},{\boldsymbol\sigma};\textcolor{black}{\nu})$ for any $\nu\in \mathcal{P}(\mathbb{R}^d)$;
\item[-] \emph{\textcolor{black}{pathwise} well-posed}, if there exists an (\emph{almost surely}) unique solution to MKV$({\bf b},{\boldsymbol\sigma};\textcolor{black}{\xi, W, (\mathcal{F}_t)_t})$ for any $(W, (\mathcal{F}_t)_t )$ Brownian motion  and any \textcolor{black}{$\xi\in m\mathcal{F}_0$}. \vspace{-8pt}
\end{itemize}

[Proposition 9 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] In the setting of Example~\ref{ex:a representative SIS epidemic model} let~\eqref{a.1} and $\eta_{0} = \frac{1}{2}$ be valid. Further, suppose that either
\begin{equation*}
c_{1,2} = c_{2,1} = c_{2,2} = g_{1,1} = 0
\end{equation*}
or both~\eqref{a.2} and one of the following four scenarios hold:
\begin{enumerate}[(i)]
\item $\frac{1}{2}(g_{1,2}^{2} + g_{2,1}^{2}) \geq \beta + \beta_{1}^{+} + (2c_{1,2} + c_{2,1})N  + c_{2,2}N^{2}$ and $g_{1,1}g_{1,2}\geq 0$.

\item $-\frac{3}{2}g_{1,1}g_{1,2} \geq 4(c_{1,2} + c_{2,1} + c_{2,2}N + \frac{1}{2}g_{1,1}^{2})\sqrt{N}$.

\item $\frac{1}{2}(g_{1,2}^{2} + g_{2,1}^{2}) \leq \beta - \beta_{1}^{-} -(\frac{3}{2}g_{1,1}g_{1,2} + (c_{2,1} + g_{1,1}^{2})\sqrt{N} + c_{2,2}N^{\frac{3}{2}})\sqrt{N}$.

\item If $g_{1,1} > 0$, then
\begin{align*}
\frac{1}{2}(g_{1,2}^{2} + g_{2,1}^{2}) &\geq \beta + \beta_{1}^{+} + (2c_{1,2} + c_{2,1})N + c_{2,2}N^{2}\\
&\quad + \frac{1}{2}\bigg(\frac{3}{4}\bigg)^{2}\frac{g_{1,1}^{2}g_{1,2}^{2}}{\frac{1}{2}g_{1,1}^{2} + c_{1,2} + c_{2,1} + c_{2,2}N}.
\end{align*}
\end{enumerate}
 If there are $u_{1},u_{2},u_{3}\in\R$ satisfying~\eqref{eq:extinction in the epidemic models 4},
\begin{equation}
\liminf_{t\uparrow\infty} g_{1,1}(t)g_{1,2}(t) \geq u_{2}\quad\text{and}\quad \limsup_{t\uparrow\infty} c_{1,2}(t) - \frac{1}{2}g_{1,1}(t)^{2} \leq u_{3},
\end{equation}
then any positive solution $I$ to~\eqref{eq:SIS epidemic model} becomes exponentially extinct if $\mu_{\infty} + \gamma_{\infty} > 0$ and
\begin{equation}
(u_{1} + u_{3}N_{\infty} - u_{2}N^{\frac{1}{2}})N_{\infty} < \mu_{\infty} + \gamma_{\infty}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

