[Lem 100 of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Consider any adapted sequence of random variables $(X_n)_{n\ge 0}$ defined on any filtered probability space $(\Omega, (\mathcal F_r)_{r\in \mathbb Z_{\ge 0}}, P),$ with $M_0=0$. Assume that we have $\mathcal E_{\lambda_0} (M;P):=\sup_{n\ge 1} \| E [e^{4\lambda_0|X_{n+1} -X_n|}|\mathcal F_n] \big\|_{L^\infty(\Omega,\mathcal F,P)}<\infty,$ for some $\lambda_0>0$. Then for $|\lambda|<\lambda_0$ we have that 
\begin{equation}E[ e^{\lambda X_r}] \leq E\bigg[ \prod_{s=0}^{r-1} E[e^{2\lambda (X_{s+1}-X_s)}|\mathcal F_s]\bigg]^{1/2}.
\end{equation}
If in particular $X$ is a martingale, then for $|\lambda|<\lambda_0$ we have that 
\begin{align}
     \notag E[ e^{\lambda X_r}] &\leq E\bigg[ \prod_{s=0}^{r-1} \big( 1+4 \lambda^2 \mathcal E_{\lambda_0}(M,P)^{1/2}  E[|X_{s+1}-X_s|^4|\mathcal F_s]^{1/2}\big)\bigg]^{1/2} \\& \leq E\bigg[e^{4 \lambda^2 \mathcal E_{\lambda_0}(M,P)^{1/2}\sum_{s=0}^{r-1}  E\big[|X_{s+1}-X_s|^4\big|\mathcal F_s\big]^{1/2}}\bigg]^{1/2}
\end{align}

[Lemma lem:quotient_integral of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] For every $X\in V_1$ with $|X|_{\mathcal H}=1$ and every $f\in L^1(\mathbb G, dx)$,
\begin{align*}
\int_{\mathbb G}f(g)\,dg
=
\int_{\mathbb R}
\int_{\mathbb H_X}
f\bigl(h\exp(tX)\bigr)\,d\nu_X(h)\,dt.
\end{align*}

