[Lemma lem:constant_local_holder of arXiv:2608.13452, 'Wasserstein stability of the zero cell of a Poisson hyperplane tessellation under directio'] Let \(\phi_0\) be an even nondegenerate probability measure on
    \(S^{d-1}\).
    Then there exist
    \(\varepsilon_0>0\), \(a_0>0\), \(0<\Delta< \infty\) and pairwise disjoint open sets
    \(U_1,\ldots,U_{2d}\subset S^{d-1}\), depending only on \(\phi_0\), such
    that the following hold:

    \begin{enumerate}
        \item For every probability measure \(\phi\) on \(S^{d-1}\) satisfying \(W_{\mathrm{geo}}(\phi,\phi_0)<\varepsilon_0\), one has \(\phi(U_i)>a_0\) for all \(i \in \{1,\ldots,2d \}\).
        \item For every \((u_1,\ldots,u_{2d}) \in U_1 \times \cdots \times U_{2d}\), \(P(u_1,\dots, u_{2d})\) is a bounded polytope, contains \(0\) in its interior, and satisfies
                \begin{align} 
                R_0\biggl(P(u_1,\ldots,u_{2d}) \biggr) \leq \Delta.
                \end{align}
    \end{enumerate}

[Theorem 19 (TV local-error framework) of arXiv:2605.24937, '2605.24937'] Assume~\eqref{eq:one-step-w2-framework},~\eqref{eq:reg-framework}, and
\eqref{eq:tv-local-error}, and let $L\in[\tfrac12,2]$. With
$\overline a_0,\overline a_1$ as in
Lemma~\ref{lem:shifted-recursion} (with $\widehat P$ replaced by
$\widetilde P$) and $\bar N=N\wedge 1/(1-L)_{+}$,
\begin{equation}
  TV\!\bigl(\mu\widetilde P^{N},\nu P^{N}\bigr)
  \;\lesssim\;
  \overline C_{\mathrm{TV}}\,\lambda
  +\sqrt{
    \tfrac{L^{-1}-1}{L^{-N}-1}\,\W^{2}(\mu,\nu)
    +\bigl(((L-1)N)\vee\log\bar N\bigr)\,\overline a_0^{\,2}
    +\bar N\,\overline a_1^{\,2}
  }.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 1005 of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] \medskip Define 
\begin{equation}
I=\mathrm{FS}(q_{1},q_{2},\dots ),\qquad I^{\prime }=\mathrm{FS}
(q_{2},q_{3},\dots ),\qquad m=q_{1}.  
\end{equation}
Then $I^{\prime }\subset I$ and for every $n\in I^{\prime }$ we have $n+m\in
I$.

[Lemma 6 of arXiv:2512.04544, 'On the diameter of random uniform hypergraphs in dense regime'] Let $c,d,n,p$  be as in Assumption \ref{ass bollobas}, and $G \in \mathscr{G}(n,p)$.  Suppose $I$ is the index set as defined in \eqref{def I}. Then, each $\alpha\in I$,
\begin{align*}
\Prob \left( X_ \alpha =1 \right) \approx \frac{c}{n^2}, \mbox{ as } n\to \infty,
\end{align*}	
where $X_\alpha$ is as defined in \eqref{eqn:xalpha}. (Proof in the paper; no proof environment follows the statement in the TeX.)

