\begin{align*}
\overline{\mathfrak{P}}_{\Theta}^{t,x,b,c,v}
=\overline{\mathfrak{P}}_{sem}^{ac}
&\cap\bigl\{\overline{\mathbb{P}}\in\mathcal{P}(\overline{\Omega})\big|\overline{\mathbb{P}}[(\overline{X}_s,\overline{B}_s,\overline{C}_s,\{\overline{V}_s^i\}_{i\in\mathbb{N}})=(x,b,c,v),\, 0\le s\le t]=1\bigr\}\\
&\quad\cap\Bigl\{\overline{\mathbb{P}}\in\overline{\mathfrak{P}}_{sem}^{ac}\mid
