[Thm prop:coupling0 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] If $\gamma$ chosen small enough, then, given any $0 < \eta' < \eta < \tfrac{1}{2}$ sufficiently small (depending only on $\gamma$) there exists a constant $c=c(\eta,\eta') > 0$ such that, if $k$ is sufficiently large, for any $2k \leq T \leq {\rm e}^{ck^\gamma}$, $n \geq k$ and $x,\widetilde{x} \in {\rm D}_n$ satisfying that $x \in {\rm B}^-[\widetilde{x};T-1]$ and $\overline{{\rm B}^+[\widetilde{x};T]} \subseteq {\rm D}_n$, the asymptotics	\begin{equation}
		\mathbb{P} \Big( \big\{ Z_t[x;1] = (u,\overline{y})\big\} \setminus \mathrm{NR}^{\eta,[2,T-1]}_{n,t}(x) \,\Big|\,Z_t[\widetilde{x};T] = (v,\overline{z}) \Big)=r_{k,T}(\widehat{u},\widehat{v})h_k(\overline{y})(1+o_k(1))
	\end{equation} hold uniformly over all $t > 0$, $(u,\overline{y}) \in \mathcal Z_k^{\eta'}[1]$ and $(v,\overline{z}) \in \mathcal Z_k^{\eta'}[T]$, where the functions $r_{k,T}$, $h_k$ are respectively given by
	\begin{equation}
		r_{k,T}(\widehat{u},\widehat{v}):=	 \sqrt{\frac{2}{\pi}}(Tk^{\frac{3}{2}})^{-1}{\rm e}^{-2(T-1)k^\gamma}\left(\widehat{u}{\rm e}^{2\sqrt{2}\widehat{u}}\right)\left(\widehat{v}{\rm e}^{-2\sqrt{2}\widehat{v}-\frac{\widehat{v}^2}{Tk^\gamma}}\right)
	\end{equation}and
	\begin{equation}
		h_k(\overline{y}):=\begin{cases}1 & \text{ if $\overline{y}=\emptyset$}\\ \\\displaystyle{\prod_{i=1}^m \amalg_{{\rm B}^-[0;1]}(y_i) \Pi_{{\rm B}^+[0;1]}(0,y_i')} &\text{ if $\overline{y}=((y_1,y_1'),\dots,(y_{m},y'_{m}))$ for some $m \in \mathbb N$}\,.
		\end{cases}	
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:lbm-active-response-multiplicity of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] For $x\in\Omega_{\rm LBM}$ and an eigenvalue $\Lambda>0$ of multiplicity $r$,
\begin{equation}
 \mathcal N_x(\Lambda)\text{ is a singleton}
 \quad\Longleftrightarrow\quad r=1.

