[Prop 22 of arXiv:2607.06745, 'Regularization and asymptotic behaviour of Ornstein-Uhlenbeck evolution operators in infin'] The following two facts hold true.

i) $\sigma_{p}\left(U\left(T,0\right)^{*}\right)\cap S_{\mathbb{C}}\left(0,e^{\omega_{0}T}\right)=\sigma_{p}\left(P_{0}\right)\cap S_{\mathbb{C}}\left(0,e^{\omega_{0}T}\right)$;

ii) $\sigma_{s}\left(U\left(T,0\right)^{*}\right)\cap S_{\mathbb{C}}\left(0,e^{\omega_{0}T}\right)\subseteq\sigma_{s}\left(P_{0}\right)$.

[Lemma l.equival_jumps of arXiv:2411.14105, 'Simultaneous replica-symmetry breaking \\ for vector spin glasses'] Let $s\in[0,1)$. The following are equivalent:
\begin{enumerate}
    \item it holds that $\alpha^{-1}(s+)>\alpha^{-1}(s)$;
    \item there are $t,t_\star\in \{0\}\cup\supp\mathrm{d}\alpha$ such that
    \begin{align}
        t_\star>t,\qquad \alpha(t)=s,\qquad t=\alpha^{-1}(s),\qquad t_\star =\alpha^{-1}(s+),\qquad (t,t_\star)\cap \supp\mathrm{d} \alpha=\emptyset.
    \end{align}
\end{enumerate}

[Lem 67 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] \quad\par
\begin{itemize}
  \item [$\rm{(i)}$]Let $A,\;B$ be closed subsets of a metric space $(M,d)$.
Suppose that $A$ is unbounded and $B$ has at least two distinct elements.
Taking $a\in A,\;b\in B$, set $A^{(r)}=A\cap \overline{B(a,r)},\;B^{(r)}=B\cap \overline{B(b,r)}$ for $r>0$.
Then there exists an $\tilde{r}_1>0$ such that there exist
$a_0^{r},a_1^{r}\in A^{(r)},\;b_0^{r},b_1^{r}\in B^{(r)}$ for any $r>\tilde{r}_1$ satisfying
the following:
\begin{itemize}
  \item $d(a_0^{r},b_0^{r}),\;d(a_1^{r},b_1^{r})\leq d_{\rm{H}}(A^{(r)},B^{(r)})$;
  \item $\displaystyle  \inf_{r>\tilde{r}_1}d(a_0^{r},a_1^{r})\wedge d(b_0^{r},b_1^{r})>0$;
  \item the set $\{a_0^r,a_1^r,b_0^r,b_1^r:r>\tilde{r}_1 \}$ is bounded.
\end{itemize}
\item[$\rm{(ii)}$]Suppose Assumption 1, and we regard $F,\;F_n,\;n\in\N$ as subsets of a common $\bcm$ space $(M,d)$.
Then there exists an $r_1>0$ such that, for any $r>r_1$ and $n\in\N$ there exist
$a_0^{n,r},a_1^{n,r}\in F^{(r)},\;b_0^{n,r},b_1^{n,r}\in F_n^{(r)}$ satisfying
the following:
\begin{itemize}
  \item $d(a_0^{n,r},b_0^{n,r}),\;d(a_1^{n,r},b_1^{n,r})\leq d_{\rm{H}}(F^{(r)},F_n^{(r)})$;
  \item $\displaystyle \delta:= \inf_{\substack{n\in\N\\r>r_1}}d(a_0^{n,r},a_1^{n,r})\wedge d(b_0^{n,r},b_1^{n,r})>0$;
  \item there exists an $r_{\ast}$ such that the set $\{a_0^{n,r},a_1^{n,r},b_0^{n,r},b_1^{n,r}:r>r_1,n\in\N \}$ is a subset of $B(\rho,r_{\ast})$ and $B(\rho_n,r_{\ast}),\;n\in\N$.
\end{itemize}
\end{itemize}

[Lemma 62 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Fix $N\geq 0$. Let $z\in D\setminus A_{0,b}$ such that $2\pi V_{A_{0,b}}<\vert\log\varepsilon\vert$.
Then
\begin{displaymath}
\Big\vert
\sum_{k=N+1}^{+\infty}
(-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\dfrac{\E[\psi_{2k+1, A} \vert A_{0,b},\ell_{0,b}](z)}{\big(\frac{1}{2\pi}\vert\log \varepsilon\vert\big)^{k + 1/2}}
\Big\vert
\leq
\dfrac{1}{\sqrt{2\pi}}
\big(u^{N+3/2}F_{N}(u)\big)
\Big(
u=
\dfrac{b^{2}\vee V_{A_{0,b}}(z)}{\frac{1}{2\pi}\vert\log\varepsilon\vert}
\Big).
\end{displaymath}
Let $z\in D\setminus A_{0,b}$ such that $\CR(z,D\setminus A_{0,b})\in (\varepsilon,\varepsilon^{-1})$.
Then
\begin{multline*}
\Big\vert
\sum_{k=N+1}^{+\infty}
(-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\dfrac{\E[\tilde{\psi}_{2k+1, A} \vert A_{0,b},\ell_{0,b}](z)}{\big(\frac{1}{2\pi}\vert\log \varepsilon\vert\big)^{k + 1/2}}
\Big\vert
\\
\leq
\dfrac{1}{\sqrt{2\pi}}
\big(u^{N+3/2}F_{N}(u)\big)
\Big(
u=
\dfrac{b^{2}\vee (\frac{1}{2\pi}\vert \log \CR(z,D\setminus A_{0,b})\vert)}{\frac{1}{2\pi}\vert\log\varepsilon\vert}
\Big).
\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Def Def_strongly_convex_3 of arXiv:2606.22183, 'Expected loss of quasi-arithmetic means of exchangeable random variables'] Let $I\subseteq \mathbb{R}$ be a nondegenerate interval and $\mu\in\mathbb{R}_+$.
A function $L:I\to\mathbb{R}$ is called strongly convex with modulus $\mu$ if
 \begin{align*}
  L(tx+(1-t)y) \leqslant t L(x) + (1-t)L(y) - \mu \cdot t (1-t) (x-y)^2,\qquad t\in[0,1], \; x,y\in I.
 \end{align*}

