2D C^{j-1} j\frac{(\Gamma(\alpha+1))^{j-1}\Gamma(\beta+1)}{\Gamma(\alpha (j-1)+\beta+1)} t^{\alpha(j-1) + \beta}
\end{equation}
and
\begin{equation}
V_j(t) \leq 5 \rho_j t^{\alpha j}, \quad t \geq 0.
\end{equation}

