[Proposition 3 ($L^2$ semigroup with bounded potential) of arXiv:2608.29854, '2608.29854'] Assume \eqref{eq:ES}, let $\cV$ be admissible with associated operator
$A$, and let $q:I\to\mathbb R$ be bounded and Borel.  Let $Q$ be
multiplication on $H$ by $q\circ s^{-1}$.  Then
\[
  B=A-Q,\qquad \Dom(B)=\Dom(A),
\]
is self-adjoint and bounded above by $\|q^-\|_\infty$.  Moreover,
\begin{equation}
  T_t^q=U^{-1}e^{tB}U,\qquad t\ge0,
\end{equation}
defines a strongly continuous semigroup on $L^2(I,\mu)$ satisfying
\begin{equation}
  \|T_t^qf\|_{L^2(I,\mu)}
  \le e^{t\|q^-\|_\infty}\|f\|_{L^2(I,\mu)},
  \qquad f\in L^2(I,\mu).
\end{equation}

[Lemma 23 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exists a constant $C_{14}>0$, which depends on $\delta$, $T^*$, $\|v_0\|_{H^1(\Omega)}$ and $\|w_0\|_{H^1(\Omega)}$, such that 

\begin{align*}
&\sup_{\varepsilon \in (0,1),\,\nu \in (0,1)} \left( \sup_{0 \le t \le T} \|w_{\text{{\tiny $\delta,\!\varepsilon,\!\nu$}}}(t)\|_{H^1(\Omega)}^2
+\int_0^T \|w_{\text{{\tiny $\delta,\!\varepsilon,\!\nu$}}}'(t)\|_{L^2 (\Omega)}^2dt \right.\\
&\hspace*{4cm}\left.+\int_0^T \|w_{\text{{\tiny $\delta,\!\varepsilon,\!\nu$}}}(t)\|_{H^2(\Omega)}^2 ds \right) \le C_{14}.
\end{align*}

