body:
[Definition 8 (Uniformization gate) of arXiv:2608.25925, '\textbf{Jump Closure and Limit Uniformization\\in the Ideal Completion of the Turing Degre'] Let
\[
\mathbf a_0\ltT\mathbf a_1\ltT\mathbf a_2\ltT\cdots
\]
be a strictly increasing sequence of Turing degrees. Put
\begin{equation}
A=\bigcup_{n<\omega}\down\mathbf a_n.

\end{equation}
Let $\mathbf b$ satisfy
\begin{equation}
\mathbf a_n\leT\mathbf b\quad\text{for every }n,

\end{equation}
and
\begin{equation}
\mathbf b\notin A.

\end{equation}
Define
\begin{equation}
U_{A,\mathbf b}(I)
=
\begin{cases}
\operatorname{Idl}(I\cup\{\mathbf b\}),&A\subseteq I,\\[3pt]
I,&A\nsubseteq I.
\end{cases}

\end{equation}

