body:
[Lemma lem.coupling.discrete of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] Fix $n\in{\mathbb N}$, $\bm{x}\in{\mathbb R}^n$, and $k_0 \in \{0,1,\dots,n - 1\}$, and write $t_0=k_0/n$. Let $\bm{B}=(\bm{B}(t))_{t_0\leq t \leq 1}$ be an $n$-dimensional Brownian motion and denote its canonical filtration by $\mathbb{F}=(\mathcal{F}(t))_{t_0\leq t\leq 1}$. Also, define the filtration $\mathbb{G} = (\mathcal{G}(k))_{k=k_0,\dots,n}$ by $\mathcal{G}(k)=\mathcal{F}(\tfrac{k}{n})$. Suppose we are given random vectors $\bm{b}(k_0),\dots,\bm{b}(n-1)\in{\mathbb R}^n$ such that
    \begin{equation*}
        |\bm{b}(k)|_2\leq \frac{c_0}{\sqrt{n}},\qquad \bm{b}(k)\text{ is ${\mathcal G}(k)$-measurable,}\qquad\text{for all $k=k_0,\dots,n-1$.}
    \end{equation*}
    Then, there exist processes $\bm{Z}=(\bm{Z}(k))_{k=k_0+1,\dots,n}$ and $\varepsilon=(\varepsilon(k))_{k={k_0+1,\dots,n}}$ such that the following properties hold:
    \begin{enumerate}
        \item The triple $(\mathbb{G}, \bm{Z}, \varepsilon)$ satisfies the assumptions of Lemma~(lem.dpp of the paper) with $\nu=\gamma$ and $k_1=n$.

        \item We have
        \begin{align} 
            \bm{b}(k) = {\mathbb E}\big[\varepsilon(k+1) \bm{Z}(k+1)\,\big|\,{\mathcal G}(k)\big], \qquad k = k_0,\dots,n-1.
        \end{align}
        In particular, we have the martingale decomposition
        \begin{align}
            \bm{Y}(k) \coloneqq \bm{x} + \sum_{\ell=k_0+1}^k \varepsilon(\ell)\bm{Z}(\ell) = \bm{x} + \sum_{\ell=k_0 + 1}^k \bm{b}(\ell - 1) + \sum_{\ell= k_0 + 1}^k \bm{\sigma}(\ell),
        \end{align}
        where $\bm{\sigma}(\ell) \coloneqq \varepsilon(\ell) \bm{Z}(\ell) - {\mathbb E}\big[\varepsilon(\ell) \bm{Z}(\ell)\,\big|\,\mathcal{G}(\ell-1)\big]$ and $k=k_0,\dots,n$.

        \item For every $p > 2$ and $k_1=k_0+1,\dots,n$,
        \begin{align}
            {\mathbb E}\bigg|\sum_{k=k_0+1}^{k_1}\bm{\sigma}(k) - \big(\bm{B}(\tfrac{k_1}{n}) - \bm{B}(\tfrac{k_0}{n})\big)\bigg|_\infty
            &\leq C_p n^{\frac14} \max_{k_0 \leq k < k_1} \bigg(\sum_{i=1}^n \|b_i(k)\|_p^p\bigg)^{\frac{1}{2p}}, 
        \end{align}
        where $C_p>0$ is a constant that depends only on $p$.

        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 of arXiv:2606.14564, 'Upper tails for irregular graphs \\ beyond the mean-field regime'] For all $p \le 1/2$ and $G \subseteq K_n$,
  \begin{equation}

    \Ex_G[X]-\Ex[X] =\bigl(1+\Theta(n^{-1}+p)\bigr) \cdot \sum_{\emptyset \neq J\subseteq H} \frac{|\Emb(J,H)|}{|\Aut(H)|} \cdot N(J,G)\cdot n^{v_H-v_J} p^{e_H-e_J},
  \end{equation}    
  where the sum is over all unlabelled subgraphs of $H$ without isolated vertices. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma H-theorem of arXiv:2511.05223, 'Kac's Program and Relative Entropy Decay for Nonlinear Spin-Exchange Dynamics'] Let $p_t$ denote the solution of ((non-linear rqs of the paper)) with initial datum $p\in\ensuremath{\mathcal P}(\O)$, and let $\mu = \mu_{J,h}$ for some arbitrary, fixed  $h\in\G_\ensuremath{\mathcal A}$. Then,  

\begin{equation} 
    \frac{d}{dt} H(p_t\,|\,\mu) = -\mathcal{D}_{\mu}(f_t), 
    \,\qquad t\ge0, 
\end{equation}
where  $f_t: = p_t/\mu$, 
and the entropy dissipation functional \(\mathcal{D}_{\mu}\) is  defined by 
\begin{equation}   
   \mathcal{D}_{\mu}(f)  = \frac{1}{4} \sum_{\sigma, \sigma', \tau, \tau'}\mu(\tau) \mu(\tau') \mathcal{Q}_J^\ensuremath{\mathcal K}(\tau, \tau'; \sigma, \sigma') \left(f(\tau)f(\tau') - f(\sigma)f(\sigma')\right) \log\left(\frac{f(\tau)f(\tau')}{f(\sigma)f(\sigma')}\right).
\end{equation}

In particular,  $H(p_t\,|\, \mu)$ is non-increasing in $t\ge 0$. Moreover, $p\in \mathcal{P}(\Omega)$ is stationary iff the density $f=p/\mu$ satisfies $ f(\tau)f(\tau') = f(\sigma)f(\sigma')$ whenever $\mathcal{Q}_J^\ensuremath{\mathcal K}(\tau, \tau'; \sigma, \sigma')>0$.

