[Definition def:characteristic:functional of arXiv:2605.28106, 'Gaussian Processes with Sample Paths in Reproducing Kernel Banach Spaces'] Let \( \mu \) be a probability measure on \( \mathcal{C}(X,\Gamma) \).
    The \emph{characteristic functional} of \( \mu \) is the functional
    \begin{equation} 
        \widehat{\mu}:\Gamma\to\mathbb{C}, \qquad
        f \mapsto \int_X e^{if(x)} \, \mu(dx).
    \end{equation}

[Proposition 5 of arXiv:2605.06953, 'Asymptotic Results for Uniform Group Drawing in the Coupon Collector's Problem'] If $s = n -\lambda\cdot n^{\frac{t-1}{t}}$ then,
    \begin{align*}
        \lim_{n \to \infty} \PP[Y = i] = 
        \begin{cases}
            e^{-\lambda^t}, &i=t, \\
            1-e^{-\lambda^t}, &i=t+1, \\
            0, &\text{otherwise}.
        \end{cases}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:frostman-green-smoothing of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Let $\mu$ be a finite positive Radon measure on $D$ satisfying, for some
$C_\mu<\infty$ and $\alpha>0$,
\begin{equation}
 \mu(B_D(z,r))\le C_\mu r^\alpha,
 \qquad z\in D,
 \quad 0<r\le1.
\end{equation}
Then $\mu(\{z\})=0$ for every $z\in D$.  For every $p>0$,
\begin{equation}
 L_p(\mu)
 :=\sup_{z\in D}\int_D
 \left(1+\log^+\frac1{|z-w|}\right)^p\mu(dw)<\infty.
\end{equation}
Moreover, for every compact $K\Subset D$,
\begin{equation}
 \sup_{\substack{z,z'\in K\\|z-z'|\le\delta}}
 \int_D|G_D(z,w)-G_D(z',w)|^2\,\mu(dw)
 \xrightarrow[\delta\downarrow0]{}0.
\end{equation}
In particular,
\begin{equation}
 \sup_{z\in D}\int_DG_D(z,w)^2\,\mu(dw)
 \le C_D^2L_2(\mu)<\infty.
\end{equation}

