[Proposition prop:Markov of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Let $D\subset \mathbb{C}$ be a domain with $\partial D =  \partial^D\cup\partial^F$, $\partial^D\cap\partial^F=\emptyset$, and $U\subset D$ open. Let $h$ be the GFF on $D$ with  \textit{Dirichlet} (resp. free) \textit{boundary conditions} on $\partial^D$ (resp. $\partial^F$). Then we can write $h=h_1+h_2$ where: 
		\begin{enumerate}
			\item $h_1$ and $h_2$ are independent;
			\item $h_1$ is a GFF on $U$ with Dirichlet boundary condition on $\partial U\backslash \partial^F$ and free on $\partial U\cap \partial^F$;
			\item $h_2$ is the same as $h$ outside $U$ and harmonic inside $U$.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 26 of arXiv:2506.09609, 'Schramm-Loewner evolution contains a topological Sierpi\'nski carpet when $\kappa$ is clos'] Fix $N \geq 100$. For all sufficiently large $M$ (which may depend on $N$ and $\varrho$), with probability $1 - o_R(1)$ as $R \to \infty$, the set $\mathscr{U}$ is $N$-separated in the following sense. Let $\mathsf{m} = \mathsf{m}(N, R, \varrho)$ be the largest integer $m$ such that $N^m \leq \varrho^{-1} 10^{-4} R$. There exists a sequence of vertex sets $\{\mathcal{A}_m\}_{0 \leq m \leq \mathsf m - 1}$ satisfying:
    \begin{enumerate}[i.]
        \item $\mathcal{A}_m \subset \varrho N^m \mathbb{Z}^2 \cap \mathscr{L}_R$ for $0 \leq m \leq \mathsf m - 1$; 
        \item For $0 \leq m \leq \mathsf m - 1$, each vertex in $\mathcal{A}_m$ has $|\cdot|_\infty$-distance at least $\frac{1}{10} \varrho N^{m+1}$ away from each other; 
        \item We have $\mathscr{U} \subset \cup_{m=0}^{\mathsf{m} - 1} \cup_{y \in \mathcal{A}_m} B(y, 10 \varrho N^m)$. 
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 (Common Hilbert--Schmidt bound) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] Each flattening of~\eqref{eq:model-kernel} has the same Hilbert--Schmidt norm, and
\begin{equation}
 \norm{F_j}_{\Sch_2}
 \lesssim |A_N|\norm{k}_{L^2}
 N^{d/2}Q^{d/2}M^{d/2},\qquad j=1,2,3,4.
\end{equation}

[Lemma 161 (Perfect divergence structure for derivative-losing vorticity) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] For $\Sigma_t$-tangent vectorfields $\SigmatTan_1, \, \SigmatTan_2$, denote their Cartesian inner product by $\SigmatTan_1\cdot\SigmatTan_2 = \sum_{i=1}^3\SigmatTan_1^i\cdot\SigmatTan_2^i$. Then the following identity holds:
	\begin{align}
		\begin{split} 
		&  - \int_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}} \Speed^2 \exp(2\LogDensity) (\multipliervectorfield \tander^N \vortrenormalized)\cdot (\upmu \tander^N \vortrenormalized) \weight^{\blowupratetoporderwave} \ReciprocalLunitAppliedtoTimeFunction \, \voldiamond 
		= - 2  \int_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}} \Speed^2 \exp(2\LogDensity)  (\upmu \Transport \tander^N \vortrenormalized)\cdot (\upmu \tander^N \vortrenormalized) \weight^{\blowupratetoporderwave} \ReciprocalLunitAppliedtoTimeFunction \, \voldiamond \\
		 & \ \ - \frac{1}{2} \int_{\ingoingcharacteristicsurfacetwoarg{\ubar}{[\moreinterestingu_1,u]}}  \upmu \Speed^2 \exp(2\LogDensity) |\tander^N \vortrenormalized|^2 \weight^{\blowupratetoporderwave}  \volingoingnullhypersurface +  \frac{1}{2} \int_{\ingoingcharacteristicsurfacetwoarg{\leftubar}{[\moreinterestingu_1,u]}}  \upmu \Speed^2 \exp(2\LogDensity) |\tander^N \vortrenormalized|^2 \weight^{\blowupratetoporderwave}  \volingoingnullhypersurface \\
