body:
[Lemma lem.tau-tails of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] There exist constants $C=C(d,\Lambda,r_0)>0$ and $c=c(d,\Lambda,r_0)>0$ such that for every $\lambda\in(0,1]$ and $t>0$,
		\begin{equation}
			\sup_\omega \widehat P^{\lambda,\omega}_0\bigl(\tau_1\ge\lambda^{-2}t\bigr)\le Ce^{-ct}\, ,
		\end{equation}
		and for every $k\ge 1$,
		\begin{equation}
			\widehat{\mathbb P}^\lambda_0\bigl(\Delta\tau_k\ge\lambda^{-2}t\bigr)\le Ce^{-ct}\, .
		\end{equation}

[Proposition Prop.BDG of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] For two constants $p\geq 1$ and $T>0$, assume that
 	\begin{eqnarray*}
 	\sup_{t\in[0,T]}\mathbf{E}\Big[\big|X(t)\big|^{p}\Big]<\infty
 	\quad \mbox{and}\quad 
 	\int_0^T ds \int_0^\infty \big|g(s,y)\big|^{2p}\mu(dy) <\infty.
 	\end{eqnarray*}
 	Then there exists a constant $C>0$ depending only on $p$ such that
 	\begin{eqnarray} 
 	\sup_{t\in[0,T]}\mathbf{E}\Big[ \big| B(f,t) \big|^{2p}  \Big] 
 	\leq C\cdot \sup_{t\in[0,T]}\mathbf{E} \Big[\big|X(t)\big|^p \Big] \cdot \bigg| \int_0^T   \big|f(s)\big|^{2} ds  \bigg|^{p}
 	\end{eqnarray}
 	and 
 	\begin{eqnarray} 
 	\sup_{t\in[0,T]}\mathbf{E}\Big[ \big| \widetilde{N}(g,t) \big|^{2p}  \Big] 

 	\!\!\!&\leq\!\!\!& C  \cdot \sup_{t\in[0,T]}\mathbf{E} \Big[\big|X(t)\big|^p \Big] \cdot \bigg| \int_0^T ds \int_0^\infty\big|g(s,y)\big|^{2} \mu(dy)  \bigg|^{p} \cr
 	\!\!\!&\!\!\!& + C \cdot \sup_{t\in[0,T]}\mathbf{E}\Big[\big|X(t)\big|\Big]\cdot \int_0^T ds \int_0^\infty\big|g(s,y)\big|^{2p} \mu(dy) .
 	\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Dfn of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] [{Continuous functor}]
  We say that a functor $\tau$ is \textit{continuous}
  if $\tau$ satisfies Assumption (3. assum: pointwise continuity of the paper).

[Lemma 7 of arXiv:2605.11264, 'Uniform sampling of multitype continuous-time Bienaym\'e-Galton-Watson trees'] Fix $i\in [d]$. For any $\bm{\ell}\in \z^d_+\setminus\{\bo 0\}$ with $\ell_i>0$ and $0< t< T$, we have 
\begin{align*}
	& 	\Q^{(k),\bm \theta}_{T,r}\paren{\bo{L}_\emptyset=\bm{\ell}\left|\chi_\emptyset\in {\rm d} t,\tau_1>t ,c (\varsigma^{(1)}_{t+})=i \right.} = \frac{\ell_ip_r\paren{\bm{\ell}}\prod_{m\in[d]}\E_m\left[e^{-\bm \theta\cdot \bo Z_{T-t}}\right]^{\ell_m}}{
	\mathbb{E}_r\left[L^{(i)}\prod_{m\in[d]}\E_m\left[e^{-\bm \theta\cdot \bo Z_{T-t}}\right]^{L^{(m)}}\right]},
\end{align*}
where $L^{(i)}$ denotes the $i$-th coordinate of the r.v. $\bo{L}$.

