[Prop 87 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] With the notations above,
for every $n\geq 1$, the following decomposition holds:
\begin{displaymath}
:\Phi^{n}: ~=~
\sum_{j=0}^{n} \dfrac{n!}{j! (n-j)!} Q_{n-j}(h_{\mathcal{A}},V_{\mathcal{A}})\,:\Phi_{D\setminus \mathcal{A}}^{j} : \, ,
\end{displaymath}
In particular,
\begin{displaymath}
\E\big[ :\Phi^{n}: \big\vert \mathcal{A}, h_{\mathcal{A}}\big]
= Q_{n}(h_{\mathcal{A}},V_{\mathcal{A}}).
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: separate outer of arXiv:2609.03755, 'The Scramble Number of Outerplanar Graphs'] Let $G$ be a maximal outerplanar graph. Under the isomorphism that maps $G[N(v)\cup\{v\}]$ to $F_{\deg(v)}$, let $x,y\in N(v)$ map to non adjacent path vertices $u_i$ and $u_j$ such that $i<j$. We may produce a cut $C$ such that
    \begin{enumerate}
        \item $C$ disconnects at least two non-empty vertex sets,
        \item the vertices $u_{i+1}, \ldots, u_{j-1}$ lie in the same component, and $v$ lies in another component,
        \item $|C|\leq \deg(x)+\deg(y)+(j-i)$.
    \end{enumerate}

[Theorem 7 (Markov property) of arXiv:2607.02108, 'A Two-Color Lift of the Shifted \texorpdfstring{$t$}{t}-Schur Measure'] For every $\mu$ in the support of the marginal distribution,
\begin{equation}
        \sum_{\lambda\in\SP}K_X^Y(\mu,\lambda)=1.
\end{equation}
Moreover,
\begin{equation}
        \Prob_q^{X,Y}(\mu,\lambda)
        =\pi_{qX,Y}(\mu)K_X^Y(\mu,\lambda),
\end{equation}
where
\begin{equation}
        \pi_{qX,Y}(\mu)=\frac{Q_\mu(qX)P_\mu(Y)}{\Ht(qX;Y)}.
\end{equation}

[Proposition 11 of arXiv:2606.01881, '2606.01881'] For every $\eps>0$,
\begin{equation}
        \Pp\bigl(L_{2^k}<2^{(1-\eps)pk}\text{ for infinitely many }k\bigr)=0.
\end{equation}

