Moreover, for every \(c>0\),
\begin{equation}
  \frac{\mathcal Z(ca)}{\mathcal Z(a)}
  \longrightarrow c^{-\theta}.

\end{equation}

[Proposition of arXiv:2412.08400, '\vspace{-1.0cm} Characterization of Exponential Families of \\ Lumpable Stochastic Matrice'] For $(x_0,x_0') \in \mathcal{U}$, let
$G^{\uparrow}_{x_0,x_0'} \in \mathcal{F}(\mathcal{Y},\mathcal{E})$ be such that for any $(y,y') \in \mathcal{E}$,
    \begin{equation*}
    G^{\uparrow}_{x_0,x_0'}(y,y') = \pred{ (y,y') \in E_{x_0,x_0'} },
\end{equation*}
where $E_{x_0,x_0'}$ is introduced in (equation eq:anchor-points of the paper) and the sets $\mathcal{U}, \mathcal{R}$ are introduced in (equation equation:block-type-nomenclature of the paper).
For any $(y_0, y_0') \in \mathcal{R}$, let $G^{\uparrow}_{y_0, y_0'} \in \mathcal{F}(\mathcal{Y}, \mathcal{E})$ be such that for any $(y,y') \in \mathcal{E}$,
\begin{equation*}
    G^{\uparrow}_{y_0, y_0'}(y,y') = \delta\left[(y,y') = (y_0, y_0')\right].
\end{equation*}
The system of functions
\begin{equation*}
    \mathcal{B}_{\kappa}(\mathcal{Y}, \mathcal{E}) \triangleq \set{G^{\uparrow}_{x_0,x_0'} \colon (x_0,x_0') \in \mathcal{U}} \cup \set{G^{\uparrow}_{y_0, y_0'} \colon (y_0,y_0') \in \mathcal{R}},
\end{equation*}
forms a basis for $\spann(\mathcal{G}_{\kappa}(\mathcal{Y}, \mathcal{E}))$, and
\begin{equation*}
    \dim \spann(\mathcal{G}_\kappa(\mathcal{Y}, \mathcal{E})) = 
    \left| \mathcal{U} \right| + \left| \mathcal{R} \right|.
