[Defi The decoupling map of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Let $n\in \mathbb N$. Let $u\in \widetilde{\mathcal{W}}_n$ be such that $|u|_\gamma\leqslant (\lambda_\gamma+\varepsilon)n$ for $\gamma\in \{1,2\}$ and set $(u^1,\ldots ,u^r)=F_n(u)$.
	For $\gamma\in \{1,2\}$, we denote by $\underline v^{(\gamma)}$ the list $ (u^{j_\gamma(1)},\ldots, u^{j_\gamma(r_\gamma)})$.
	Then $(\underline v^{(1)},\underline v^{(2)})\in \mathcal S_{r_1, T_1}\times \mathcal S_{r_2,T_2}$ and we set 
	\begin{equation*}
		\Phi_n^{(1)}(u)=G_{r_1, T_1}\big(\underline v^{(1)}\big), \qquad		\Phi_n^{(2)}(u)=G_{r_2,T_2 }\big(\underline v^{(2)}\big), \qquad\Phi_n(u)=\big(\Phi_n^{(1)}(u),\Phi_n^{(2)}(u)\big).
	\end{equation*}

[Proposition prop:tail_Holder of arXiv:2605.30999, 'Functional central limit theorems for $U$-statistics of $\beta$-mixing data'] Let $h\colon S^m\to \mathbb R$ be a measurable function and let $\left(X_i\right)_{i\in \mathbb Z}$ be a strictly stationary sequence. Suppose that 
\begin{equation*}
    \lim_{t\to +\infty}\max_{1\leqslant k\leqslant m}
    \sup_{\bm{i}\in\operatorname{Inc}^k} t^p\mathbb P\pr{\abs{h\pr{X_{i_1},\dots,X_{i_k},X_1^*,\dots,X_{m-k}^*}}>t  }=0.
\end{equation*}
Then for each $k\in\llbracket 1,m\rrbracket$, 
\begin{equation*}
   \lim_{t\to +\infty} t^p \sup_{\bm{i}\in I^k_\infty}  \mathbb P\pr{\abs{\pi_{k,m}\left(h\right)\pr{X_{\bm{i}}}}>t}=0. 
\end{equation*}

