[Lemma 14 of arXiv:2608.30409, 'Gradient estimates and volume doubling for locally finite weighted graphs with $CD\psi(n,-'] Let $G=\left(V,E\right)$ be a locally finite weighted graph satisfying the $CD\psi\left(n,-K\right)$ condition with $K\geq0$, where $\psi\in C^{1}\left(0,+\infty\right)$ is a concave function. Then for any $0<f\in \ell^{\infty}\left(V\right)$ with $R_{f}<\infty$ and $\tau>0$, 
    \begin{equation*}
    \begin{aligned}
        \tau P_t\left(f\cdotp  \Gamma^{\psi}\left(f\right)\right)-\left(\tau+t\right) P_t f\cdotp\Gamma^{\psi}\left(P_t f\right)
        \geq -\psi^{\prime}\left(1\right)t\left[1+K(2\tau+t)\right]\Delta P_t f\\
        -\frac{n}{8}\left[\log\left(1+\frac{t}{\tau}\right)+4Kt+4K^{2}\tau t+2K^{2}t^{2}\right] P_t f. 
    \end{aligned}       
    \end{equation*}

