    \begin{itemize}

      \item Case 1: $0 < \alpha \le \beta \le 2$;

      \item Case 2: $0 < \beta < 2 \wedge \alpha$ and $\alpha \not\in 2\mathbb{N}$;

      \item Case 3: $\alpha>\beta =2$ and $\alpha\not\in 2\mathbb{N}$;
            \begin{itemize}
              \item Subcase 3-1: $\gamma < \alpha - 3 + d/2$;
              \item Subcase 3-2: $\gamma > \alpha - 3 + d/2$;
              \item Subcase 3-3: $\gamma = \alpha - 3 + d/2$.
            \end{itemize}

      \item Case 4: $\alpha = 2$ and $\beta < 2$;

      \item Case 5: $\alpha \in 2 \mathbb{N}+2$ and $\beta \in (0, 2)$.

    \end{itemize}
  \end{multicols}
