[Definition def:SUSY1eps of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $\zeta\in\mathrm{Prefix}_2(u,q)$ for some $u,q\in(0,1)$.
		We define $\mathrm{SUSY}_1(\zeta,\varepsilon)$ as the set of $\mathbf{m}\in[-1+\delta_\varepsilon,1-\delta_\varepsilon]^N$ such that
		\begin{equation*}
			\left|\frac{1}{N}\|\mathbf{m}\|^2-q\right|\leq\varepsilon,
			\qquad
			\left|\frac{1}{N}\langle\partial_m h_\zeta(q,\mathbf{m}),\mathbf{m}\rangle
			-\xi'(q)\int_0^1\zeta([0,t])\,\mathrm{d} t\right|\leq \varepsilon,
		\end{equation*}
		and
		\begin{equation*}
			\mathrm{dist}\!\bigl(\zeta_\mathbf{m},\,\zeta|_{(q,1]}+\zeta([0,q])\,\delta_q\bigr)\leq\varepsilon,
		\end{equation*}
		where we recall that $\mathrm{dist}$ is as in (equation def:dist of the paper).

[Lemma 16 of arXiv:2609.03084, 'Convergence rates to traveling waves for an FKPP model with nonlinear advection'] For $x \geq 2t$, let
        \begin{equation}
            \phi(t, x) = \frac{K(x-2t)}{t^{3/2}}e^{-(x-2t)}e^{\frac{-(x-2t)^2}{4t}},
        \end{equation}
        where $K$ is a positive constant.
        Then there exists a $T > 0$ such that
        \begin{equation}
            \bar \phi(t, x) = \left(1- \frac{1}{t^{1/4}}\right) \phi(t, x) 
        \end{equation}
        is a nonnegative supersolution of \eqref{main_eq} for $t > T$.

[Definition D:main-nondegenerate-arc of arXiv:2607.15966, 'Canonical Mandelbrot Cascades on Curves Are Rajchman'] A map \(\gamma:[0,1]\to\mathbb{R}^2\) is a fixed nondegenerate \(C^2\) embedded arc if it is a \(C^2\) embedding and
\begin{equation}
\inf_{t\in[0,1]}|\gamma'(t)|>0,
\qquad
\inf_{t\in[0,1]}
|\det(\gamma'(t),\gamma''(t))|>0.
\end{equation}

