body:
[Theorem 3 of arXiv:2607.25986, 'Asymptotics of a two-species particle system associated to the doubly parabolic Keller-Seg'] Suppose Assumption~\ref{mol} and that $\chi<\chi^*_\theta$. Fix $\sigma\in (0,\frac 12]$.

\vip

(i) Set
\begin{equation}
\Aa_\sigma=\{(N,M,\e) : N\geq 2, M>0, \e\in (0,1], N M\e^{3+\sigma}\geq 1, N M^{1+\sigma} \e^{2+\sigma} \geq 1\}.
\end{equation}
The family 
$((X^{1,N,M,\e}_t)_{t\geq 0} : (N,M,\e)\in \Aa_\sigma)$ is tight in $C(\R_+,\R^2)$.

\vip

(ii) Fix $N\geq 2$ and consider $(M_n)_{n\geq 1}$ valued in $(0,\infty)$ and $(\e_n)_{n\geq1}$ valued in 
$(0,1]$ such that 
\begin{equation}
\lim_{n\to \infty} M_n= \infty, \quad \lim_{n\to \infty} \e_n=0 \quad \text{and} \quad \lim_{n\to\infty}
M_n\e_n^{3+\sigma}=\infty.
\end{equation}
Then the family $((X^{k,N,M_n,\e_n}_t)_{t\geq 0, k \in I_N} : n\geq 1)$ is tight in $C(\R_+,(\R^2)^N)$
and any limit point $((X^{k,N}_t)_{t\geq 0, k \in I_N}$ as $M\to \infty$ is a $(\rho_0,c_0,N)$-1SKS system.

\vip

(iii) Consider  $(M_N)_{N\geq 2}$ valued in $(0,\infty)$ and $(\e_N)_{N\geq2}$ valued in $(0,1]$ such that 
\begin{equation}
\lim_{N\to \infty} \e_{N}=0, \quad \lim_{N\to \infty}  N M_N\e_N^{3+\sigma}=\infty\quad \text{and} 
\quad \lim_{N\to \infty} N M_N^{1+\sigma}\e_N^{2+\sigma}=\infty.
\end{equation}
Then the family $(\mu^{N,{M_N}} : N \geq 2)$ is tight in $\Pp(C(\R_+,\R^2))$ and any (possibly random) 
limit $\mu$ a.s. solves $\mathcal{(MP)}(\rho_0,c_0)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:measurable-finite-rank-invariants of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] From the preceding definitions we obtain the following three properties.
\begin{enumerate}[label=\textnormal{(\roman*)},leftmargin=2.1em,itemsep=2pt,topsep=3pt]
 \item For every $\mu$,
 \begin{equation}
  d_N^\Pi(\mu)\uparrow\rank\Pi_\mu,
  \qquad
  \mu\longmapsto\rank\Pi_\mu\quad\text{is measurable}.
 \end{equation}

 \item For every $k\ge1$ and every $\mu$,
 \begin{equation}
  t_{k,N}^B(\mu)\longrightarrow\Tr(B_\mu^k),
  \qquad
  \mu\longmapsto\Tr(B_\mu^k)\quad\text{is measurable}.
 \end{equation}

 \item Let $Y$ be a standard Borel space.  If the matrix coefficients of
 $\Pi_{\mu,y}$ and $B_{\mu,y}$ are measurable in $(\mu,y)$, then, for every
 $k\ge1$,
 \begin{equation}
  (\mu,y)\longmapsto
  \bigl(\rank\Pi_{\mu,y},\Tr(B_{\mu,y}^k)\bigr)
  \quad\text{is measurable into }\mathbb N_0\times\mathbb R.
 \end{equation}
\end{enumerate}

