[Corollary exchangeability_degrees of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] For $m,n \in \mathbb{N}$, let $G^{(n)}$ be a URD and let $G_1$ be the resulting graph in the Kingman $(m,n)$-coalescent. Recall that $\mathbb A_n$ and $\mathbb F_n$ are the sets of active and frozen vertices of $G^{(n)}$, respectively. With $\sigma_a$ and $\sigma_f$ uniform permutations of the element of $\mathbb A_n$ and $\mathbb F_n$, respectively,
\begin{equation} \begin{aligned} 
\big({}&(\deg_{G_1}(a_v), \ell_{G_1}(a_v), u_{G_1}(a_v))_{v\in [A_n]},(\deg_{G_1}(f_w), \ell_{G_1}(f_w), u_{G_1}(f_w))_{w\in [F_n]}\big)\\
&\overset \mathrm{d} = \big((\deg_n(\sigma_a(o)),\sigma_a(o),u_n(\sigma_a(o)))_{o\in \mathbb A_n},((\deg_n(\sigma_f(u)),\sigma_f(u),u_n(\sigma_f(u)))_{u\in \mathbb F_n})\big).
\end{aligned} \end{equation} 
And, jointly for $i,j\in\mathbb{N}$, $A\subseteq [A_n]$, and $F\subseteq [F_n]$, 
\begin{equation} \begin{aligned}
({}&|\{v\in A: \deg_{G_1}(a_v)=i\}|,|\{w\in F: \deg_{G_1}(f_w)=j\}|)\\
&\overset \mathrm{d}= (|\{o\in \mathbb A_n: \deg_n(\sigma_a(o))=i\}|,|\{u\in \mathbb F_n: \deg_n(\sigma_f(u))=j\}|).
\end{aligned}\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thrm:GreenKernel1 of arXiv:2411.09976, 'Occupation times on the legs of a diffusion spider'] The Green kernel of the diffusion spider $\mathbf{X}$ has a density~$\mathbf{g}_\lambda$ with respect to the speed measure~$\mathbf{m}$, which is 
given for $ x\geq 0$ and $y\geq 0$ by
\begin{equation}

\mathbf{g}_\lambda((x,i),(y,j))=
\begin{cases}
\varphi(y)\tilde{\psi}(x,i), &\quad x\leq y,\ i=j, \\[2pt]
\varphi(x)\tilde{\psi}(y,i), &\quad y\leq x,\ i=j, \\[2pt]
c_\lambda^{-1}\,\varphi(y)\varphi(x), &\quad i\neq j,
\end{cases}
\end{equation}
where 
\begin{equation}

\tilde{\psi}(x,i):=\frac1{\beta_i}\psi^{\partial}(x)+\frac1{c_\lambda}\varphi(x)
\end{equation}
and 
\begin{equation}

c_\lambda:=-\frac{d}{dS}\varphi(0+)>0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

