body:
[Lem 1 of arXiv:2512.05687, '$L^p$-Boltzmann-Gibbs principle \\ via Littlewood-Paley-Stein inequality'] For functions $F=F(\phi)$ and $G=G(\phi) \in C^2(\R^N)$, if all integrals
in the following converge, we have
\begin{align*} 
& \int_{\R^N} GL_0F d\hat\mu_{N,m} = \int_{\R^N} FL_0G d\hat\mu_{N,m}
= -\frac12 \int_{\R^N} \sum_{x\in \T_N} \partial_{\phi(x)} F \cdot \partial_{\phi(x)} G \, d\hat\mu_{N,m}, \\
& \int_{\R^N} G L_1 F d\hat\mu_{N,m} = -\int_{\R^N} F L_1 G d\hat\mu_{N,m},
\intertext{and}
& \Ga(F) = \sum_{x\in \T_N} \big(\partial_{\phi(x)} F\big)^2 =: |D_\phi F|^2,
\end{align*}
where $D_\phi F = (\partial_{\phi(x)} F)_{x\in \T_N}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 8 of arXiv:2506.08775, 'Markovian multivariate Hawkes population processes: Efficient evaluation of moments'] If $\bm{C}_{i}^{m_{i}\times m_{i}}$ is invertible for all $i\in\{1,\ldots,n\}$,
then 
\begin{align} 
\begin{split}
\begin{bmatrix} \bm{\Psi}^{(0,1)}_t \\ 
    \vdots \\
    \bm{\Psi}^{(0,n)}_t\end{bmatrix}
    &= e^{\bm{A}_{n}^{\mathfrak{m}_{n}\times\mathfrak{m}_{n}}t}
    \begin{bmatrix} \bm{\Psi}^{(0,1)}_0 \\ 
    \vdots \\
    \bm{\Psi}^{(0,n)}_0\end{bmatrix}
    -\left(\bm{A}_{n}^{\mathfrak{m}_{n}\times\mathfrak{m}_{n}}\right)^{-1}\left(\bm{I}^{\mathfrak{m}_{n}\times\mathfrak{m}_{n}} - e^{\bm{A}_{n}^{\mathfrak{m}_{n}\times\mathfrak{m}_{n}}t}\right)\begin{bmatrix}
    \bm{b}^{2\times 1}  \\
    \bm{0}^{(\mathfrak{m}_{n}-m_{1})\times 1}
    \end{bmatrix}.
\end{split}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 14 of arXiv:2608.26288, 'Muon with Finite Newton--Schulz: The Smoothing Benefit in Nonsmooth Nonconvex Optimization'] Suppose~\cref{ass:general-spectral-link} holds and let $(C_t)_{t\geq1}$ be a positive sequence.
For any $t\geq1$, the action~\cref{eq:general-spectral-action} is the FTRL update
\begin{equation}
  X_t^h
  =-D\nabla\widetilde\Phi_{h,C_t}(M_{t-1})
  \in\argmin_{\lVert X\rVert_{\mathrm{op}}\leq D}
  \left\{
    \inpr*{\sum_{s=1}^{t-1}\beta^{-s}G_s,X}
    +\frac{R_{h,C_t}(X)}{(1-\beta)\beta^{t-1}}
  \right\},

\end{equation}
where the regularizer $R_{h,C}$ is given by
\begin{equation}
  R_{h,C}(X)
  \coloneqq D\widetilde\Phi_{h,C}^*(X/D)
  =DC\sum_{i=1}^r
  \phi_h^*\left(\frac{\sigma_i(X)}{D}\right).

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem l:1103.7 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Fix $u \geq 0$ and, for each $n \geq 1$, some deterministic subset $\widetilde{{\rm D}}_n \subseteq \mathbb{Z}^2$. In addition, let us set
	\begin{equation}
		{\rm W}^{\widetilde{{\rm D}}_n}_n(u) = {\rm W}_n(u) \cap \widetilde{{\rm D}}_n
		\quad ; \qquad 
		{\mathbf W}^{\widetilde{{\rm D}}_n}_n(u) := \big\{ z \in \mathbb{X}_{n-r_n} :\: {\rm W}^{\widetilde{{\rm D}}_n} \cap {\rm Q}(z;n-r_n) \neq \emptyset\} \,.
	\end{equation}
	Then,
	\begin{equation}
		\lim_{\delta \downarrow 0} \limsup_{n \to \infty}
		\mathbb{P} \bigg( \frac{1}{\sqrt{n}}|{\mathbf W}^{\widetilde{{\rm D}}_n}_n(u)| > \delta^{-1} \sqrt{|{\rm D}_n^\circ \cap \widetilde{{\rm D}}_n|/|{\rm D}_n|} \bigg) = 0 \,.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:one_step_improvement_intro of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] There exists $\gamma_0>0$, a spatial scale $\eta\in (0,1/4]$ and a frequency $L_0\geq 1$ such that for every $N\geq L_0$, it holds that
\begin{align}

\Big({\mathbf E}\Big\|v^N-\fint_{\eta B} v^N\Big\|_{\underline{L}^2(\eta Q)}^r \Big)^{1/r}
&
\leq \eta^{\gamma_0}\Big({\mathbf E}\Big\|v^N-\fint_{B} v^N\Big\|_{\underline{L}^2( Q)}^r \Big)^{1/r}\\ 
\nonumber
&+ \mathscr{C}_Q[\pi^N,(\widetilde{\pi}^N_{k,\alpha})_{k,\alpha},F,G],
\end{align}
where the last term collects the contributions of pressures and forcing at the scale $Q$ (see Subsection (ss:role_pressure_intro of the paper) for details on the former). (Proof in the paper; no proof environment follows the statement in the TeX.)

