[Def Def_strongly_convex_2 of arXiv:2606.22183, 'Expected loss of quasi-arithmetic means of exchangeable random variables'] Let $I\subseteq \mathbb{R}$ be a nondegenerate interval, and $\alpha:(I-I)\to\mathbb{R}_+$ be an even function.
A function $L:I\to\mathbb{R}$ is said to be strongly convex with respect to the error function $\alpha$, briefly strongly $\alpha$-convex, if
 \begin{align}
  \begin{split}
  L(tx+(1-t)y)&\leqslant  tL(x)+(1-t)L(y)\\
              &\phantom{\leqslant\;}- t\alpha((1-t)(x-y))-(1-t)\alpha(t(y-x)),\qquad x,y\in I,\,t\in[0,1].
 \end{split}
 \end{align}

[Definition def:anisocyl of arXiv:2602.08591, 'The Yang--Mills measure on compact surfaces as a \\ universal scaling limit of lattice gau'] Set $\alpha\in (0,1)$.
Outside $\Psi(\mathrm{Crit}(f)_1)$, on some product of intervals $I\times J\subset [\min(f),\max(f)]_r\times \mathcal{S}^1_\theta $ which avoids $\Psi(\mathrm{Crit}(f)_1)$, we define these local semi-norms on smooth connections as~:
\begin{equation}
\Vert \tilde{A}\Vert_{\mathcal{W}^{\alpha,\alpha-1;p}_{r,\theta}(I\times J) }\coloneq    \Vert W\Vert_{\mathcal{W}^{\alpha,\alpha;p}_{r,\theta}(I\times J) }= 
\left(
\int_{I^2} \frac{\Vert W(r_1,.)-W(r_2,.) \Vert^p_{W^{\alpha,p}_{\theta,J}}}{\vert r_1-r_2\vert^{1+\alpha p}} \mathrm{d} r_1\mathrm{d} r_2 \right)^{\frac{1}{p}} + \Vert W \Vert_{L^p(I\times J)}  \end{equation}
for $\tilde{A}(r,u) \coloneq \partial_\theta W(r,\theta) $ and $W(.,0)=0$~\footnote{This acts like some half--Dirichlet condition on $W$.} for $J=[0,a]$.

The H\"older version reads
\begin{equation}
 \Vert \tilde{A}\Vert_{\mathcal{C}^{\alpha,\alpha-1}_{r,\theta}(I\times J) }\coloneq    \Vert W\Vert_{\mathcal{C}^{\alpha,\alpha}_{r,\theta}(I\times J) }= 
\sup_{ r_1\neq r_2\in  I^2} \frac{\Vert W(r_1,.)-W(r_2,.) \Vert^p_{\mathcal{C}^{\alpha}_{\theta,J}}}{\vert r_1-r_2\vert^{\alpha}}+ \sup_{(I\times J)}\vert W\vert.    
\end{equation}

[Lm Concentration Bound of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] Let $F:\mathbb{R}^{n^2+(k+1)n} \to \mathbb{R}$ be a function with bounded Lipschitz norm on compact sets (independently of $n$ or $k$) and $|F(x)| \leq C(1+||x||)^d$ for some constants $C,d>0$ (again independent of $n$ or $k$). Then
    \begin{equation*}
    \begin{split}
        &\mathbb{P}\left(\sup_{t \in [0,T]} |F(\Tilde{M}(t)/\sqrt{n},\theta_0(t),\dots,\theta_k(t))-\mathbb{E} F(\Tilde{M}(t)/\sqrt{n},\theta_0(t),\dots,\theta_k(t))| > u\right) \\
        &\hspace{7cm}\leq C e^{-c(T,k) \frac{n u^2}{\log(n)}}+e^{-c(T,k)\frac{n}{\log(n)}},
        \end{split}
    \end{equation*}
    where the constants $C$ and $c(T,k)$ do not depend on $n$. In particular, setting $u=\sqrt{w}\log(n)n^{-1/2}$, we have
    \begin{equation*}
        \mathbb{P}\left(\sup_{t \in [0,T]} |F(\Tilde{M}(t)/\sqrt{n},\theta_0(t),\dots,\theta_k(t))-\mathbb{E} F(\Tilde{M}(t)/\sqrt{n},\theta_0(t),\dots,\theta_k(t))| > \frac{\sqrt{w}\log(n)}{n^{1/2}}\right) \leq C n^{-c(T,k)w},
    \end{equation*}
    which is summable for $w>c(T,k)^{-1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

