body:
[Theorem T:MomBdd of arXiv:2412.03521, 'On ergodic properties of stochastic PDEs'] Let $u(t,x; \mu)$ be the solution to~(equation E:SHE of the paper) starting from a rough
  initial condition $\mu$ which satisfies~(equation A:icon of the paper). Assume that
  \begin{enumerate}[wide, labelwidth=!, labelindent=0pt, label=\emph{(\roman*)}]
    \setlength\itemsep{.1in}

    \item the diffusion coefficient $b$ satisfies the degenerate
      condition~(equation E:Cond-b of the paper);

    \item $\rho: \mathbb{R}^d \to \mathbb{R}_+$ is a nonnegative $L^1 (\mathbb{R}^d)$ function;

    \item for all $t > 0$, the initial condition $\mu$ satisfies the condition
      that $\mathcal{G}_{\rho}(t;|\mu|) < \infty$, where
      \begin{equation}
        \mathcal{G}_{\rho}(t;\mu)
        \coloneqq \int_{\mathbb{R}^d} \left[\left(p(t,\cdot) * \mu\right)(x) \right]^2 \rho(x)\: \ensuremath{\mathrm{d}} x;
      \end{equation}

    \item the spectral measure $\widehat{f}$ satisfies~(equation E:Upsilon_0 of the paper),
      i.e., $\Upsilon(0)<\infty$, and the Lipschitz constant $L_b$ is small
      enough so that $4 L_b^2\Upsilon(0) < 1$.

  \end{enumerate}
  Then there exists a unique $L^2 (\Omega)$-continuous solution $u(t,x)$ such
  that for some constant $C>0$, which does not depend on $t$, the following
  holds:
  \begin{equation}
    \mathbb{E}\left(\left\|  u(t,\cdot; \mu)   \right\|_{\rho}^2\right)
    \le C \mathcal{G}_{\rho}\left(t; |\mu|\right)
    < \infty, \quad \text{for any $t > 0$},
  \end{equation}
  where we recall that the norm $\left\|  \cdot   \right\|_\rho$ is given
  by~(equation E:WeightedNorm of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:Delta-moments of arXiv:2608.26765, 'Beyond Client Averaging: A Client-Independent Second-Order Stationary-Bias Component in St'] For the $\Delta$ in Equation~(equation eq:Delta-def of the paper),
\begin{align}
  \mathbb{E}[\Delta^2]&\le C_H\gamma^2s_{\gamma,N},                              \\
  \mathbb{E}[\Delta^4]&\le C_H\gamma^7,                                         \\
  \mathbb{E}|\Delta|^6&\le C_H\gamma^9.                                         
\end{align}
A second, weaker but sometimes useful estimate is
\begin{equation}

  \mathbb{E}[\Delta^4]\le C_H\gamma^4(M_4+\gamma^4),
  \qquad M_4:=\mathbb{E}[x^4].
\end{equation}

[Lemma 233 ($L^2$ estimates for the terms featuring a perfect divergence structure) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $N = \Ntop$,  let 
$\tander^N \in \mathfrak{P}^{(N)}$ be the set of top order $\nullhyparg{u}$-tangential commutator operators from
Def.\,\ref{D:STRINGSOFCOMMUTATIONVECTORFIELDS}. Let $\blowuprateofwaveWRTnumberofcommutations(N) = \blowupratetoporderwave$ denote the blowup rate of the wave variables defined in \eqref{E:BLOWUPRATEOFWAVEWRTNUMBEROFCOMMUTATORS}. For $\Sigma_t$-tangent vectorfields $\SigmatTan_1, \, \SigmatTan_2$, denote their Cartesian inner product by $\SigmatTan_1\cdot\SigmatTan_2 = \sum_{i=1}^3\SigmatTan_1^i\cdot\SigmatTan_2^i$. Then the following estimate holds for
$(\ubar,u) \in [\leftubar,\ubarboot) \times [\moreinterestingu_1,\moreinterestingu_2]$:
\begin{align}
		\begin{split} 
			 - \int_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}} \Speed^2 \exp(2\LogDensity) (\multipliervectorfield \tander^N \vortrenormalized)\cdot (\upmu \tander^N \vortrenormalized) \weight^{\blowupratetoporderwave} \ReciprocalLunitAppliedtoTimeFunction \, \voldiamond \le  C \, \Errortop(\ubar,u),
		\end{split}
	\end{align}
where we note that \eqref{E:L2ESTIMATESFORTHETERMSFEATURINGADIVERGENCESTRUCTURE} does not feature an absolute value on the left hand side.

