\begin{align*}
\sup_{N\in \N^*}\sup_{t\in [0,T]} \big\lVert \langle v \rangle^k F^{(N)}_{t} \big\rVert_{L^2_{x,v}}<\infty , \qquad \sup_{N\in \N^*} \sup_{t\in [0,T]} \big\lVert u^{(N)}_{t} \big\rVert_{\gamma,p}<\infty \\
\text{ and } \quad \sup_{N\in \N^*}\Big( \sup_{t\in [0,T]} \lVert m_{0}(F^{(N)}_{t})\rVert_{L^2_{x}} + \sup_{t\in [0,T]} \lVert m_{1}(F^{(N)}_{t})\rVert_{L^2_{x}} \Big) <\infty .
\end{align*}

